		private static void BootLog(string msg)
		{
			try
			{
				if (!string.IsNullOrEmpty(_bootLogFile))
				{
					File.AppendAllText(_bootLogFile, $"[{DateTime.Now:HH:mm:ss.fff}] {msg}{Environment.NewLine}");
				}
			}
			catch
			{
			}
		}

		private void FailAndExit(string title, Exception ex)
		{
			try
			{
				BootLog("FailAndExit: " + title);
				System.Windows.MessageBox.Show($"{title}：\n\n{ex.Message}\n\n{ex.StackTrace}\n\n" + "详细日志已保存至：" + _bootLogFile, "程序启动失败", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			finally
			{
				Shutdown(-1);
			}
		}

		protected override void OnExit(ExitEventArgs e)
		{
			//IL_0059: Unknown result type (might be due to invalid IL or missing references)
			//IL_0063: Expected O, but got Unknown
			BootLog($"=== APP EXIT code={e.ApplicationExitCode} ===");
			AppDomain.CurrentDomain.UnhandledException -= OnUnhandledException;
			base.DispatcherUnhandledException -= new DispatcherUnhandledExceptionEventHandler(OnDispatcherUnhandledException);
			TaskScheduler.UnobservedTaskException -= OnUnobservedTaskException;
			base.OnExit(e);
		}

		private void OnDispatcherUnhandledException(object sender, DispatcherUnhandledExceptionEventArgs e)
		{
			BootLog($"DispatcherUnhandledException: {e.Exception}");
			ShowExceptionDialog("UI线程异常", e.Exception);
			e.Handled = true;
		}

		private void OnUnhandledException(object? sender, UnhandledExceptionEventArgs e)
		{
			if (e.ExceptionObject is Exception ex)
			{
				BootLog($"UnhandledException (isTerminating={e.IsTerminating}): {ex}");
				ShowExceptionDialog("应用程序异常", ex);
			}
		}

		private void OnUnobservedTaskException(object? sender, UnobservedTaskExceptionEventArgs e)
		{
			LogException("任务线程异常（已静默处理）", e.Exception);
			e.SetObserved();
		}

		private void ShowExceptionDialog(string title, Exception ex)
		{
			LogException(title, ex);
			System.Windows.MessageBox.Show($"发生{title}：\n\n{ex.Message}\n\n{ex.StackTrace}", title, MessageBoxButton.OK, MessageBoxImage.Hand);
		}

		private void LogException(string title, Exception ex)
		{
			try
			{
				string text = System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "logs");
				Directory.CreateDirectory(text);
				string path = System.IO.Path.Combine(text, $"app_{DateTime.Now:yyyyMMdd}.log");
				string text2 = $"[{DateTime.Now:HH:mm:ss.fff}] {title}：\n{ex.Message}\n{ex.StackTrace}";
				if (ex.InnerException != null)
				{
					text2 = text2 + "\n内部异常：" + ex.InnerException.Message + "\n" + ex.InnerException.StackTrace;
				}
				File.AppendAllText(path, text2 + Environment.NewLine);
			}
			catch (Exception)
			{
			}
		}

		private void CheckForUpdatesOnStartup()
		{
			Task.Run(async delegate
			{
				_ = 3;
				try
				{
					SettingsService settingsService = new SettingsService();
					UpdateSettings updateSettings = await settingsService.GetUpdateSettingsAsync();
					if (updateSettings.CheckOnStartup && (!updateSettings.LastCheckTime.HasValue || !((DateTime.Now - updateSettings.LastCheckTime.Value).TotalHours < (double)updateSettings.NotifyIntervalHours)))
					{
						string version = VersionHelper.GetVersion();
						UpdateCheckService updateChecker = new UpdateCheckService((string)null);
						try
						{
							UpdateInfo updateInfo = await updateChecker.CheckForUpdateAsync(version, updateSettings);
							updateSettings.LastCheckTime = DateTime.Now;
							await settingsService.SaveUpdateSettingsAsync(updateSettings);
							if (updateInfo == null || updateInfo.Version == updateSettings.SkippedVersion)
							{
								return;
							}
							await ((DispatcherObject)this).Dispatcher.InvokeAsync((Action)delegate
							{
								if (base.MainWindow != null)
								{
									UpdateDialog updateDialog = new UpdateDialog(updateInfo, updateSettings);
									updateDialog.Owner = base.MainWindow;
									updateDialog.ShowDialog();
								}
							});
						}
						finally
						{
							((IDisposable)updateChecker)?.Dispose();
						}
					}
				}
				catch (Exception ex)
				{
					LogException("启动时版本检查失败", ex);
				}
			});
		}

