		private void GeneratePortBat_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				List<PortScanResult> source = _portScanResults.Where((PortScanResult r) => r.IsSelected).ToList();
				if (!source.Any())
				{
					System.Windows.MessageBox.Show("请先勾选要关闭的端口", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				string text = string.Join(", ", source.Select((PortScanResult p) => p.PortNumber));
				string text2 = ((System.Windows.MessageBox.Show("即将为以下端口生成关闭脚本：\n" + text + "\n\n是否使用高级选项？\n【是】高级选项：包含防火墙规则备份、入站+出站双向拦截、规则验证\n【否】标准选项：仅添加入站拦截规则", "端口关闭脚本选项", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes) ? _portManagementService.GeneratePortClosureScript(source.Select((PortScanResult p) => p.PortNumber).ToList()) : _portManagementService.GenerateAdvancedPortClosureScript(source.Select((PortScanResult p) => p.PortNumber).ToList()));
				string text3 = $"关闭端口脚本_{DateTime.Now:yyyyMMdd_HHmmss}.bat";
				string text4 = _portManagementService.SaveScriptToFile(text2, text3);
				System.Windows.MessageBox.Show("端口关闭脚本已成功生成！\n\n保存位置：" + text4 + "\n包含端口：" + text + "\n\n使用说明：\n1. 右键点击此BAT文件\n2. 选择\"以管理员身份运行\"\n3. 脚本将自动添加防火墙规则关闭端口", "脚本生成成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				StatusTextBlock.Text = "已生成端口关闭脚本：" + text4;
				Log("端口关闭脚本已生成：" + text4);
			}
