								Margin = new Thickness(0.0, 0.0, 0.0, 15.0)
							});
						}
					}
					scrollViewer.Content = stackPanel;
					obj.Content = scrollViewer;
					obj.ShowDialog();
				}
				else
				{
					System.Windows.MessageBox.Show("无法找到指定的扫描结果", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("查看扫描结果详情失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

