		private static void WriteLog(string message)
		{
			try
			{
				string contents = $"[{DateTime.Now:yyyy-MM-dd HH:mm:ss.fff}] {message}{Environment.NewLine}";
				File.AppendAllText(_logFilePath, contents);
			}
			catch
			{
			}
		}

		private static void WriteErrorLog(string context, Exception ex)
		{
			string text = $"[ERROR] {context}: {ex.Message}\nStackTrace: {ex.StackTrace}";
			if (ex.InnerException != null)
			{
				text = text + "\nInnerException: " + ex.InnerException.Message + "\n" + ex.InnerException.StackTrace;
			}
			WriteLog(text);
		}

		private static void AddChartImage(DocX doc, byte[] imageData, float width = 400f, float height = 220f)
		{
			if (imageData == null || imageData.Length == 0)
			{
				WriteLog("[WordReport] 图表数据为空，跳过插入");
				return;
			}
			try
			{
				using MemoryStream memoryStream = new MemoryStream(imageData);
				Picture val = ((Document)doc).AddImage((Stream)memoryStream, "image/jpeg").CreatePicture();
				val.Width = width;
				val.Height = height;
				Paragraph obj = ((Container)doc).InsertParagraph();
				obj.Alignment = (Alignment)1;
				obj.AppendPicture(val);
				obj.SpacingBefore(10.0);
				obj.SpacingAfter(10.0);
			}
			catch (Exception ex)
			{
				WriteLog("[WordReport] 图表插入失败: " + ex.Message);
			}
		}

