		public static string GenerateFromHistoryRecordToPath(CompleteScanResult record, string savePath)
		{
			if (record == null)
			{
				throw new ArgumentNullException("record", "扫描记录为空");
			}
			if (string.IsNullOrWhiteSpace(savePath))
			{
				throw new ArgumentException("保存路径不能为空", "savePath");
			}
			List<PortScanResult> list = record.PortScanResults ?? new List<PortScanResult>();
			List<VulnerabilityResult> list2 = record.VulnerabilityResults ?? new List<VulnerabilityResult>();
			if (!list.Any() && !list2.Any())
			{
				throw new InvalidDataException("该扫描记录暂无数据（端口和漏洞均为空）");
			}
			string targetIp = (string.IsNullOrWhiteSpace(record.TargetIp) ? "未知目标" : record.TargetIp);
			try
			{
				string directoryName = System.IO.Path.GetDirectoryName(savePath);
				if (!string.IsNullOrEmpty(directoryName) && !Directory.Exists(directoryName))
				{
					Directory.CreateDirectory(directoryName);
				}
				using (MemoryStream memoryStream = new MemoryStream())
				{
					DocX val = DocX.Create((Stream)memoryStream, (DocumentTypes)0);
					try
					{
						GenerateCoverPage(val, targetIp, list, list2, isComposite: false, 0, record.ScanType);
						AddPageBreak(val);
						GenerateTableOfContents(val);
						AddPageBreak(val);
						GenerateExecutiveSummary(val, list, list2, targetIp, record.ScanType);
						AddPageBreak(val);
						GenerateScanScopeSection(val, targetIp, list, list2, record.ScanType);
						AddPageBreak(val);
						GeneratePortScanSection(val, list);
						AddPageBreak(val);
						GenerateVulnerabilitySection(val, list2);
						AddPageBreak(val);
						GenerateRiskAssessment(val, list2, list);
						AddPageBreak(val);
						GenerateRemediationSection(val, list2);
						AddPageBreak(val);
						GenerateThreatIntelligenceSection(val, list2, list);
						AddPageBreak(val);
						GenerateComplianceSection(val, list2, list);
						AddPageBreak(val);
						GenerateConclusionSection(val, list2, list);
						AddPageBreak(val);
						GenerateCveAppendix(val, list2);
						((Document)val).Save("");
					}
					finally
					{
						((IDisposable)val)?.Dispose();
					}
					using FileStream fileStream = new FileStream(savePath, FileMode.Create, FileAccess.Write, FileShare.None, 4096, FileOptions.WriteThrough | FileOptions.SequentialScan);
					memoryStream.Position = 0L;
					memoryStream.CopyTo(fileStream);
					fileStream.Flush();
				}
				WriteLog("[WordReport] Word报告生成成功：" + savePath);
				return savePath;
			}
			catch (Exception ex)
			{
				WriteErrorLog("单记录Word报告生成失败", ex);
				throw;
			}
		}

		public static string GenerateFromMultipleRecordsToPath(List<CompleteScanResult> records, string savePath)
		{
			if (records == null || !records.Any())
			{
				throw new ArgumentException("扫描记录列表为空");
			}
			if (string.IsNullOrWhiteSpace(savePath))
			{
				throw new ArgumentException("保存路径不能为空", "savePath");
			}
			List<PortScanResult> list = (from p in records.SelectMany((CompleteScanResult r) => r.PortScanResults ?? new List<PortScanResult>())
				group p by (p != null) ? p.PortNumber : 0 into g
				select g.First() into p
				orderby p.PortNumber
				select p).ToList();
			List<VulnerabilityResult> list2 = (from v in records.SelectMany((CompleteScanResult r) => r.VulnerabilityResults ?? new List<VulnerabilityResult>())
				group v by ((v != null) ? v.CveId : null) ?? ((v != null) ? v.Name : null) ?? Guid.NewGuid().ToString() into g
				select g.OrderByDescending((VulnerabilityResult v) => GetRiskPriority((v != null) ? v.RiskLevel : null)).First() into v
				orderby GetRiskPriority((v != null) ? v.RiskLevel : null) descending
				select v).ToList();
			if (!list.Any() && !list2.Any())
			{
				throw new InvalidDataException("所有扫描记录均无有效数据");
			}
			string targetIp = "多目标综合";
			try
			{
				string directoryName = System.IO.Path.GetDirectoryName(savePath);
				if (!string.IsNullOrEmpty(directoryName) && !Directory.Exists(directoryName))
				{
					Directory.CreateDirectory(directoryName);
				}
				using (MemoryStream memoryStream = new MemoryStream())
				{
					DocX val = DocX.Create((Stream)memoryStream, (DocumentTypes)0);
					try
					{
						GenerateCoverPage(val, targetIp, list, list2, isComposite: true, records.Count, BuildScanTypesString(records));
						AddPageBreak(val);
						GenerateTableOfContents(val);
						AddPageBreak(val);
						GenerateExecutiveSummary(val, list, list2, targetIp, BuildScanTypesString(records));
						AddPageBreak(val);
						GenerateScanScopeSection(val, targetIp, list, list2, BuildScanTypesString(records));
						AddPageBreak(val);
						GeneratePortScanSection(val, list);
						AddPageBreak(val);
						GenerateVulnerabilitySection(val, list2);
						AddPageBreak(val);
						GenerateRiskAssessment(val, list2, list);
						AddPageBreak(val);
						GenerateRemediationSection(val, list2);
						AddPageBreak(val);
						GenerateThreatIntelligenceSection(val, list2, list);
						AddPageBreak(val);
						GenerateComplianceSection(val, list2, list);
						AddPageBreak(val);
						GenerateConclusionSection(val, list2, list);
						AddPageBreak(val);
						GenerateCveAppendix(val, list2);
						((Document)val).Save("");
					}
					finally
					{
						((IDisposable)val)?.Dispose();
					}
					using FileStream fileStream = new FileStream(savePath, FileMode.Create, FileAccess.Write, FileShare.None, 4096, FileOptions.WriteThrough | FileOptions.SequentialScan);
					memoryStream.Position = 0L;
					memoryStream.CopyTo(fileStream);
					fileStream.Flush();
				}
				WriteLog($"[WordReport] 综合Word报告生成成功：{savePath} (合并{records.Count}条记录)");
				return savePath;
			}
			catch (Exception ex)
			{
				WriteErrorLog("多记录综合Word报告生成失败", ex);
				throw;
			}
		}

		private static void AddPageBreak(DocX doc)
		{
			((InsertBeforeOrAfter)((Container)doc).InsertParagraph()).InsertPageBreakAfterSelf();
		}

