		}

		private static void AddVulnerabilityDetailBlock(DocX doc, VulnerabilityResult vuln, int detailIndex)
		{
			//IL_009a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0111: Unknown result type (might be due to invalid IL or missing references)
			//IL_0164: Unknown result type (might be due to invalid IL or missing references)
			//IL_00db: Unknown result type (might be due to invalid IL or missing references)
			//IL_024f: Unknown result type (might be due to invalid IL or missing references)
			//IL_04d3: Unknown result type (might be due to invalid IL or missing references)
			//IL_04fe: Unknown result type (might be due to invalid IL or missing references)
			//IL_0637: Unknown result type (might be due to invalid IL or missing references)
			//IL_06cd: Unknown result type (might be due to invalid IL or missing references)
			//IL_0681: Unknown result type (might be due to invalid IL or missing references)
			//IL_0774: Unknown result type (might be due to invalid IL or missing references)
			//IL_08d0: Unknown result type (might be due to invalid IL or missing references)
			//IL_0866: Unknown result type (might be due to invalid IL or missing references)
			//IL_0891: Unknown result type (might be due to invalid IL or missing references)
			if (vuln == null)
			{
				return;
			}
			string text = (string.IsNullOrWhiteSpace(vuln.RiskLevel) ? "未分类" : vuln.RiskLevel);
			string value = (string.IsNullOrWhiteSpace(vuln.Name) ? "未知漏洞" : vuln.Name);
			double value2 = EstimateCvssScore(text);
			Paragraph val = ((Container)doc).InsertParagraph();
			val.Append($"[{detailIndex}] {value}").FontSize(11.0).Bold(true)
				.Color(DeepBlue);
			if (!string.IsNullOrWhiteSpace(vuln.CveId))
			{
				val.Append(" (" + vuln.CveId + ")").FontSize(10.0).Color(AccentBlue);
			}
			val.Append("  [" + text + "]").FontSize(10.0).Bold(true)
				.Color(GetRiskColor(text));
			val.SpacingBefore(12.0);
			val.SpacingAfter(6.0);
			Paragraph val2 = ((Container)doc).InsertParagraph();
			val2.Append("\n【漏洞概述】\n").FontSize(10.0).Bold(true)
				.Color(DeepBlue);
			string text2 = GetSafeString(vuln.Description);
			if (string.IsNullOrWhiteSpace(text2) || text2 == "-")
			{
				text2 = "该漏洞影响 " + (string.IsNullOrWhiteSpace(vuln.Service) ? "系统" : vuln.Service) + "服务" + (vuln.Port.HasValue ? $"（端口 {vuln.Port.Value}）" : "");
			}
			val2.Append(text2).FontSize(10.0);
			val2.Append("\n【CVSS评分详情】\n").FontSize(10.0).Bold(true)
				.Color(DeepBlue);
			string text3 = (vuln.Port.HasValue ? "网络(N)" : "本地(L)");
			string text4 = ((text == "严重") ? "低" : ((text == "高危") ? "低" : "中"));
			string text5 = ((text == "严重" || text == "高危") ? "无(N)" : "低(L)");
			string text6 = "无(N)";
			string text7 = ((text == "严重") ? "改变(C)" : "未改变(U)");
			string text8 = ((text == "严重" || text == "高危") ? "高(H)" : "低(L)");
			string text9 = ((text == "严重" || text == "高危") ? "高(H)" : "低(L)");
			string text10 = ((text == "严重") ? "高(H)" : ((text == "高危") ? "高(H)" : "低(L)"));
			val2.Append("\n  • 攻击向量(AV)：" + text3).FontSize(9.0);
			val2.Append("\n  • 攻击复杂度(AC)：" + text4).FontSize(9.0);
			val2.Append("\n  • 权限要求(PR)：" + text5).FontSize(9.0);
			val2.Append("\n  • 用户交互(UI)：" + text6).FontSize(9.0);
			val2.Append("\n  • 影响范围(S)：" + text7).FontSize(9.0);
			val2.Append("\n  • 机密性(C)：" + text8).FontSize(9.0);
			val2.Append("\n  • 完整性(I)：" + text9).FontSize(9.0);
			val2.Append("\n  • 可用性(A)：" + text10).FontSize(9.0);
			val2.Append($"\n  • 综合评分：{value2:F1}/10.0").FontSize(10.0).Bold(true)
				.Color(GetRiskColor(text));
			val2.Append("\n\n【基本信息】\n").FontSize(10.0).Bold(true)
				.Color(DeepBlue);
			val2.Append($"\n  • CVSS评分：{value2:F1} ({text})").FontSize(9.0);
			val2.Append("\n  • 影响端口：" + ((vuln != null && vuln.Port.HasValue) ? $"TCP/{vuln.Port.Value}" : "N/A")).FontSize(9.0);
			val2.Append("\n  • 影响服务：" + (string.IsNullOrWhiteSpace(vuln.Service) ? "N/A" : vuln.Service)).FontSize(9.0);
			val2.Append("\n  • 风险等级：" + text).FontSize(9.0).Bold(true)
				.Color(GetRiskColor(text));
			if (!string.IsNullOrWhiteSpace(vuln.DetectionMethod) && vuln.DetectionMethod != "-")
			{
				val2.Append("\n\n【检测方法】\n").FontSize(10.0).Bold(true)
					.Color(DeepBlue);
				val2.Append(GetSafeString(vuln.DetectionMethod)).FontSize(10.0);
			}
			val2.Append("\n\n【影响范围分析】\n").FontSize(10.0).Bold(true)
				.Color(DeepBlue);
			switch (text)
			{
			case "严重":
			case "高危":
				val2.Append("该漏洞可导致远程代码执行或权限提升，攻击者可能完全控制受影响的系统。影响范围包括：系统完整性破坏、敏感数据泄露、服务中断等严重后果。").FontSize(10.0);
				break;
			case "中危":
				val2.Append("该漏洞可导致信息泄露或服务降级，攻击者可能获取部分系统信息或造成服务影响。建议尽快修复。").FontSize(10.0);
				break;
			default:
				val2.Append("该漏洞风险较低，主要影响信息收集或带来有限的安全隐患。建议纳入常规修复计划。").FontSize(10.0);
				break;
			}
			val2.Append("\n\n【修复方案】\n").FontSize(10.0).Bold(true)
				.Color(DeepBlue);
			foreach (string item in (from l in GetSafeString(vuln.Solution ?? "请参考官方安全公告获取补丁信息。").Split('\n')
				where !string.IsNullOrWhiteSpace(l)
				select l.Trim()).Take(5))
			{
				val2.Append("  • " + item + "\n").FontSize(10.0);
			}
			if (!string.IsNullOrWhiteSpace(vuln.References))
			{
				val2.Append("\n\n【参考链接】\n").FontSize(10.0).Bold(true)
					.Color(DeepBlue);
				val2.Append(GetSafeString(vuln.References)).FontSize(9.0).Color(AccentBlue);
			}
			val2.SpacingAfter(20.0);
			Paragraph obj = ((Container)doc).InsertParagraph(new string('─', 60));
			obj.FontSize(7.0);
			obj.Color(MidGray);
			obj.SpacingAfter(8.0);
		}

