		private static List<(string, string, string, string)> BuildThreatVectors(List<PortScanResult> openPorts, List<VulnerabilityResult> vulns)
		{
			List<(string, string, string, string)> list = new List<(string, string, string, string)>();
			HashSet<int> hashSet = openPorts.Select((PortScanResult p) => (p != null) ? p.PortNumber : 0).ToHashSet();
			if (hashSet.Contains(21) || hashSet.Contains(20))
			{
				list.Add(("FTP服务威胁", "20-21/FTP", "高", "匿名登录、弱口令暴力破解、明文传输嗅探"));
			}
			if (hashSet.Contains(22))
			{
				list.Add(("SSH服务威胁", "22/SSH", "中", "暴力破解、密钥窃取、配置不当利用"));
			}
			if (hashSet.Contains(23))
			{
				list.Add(("Telnet服务威胁", "23/Telnet", "严重", "明文传输嗅探、弱口令、未授权访问"));
			}
			if (hashSet.Contains(25) || hashSet.Contains(110) || hashSet.Contains(143))
			{
				list.Add(("邮件服务威胁", "25,110,143/SMTP/POP3/IMAP", "中", "邮件中继滥用、凭据嗅探、钓鱼攻击"));
			}
			if (hashSet.Contains(80) || hashSet.Contains(443) || hashSet.Contains(8080) || hashSet.Contains(8443))
			{
				list.Add(("Web服务威胁", "80,443,8080,8443/HTTP(S)", "高", "SQL注入、XSS、CSRF、目录遍历、Web Shell"));
			}
			if (hashSet.Contains(135))
			{
				list.Add(("RPC服务威胁", "135/RPC", "严重", "RPC漏洞利用、DCOM攻击、信息泄露"));
			}
			if (hashSet.Contains(139) || hashSet.Contains(445))
			{
				list.Add(("SMB服务威胁", "139,445/SMB", "严重", "EternalBlue、SMB漏洞利用、共享泄露"));
			}
			if (hashSet.Contains(3389))
			{
				list.Add(("RDP服务威胁", "3389/RDP", "严重", "BlueKeep漏洞、暴力破解、凭据窃取"));
			}
			if (hashSet.Contains(1433) || hashSet.Contains(3306) || hashSet.Contains(5432) || hashSet.Contains(1521))
			{
				list.Add(("数据库服务威胁", "1433,3306,5432,1521/数据库", "严重", "暴力破解、SQL注入、未授权访问、数据泄露"));
			}
			if (hashSet.Contains(6379))
			{
				list.Add(("Redis服务威胁", "6379/Redis", "严重", "未授权访问、主从复制RCE、数据泄露"));
			}
			if (hashSet.Contains(27017) || hashSet.Contains(27018))
			{
				list.Add(("MongoDB服务威胁", "27017,27018/MongoDB", "严重", "未授权访问、数据泄露、勒索攻击"));
			}
			if (vulns.Any((VulnerabilityResult v) => IsCritical((v != null) ? v.RiskLevel : null)))
			{
				list.Add(("严重漏洞利用", "多端口/多服务", "严重", "远程代码执行、权限提升、数据窃取"));
			}
			if (vulns.Any((VulnerabilityResult v) => IsHigh((v != null) ? v.RiskLevel : null)))
			{
				list.Add(("高危漏洞利用", "多端口/多服务", "高", "权限提升、信息泄露、服务拒绝"));
			}
			if (!list.Any())
			{
				list.Add(("常规网络威胁", "通用", "低", "端口扫描、服务探测、信息收集"));
			}
			return list;
		}

		private static List<(string, string, string)> BuildAttackSurfaceItems(List<PortScanResult> openPorts, List<VulnerabilityResult> vulns, List<VulnerabilityResult> highRiskVulns)
		{
			List<(string, string, string)> list = new List<(string, string, string)>();
			bool flag = openPorts.Select((PortScanResult p) => (p != null) ? p.PortNumber : 0).ToList().Any((int p) => p == 445 || p == 135 || p == 3389 || p == 23);
			list.Add(("外部可达端口数", $"{openPorts.Count}个开放端口" + (flag ? "（含高危端口）" : "（未发现高危端口）"), flag ? "高" : "低"));
			list.Add(("已知漏洞数量", $"{vulns.Count}个漏洞" + (highRiskVulns.Any() ? $"（含{highRiskVulns.Count}个高危）" : ""), highRiskVulns.Any() ? "高" : "低"));
			bool flag2 = openPorts.Any((PortScanResult p) => (p != null && p.PortNumber == 80) || (p != null && p.PortNumber == 443));
			list.Add(("服务暴露面", flag2 ? "Web服务对外暴露" : "无Web服务对外暴露", flag2 ? "中" : "低"));
			bool flag3 = highRiskVulns.Any((VulnerabilityResult v) => (v != null && v.Name?.ToLower().Contains("auth") == true) || (v != null && v.Name?.ToLower().Contains("认证") == true) || (v != null && v.Name?.ToLower().Contains("login") == true));
			list.Add(("身份认证风险", flag3 ? "存在认证相关漏洞" : "未发现认证相关漏洞", flag3 ? "高" : "低"));
			bool flag4 = vulns.Any((VulnerabilityResult v) => (v != null && v.Name?.ToLower().Contains("disclosure") == true) || (v != null && v.Name?.ToLower().Contains("泄露") == true) || (v != null && v.Name?.ToLower().Contains("leak") == true));
			list.Add(("数据泄露风险", flag4 ? "存在信息泄露风险" : "未发现数据泄露风险", flag4 ? "中" : "低"));
			return list;
		}

