		private static List<(string, string, string, string)> BuildComplianceItems(List<VulnerabilityResult> vulns, List<PortScanResult> openPorts)
		{
			bool flag = vulns.Any((VulnerabilityResult v) => IsCritical((v != null) ? v.RiskLevel : null) || IsHigh((v != null) ? v.RiskLevel : null));
			bool flag2 = openPorts.Select((PortScanResult p) => (p != null) ? p.PortNumber : 0).ToHashSet().Any((int p) => p == 445 || p == 135 || p == 3389 || p == 3306 || p == 1433);
			return new List<(string, string, string, string)>
			{
				("等保2.0", "安全物理环境/安全通信网络/安全区域边界", flag ? "存在高危漏洞，不满足安全计算环境要求" : "基本满足安全计算环境要求", flag ? "不合规" : "部分合规"),
				("ISO 27001", "A.12漏洞管理/A.9访问控制/A.13通信安全", flag ? "漏洞管理流程存在缺陷" : "漏洞管理基本到位", flag ? "不合规" : "部分合规"),
				("GDPR", "第32条安全措施/第25条数据保护设计", flag2 ? "敏感端口暴露，数据保护措施不足" : "数据保护措施基本到位", flag2 ? "不合规" : "部分合规"),
				("PCI DSS", "Requirement 6安全系统/Requirement 1防火墙", flag ? "系统安全维护不达标" : "系统安全维护基本达标", flag ? "不合规" : "部分合规"),
				("CIS Controls", "CIS 3数据保护/CIS 7漏洞管理/CIS 9网络监控", flag ? "漏洞管理和网络监控存在不足" : "基本满足CIS控制要求", flag ? "部分合规" : "基本合规")
			};
		}

		private static List<(string, string, string, string, string)> BuildComplianceGaps(List<VulnerabilityResult> vulns, List<PortScanResult> openPorts)
		{
			List<(string, string, string, string, string)> list = new List<(string, string, string, string, string)>();
			List<VulnerabilityResult> list2 = vulns.Where((VulnerabilityResult v) => IsCritical((v != null) ? v.RiskLevel : null) || IsHigh((v != null) ? v.RiskLevel : null)).ToList();
			HashSet<int> hashSet = openPorts.Select((PortScanResult p) => (p != null) ? p.PortNumber : 0).ToHashSet();
			if (list2.Any())
			{
				list.Add(("高危漏洞未修复", "等保2.0/ISO 27001/PCI DSS", $"存在{list2.Count}个高危漏洞未修复", "高", "立即制定漏洞修复计划，优先处理严重和高危漏洞"));
			}
			if (hashSet.Contains(445) || hashSet.Contains(135))
			{
				list.Add(("高危端口暴露", "等保2.0/CIS Controls", "SMB/RPC高危端口对外暴露", "高", "关闭不必要的端口，配置防火墙规则限制访问"));
			}
			if (hashSet.Contains(3389))
			{
				list.Add(("远程桌面暴露", "等保2.0/CIS Controls", "RDP端口对外暴露，存在暴力破解风险", "高", "限制RDP访问来源，启用网络级别认证(NLA)"));
			}
			if (hashSet.Contains(3306) || hashSet.Contains(1433) || hashSet.Contains(5432))
			{
