		private static int CalculateSecurityScore(List<VulnerabilityResult> vulns, List<PortScanResult> openPorts)
		{
			int num = 100;
			int num2 = vulns.Count((VulnerabilityResult v) => IsCritical((v != null) ? v.RiskLevel : null));
			int num3 = vulns.Count((VulnerabilityResult v) => IsHigh((v != null) ? v.RiskLevel : null));
			int num4 = vulns.Count((VulnerabilityResult v) => IsMedium((v != null) ? v.RiskLevel : null));
			int num5 = vulns.Count((VulnerabilityResult v) => IsLow((v != null) ? v.RiskLevel : null));
			num -= num2 * 15;
			num -= num3 * 8;
			num -= num4 * 3;
			num -= num5;
			HashSet<int> hashSet = openPorts.Select((PortScanResult p) => (p != null) ? p.PortNumber : 0).ToHashSet();
			if (hashSet.Contains(445) || hashSet.Contains(135))
			{
				num -= 10;
			}
			if (hashSet.Contains(3389))
			{
				num -= 8;
			}
			if (hashSet.Contains(23))
			{
				num -= 10;
			}
			if (hashSet.Contains(3306) || hashSet.Contains(1433) || hashSet.Contains(5432))
			{
				num -= 5;
			}
			if (openPorts.Count > 20)
			{
				num -= 5;
			}
			else if (openPorts.Count > 10)
			{
				num -= 3;
			}
			return Math.Max(0, Math.Min(100, num));
		}

		private static string GetSecurityRatingDescription(int score)
		{
			if (score >= 90)
			{
				return "系统安全状况优秀，仅存在少量低风险问题，建议持续保持安全监控。";
			}
			if (score >= 75)
			{
				return "系统安全状况良好，存在部分中等风险问题，建议按计划进行安全加固。";
			}
			if (score >= 60)
			{
				return "系统安全状况一般，存在多个安全风险，建议尽快制定并执行安全改进计划。";
			}
			if (score >= 40)
			{
				return "系统安全状况较差，存在高危安全风险，建议立即采取紧急修复措施。";
			}
			return "系统安全状况严重，存在严重安全漏洞和重大风险，建议立即启动应急响应。";
		}

		private static List<string> BuildCoreConclusions(List<VulnerabilityResult> vulns, List<PortScanResult> openPorts)
		{
			List<string> list = new List<string>();
			List<VulnerabilityResult> list2 = vulns.Where((VulnerabilityResult v) => IsCritical((v != null) ? v.RiskLevel : null) || IsHigh((v != null) ? v.RiskLevel : null)).ToList();
			HashSet<int> hashSet = openPorts.Select((PortScanResult p) => (p != null) ? p.PortNumber : 0).ToHashSet();
			if (vulns.Any((VulnerabilityResult v) => IsCritical((v != null) ? v.RiskLevel : null)))
			{
				list.Add($"本次扫描发现{vulns.Count((VulnerabilityResult v) => IsCritical(v.RiskLevel))}个严重漏洞，存在被远程攻击的高风险，攻击者可利用这些漏洞获取系统控制权。");
			}
			if (list2.Any())
			{
				list.Add($"共发现{list2.Count}个高危漏洞，涉及多个服务端口，需优先处理以降低被攻击风险。");
			}
			if (hashSet.Contains(445) || hashSet.Contains(135) || hashSet.Contains(3389))
			{
				list.Add("系统暴露了SMB/RPC/RDP等高危端口，这些端口是勒索软件和蠕虫病毒的主要传播通道。");
			}
			if (hashSet.Contains(3306) || hashSet.Contains(1433) || hashSet.Contains(5432) || hashSet.Contains(6379))
			{
				list.Add("数据库或缓存服务端口对外暴露，存在数据泄露和未授权访问风险。");
			}
			if (openPorts.Count > 15)
			{
				list.Add($"开放端口数量较多（{openPorts.Count}个），攻击面较大，建议关闭不必要的端口和服务。");
			}
			list.Add("建议建立常态化安全扫描机制，定期评估系统安全状况，及时发现和修复新增安全风险。");
			if (!vulns.Any())
			{
				list.Insert(0, "本次扫描未发现安全漏洞，系统安全状况良好，建议持续保持安全监控。");
			}
			return list;
		}

