		private static void GenerateCveAppendix(DocX doc, List<VulnerabilityResult> vulns)
		{
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			//IL_006f: Unknown result type (might be due to invalid IL or missing references)
			//IL_05dd: Unknown result type (might be due to invalid IL or missing references)
			//IL_03c9: Unknown result type (might be due to invalid IL or missing references)
			//IL_048b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0579: Unknown result type (might be due to invalid IL or missing references)
			Paragraph obj = ((Container)doc).InsertParagraph("附录一、CVE漏洞参考信息");
			obj.FontSize(16.0).Bold(true);
			obj.Color(DeepBlue);
			obj.SpacingBefore(15.0);
			obj.SpacingAfter(4.0);
			Paragraph obj2 = ((Container)doc).InsertParagraph(new string('─', 50));
			obj2.FontSize(7.0);
			obj2.Color(AccentBlue);
			obj2.SpacingAfter(12.0);
			List<VulnerabilityResult> list = vulns ?? new List<VulnerabilityResult>();
			if (!list.Any())
			{
				Paragraph obj3 = ((Container)doc).InsertParagraph("本次扫描未检测到任何CVE漏洞，无参考信息可供列出。");
				obj3.Alignment = (Alignment)1;
				obj3.SpacingAfter(15.0);
				return;
			}
			List<VulnerabilityResult> list2 = (from v in list
				where !string.IsNullOrWhiteSpace((v != null) ? v.CveId : null) && v.CveId.StartsWith("CVE-", StringComparison.OrdinalIgnoreCase)
				group v by v.CveId?.ToUpper() into g
				select g.First() into v
				orderby GetRiskPriority((v != null) ? v.RiskLevel : null) descending
				select v).ToList();
			if (!list2.Any())
			{
				Paragraph obj4 = ((Container)doc).InsertParagraph($"检测到{list.Count}个漏洞，但均未关联标准CVE编号。");
				obj4.FontSize(10.0);
				obj4.SpacingAfter(10.0);
				return;
			}
			Paragraph obj5 = ((Container)doc).InsertParagraph($"本次扫描共关联{list2.Count}个唯一CVE编号，按风险等级从高到低排列如下。每个CVE均可在NVD（National Vulnerability Database）查询详细信息。");
			obj5.FontSize(10.0);
			obj5.SpacingBefore(8.0);
			obj5.SpacingAfter(14.0);
			Table val = ((Document)doc).AddTable(list2.Count + 1, 6);
			val.Design = (TableDesign)2;
			val.Alignment = (Alignment)1;
			string[] headers = new string[6] { "CVE编号", "漏洞名称", "风险等级", "CVSS估算", "影响服务", "NVD链接" };
			StyleTableHeader(val, headers);
			int num = 1;
			foreach (VulnerabilityResult item in list2)
			{
				((Container)val.Rows[num].Cells[0]).Paragraphs[0].Append(item.CveId.ToUpper()).FontSize(9.0).Bold(true);
				((Container)val.Rows[num].Cells[0]).Paragraphs[0].Alignment = (Alignment)1;
				string text = item.Name ?? "-";
				((Container)val.Rows[num].Cells[1]).Paragraphs[0].Append((text.Length > 50) ? (text.Substring(0, 47) + "...") : text).FontSize(9.0);
				string text2 = item.RiskLevel ?? "未分类";
				((Container)val.Rows[num].Cells[2]).Paragraphs[0].Append(text2).FontSize(9.0).Bold(true)
					.Color(GetRiskColor(text2));
				((Container)val.Rows[num].Cells[2]).Paragraphs[0].Alignment = (Alignment)1;
				double value = EstimateCvssScore(item.RiskLevel);
				((Container)val.Rows[num].Cells[3]).Paragraphs[0].Append($"{value:F1}").FontSize(9.0).Bold(true);
				((Container)val.Rows[num].Cells[3]).Paragraphs[0].Color(GetRiskColor(text2));
				((Container)val.Rows[num].Cells[3]).Paragraphs[0].Alignment = (Alignment)1;
				string text3 = item.Service ?? "-";
				((Container)val.Rows[num].Cells[4]).Paragraphs[0].Append(text3).FontSize(9.0);
				string text4 = "https://nvd.nist.gov/vuln/detail/" + item.CveId;
				((Container)val.Rows[num].Cells[5]).Paragraphs[0].Append(text4).FontSize(7.0);
				((Container)val.Rows[num].Cells[5]).Paragraphs[0].Color(AccentBlue);
				num++;
			}
			ApplyTableRowShading(val);
			((Container)doc).InsertParagraph().SpacingAfter(22.0);
			Paragraph obj6 = ((Container)doc).InsertParagraph("注：CVSS评分为基于漏洞风险等级的估算值，实际评分请参考NVD官方数据库。NVD链接为静态参考URL，请粘贴至浏览器访问。");
			obj6.FontSize(9.0);
			obj6.Color(MidGray);
		}

		private static string GetSafeString(string value)
		{
			if (!string.IsNullOrWhiteSpace(value))
			{
				return value;
			}
			return "-";
		}

		private static double EstimateCvssScore(string riskLevel)
		{
			if (string.IsNullOrEmpty(riskLevel))
			{
				return 0.0;
			}
			if (IsCritical(riskLevel))
			{
				return 9.5;
			}
			if (IsHigh(riskLevel))
			{
				return 7.5;
			}
			if (IsMedium(riskLevel))
			{
				return 5.5;
			}
			if (IsLow(riskLevel))
			{
				return 3.0;
			}
			return 1.0;
		}

		private static int GetRiskPriority(string riskLevel)
		{
			if (string.IsNullOrWhiteSpace(riskLevel))
			{
				return 0;
			}
			if (IsCritical(riskLevel))
			{
				return 5;
			}
			if (IsHigh(riskLevel))
			{
				return 4;
			}
			if (IsMedium(riskLevel))
			{
				return 3;
			}
			if (IsLow(riskLevel))
			{
				return 2;
			}
			return 1;
		}

		private static string CalculateOverallRiskLevel(List<VulnerabilityResult> vulnerabilities)
		{
			if (vulnerabilities == null || !vulnerabilities.Any())
			{
				return "信息";
			}
			try
			{
				if (vulnerabilities.Any((VulnerabilityResult v) => IsCritical((v != null) ? v.RiskLevel : null)))
				{
					return "严重";
				}
				if (vulnerabilities.Any((VulnerabilityResult v) => IsHigh((v != null) ? v.RiskLevel : null)))
				{
					return "高";
				}
				if (vulnerabilities.Any((VulnerabilityResult v) => IsMedium((v != null) ? v.RiskLevel : null)))
				{
					return "中";
				}
				return "低";
			}
			catch (Exception)
			{
				return "信息";
			}
		}

		private static bool IsCritical(string riskLevel)
		{
			if (string.IsNullOrWhiteSpace(riskLevel))
			{
				return false;
			}
			string text = riskLevel.Trim().ToLower();
			if (!text.Contains("严重"))
			{
				return text == "critical";
			}
			return true;
		}

		private static bool IsHigh(string riskLevel)
		{
			if (string.IsNullOrWhiteSpace(riskLevel))
			{
				return false;
			}
			string text = riskLevel.Trim().ToLower();
			if (!text.Contains("高") || text.Contains("严重"))
			{
				return text == "high";
			}
			return true;
		}

		private static bool IsMedium(string riskLevel)
		{
			if (string.IsNullOrWhiteSpace(riskLevel))
			{
				return false;
			}
			string text = riskLevel.Trim().ToLower();
			if (!text.Contains("中"))
			{
				return text == "medium";
			}
			return true;
		}

		private static bool IsLow(string riskLevel)
		{
			if (string.IsNullOrWhiteSpace(riskLevel))
			{
				return false;
			}
			string text = riskLevel.Trim().ToLower();
			if (!text.Contains("低"))
			{
				return text == "low";
			}
			return true;
		}

		private static Color GetRiskColor(string riskLevel)
		{
			//IL_0008: Unknown result type (might be due to invalid IL or missing references)
			//IL_0034: Unknown result type (might be due to invalid IL or missing references)
			//IL_0061: Unknown result type (might be due to invalid IL or missing references)
			//IL_0081: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a1: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a7: Unknown result type (might be due to invalid IL or missing references)
			if (string.IsNullOrWhiteSpace(riskLevel))
			{
				return Color.Gray;
			}
			string text = riskLevel.Trim().ToLower();
			if (text.Contains("严重") || text == "critical")
			{
				return Color.Red;
			}
			if ((text.Contains("高") && !text.Contains("严重")) || text == "high")
			{
				return Color.OrangeRed;
			}
			if (text.Contains("中") || text == "medium")
			{
				return Color.Orange;
			}
			if (text.Contains("低") || text == "low")
			{
				return Color.Green;
			}
			return Color.Gray;
		}

		private static Color GetComplianceColor(string complianceLevel)
		{
			//IL_0008: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			//IL_0035: Unknown result type (might be due to invalid IL or missing references)
			//IL_0048: Unknown result type (might be due to invalid IL or missing references)
			//IL_0061: Unknown result type (might be due to invalid IL or missing references)
			//IL_005b: Unknown result type (might be due to invalid IL or missing references)
			if (string.IsNullOrWhiteSpace(complianceLevel))
			{
				return Color.Gray;
			}
			string text = complianceLevel.Trim();
			if (text.Contains("不合规"))
			{
				return Color.Red;
			}
			if (text.Contains("部分合规"))
			{
				return Color.Orange;
			}
			if (text.Contains("基本合规"))
			{
				return Color.YellowGreen;
			}
			if (text.Contains("完全合规"))
			{
				return Color.Green;
			}
			return Color.Gray;
		}

		private static string BuildScanTypesString(List<CompleteScanResult> records)
		{
			if (records == null || !records.Any())
			{
				return "综合扫描";
			}
			List<string> list = (from r in records
				select (r == null) ? null : r.ScanType into s
				where !string.IsNullOrWhiteSpace(s)
				select s).Distinct().ToList();
			if (!list.Any())
			{
				return "综合扫描";
			}
			List<string> list2 = new List<string>();
			foreach (string item in list)
			{
				if (item.Contains("专家模式"))
				{
					list2.Add("专家模式");
				}
				else if (item.Contains("漏洞"))
				{
					list2.Add("漏洞扫描");
				}
				else if (item.Contains("TCP"))
				{
					list2.Add("TCP端口扫描");
				}
				else if (item.Contains("UDP"))
				{
					list2.Add("UDP端口扫描");
				}
				else
				{
					list2.Add(item);
				}
			}
			List<string> values = list2.Distinct().ToList();
			return string.Join(" + ", values);
		}
	}
