				if (int.TryParse(ConcurrencyTextBox.Text, out var result) && int.TryParse(TimeoutTextBox.Text, out var result2))
				{
					TimeSpan timeSpan = ScanPresetRegistry.EstimateDuration(num, result, result2);
					PreviewDurationText.Text = $"预计耗时 ~{(int)timeSpan.TotalSeconds} 秒";
				}
			}
			catch
			{
				PreviewPortCountText.Text = "0 个端口";
				PreviewDurationText.Text = "预计耗时 --";
			}
		}

		private async Task LoadLastHistoryAsync()
		{
			try
			{
				string target = TargetIpTextBox.Text?.Trim() ?? "";
				if (string.IsNullOrEmpty(target))
				{
					LastHistoryText.Text = "（暂无历史）";
					return;
				}
				ScanHistoryItem val = (from h in (await _db.GetScanHistoryAsync())?.Where((ScanHistoryItem h) => string.Equals(h.TargetIp, target, StringComparison.OrdinalIgnoreCase))
					orderby h.ScanTime descending
					select h).FirstOrDefault();
				if (val == null)
				{
					LastHistoryText.Text = "（暂无历史）";
					return;
				}
				LastHistoryText.Text = $"{val.ScanTime:yyyy-MM-dd HH:mm}\n开放端口 {val.OpenPortsCount} / 漏洞 {val.VulnerabilitiesCount} / 风险 {val.RiskLevel}";
			}
			catch
			{
				LastHistoryText.Text = "（暂无历史）";
			}
		}

		private void StartButton_Click(object sender, RoutedEventArgs e)
		{
			//IL_007a: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a1: Invalid comparison between Unknown and I4
			ClearError(IpErrorTextBlock);
			ClearError(PortErrorTextBlock);
			ClearError(ProtocolErrorTextBlock);
			string text = TargetIpTextBox.Text?.Trim() ?? "";
			if (string.IsNullOrEmpty(text))
			{
				ShowError(IpErrorTextBlock, "请输入目标 IP 或域名");
				return;
			}
			if (!IsValidTarget(text))
			{
				ShowError(IpErrorTextBlock, "格式无效。请输入 IPv4（如 192.168.1.1）或域名（如 example.com）");
				return;
			}
			ScanPreset selectedPreset = GetSelectedPreset();
			string text2 = PortRangeTextBox.Text?.Trim() ?? "";
			if ((int)selectedPreset == 5)
			{
				if (string.IsNullOrEmpty(text2))
				{
					ShowError(PortErrorTextBlock, "Custom 模式必须填写端口");
					return;
				}
				try
				{
					ScanPresetRegistry.ParsePortList(text2);
				}
				catch (Exception ex)
				{
					ShowError(PortErrorTextBlock, ex.Message);
					return;
				}
			}
			if (TcpCheckBox.IsChecked != true && UdpCheckBox.IsChecked != true)
			{
				ShowError(ProtocolErrorTextBlock, "请至少选择一种协议（TCP / UDP）");
				return;
			}
			if (!int.TryParse(ConcurrencyTextBox.Text, out var result) || result < 1 || result > 1000)
			{
				System.Windows.MessageBox.Show("并发数必须是 1-1000 的整数", "参数无效", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			if (!int.TryParse(TimeoutTextBox.Text, out var result2) || result2 < 1 || result2 > 300)
			{
				System.Windows.MessageBox.Show("超时必须是 1-300 秒的整数", "参数无效", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			if (!int.TryParse(RetryTextBox.Text, out var result3) || result3 < 0 || result3 > 3)
			{
				System.Windows.MessageBox.Show("重试次数必须是 0-3 的整数", "参数无效", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			base.DialogResult = true;
			Close();
		}

		private static bool IsValidTarget(string target)
		{
			if (IPAddress.TryParse(target, out IPAddress _))
			{
				return true;
			}
			string pattern = "^[a-zA-Z0-9]([a-zA-Z0-9\\-]{0,61}[a-zA-Z0-9])?(\\.[a-zA-Z0-9]([a-zA-Z0-9\\-]{0,61}[a-zA-Z0-9])?)*\\.[a-zA-Z]{2,}$";
			return Regex.IsMatch(target, pattern);
		}

		public ComprehensiveScanOptions BuildOptions()
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			//IL_0040: Unknown result type (might be due to invalid IL or missing references)
