		private void ApplyRiskBadge(string level)
		{
			RiskBadgeText.Text = level ?? "无风险";
			Border riskBadge = RiskBadge;
			riskBadge.Background = (level ?? "") switch
			{
				"严重风险" => new SolidColorBrush(System.Windows.Media.Color.FromRgb(192, 57, 43)), 
				"高风险" => new SolidColorBrush(System.Windows.Media.Color.FromRgb(231, 76, 60)), 
				"中风险" => new SolidColorBrush(System.Windows.Media.Color.FromRgb(243, 156, 18)), 
				"低风险" => new SolidColorBrush(System.Windows.Media.Color.FromRgb(241, 196, 15)), 
				_ => new SolidColorBrush(System.Windows.Media.Color.FromRgb(39, 174, 96)), 
			};
		}

		private void BuildOverview()
		{
			//IL_028f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0294: Unknown result type (might be due to invalid IL or missing references)
			//IL_0296: Unknown result type (might be due to invalid IL or missing references)
			//IL_0299: Unknown result type (might be due to invalid IL or missing references)
			//IL_02af: Expected I4, but got Unknown
			OverviewPanel.Children.Clear();
			Border border = BuildSectionBorder("\ud83d\udccb 扫描摘要");
			StackPanel stackPanel = new StackPanel();
			AddKvRow(stackPanel, "目标", _result.TargetIp);
			AddKvRow(stackPanel, "扫描类型", _result.ScanType);
			AddKvRow(stackPanel, "扫描时间", _result.ScanTime.ToString("yyyy-MM-dd HH:mm:ss"));
			AddKvRow(stackPanel, "总耗时", $"{_result.ScanDurationSeconds:F1} 秒");
			AddKvRow(stackPanel, "主机存活", _result.HostAlive ? "✅ 是" : "❌ 否（结果可能不完整）");
			AddKvRow(stackPanel, "开放端口", $"{_result.OpenPortsCount}（TCP {_result.TcpOpenPorts} / UDP {_result.UdpOpenPorts}）");
			AddKvRow(stackPanel, "漏洞总数", $"{_result.VulnerabilitiesCount}（漏洞扫描 {_result.VulnerabilityResults.Count} / 插件扫描 {_result.PluginResults.Count}）");
			AddKvRow(stackPanel, "风险等级", _result.RiskLevel);
			if (_result.HasVulnerabilityScanError)
			{
				AddKvRow(stackPanel, "⚠ 异常", "漏洞扫描阶段出现异常");
			}
			if (_result.HasPluginScanError)
			{
				AddKvRow(stackPanel, "⚠ 异常", "插件扫描阶段出现异常");
			}
			if (_result.Cancelled)
			{
				AddKvRow(stackPanel, "⛔ 状态", "扫描已被用户取消");
			}
			border.Child = stackPanel;
			OverviewPanel.Children.Add(border);
			Border border2 = BuildSectionBorder("⏱ 阶段时间线");
			StackPanel stackPanel2 = new StackPanel();
			foreach (ScanPhaseExecution phase in _result.Phases)
			{
				ScanPhaseStatus status = phase.Status;
				string value = (status - 1) switch
				{
					1 => "✅", 
					2 => "❌", 
					3 => "⏭", 
					0 => "\ud83d\udd04", 
					_ => "⏳", 
				};
				TextBlock element = new TextBlock
				{
					Text = $"{value} {phase.PhaseName}  -  {phase.DurationMs} ms  {(string.IsNullOrEmpty(phase.ErrorMessage) ? "" : ("  (" + phase.ErrorMessage + ")"))}",
					FontSize = 12.0,
					Margin = new Thickness(0.0, 2.0, 0.0, 2.0)
				};
				stackPanel2.Children.Add(element);
			}
			border2.Child = stackPanel2;
			OverviewPanel.Children.Add(border2);
		}

		private Border BuildSectionBorder(string title)
		{
			return new Border
			{
				BorderBrush = new SolidColorBrush(System.Windows.Media.Color.FromRgb(221, 225, 231)),
				BorderThickness = new Thickness(1.0),
				CornerRadius = new CornerRadius(6.0),
				Padding = new Thickness(12.0),
				Margin = new Thickness(0.0, 0.0, 0.0, 10.0),
				Background = System.Windows.Media.Brushes.White,
				Child = new TextBlock
				{
					Text = title,
					FontWeight = FontWeights.Bold,
					FontSize = 13.0,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(44, 62, 80)),
					Margin = new Thickness(0.0, 0.0, 0.0, 6.0)
				}
			};
		}

		private void AddKvRow(StackPanel parent, string key, string value)
		{
			StackPanel stackPanel = new StackPanel
			{
				Orientation = System.Windows.Controls.Orientation.Horizontal,
				Margin = new Thickness(0.0, 2.0, 0.0, 2.0)
			};
			stackPanel.Children.Add(new TextBlock
			{
				Text = key + ":",
				FontWeight = FontWeights.SemiBold,
				Width = 100.0,
				Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(127, 140, 141)),
				FontSize = 12.0
			});
			stackPanel.Children.Add(new TextBlock
			{
				Text = (value ?? "-"),
				FontSize = 12.0,
				TextWrapping = TextWrapping.Wrap
			});
			parent.Children.Add(stackPanel);
		}

		private void LoadPorts()
		{
			List<PortScanResult> itemsSource = (from p in _result.AllPortResults?.Where((PortScanResult p) => p.Status == "开放" || p.Status == "开放或过滤")
				orderby p.PortNumber
				select p).ToList() ?? new List<PortScanResult>();
			PortsDataGrid.ItemsSource = itemsSource;
		}

		private void LoadVulns()
		{
			_allVulns = _result.VulnerabilityResults?.ToList() ?? new List<VulnerabilityResult>();
			_allPlugins = _result.PluginResults?.ToList() ?? new List<VulnerabilityResult>();
			VulnCountText.Text = $"共 {_allVulns.Count} 个";
			VulnsDataGrid.ItemsSource = _allVulns;
		}

		private void VulnFilterCombo_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			if (!base.IsLoaded)
			{
				return;
			}
			string tag = (VulnFilterCombo.SelectedItem as ComboBoxItem)?.Tag?.ToString() ?? "";
			IEnumerable<VulnerabilityResult> source = _allVulns;
			if (!string.IsNullOrEmpty(tag))
			{
				source = source.Where((VulnerabilityResult v) => (v.RiskLevel ?? "").Contains(tag));
			}
			List<VulnerabilityResult> list = source.ToList();
			VulnsDataGrid.ItemsSource = list;
			VulnCountText.Text = $"共 {list.Count} 个（已按 {tag} 筛选）";
		}

		private void LoadServices()
		{
			var itemsSource = (from p in _result.AllPortResults?.Where((PortScanResult p) => p.Status == "开放" || p.Status == "开放或过滤").ToList() ?? new List<PortScanResult>()
				group p by (!string.IsNullOrEmpty(p.Service)) ? p.Service : "未知" into g
				select new
				{
					Service = g.Key,
					Count = g.Count(),
					Ports = string.Join(", ", from p in g
						select p.PortNumber into n
						orderby n
						select n),
					Versions = string.Join("; ", (from p in g
						select p.ServiceVersion into v
						where !string.IsNullOrEmpty(v)
						select v).Distinct())
				} into s
				orderby s.Count descending
				select s).ToList();
			ServicesDataGrid.ItemsSource = itemsSource;
		}

		private void LoadPlugins()
		{
			PluginsDataGrid.ItemsSource = _allPlugins;
		}

		private async void ExportJsonButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				Microsoft.Win32.SaveFileDialog dlg = new Microsoft.Win32.SaveFileDialog
				{
					Filter = "JSON 文件|*.json",
					FileName = $"综合扫描_{_result.TargetIp}_{DateTime.Now:yyyyMMdd_HHmmss}.json",
					Title = "导出综合扫描结果（JSON）"
				};
				if (dlg.ShowDialog() == true)
				{
					ExportOptions val = new ExportOptions
					{
						Title = "综合扫描结果 - " + _result.TargetIp,
						TotalTargets = 1,
						TotalOpenPorts = _result.OpenPortsCount,
						TotalVulnerabilities = _result.VulnerabilitiesCount
					};
					string contents = _exportService.ExportToJson((IEnumerable<PortScanResult>)_result.AllPortResults, (IEnumerable<VulnerabilityResult>)_result.VulnerabilityResults, val);
					await File.WriteAllTextAsync(dlg.FileName, contents);
					System.Windows.MessageBox.Show("已导出到:\n" + dlg.FileName, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出 JSON 失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

