		private void QueryTextBox_KeyDown(object sender, System.Windows.Input.KeyEventArgs e)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0007: Invalid comparison between Unknown and I4
			if ((int)e.Key == 6)
			{
				Query_Click(sender, e);
			}
		}

		private async void Query_Click(object sender, RoutedEventArgs e)
		{
			string query = QueryTextBox.Text.Trim();
			if (string.IsNullOrEmpty(query))
			{
				System.Windows.MessageBox.Show("请输入域名或IP地址（多个用逗号或换行分隔）", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			ShowLoading(show: true, "正在查询中...");
			StatusText.Text = "正在查询...";
			try
			{
				List<string> list = ParseQueries(query);
				List<DnsResult> results = new List<DnsResult>();
				int index = 1;
				DateTime totalStart = DateTime.Now;
				foreach (string q in list)
				{
					Stopwatch stopwatch = Stopwatch.StartNew();
					try
					{
						if (IsIpAddress(q))
						{
							results.Add(new DnsResult
							{
								Index = index++,
								Source = q,
								IpAddress = q,
								AddressType = GetIpType(q),
								AddressFamily = GetAddressFamily(q),
								DurationMs = (int)stopwatch.ElapsedMilliseconds,
								Status = "✓ 成功"
							});
						}
						else
						{
							IPAddress[] array = await Dns.GetHostAddressesAsync(q);
							bool flag = true;
							IPAddress[] array2 = array;
							foreach (IPAddress iPAddress in array2)
							{
								results.Add(new DnsResult
								{
									Index = (flag ? index : 0),
									Source = (flag ? q : ""),
									IpAddress = iPAddress.ToString(),
									AddressType = GetIpType(iPAddress.ToString()),
									AddressFamily = GetAddressFamily(iPAddress.ToString()),
									DurationMs = (int)stopwatch.ElapsedMilliseconds,
									Status = "✓ 成功"
								});
								flag = false;
							}
							if (!array.Any())
							{
								results.Add(new DnsResult
								{
									Index = index++,
									Source = q,
									IpAddress = "-",
									DurationMs = (int)stopwatch.ElapsedMilliseconds,
									Status = "✗ 无结果"
								});
							}
							else
							{
								index++;
							}
						}
						if (IpLocationCheckBox.IsChecked != true)
						{
							continue;
						}
						DnsResult dnsResult = results.LastOrDefault((DnsResult r) => r.Source == q);
						if (dnsResult != null)
						{
							string ipAddress = dnsResult.IpAddress;
							if (IsIpAddress(ipAddress) && !ipAddress.StartsWith("127."))
							{
								await QueryIpInfoAsync(ipAddress);
							}
						}
					}
					catch (Exception ex)
					{
						results.Add(new DnsResult
						{
							Index = index++,
							Source = q,
							IpAddress = "-",
							DurationMs = (int)stopwatch.ElapsedMilliseconds,
							Status = "✗ 失败: " + ex.Message.Substring(0, Math.Min(20, ex.Message.Length))
						});
					}
				}
				int value = (int)(DateTime.Now - totalStart).TotalMilliseconds;
				DnsResultsGrid.ItemsSource = results;
				DnsCountText.Text = results.Count.ToString();
				DnsDurationText.Text = value.ToString();
				_currentDnsResults.Clear();
				_currentDnsResults.AddRange(results);
				AddHistory(query, "DNS解析", $"共解析 {results.Count} 条结果，耗时 {value}ms");
				if (ReverseDnsCheckBox.IsChecked == true && results.Any())
				{
					await PerformReverseDnsAsync(results);
				}
				if (PingTestCheckBox.IsChecked == true && results.Any())
				{
					DnsResult dnsResult2 = results.FirstOrDefault((DnsResult r) => IsIpAddress(r.IpAddress) && !r.IpAddress.StartsWith("127."));
					if (dnsResult2 != null)
					{
						ResultTabs.SelectedIndex = 3;
						await PerformPingAsync(dnsResult2.IpAddress, 4);
					}
				}
				if (results.Count == 1 && IsIpAddress(results[0].IpAddress))
				{
					await QueryIpInfoAsync(results[0].IpAddress);
				}
				StatusText.Text = $"✓ 查询完成，共 {results.Count} 条结果";
			}
			catch (Exception ex2)
			{
				StatusText.Text = "✗ 查询失败: " + ex2.Message;
				System.Windows.MessageBox.Show("查询失败: " + ex2.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			finally
			{
				ShowLoading(show: false);
			}
		}

		private async void Ping_Click(object sender, RoutedEventArgs e)
		{
			string target = QueryTextBox.Text.Trim();
			if (string.IsNullOrEmpty(target))
			{
				System.Windows.MessageBox.Show("请输入要Ping的目标", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			try
			{
				if (!IsIpAddress(target))
				{
					target = (await Dns.GetHostAddressesAsync(target)).FirstOrDefault()?.ToString() ?? target;
				}
			}
			catch
			{
			}
			ResultTabs.SelectedIndex = 3;
			await PerformPingAsync(target, 4);
		}

		private async Task PerformPingAsync(string target, int count)
		{
			ShowLoading(show: true, "正在Ping " + target + "...");
			StatusText.Text = "正在Ping " + target + "...";
			try
			{
				PingTargetText.Text = target;
				List<PingResult> results = new List<PingResult>();
				List<long> rtts = new List<long>();
				int lost = 0;
				using Ping ping = new Ping();
				for (int i = 1; i <= count; i++)
				{
					try
					{
						PingReply pingReply = await ping.SendPingAsync(target, 3000);
						PingResult item = new PingResult
						{
							Index = i,
							Bytes = 32,
							Address = (pingReply.Address?.ToString() ?? target),
							Sequence = $"{i} TTL={pingReply.Options?.Ttl ?? 0}",
							RttMs = pingReply.RoundtripTime,
							Status = ((pingReply.Status == IPStatus.Success) ? "✓ 成功" : $"✗ {pingReply.Status}")
						};
						results.Add(item);
						if (pingReply.Status == IPStatus.Success)
						{
							rtts.Add(pingReply.RoundtripTime);
						}
						else
						{
							lost++;
						}
					}
					catch (Exception ex)
					{
						results.Add(new PingResult
						{
							Index = i,
							Bytes = 32,
							Address = target,
							Sequence = $"{i}",
							RttMs = -1L,
							Status = "✗ " + ex.Message.Substring(0, Math.Min(20, ex.Message.Length))
						});
						lost++;
					}
				}
				PingResultsGrid.ItemsSource = results;
				if (rtts.Any())
				{
					PingAvgText.Text = $"{rtts.Average():F0}";
				}
				else
				{
					PingAvgText.Text = "-";
				}
				PingLossText.Text = $"{(double)lost * 100.0 / (double)count:F0}%";
				AddHistory(target, "Ping测试", $"发送{count}次，丢包{lost}次，平均延迟{(rtts.Any() ? rtts.Average().ToString("F0") : "-")}ms");
				StatusText.Text = $"✓ Ping完成，{count}次，丢包{lost}次";
			}
			catch (Exception ex2)
			{
				StatusText.Text = "✗ Ping失败: " + ex2.Message;
				System.Windows.MessageBox.Show("Ping失败: " + ex2.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			finally
			{
				ShowLoading(show: false);
			}
		}

		private async void ScanIpRange_Click(object sender, RoutedEventArgs e)
		{
			string range = IpRangeTextBox.Text.Trim();
			if (string.IsNullOrEmpty(range))
			{
				System.Windows.MessageBox.Show("请输入IP段（如 192.168.1.0/24）", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			ShowLoading(show: true, "正在扫描IP段...");
			StatusText.Text = "正在扫描IP段...";
			try
			{
				List<string> ips = ParseIpRange(range);
				if (ips.Count > 1000 && System.Windows.MessageBox.Show($"IP段包含 {ips.Count} 个地址，扫描可能需要较长时间。\n是否继续？", "确认", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes)
				{
					return;
				}
				List<DnsResult> results = new List<DnsResult>();
				int index = 1;
				DateTime totalStart = DateTime.Now;
				foreach (string ip in ips)
				{
					Stopwatch.StartNew();
					try
					{
						using Ping ping = new Ping();
						PingReply reply = await ping.SendPingAsync(ip, 1000);
						if (reply.Status == IPStatus.Success)
						{
							try
							{
								IPHostEntry iPHostEntry = await Dns.GetHostEntryAsync(ip);
								results.Add(new DnsResult
								{
									Index = index++,
									Source = iPHostEntry.HostName,
									IpAddress = ip,
									AddressType = "IPv4",
									AddressFamily = "IPv4",
									DurationMs = (int)reply.RoundtripTime,
									Status = "✓ 在线"
								});
							}
							catch
							{
								results.Add(new DnsResult
								{
									Index = index++,
									Source = "-",
									IpAddress = ip,
									AddressType = "IPv4",
									AddressFamily = "IPv4",
									DurationMs = (int)reply.RoundtripTime,
									Status = "✓ 在线"
								});
							}
						}
					}
					catch
					{
					}
				}
				int value = (int)(DateTime.Now - totalStart).TotalMilliseconds;
				DnsResultsGrid.ItemsSource = results;
				DnsCountText.Text = results.Count.ToString();
				DnsDurationText.Text = value.ToString();
				_currentDnsResults.Clear();
				_currentDnsResults.AddRange(results);
				AddHistory(range, "IP段扫描", $"扫描{ips.Count}个地址，发现{results.Count}个在线，耗时{value}ms");
				StatusText.Text = $"✓ 扫描完成，{results.Count}/{ips.Count} 在线";
			}
			catch (Exception ex)
			{
				StatusText.Text = "✗ 扫描失败: " + ex.Message;
				System.Windows.MessageBox.Show("扫描失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			finally
			{
				ShowLoading(show: false);
			}
		}

		private async void BatchResolve_Click(object sender, RoutedEventArgs e)
		{
			BatchInputDialog batchInputDialog = new BatchInputDialog("批量解析", "请输入要批量解析的域名或IP（每行一个）：");
			if (batchInputDialog.ShowDialog() == true && !string.IsNullOrWhiteSpace(batchInputDialog.InputText))
			{
				QueryTextBox.Text = batchInputDialog.InputText;
				await Task.Delay(100);
				Query_Click(sender, e);
			}
		}

		private void ExportResults_Click(object sender, RoutedEventArgs e)
		{
			if (!_currentDnsResults.Any())
			{
				System.Windows.MessageBox.Show("没有可导出的结果", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Filter = "CSV文件 (*.csv)|*.csv|文本文件 (*.txt)|*.txt",
				FileName = $"IP查询结果_{DateTime.Now:yyyyMMdd_HHmmss}.csv"
			};
			if (saveFileDialog.ShowDialog() != true)
			{
				return;
			}
			try
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.AppendLine("序号,源,IP地址,类型,地址族,耗时(ms),状态");
				foreach (DnsResult currentDnsResult in _currentDnsResults)
				{
					StringBuilder stringBuilder2 = stringBuilder;
					StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(6, 7, stringBuilder2);
					handler.AppendFormatted(currentDnsResult.Index);
					handler.AppendLiteral(",");
					handler.AppendFormatted(currentDnsResult.Source);
					handler.AppendLiteral(",");
					handler.AppendFormatted(currentDnsResult.IpAddress);
					handler.AppendLiteral(",");
					handler.AppendFormatted(currentDnsResult.AddressType);
					handler.AppendLiteral(",");
					handler.AppendFormatted(currentDnsResult.AddressFamily);
					handler.AppendLiteral(",");
					handler.AppendFormatted(currentDnsResult.DurationMs);
					handler.AppendLiteral(",");
					handler.AppendFormatted(currentDnsResult.Status);
					stringBuilder2.AppendLine(ref handler);
				}
				File.WriteAllText(saveFileDialog.FileName, stringBuilder.ToString(), Encoding.UTF8);
				System.Windows.MessageBox.Show("结果已导出到: " + saveFileDialog.FileName, "成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				AddHistory(saveFileDialog.FileName, "导出结果", $"导出{_currentDnsResults.Count}条记录");
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

