		private List<string> ParseQueries(string input)
		{
			return (from s in input.Split(new char[5] { ',', '\n', '\r', ';', ' ' }, StringSplitOptions.RemoveEmptyEntries)
				select s.Trim() into s
				where !string.IsNullOrEmpty(s)
				select s).Distinct().ToList();
		}

		private List<string> ParseIpRange(string range)
		{
			List<string> list = new List<string>();
			try
			{
				if (range.Contains("/"))
				{
					string[] array = range.Split('/');
					if (array.Length == 2 && int.TryParse(array[1], out var result))
					{
						if (!IPAddress.TryParse(array[0], out IPAddress address))
						{
							throw new ArgumentException("无效的IP地址");
						}
						byte[] addressBytes = address.GetAddressBytes();
						if (addressBytes.Length != 4)
						{
							throw new ArgumentException("仅支持IPv4网段");
						}
						int num = (addressBytes[0] << 24) | (addressBytes[1] << 16) | (addressBytes[2] << 8) | addressBytes[3];
						uint num2 = ((result != 0) ? ((uint)(-1 << 32 - result)) : 0u);
						int num3 = num & (int)num2;
						uint num4 = (uint)num3 | ~num2;
						for (uint num5 = (uint)num3; num5 <= num4; num5++)
						{
							if (list.Count >= 65536)
							{
								break;
							}
							list.Add($"{num5 >> 24}.{(num5 >> 16) & 0xFF}.{(num5 >> 8) & 0xFF}.{num5 & 0xFF}");
						}
					}
				}
				else if (range.Contains("-"))
				{
					string[] array2 = range.Split('-');
					if (array2.Length == 2 && IPAddress.TryParse(array2[0], out IPAddress address2) && IPAddress.TryParse(array2[1], out IPAddress address3))
					{
						byte[] addressBytes2 = address2.GetAddressBytes();
						byte[] addressBytes3 = address3.GetAddressBytes();
						int num6 = (addressBytes2[0] << 24) | (addressBytes2[1] << 16) | (addressBytes2[2] << 8) | addressBytes2[3];
						uint num7 = (uint)((addressBytes3[0] << 24) | (addressBytes3[1] << 16) | (addressBytes3[2] << 8) | addressBytes3[3]);
						for (uint num8 = (uint)num6; num8 <= num7; num8++)
						{
							if (list.Count >= 65536)
							{
								break;
							}
							list.Add($"{num8 >> 24}.{(num8 >> 16) & 0xFF}.{(num8 >> 8) & 0xFF}.{num8 & 0xFF}");
						}
					}
				}
				else
				{
					list.Add(range);
				}
			}
			catch (Exception ex)
			{
				throw new ArgumentException("解析IP段失败: " + ex.Message);
			}
			return list;
		}

		private async Task QueryIpInfoAsync(string ip)
		{
			try
			{
				IpInfoResult ipInfo = await _ipInfoService.GetIpInfoAsync(ip);
				if (IpLocationCheckBox.IsChecked == true)
				{
					ShowIpLocation(ipInfo);
				}
				if (IpDetailsCheckBox.IsChecked == true)
				{
					ShowIpDetails(ipInfo);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("IP信息查询失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Exclamation);
			}
		}

		private async Task PerformReverseDnsAsync(List<DnsResult> results)
		{
			foreach (DnsResult r in results.Where((DnsResult x) => IsIpAddress(x.IpAddress) && !x.IpAddress.StartsWith("127.")).Take(10))
			{
				try
				{
					r.Status = "✓ " + (await Dns.GetHostEntryAsync(r.IpAddress)).HostName;
				}
				catch
				{
				}
			}
			DnsResultsGrid.Items.Refresh();
		}

		private void ShowIpLocation(IpInfoResult ipInfo)
		{
			IpLocationPanel.Visibility = Visibility.Visible;
			LocationIpText.Text = ipInfo.Query;
			LocationCountryFlag.Text = GetCountryFlag(ipInfo.CountryCode);
			LocationCountryText.Text = ipInfo.Country + " (" + ipInfo.CountryCode + ")";
			LocationRegionText.Text = (string.IsNullOrEmpty(ipInfo.Region) ? "未知" : ipInfo.Region);
			LocationCityText.Text = (string.IsNullOrEmpty(ipInfo.City) ? "未知" : ipInfo.City);
			LocationZipText.Text = (string.IsNullOrEmpty(ipInfo.Zip) ? "未知" : ipInfo.Zip);
			LocationIspText.Text = (string.IsNullOrEmpty(ipInfo.Isp) ? "未知" : ipInfo.Isp);
			LocationCoordsText.Text = (string.IsNullOrEmpty(ipInfo.Latitude) ? "未知" : (ipInfo.Latitude + ", " + ipInfo.Longitude));
		}

