		public async Task<IpInfoResult> GetIpInfoAsync(string ip)
		{
			_ = 1;
			try
			{
				using HttpClient client = new HttpClient();
				client.Timeout = TimeSpan.FromSeconds(10.0);
				client.DefaultRequestHeaders.Add("User-Agent", "NetSecurityScanner/1.0");
				IpApiResponse ipApiResponse = JsonSerializer.Deserialize<IpApiResponse>(await client.GetStringAsync("http://ip-api.com/json/" + ip + "?lang=zh-CN"), new JsonSerializerOptions
				{
					PropertyNameCaseInsensitive = true
				});
				if (ipApiResponse != null && ipApiResponse.Status == "success")
				{
					IpInfoResult ipInfo = new IpInfoResult
					{
						Query = (ipApiResponse.Query ?? ip),
						Status = (ipApiResponse.Status ?? "fail"),
						Country = (ipApiResponse.Country ?? "未知"),
						CountryCode = (ipApiResponse.CountryCode ?? ""),
						Region = (ipApiResponse.RegionName ?? "未知"),
						RegionName = (ipApiResponse.RegionName ?? "未知"),
						RegionCode = (ipApiResponse.Region ?? ""),
						City = (ipApiResponse.City ?? "未知"),
						Zip = (ipApiResponse.Zip ?? ""),
						Latitude = (ipApiResponse.Lat?.ToString() ?? ""),
						Longitude = (ipApiResponse.Lon?.ToString() ?? ""),
						Timezone = (ipApiResponse.Timezone ?? "未知"),
						Isp = (ipApiResponse.Isp ?? "未知"),
						Org = (ipApiResponse.Org ?? "未知"),
						As = (ipApiResponse.As ?? "未知"),
						Proxy = (ipApiResponse.Proxy ?? "false"),
						Currency = GetCurrencyByCountry(ipApiResponse.CountryCode ?? ""),
						Language = GetLanguageByCountry(ipApiResponse.CountryCode ?? "")
					};
					try
					{
						ipInfo.Hostname = (await Dns.GetHostEntryAsync(ip)).HostName ?? "未知";
					}
					catch
					{
						ipInfo.Hostname = "未知";
					}
					return ipInfo;
				}
				return new IpInfoResult
				{
					Query = ip,
					Status = "fail"
				};
			}
			catch
			{
				return new IpInfoResult
				{
					Query = ip,
					Status = "error"
				};
			}
		}

		public async Task<string> GetWhoisAsync(string ip)
		{
			try
			{
				using HttpClient client = new HttpClient();
				client.Timeout = TimeSpan.FromSeconds(15.0);
				client.DefaultRequestHeaders.Add("User-Agent", "NetSecurityScanner/1.0");
				return FormatWhoisResponse(await client.GetStringAsync("https://whois.iana.org/?q=" + ip), ip);
			}
			catch (Exception ex)
			{
				return "Whois查询失败: " + ex.Message + "\n\n提示：Whois查询需要稳定的网络连接到 whois.iana.org\n您可以手动访问: https://whois.iana.org/ 查询 " + ip;
			}
		}

		private string FormatWhoisResponse(string raw, string ip)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("========== Whois 查询结果 ==========");
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder3 = stringBuilder2;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(6, 1, stringBuilder2);
			handler.AppendLiteral("查询目标: ");
			handler.AppendFormatted(ip);
			stringBuilder3.AppendLine(ref handler);
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder4 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(6, 1, stringBuilder2);
			handler.AppendLiteral("查询时间: ");
			handler.AppendFormatted(DateTime.Now, "yyyy-MM-dd HH:mm:ss");
			stringBuilder4.AppendLine(ref handler);
			stringBuilder.AppendLine("====================================");
			stringBuilder.AppendLine();
			string[] array = raw.Split('\n');
			int num = 0;
			string[] array2 = array;
			foreach (string text in array2)
			{
				if (num++ > 80)
				{
					break;
				}
				if (text.Contains(":"))
				{
					int num2 = text.IndexOf(':');
					if (num2 > 0 && num2 < 30)
					{
						stringBuilder2 = stringBuilder;
						StringBuilder stringBuilder5 = stringBuilder2;
						handler = new StringBuilder.AppendInterpolatedStringHandler(4, 2, stringBuilder2);
						handler.AppendLiteral("  ");
						handler.AppendFormatted<string>(text.Substring(0, num2).Trim(), -25);
						handler.AppendLiteral(": ");
						handler.AppendFormatted(text.Substring(num2 + 1).Trim());
						stringBuilder5.AppendLine(ref handler);
					}
					else
					{
						stringBuilder2 = stringBuilder;
						StringBuilder stringBuilder6 = stringBuilder2;
						handler = new StringBuilder.AppendInterpolatedStringHandler(2, 1, stringBuilder2);
						handler.AppendLiteral("  ");
						handler.AppendFormatted(text.Trim());
						stringBuilder6.AppendLine(ref handler);
					}
				}
				else
				{
					stringBuilder.AppendLine(text.Trim());
				}
			}
			return stringBuilder.ToString();
		}

