		private static bool SetClipboardTextWin32(string text, out Exception? lastError)
		{
			lastError = null;
			IntPtr intPtr = IntPtr.Zero;
			try
			{
				byte[] bytes = Encoding.Unicode.GetBytes(text + "\0");
				intPtr = GlobalAlloc(2u, (UIntPtr)(ulong)bytes.Length);
				if (intPtr == IntPtr.Zero)
				{
					lastError = new InvalidOperationException("GlobalAlloc 失败");
					return false;
				}
				IntPtr intPtr2 = GlobalLock(intPtr);
				if (intPtr2 == IntPtr.Zero)
				{
					lastError = new InvalidOperationException("GlobalLock 失败");
					return false;
				}
				Marshal.Copy(bytes, 0, intPtr2, bytes.Length);
				GlobalUnlock(intPtr);
				int[] array = new int[4] { 0, 30, 60, 120 };
				bool flag = false;
				int value = 0;
				for (int i = 0; i < array.Length; i++)
				{
					if (array[i] > 0)
					{
						Thread.Sleep(array[i]);
					}
					if (OpenClipboard(IntPtr.Zero))
					{
						flag = true;
						break;
					}
					value = Marshal.GetLastWin32Error();
				}
				if (!flag)
				{
					lastError = new InvalidOperationException($"OpenClipboard 失败 (Win32 错误码={value}, 0x{value:X})");
					return false;
				}
				try
				{
					EmptyClipboard();
					if (SetClipboardData(13u, intPtr) == IntPtr.Zero)
					{
						lastError = new InvalidOperationException($"SetClipboardData 失败 (Win32 错误码={Marshal.GetLastWin32Error()})");
						return false;
					}
					intPtr = IntPtr.Zero;
					return true;
				}
				finally
				{
					CloseClipboard();
				}
			}
			catch (Exception ex)
			{
				lastError = ex;
				return false;
			}
			finally
			{
				if (intPtr != IntPtr.Zero)
				{
					GlobalFree(intPtr);
				}
			}
		}

