				border.Background = new SolidColorBrush(System.Windows.Media.Color.FromRgb(52, 152, 219));
				border.BorderBrush = new SolidColorBrush(System.Windows.Media.Color.FromRgb(41, 128, 185));
			}
			else if (isDone)
			{
				border.Background = new SolidColorBrush(System.Windows.Media.Color.FromRgb(232, 248, 245));
				border.BorderBrush = new SolidColorBrush(System.Windows.Media.Color.FromRgb(39, 174, 96));
			}
			else
			{
				border.Background = new SolidColorBrush(System.Windows.Media.Color.FromRgb(236, 239, 241));
				border.BorderBrush = new SolidColorBrush(System.Windows.Media.Color.FromRgb(208, 215, 222));
			}
		}

		private void OnProgressReport(ScanPhaseProgress p)
		{
			ScanPhaseProgress p2 = p;
			if (!((DispatcherObject)this).Dispatcher.CheckAccess())
			{
				((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
				{
					OnProgressReport(p2);
				});
			}
			else
			{
				ApplyProgress(p2);
			}
		}

		private void ApplyProgress(ScanPhaseProgress p)
		{
			//IL_0002: Unknown result type (might be due to invalid IL or missing references)
			//IL_01a5: Unknown result type (might be due to invalid IL or missing references)
			_currentPhase = p.Phase;
			MainProgressBar.Value = p.Progress;
			PercentText.Text = $"{p.Progress}%";
			StatusText.Text = p.Message ?? string.Empty;
			SubProgressBar.Value = p.SubProgress;
			CurrentPhaseText.Text = "▶ " + p.PhaseName;
			CurrentItemText.Text = (string.IsNullOrEmpty(p.CurrentItem) ? "" : p.CurrentItem);
			TimeSpan timeSpan = TimeSpan.FromMilliseconds(p.ElapsedMs);
			ElapsedText.Text = $"已用 {(int)timeSpan.TotalMinutes}:{timeSpan.Seconds:D2}";
			if (p.EstimatedRemainingMs > 0)
			{
				TimeSpan timeSpan2 = TimeSpan.FromMilliseconds(p.EstimatedRemainingMs);
				RemainingText.Text = $"剩余 ~{(int)timeSpan2.TotalMinutes}:{timeSpan2.Seconds:D2}";
			}
			else
			{
				RemainingText.Text = "剩余 --:--";
			}
			UpdatePhaseStepper(p.Phase);
			if (p.DiscoveredPorts == null || p.DiscoveredPorts.Count <= 0)
			{
				return;
			}
			foreach (int discoveredPort in p.DiscoveredPorts)
			{
				if (!_allDiscoveredPorts.Contains(discoveredPort))
				{
					_allDiscoveredPorts.Add(discoveredPort);
				}
			}
			RefreshPortList();
		}

		private void UpdatePhaseStepper(ScanPhase current)
		{
			//IL_0013: Unknown result type (might be due to invalid IL or missing references)
			//IL_003f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0041: Unknown result type (might be due to invalid IL or missing references)
			//IL_0045: Unknown result type (might be due to invalid IL or missing references)
			//IL_004b: Unknown result type (might be due to invalid IL or missing references)
			//IL_004c: Unknown result type (might be due to invalid IL or missing references)
			//IL_009d: Unknown result type (might be due to invalid IL or missing references)
			ScanPhase[] array = new ScanPhase[6];
			RuntimeHelpers.InitializeArray(array, (RuntimeFieldHandle)/*OpCode not supported: LdMemberToken*/);
			ScanPhase[] array2 = (ScanPhase[])(object)array;
			int num = Array.IndexOf(array2, current);
			foreach (KeyValuePair<ScanPhase, Border> item2 in _phaseChipMap)
			{
				item2.Deconstruct(out var key, out var value);
				ScanPhase val = key;
				Border border = value;
				int num2 = Array.IndexOf(array2, val);
				bool flag = val == current;
				bool flag2 = num2 < num;
				ApplyPhaseStyle(border, flag, flag2);
				if (border.Child is StackPanel stackPanel && stackPanel.Children.Count >= 2)
				{
					if (stackPanel.Children[0] is TextBlock textBlock)
					{
						string item = GetPhaseInfo(val).Icon;
						textBlock.Text = (flag2 ? "✅" : item);
					}
					if (stackPanel.Children[1] is TextBlock textBlock2)
					{
						textBlock2.FontWeight = (flag ? FontWeights.Bold : FontWeights.Normal);
						textBlock2.Foreground = (flag ? System.Windows.Media.Brushes.White : (flag2 ? new SolidColorBrush(System.Windows.Media.Color.FromRgb(39, 174, 96)) : new SolidColorBrush(System.Windows.Media.Color.FromRgb(127, 140, 141))));
					}
				}
			}
		}

		private static (string Icon, string Name, ScanPhase _) GetPhaseInfo(ScanPhase phase)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_001e: Expected I4, but got Unknown
			//IL_009c: Unknown result type (might be due to invalid IL or missing references)
			return (int)phase switch
			{
				0 => (Icon: "\ud83d\udd0d", Name: "存活", _: (ScanPhase)0), 
				1 => (Icon: "\ud83d\udd0c", Name: "TCP", _: (ScanPhase)1), 
				2 => (Icon: "\ud83d\udce1", Name: "UDP", _: (ScanPhase)2), 
				3 => (Icon: "\ud83e\uddec", Name: "服务", _: (ScanPhase)3), 
				4 => (Icon: "\ud83d\udee1\ufe0f", Name: "漏洞", _: (ScanPhase)4), 
				5 => (Icon: "\ud83e\udde9", Name: "插件", _: (ScanPhase)5), 
				_ => (Icon: "⏳", Name: "处理", _: phase), 
			};
		}

		private void RefreshPortList()
		{
			PortCountText.Text = $"{_allDiscoveredPorts.Count} 个";
			DiscoveredPortsList.ItemsSource = null;
			DiscoveredPortsList.ItemsSource = (from p in _allDiscoveredPorts
				orderby p
				select $"  •  {p}").ToList();
		}

