		private void Browse_Click(object sender, RoutedEventArgs e)
		{
			string targetMode = GetTargetMode();
			try
			{
				switch (targetMode)
				{
				case "File":
					BrowseFile();
					break;
				case "Directory":
					BrowseDirectory();
					break;
				case "Config":
					BrowseConfigFile();
					break;
				default:
					System.Windows.MessageBox.Show("文本粘贴模式无需浏览文件", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					break;
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("浏览失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private void BrowseFile()
		{
			Microsoft.Win32.OpenFileDialog openFileDialog = new Microsoft.Win32.OpenFileDialog
			{
				Filter = "Agent文件|*.py;*.js;*.ts;*.yaml;*.yml;*.json|Python文件|*.py|JavaScript文件|*.js;*.ts|配置文件|*.yaml;*.yml;*.json|所有文件|*.*",
				Title = "选择要扫描的Agent文件"
			};
			if (openFileDialog.ShowDialog() == true)
			{
				TargetPathTextBox.Text = openFileDialog.FileName;
				TargetPathTextBox.Foreground = System.Windows.Media.Brushes.Black;
			}
		}

		private void BrowseDirectory()
		{
			using FolderBrowserDialog folderBrowserDialog = new FolderBrowserDialog
			{
				Description = "选择要扫描的Agent目录",
				UseDescriptionForTitle = true
			};
			if (folderBrowserDialog.ShowDialog() == System.Windows.Forms.DialogResult.OK && !string.IsNullOrEmpty(folderBrowserDialog.SelectedPath))
			{
				TargetPathTextBox.Text = folderBrowserDialog.SelectedPath;
				TargetPathTextBox.Foreground = System.Windows.Media.Brushes.Black;
			}
		}

		private void BrowseConfigFile()
		{
			Microsoft.Win32.OpenFileDialog openFileDialog = new Microsoft.Win32.OpenFileDialog
			{
				Filter = "配置文件|*.json;*.yaml;*.yml;*.xml|JSON文件|*.json|YAML文件|*.yaml;*.yml|XML文件|*.xml",
				Title = "选择Agent配置文件"
			};
			if (openFileDialog.ShowDialog() == true)
			{
				TargetPathTextBox.Text = openFileDialog.FileName;
				TargetPathTextBox.Foreground = System.Windows.Media.Brushes.Black;
			}
		}

		private async void StartScan_Click(object sender, RoutedEventArgs e)
		{
			string text = TargetPathTextBox.Text.Trim();
			if (string.IsNullOrEmpty(text) || TargetPathTextBox.Foreground == System.Windows.Media.Brushes.Gray)
			{
				System.Windows.MessageBox.Show("请先输入或选择扫描目标", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
			}
			else
			{
				if (!ValidateTarget(text))
				{
					return;
				}
				PrepareScanOptions(text);
				_cts = new CancellationTokenSource();
				_scanStartTime = DateTime.Now;
				SetScanningUIState(isScanning: true);
				try
				{
					await PerformScanAsync(_cts.Token);
					if (_currentResult != null)
					{
						UpdateResultDisplay(_currentResult);
						ScanStatusText.Text = "状态: 扫描完成";
						ExportReportButton.IsEnabled = true;
					}
				}
				catch (OperationCanceledException)
				{
					ScanStatusText.Text = "状态: 已取消";
					CurrentPhaseText.Text = "";
				}
				catch (Exception ex2)
				{
					ScanStatusText.Text = "状态: 扫描失败";
					System.Windows.MessageBox.Show("扫描失败: " + ex2.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				}
				finally
				{
					SetScanningUIState(isScanning: false);
					DispatcherTimer? elapsedTimer = _elapsedTimer;
					if (elapsedTimer != null)
					{
						elapsedTimer.Stop();
					}
					UpdateStatusBar();
				}
			}
		}

		private bool ValidateTarget(string target)
		{
			switch (GetTargetMode())
			{
			case "Text":
				if (target.Length < 10)
				{
					System.Windows.MessageBox.Show("输入的内容太短，请提供有效的代码或提示词", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
					return false;
				}
				return true;
			case "File":
			case "Config":
				if (!File.Exists(target))
				{
					System.Windows.MessageBox.Show("文件不存在，请检查路径是否正确", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
					return false;
				}
				return true;
			case "Directory":
				if (!Directory.Exists(target))
				{
					System.Windows.MessageBox.Show("目录不存在，请检查路径是否正确", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
					return false;
				}
				return true;
			default:
				return true;
			}
		}

		private void PrepareScanOptions(string target)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0014: Unknown result type (might be due to invalid IL or missing references)
			//IL_001e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0043: Unknown result type (might be due to invalid IL or missing references)
			//IL_0068: Unknown result type (might be due to invalid IL or missing references)
			//IL_008d: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b2: Unknown result type (might be due to invalid IL or missing references)
			//IL_00dd: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e7: Unknown result type (might be due to invalid IL or missing references)
			//IL_00f6: Unknown result type (might be due to invalid IL or missing references)
			//IL_0102: Expected O, but got Unknown
			_options = new AgentScanOptions
			{
				TargetPath = target,
				TargetType = ParseTargetMode(GetTargetMode()),
				EnableStaticAnalysis = (StaticAnalysisCheck.IsChecked ?? true),
				EnableIntentAnalysis = (IntentAnalysisCheck.IsChecked ?? true),
				EnableBehaviorSandbox = (BehaviorSandboxCheck.IsChecked ?? true),
				IncludeDependencyCheck = (DependencyCheck.IsChecked ?? true),
				ScanDepth = ParseScanDepth((ScanDepthComboBox.SelectedItem as ComboBoxItem)?.Content.ToString() ?? "标准扫描"),
				MaxFileSizeMB = 10.0,
				AgentTypeAutoDetect = true
			};
		}

		private async Task PerformScanAsync(CancellationToken token)
		{
			AgentSecurityScannerService service = new AgentSecurityScannerService();
			try
			{
				_currentResult = await service.ScanAsync(_options, (IProgress<AgentScanProgressInfo>)new Progress<AgentScanProgressInfo>(delegate(AgentScanProgressInfo p)
				{
					AgentScanProgressInfo p2 = p;
					((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
					{
						UpdateProgressFromService(p2);
					});
				}), token);
			}
			finally
			{
				service.Dispose();
			}
		}

		private void UpdateProgressFromService(AgentScanProgressInfo progress)
		{
			ScanProgressBar.Value = Math.Min(progress.Percentage, 100);
			ScanProgressText.Text = $"{Math.Min(progress.Percentage, 100)}%";
			ScanStatusText.Text = "状态: " + progress.StatusDescription;
			CurrentPhaseText.Text = (string.IsNullOrEmpty(progress.CurrentPhase) ? "" : ("阶段: " + progress.CurrentPhase));
			TotalFoundText.Text = $"已发现: {progress.FindingsCount}";
		}

		private void StopScan_Click(object sender, RoutedEventArgs e)
		{
			_cts?.Cancel();
			StopScanButton.IsEnabled = false;
			StartScanButton.IsEnabled = true;
			ScanStatusText.Text = "状态: 正在停止...";
			CurrentPhaseText.Text = "";
		}

		private void SetScanningUIState(bool isScanning)
		{
			StartScanButton.IsEnabled = !isScanning;
			StopScanButton.IsEnabled = isScanning;
			ExportReportButton.IsEnabled = false;
			if (isScanning)
			{
				DispatcherTimer? elapsedTimer = _elapsedTimer;
				if (elapsedTimer != null)
				{
					elapsedTimer.Start();
				}
				ScanProgressBar.Value = 0.0;
				ScanProgressText.Text = "0%";
				ClearResults();
			}
		}

		private void ElapsedTimer_Tick(object? sender, EventArgs e)
		{
			TimeSpan value = DateTime.Now - _scanStartTime;
			StatusBarDuration.Text = $"扫描用时: {value:mm\\:ss}";
		}

		private void ExportReport_Click(object sender, RoutedEventArgs e)
		{
			if (_currentResult == null || _currentResult.TotalFindings == 0)
			{
				System.Windows.MessageBox.Show("没有可导出的扫描结果", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Filter = "Word报告|*.docx|PDF报告|*.pdf|HTML报告|*.html|文本报告|*.txt",
				Title = "导出Agent安全扫描报告",
