		private void ResultTab_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			if (_currentResult != null)
			{
				switch (ResultTab.SelectedIndex)
				{
				case 0:
					UpdateDashboard(_currentResult);
					break;
				case 1:
					UpdateStaticAnalysisTab(_currentResult.GetVulnerabilitiesByPhase((AgentScanPhase)0));
					break;
				case 2:
					UpdateIntentAnalysisTab(_currentResult.GetVulnerabilitiesByPhase((AgentScanPhase)1));
					break;
				case 3:
					UpdateBehaviorSandboxTab(_currentResult.GetVulnerabilitiesByPhase((AgentScanPhase)2));
					break;
				case 4:
					UpdateRemediationTab(_currentResult.AllVulnerabilities.ToList());
					break;
				}
			}
		}

		private void UpdateResultDisplay(AgentScanResult result)
		{
