		private void UpdateDashboard(AgentScanResult result)
		{
			DashboardTotalVulns.Text = result.TotalFindings.ToString();
			DashboardCriticalVulns.Text = result.CriticalCount.ToString();
			DashboardHighVulns.Text = result.HighCount.ToString();
			DashboardMediumVulns.Text = result.MediumCount.ToString();
			DashboardLowVulns.Text = result.LowCount.ToString();
			DashboardSecurityScore.Text = result.Score.ToString();
			UpdateAttackSurfaceLayers(result);
			UpdateTopIssuesList(result);
			SummaryTargetPath.Text = System.IO.Path.GetFileName(result.TargetPath);
			SummaryAgentType.Text = result.AgentType;
			SummaryDuration.Text = TimeSpan.FromMilliseconds(result.DurationMs).ToString("mm\\:ss");
			SummaryScanTime.Text = result.StartTime.ToString("yyyy-MM-dd HH:mm:ss");
			StatusBarLastUpdate.Text = $"最后更新: {DateTime.Now:HH:mm:ss}";
		}

		private void UpdateAttackSurfaceLayers(AgentScanResult result)
		{
			//IL_00bd: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c2: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d2: Unknown result type (might be due to invalid IL or missing references)
			Dictionary<AgentAttackSurfaceLayer, int> attackSurfaceSummary = result.AttackSurfaceSummary;
			int num = Math.Max(result.TotalFindings, 1);
			(AgentAttackSurfaceLayer, System.Windows.Controls.ProgressBar, TextBlock)[] array = new(AgentAttackSurfaceLayer, System.Windows.Controls.ProgressBar, TextBlock)[6]
			{
				((AgentAttackSurfaceLayer)0, LayerPromptInjection, LayerPromptCount1),
				((AgentAttackSurfaceLayer)1, LayerToolAbuse, LayerPromptCount4),
				((AgentAttackSurfaceLayer)2, LayerContextManipulation, LayerPromptCount3),
				((AgentAttackSurfaceLayer)3, LayerRoleHijack, LayerPromptCount2),
				((AgentAttackSurfaceLayer)4, LayerDataLeakage, LayerPromptCount5),
				((AgentAttackSurfaceLayer)5, LayerSupplyChain, LayerPromptCount6)
			};
			for (int i = 0; i < array.Length; i++)
			{
				(AgentAttackSurfaceLayer, System.Windows.Controls.ProgressBar, TextBlock) tuple = array[i];
				AgentAttackSurfaceLayer item = tuple.Item1;
				System.Windows.Controls.ProgressBar item2 = tuple.Item2;
				TextBlock item3 = tuple.Item3;
				int value;
				int num2 = (attackSurfaceSummary.TryGetValue(item, out value) ? value : 0);
				item2.Value = ((num > 0) ? ((int)((double)num2 * 100.0 / (double)num)) : 0);
				item3.Text = num2.ToString();
			}
		}

		private void UpdateTopIssuesList(AgentScanResult result)
		{
			//IL_009b: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a0: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b5: Unknown result type (might be due to invalid IL or missing references)
			_topIssues.Clear();
			List<AgentVulnerability> list = (from v in result.AllVulnerabilities
				orderby v.RiskLevel descending, v.CvssScore.GetValueOrDefault() descending
				select v).Take(10).ToList();
			int num = 1;
			foreach (AgentVulnerability item in list)
			{
				ObservableCollection<TopIssueItem> topIssues = _topIssues;
				TopIssueItem obj = new TopIssueItem
				{
					Index = num++,
					Title = item.Title
				};
				AgentRiskLevel riskLevel = item.RiskLevel;
				obj.LevelText = ((object)(AgentRiskLevel)(ref riskLevel)).ToString();
				obj.LevelColor = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(GetRiskLevelColor(item.RiskLevel)));
				topIssues.Add(obj);
			}
		}

		private void UpdateStaticAnalysisTab(List<AgentVulnerability>? vulns)
		{
			//IL_006a: Unknown result type (might be due to invalid IL or missing references)
			//IL_006f: Unknown result type (might be due to invalid IL or missing references)
			_staticAnalysisItems.Clear();
			if (vulns == null || vulns.Count == 0)
			{
				return;
			}
			foreach (AgentVulnerability item in vulns.Take(50))
			{
				ObservableCollection<StaticAnalysisItem> staticAnalysisItems = _staticAnalysisItems;
				StaticAnalysisItem obj = new StaticAnalysisItem
				{
					FileLocation = item.FileLocation,
					LineNumber = item.LineNumber.GetValueOrDefault(),
					Category = item.Category
				};
				AgentRiskLevel riskLevel = item.RiskLevel;
				obj.RiskLevel = ((object)(AgentRiskLevel)(ref riskLevel)).ToString();
				obj.Preview = ((item.Description.Length > 50) ? (item.Description.Substring(0, 50) + "...") : item.Description);
				staticAnalysisItems.Add(obj);
			}
			StaticResultCount.Text = $"结果: {_staticAnalysisItems.Count}";
		}

