		private void UpdateIntentAnalysisTab(List<AgentVulnerability>? vulns)
		{
			IntentCardsPanel.Children.Clear();
			if (vulns == null || vulns.Count == 0)
			{
				return;
			}
			foreach (AgentVulnerability item in vulns.Take(20))
			{
				Border element = CreateIntentCard(item);
				IntentCardsPanel.Children.Add(element);
			}
		}

