		private void UpdateBehaviorSandboxTab(List<AgentVulnerability>? vulns)
		{
			//IL_007c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0081: Unknown result type (might be due to invalid IL or missing references)
			_behaviorItems.Clear();
			if (vulns == null || vulns.Count == 0)
			{
				return;
			}
			foreach (AgentVulnerability vuln in vulns)
			{
				double valueOrDefault = vuln.CvssScore.GetValueOrDefault();
				ObservableCollection<BehaviorVulnItem> behaviorItems = _behaviorItems;
				BehaviorVulnItem obj = new BehaviorVulnItem
				{
					CveId = (vuln.CveId ?? "N/A"),
					Title = vuln.Title,
					CvssScore = valueOrDefault,
					CvssColor = GetCvssColor(valueOrDefault)
				};
				AgentRiskLevel riskLevel = vuln.RiskLevel;
				obj.RiskLevel = ((object)(AgentRiskLevel)(ref riskLevel)).ToString();
				obj.AffectedComponent = vuln.FileLocation;
				obj.Condition = ((vuln.RawEvidence.Length > 80) ? (vuln.RawEvidence.Substring(0, 80) + "...") : vuln.RawEvidence);
				behaviorItems.Add(obj);
			}
		}

		private System.Windows.Media.Brush GetCvssColor(double score)
		{
			if (score >= 4.0)
			{
				if (!(score >= 9.0))
				{
					if (score >= 7.0)
					{
						return new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#E74C3C"));
					}
					return new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#F39C12"));
				}
				return new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#C0392B"));
			}
			if (score >= 0.1)
			{
				return new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#27AE60"));
			}
			return new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#95A5A6"));
		}

		private void BehaviorDataGrid_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			object selectedItem = BehaviorDataGrid.SelectedItem;
			BehaviorVulnItem item = selectedItem as BehaviorVulnItem;
			if (item != null)
			{
				BehaviorDetailPanel.Visibility = Visibility.Visible;
				BehaviorDetailTitle.Text = item.Title;
				BehaviorDetailDesc.Text = $"CVE编号: {item.CveId}\n影响组件: {item.AffectedComponent}\n利用条件: {item.Condition}\nCVSS评分: {item.CvssScore:F1}\n危害等级: {item.RiskLevel}";
				AgentScanResult? currentResult = _currentResult;
				AgentVulnerability val = ((currentResult != null) ? ((IEnumerable<AgentVulnerability>)currentResult.AllVulnerabilities).FirstOrDefault((Func<AgentVulnerability, bool>)((AgentVulnerability v) => v.CveId == item.CveId || v.Title == item.Title)) : null);
				BehaviorDetailFix.Text = ((val != null) ? val.Remediation : null) ?? "修复建议: 请参考官方安全公告，及时升级受影响的组件版本。";
				BehaviorDetailRef.Text = ((!string.IsNullOrEmpty(item.CveId) && item.CveId != "N/A") ? ("参考链接: https://nvd.nist.gov/vuln/detail/" + item.CveId) : "");
			}
			else
			{
				BehaviorDetailPanel.Visibility = Visibility.Collapsed;
			}
		}

		private void CveId_MouseLeftButtonDown(object sender, MouseButtonEventArgs e)
		{
			if (sender is TextBlock textBlock && !string.IsNullOrEmpty(textBlock.Text))
			{
				System.Windows.Clipboard.SetText(textBlock.Text);
				System.Windows.MessageBox.Show("已复制到剪贴板: " + textBlock.Text, "复制成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
		}

		private void UpdateRemediationTab(List<AgentVulnerability>? vulns)
		{
			RemediationListPanel.Children.Clear();
			if (vulns == null || vulns.Count == 0)
			{
				return;
			}
			int pending = 0;
			int acknowledged = 0;
			foreach (AgentVulnerability item in vulns.OrderByDescending((AgentVulnerability v) => v.RiskLevel).ToList())
			{
				Border element = CreateRemediationItem(item, ref pending, ref acknowledged);
				RemediationListPanel.Children.Add(element);
			}
			RemediationPendingCount.Text = pending.ToString();
			RemediationAcknowledgedCount.Text = acknowledged.ToString();
		}

		private Border CreateRemediationItem(AgentVulnerability vuln, ref int pending, ref int acknowledged)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_01a5: Unknown result type (might be due to invalid IL or missing references)
			//IL_01aa: Unknown result type (might be due to invalid IL or missing references)
			string riskLevelColor = GetRiskLevelColor(vuln.RiskLevel);
			pending++;
			Border obj = new Border
			{
				Background = System.Windows.Media.Brushes.White,
				BorderBrush = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#E9ECEF")),
				BorderThickness = new Thickness(1.0),
				CornerRadius = new CornerRadius(6.0),
				Margin = new Thickness(0.0, 0.0, 0.0, 10.0),
				Padding = new Thickness(15.0)
			};
			Grid grid = new Grid
			{
				ColumnDefinitions = 
				{
					new ColumnDefinition
					{
						Width = GridLength.Auto
					},
					new ColumnDefinition
					{
						Width = new GridLength(1.0, GridUnitType.Star)
					},
					new ColumnDefinition
					{
						Width = GridLength.Auto
					}
				}
			};
			Border border = new Border
			{
				Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(riskLevelColor)),
				CornerRadius = new CornerRadius(3.0),
				Padding = new Thickness(10.0, 6.0, 10.0, 6.0),
				Margin = new Thickness(0.0, 0.0, 15.0, 0.0),
				VerticalAlignment = VerticalAlignment.Top
			};
			TextBlock textBlock = new TextBlock();
			AgentRiskLevel riskLevel = vuln.RiskLevel;
			textBlock.Text = ((object)(AgentRiskLevel)(ref riskLevel)).ToString();
			textBlock.Foreground = System.Windows.Media.Brushes.White;
			textBlock.FontWeight = FontWeights.Bold;
			textBlock.FontSize = 11.0;
			border.Child = textBlock;
			Grid.SetColumn(border, 0);
			StackPanel stackPanel = new StackPanel
			{
				VerticalAlignment = VerticalAlignment.Center
			};
			Grid.SetColumn(stackPanel, 1);
			stackPanel.Children.Add(new TextBlock
			{
				Text = vuln.Title,
				FontWeight = FontWeights.Bold,
				FontSize = 13.0,
				Foreground = System.Windows.Media.Brushes.DarkSlateGray,
				Margin = new Thickness(0.0, 0.0, 0.0, 5.0)
			});
			StringBuilder stringBuilder = new StringBuilder();
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder3 = stringBuilder2;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(4, 1, stringBuilder2);
			handler.AppendLiteral("分类: ");
			handler.AppendFormatted(vuln.Category);
			stringBuilder3.Append(ref handler);
			if (!string.IsNullOrEmpty(vuln.FileLocation))
			{
				stringBuilder.Append(" | 位置: " + vuln.FileLocation + (vuln.LineNumber.HasValue ? $":{vuln.LineNumber}" : ""));
			}
			if (!string.IsNullOrEmpty(vuln.CveId))
			{
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder4 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(8, 1, stringBuilder2);
				handler.AppendLiteral(" | CVE: ");
				handler.AppendFormatted(vuln.CveId);
				stringBuilder4.Append(ref handler);
			}
			if (vuln.CvssScore.HasValue)
			{
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder5 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(9, 1, stringBuilder2);
				handler.AppendLiteral(" | CVSS: ");
				handler.AppendFormatted(vuln.CvssScore.Value, "F1");
				stringBuilder5.Append(ref handler);
			}
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder6 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(9, 1, stringBuilder2);
			handler.AppendLiteral(" | 置信度: ");
			handler.AppendFormatted(vuln.Confidence * 100.0, "F0");
			handler.AppendLiteral("%");
			stringBuilder6.Append(ref handler);
			stackPanel.Children.Add(new TextBlock
			{
				Text = stringBuilder.ToString(),
				FontSize = 11.0,
				Foreground = System.Windows.Media.Brushes.Gray,
				Margin = new Thickness(0.0, 0.0, 0.0, 5.0)
			});
			if (!string.IsNullOrEmpty(vuln.Remediation))
			{
				TextBlock element = new TextBlock
				{
					Text = vuln.Remediation,
					TextWrapping = TextWrapping.Wrap,
					FontSize = 12.0,
					Foreground = System.Windows.Media.Brushes.Gray,
					Margin = new Thickness(0.0, 0.0, 0.0, 5.0)
				};
				stackPanel.Children.Add(element);
			}
			System.Windows.Controls.Button button = new System.Windows.Controls.Button
			{
				Content = "复制",
				Padding = new Thickness(15.0, 6.0, 15.0, 6.0),
				Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#3498DB")),
				Foreground = System.Windows.Media.Brushes.White,
				FontWeight = FontWeights.SemiBold,
				FontSize = 11.0,
				VerticalAlignment = VerticalAlignment.Center,
				Margin = new Thickness(15.0, 0.0, 0.0, 0.0),
				Tag = vuln
			};
			button.Click += CopyRemediation_Click;
			Grid.SetColumn(button, 2);
			grid.Children.Add(border);
			grid.Children.Add(stackPanel);
			grid.Children.Add(button);
			obj.Child = grid;
			return obj;
		}

		private void CopyRemediation_Click(object sender, RoutedEventArgs e)
		{
			//IL_0040: Unknown result type (might be due to invalid IL or missing references)
			if (sender is System.Windows.Controls.Button button)
			{
				object tag = button.Tag;
				AgentVulnerability val = (AgentVulnerability)((tag is AgentVulnerability) ? tag : null);
				if (val != null)
				{
					System.Windows.Clipboard.SetText($"[{val.RiskLevel}] {val.Title}\n分类: {val.Category} | 位置: {val.FileLocation}" + (val.LineNumber.HasValue ? $":{val.LineNumber}" : "") + "\n" + $"CVSS: {val.CvssScore?.ToString("F1") ?? "N/A"} | 置信度: {val.Confidence * 100.0:F0}%\n" + "修复步骤:\n" + val.Remediation);
					System.Windows.MessageBox.Show("修复建议已复制到剪贴板", "复制成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
		}

