		private double CalculateNetworkRisk()
		{
			int num = _portScanResults.Count((PortScanResult p) => p.Status == "开放");
			return Math.Min(10.0, (double)num * 0.5);
		}

		private double CalculateServicesRisk()
		{
			int num = (from p in _portScanResults
				where !string.IsNullOrEmpty(p.Service)
				select p.Service).Distinct().Count();
			return Math.Min(10.0, (double)num * 1.2);
		}

		private double CalculateVulnsRisk()
		{
			if (_vulnerabilityResults == null || !_vulnerabilityResults.Any())
			{
				return 0.0;
			}
			double val = _vulnerabilityResults.Sum((VulnerabilityResult v) => v.RiskLevel switch
			{
				"Critical" => 3.0, 
				"High" => 2.0, 
				"Medium" => 1.0, 
				"Low" => 0.5, 
				_ => 0.5, 
			});
			return Math.Min(10.0, val);
		}

		private double CalculatePortsRisk()
		{
			int num = _portScanResults.Count((PortScanResult p) => p.Status == "开放" && (p.PortNumber == 22 || p.PortNumber == 23 || p.PortNumber == 445 || p.PortNumber == 3389 || p.PortNumber == 3306 || p.PortNumber == 1433));
			return Math.Min(10.0, (double)num * 1.5);
		}

		private double CalculateConfigRisk()
		{
			int num = _portScanResults.Count((PortScanResult p) => p.Status == "开放" && string.IsNullOrEmpty(p.ServiceVersion));
			int num2 = _portScanResults.Count((PortScanResult p) => p.Status == "开放");
			if (num2 == 0)
			{
				return 0.0;
			}
			return Math.Min(10.0, (double)num * 1.0 / (double)num2 * 10.0);
		}

		private double CalculateAccessRisk()
		{
			int num = _portScanResults.Count((PortScanResult p) => p.Status == "开放" && (p.PortNumber == 22 || p.PortNumber == 23 || p.PortNumber == 3389 || p.PortNumber == 5900));
			return Math.Min(10.0, (double)num * 2.0);
		}

