		private (int min, int max) GetPortRange(string rangeName)
		{
			return rangeName switch
			{
				"1-1024" => (min: 1, max: 1024), 
				"1025-5K" => (min: 1025, max: 5000), 
				"5K-10K" => (min: 5001, max: 10000), 
				"10K-20K" => (min: 10001, max: 20000), 
				"20K+" => (min: 20001, max: 65535), 
				_ => (min: 1, max: 65535), 
			};
		}

		private int GetEstimatedTotalPorts(int min, int max)
		{
			return min switch
			{
				1 => 100, 
				1025 => 50, 
				5001 => 30, 
				10001 => 20, 
				20001 => 10, 
				_ => 50, 
			};
		}

