		private void RiskItemsDataGrid_Sorting(object sender, DataGridSortingEventArgs e)
		{
			e.Handled = true;
			DataGridColumn column = e.Column;
			ListSortDirection listSortDirection = ((column.SortDirection == ListSortDirection.Ascending) ? ListSortDirection.Descending : ListSortDirection.Ascending);
			column.SortDirection = listSortDirection;
			if (RiskItemsDataGrid.ItemsSource is List<AIRiskItem> source)
			{
				List<AIRiskItem> itemsSource = ((listSortDirection == ListSortDirection.Ascending) ? source.OrderBy((AIRiskItem r) => GetSortValue(r, column.SortMemberPath)).ToList() : source.OrderByDescending((AIRiskItem r) => GetSortValue(r, column.SortMemberPath)).ToList());
				RiskItemsDataGrid.ItemsSource = itemsSource;
			}
		}

		private object GetSortValue(AIRiskItem item, string memberPath)
		{
			//IL_0038: Unknown result type (might be due to invalid IL or missing references)
			return memberPath switch
			{
				"RiskLevel" => GetRiskLevelPriority(item.RiskLevel), 
				"RiskScore" => item.RiskScore, 
				"Target" => item.Target, 
				"Title" => item.Title, 
				_ => item.RiskScore, 
			};
		}

		private int GetRiskLevelPriority(RiskLevel level)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0002: Unknown result type (might be due to invalid IL or missing references)
			//IL_0018: Expected I4, but got Unknown
			return (level - 1) switch
			{
				3 => 5, 
				2 => 4, 
				1 => 3, 
				0 => 2, 
				_ => 1, 
			};
		}

