		private async void ExportReportButton_Click(object sender, RoutedEventArgs e)
		{
			if (_currentReport == null)
			{
				return;
			}
			try
			{
				Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
				{
					Filter = "JSON File|*.json|HTML File|*.html|Text File|*.txt",
					FileName = $"AI_Risk_Assessment_{DateTime.Now:yyyyMMdd_HHmmss}",
					Title = "Export AI Risk Assessment Report"
				};
				if (saveFileDialog.ShowDialog() == true)
				{
					string filePath = saveFileDialog.FileName;
					switch (System.IO.Path.GetExtension(filePath).ToLower())
					{
					case ".json":
						await ExportToJsonAsync(filePath);
						break;
					case ".html":
						await ExportToHtmlAsync(filePath);
						break;
					case ".txt":
						await ExportToTextAsync(filePath);
						break;
					}
					System.Windows.MessageBox.Show("Report exported to:\n" + filePath, "Success", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("Export failed: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async Task ExportToJsonAsync(string filePath)
		{
			string contents = JsonSerializer.Serialize<AIRiskAssessmentReport>(_currentReport, new JsonSerializerOptions
			{
