		private void FilePathTextBox_DragOver(object sender, System.Windows.DragEventArgs e)
		{
			if (e.Data.GetDataPresent(System.Windows.DataFormats.FileDrop))
			{
				e.Effects = System.Windows.DragDropEffects.Copy;
			}
		}

		private void FilePathTextBox_Drop(object sender, System.Windows.DragEventArgs e)
		{
			if (e.Data.GetDataPresent(System.Windows.DataFormats.FileDrop))
			{
				string[] array = (string[])e.Data.GetData(System.Windows.DataFormats.FileDrop);
				if (array.Length != 0)
				{
					FilePathTextBox.Text = array[0];
					UpdateFileInfo(array[0]);
				}
			}
		}

		private void SelectFile_Click(object sender, RoutedEventArgs e)
		{
			Microsoft.Win32.OpenFileDialog openFileDialog = new Microsoft.Win32.OpenFileDialog
			{
				Filter = "应用文件|*.apk;*.ipa;*.zip;*.wxapkg|Android APK|*.apk|iOS IPA|*.ipa|小程序|*.zip;*.wxapkg|所有文件|*.*",
				Title = "选择要扫描的应用文件"
			};
			if (openFileDialog.ShowDialog() == true)
			{
				FilePathTextBox.Text = openFileDialog.FileName;
				FilePathTextBox.Foreground = System.Windows.Media.Brushes.Black;
				UpdateFileInfo(openFileDialog.FileName);
			}
		}

		private void UpdateFileInfo(string filePath)
		{
			try
			{
				FileInfo fileInfo = new FileInfo(filePath);
				string text = fileInfo.Extension.ToLower();
				TextBlock fileTypeText = FileTypeText;
				string text2;
				switch (text)
				{
				case ".apk":
					text2 = "Android APK";
					break;
				case ".ipa":
					text2 = "iOS IPA";
					break;
				case ".zip":
				case ".wxapkg":
					text2 = "小程序/压缩包";
					break;
				default:
					text2 = text.ToUpper();
					break;
				}
				fileTypeText.Text = text2;
				TextBlock fileSizeText = FileSizeText;
				long length = fileInfo.Length;
				text2 = ((length < 1048576) ? ((length >= 1024) ? $"{(double)fileInfo.Length / 1024.0:F2} KB" : $"{fileInfo.Length} B") : ((length >= 1073741824) ? $"{(double)fileInfo.Length / 1073741824.0:F2} GB" : $"{(double)fileInfo.Length / 1048576.0:F2} MB"));
				fileSizeText.Text = text2;
			}
			catch (Exception ex)
			{
				FileTypeText.Text = "未知";
				FileSizeText.Text = "未知";
				System.Windows.MessageBox.Show("读取文件信息失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async void StartScan_Click(object sender, RoutedEventArgs e)
		{
			string text = FilePathTextBox.Text;
			if (string.IsNullOrEmpty(text) || text == "请选择或拖拽APK/IPA/小程序文件...")
			{
				System.Windows.MessageBox.Show("请先选择要扫描的应用文件", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			if (!File.Exists(text))
			{
				System.Windows.MessageBox.Show("文件不存在，请重新选择", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				return;
			}
			_cts = new CancellationTokenSource();
			_scanner = new AppScannerService();
			_scanner.OnProgressChanged += OnProgressChanged;
			_scanner.OnLog += OnLog;
			_vulnerabilities.Clear();
			HighCountText.Text = "0";
			MediumCountText.Text = "0";
			LowCountText.Text = "0";
			ScanStatusText.Text = "状态: 扫描中...";
			ScanLogTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] 开始扫描: {System.IO.Path.GetFileName(text)}\n");
			ScanProgressBar.Value = 0.0;
			ScanProgressText.Text = "0%";
			StartScanButton.IsEnabled = false;
			StopScanButton.IsEnabled = true;
			ExportReportButton.IsEnabled = false;
			ScanMode selectedScanMode = GetSelectedScanMode();
			try
			{
				_lastResult = await _scanner.ScanAsync(text, selectedScanMode, _cts.Token);
				DisplayResults(_lastResult);
				ScanLogTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] 扫描完成! 发现 {_lastResult.Vulnerabilities.Count} 个漏洞\n");
				ExportReportButton.IsEnabled = true;
			}
			catch (OperationCanceledException)
			{
				ScanLogTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] 扫描已取消\n");
			}
			catch (Exception ex2)
			{
				ScanLogTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] 扫描失败: {ex2.Message}\n");
				System.Windows.MessageBox.Show("扫描失败: " + ex2.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			finally
			{
				ScanStatusText.Text = "状态: 就绪";
				StartScanButton.IsEnabled = true;
				StopScanButton.IsEnabled = false;
				_scanner.OnProgressChanged -= OnProgressChanged;
				_scanner.OnLog -= OnLog;
			}
		}

		private void StopScan_Click(object sender, RoutedEventArgs e)
		{
			_cts?.Cancel();
			ScanStatusText.Text = "状态: 已停止";
			StartScanButton.IsEnabled = true;
			StopScanButton.IsEnabled = false;
		}

		private void OnProgressChanged(int progress, string message)
		{
			string message2 = message;
			((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
			{
				ScanProgressBar.Value = progress;
				ScanProgressText.Text = $"{progress}%";
				ScanStatusText.Text = "状态: " + message2;
			});
		}

		private void OnLog(string message)
		{
			string message2 = message;
			((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
			{
				ScanLogTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] {message2}\n");
				ScanLogTextBox.ScrollToEnd();
			});
		}

		private void DisplayResults(AppScanResult result)
		{
			foreach (AppVulnerabilityResult vulnerability in result.Vulnerabilities)
			{
				_vulnerabilities.Add(vulnerability);
			}
			List<AppVulnerabilityResult> list = _vulnerabilities.OrderBy((AppVulnerabilityResult v) => ((int)v.RiskLevel != 3) ? (((int)v.RiskLevel == 2) ? 1 : 2) : 0).ToList();
			_vulnerabilities.Clear();
			foreach (AppVulnerabilityResult item in list)
			{
				_vulnerabilities.Add(item);
			}
			HighCountText.Text = result.HighRiskCount.ToString();
			MediumCountText.Text = result.MediumRiskCount.ToString();
			LowCountText.Text = result.LowRiskCount.ToString();
		}

		private ScanMode GetSelectedScanMode()
		{
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			//IL_0025: Unknown result type (might be due to invalid IL or missing references)
			//IL_0029: Unknown result type (might be due to invalid IL or missing references)
			//IL_002e: Unknown result type (might be due to invalid IL or missing references)
			//IL_002d: Unknown result type (might be due to invalid IL or missing references)
			return (ScanMode)(ScanTypeComboBox.SelectedIndex switch
			{
				0 => 0, 
				1 => 1, 
				2 => 2, 
				_ => 4, 
			});
		}

		private void ExportReport_Click(object sender, RoutedEventArgs e)
		{
			if (_lastResult == null || _lastResult.Vulnerabilities.Count == 0)
			{
				System.Windows.MessageBox.Show("没有可导出的扫描结果", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Filter = "Word报告|*.docx|文本报告|*.txt|HTML报告|*.html",
				Title = "导出扫描报告",
				FileName = $"APP扫描报告_{DateTime.Now:yyyyMMdd_HHmmss}"
			};
			if (saveFileDialog.ShowDialog() != true)
			{
				return;
			}
			try
			{
				string extension = System.IO.Path.GetExtension(saveFileDialog.FileName).ToLower();
				ExportReport(saveFileDialog.FileName, extension);
				ScanLogTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] 报告已导出: {saveFileDialog.FileName}\n");
				System.Windows.MessageBox.Show("报告导出成功", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出报告失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

