		private async void AssetManagementWindow_Loaded(object sender, RoutedEventArgs e)
		{
			RefreshUiByPermission();
			if (SessionContext.Instance.Current == null && new LoginWindow
			{
				Owner = this
			}.ShowDialog() != true)
			{
				Close();
				return;
			}
			User current = SessionContext.Instance.Current;
			if (current == null || (!current.IsAdmin && (current.Permissions == null || !current.Permissions.Contains("Asset:View"))))
			{
				System.Windows.MessageBox.Show("无资产管理查看权限", "权限不足", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				Close();
			}
			else
			{
				RefreshUiByPermission();
				await RefreshAssetsAsync();
			}
		}

		private void RefreshUiByPermission()
		{
			User current = SessionContext.Instance.Current;
			if (current == null)
			{
				RoleBadgeText.Text = "\ud83d\udd12 未登录";
				RoleBadgeText.Foreground = (System.Windows.Media.Brush)new BrushConverter().ConvertFromString("#636e72");
				CurrentUserText.Text = "请先登录";
				LoginLogoutButton.Content = "\ud83d\udd11 登录";
			}
			else
			{
				string text = (string.IsNullOrWhiteSpace(current.DisplayName) ? current.Username : current.DisplayName);
				if (current.IsAdmin)
				{
					RoleBadgeText.Text = "\ud83d\udc51 管理员";
					RoleBadgeText.Foreground = (System.Windows.Media.Brush)new BrushConverter().ConvertFromString("#e17055");
				}
				else
				{
					List<string> list = current.Permissions ?? new List<string>();
					if (list.Contains("Asset:Delete") || list.Contains("Asset:Import"))
					{
						RoleBadgeText.Text = "\ud83d\udee0 操作员";
						RoleBadgeText.Foreground = (System.Windows.Media.Brush)new BrushConverter().ConvertFromString("#0984e3");
					}
					else if (list.Contains("Asset:Add") || list.Contains("Asset:Edit"))
					{
						RoleBadgeText.Text = "\ud83d\udee0 操作员";
						RoleBadgeText.Foreground = (System.Windows.Media.Brush)new BrushConverter().ConvertFromString("#0984e3");
					}
					else
					{
						RoleBadgeText.Text = "\ud83d\udc41 查看者";
						RoleBadgeText.Foreground = (System.Windows.Media.Brush)new BrushConverter().ConvertFromString("#636e72");
					}
				}
				CurrentUserText.Text = text;
				LoginLogoutButton.Content = "\ud83d\udeaa 登出";
			}
			bool flag = current != null;
			bool isAdmin = flag && current.IsAdmin;
			List<string> permissions = ((current != null) ? current.Permissions : null) ?? new List<string>();
			AddAssetButton.IsEnabled = Has("Asset:Add");
			EditAssetButton.IsEnabled = Has("Asset:Edit");
			DeleteAssetButton.IsEnabled = Has("Asset:Delete");
			ImportButton.IsEnabled = Has("Asset:Import");
			ExportButton.IsEnabled = Has("Asset:View");
			SearchButton.IsEnabled = Has("Asset:View");
			RefreshButton.IsEnabled = Has("Asset:View");
			AssetTypeFilter.IsEnabled = Has("Asset:View");
			AssetStatusFilter.IsEnabled = Has("Asset:View");
			SearchTextBox.IsEnabled = Has("Asset:View");
			ViewChangeLogButton.IsEnabled = Has("Asset:View");
			string toolTip = (flag ? "权限不足" : "请先登录");
			if (!AddAssetButton.IsEnabled)
			{
				AddAssetButton.ToolTip = toolTip;
			}
			if (!EditAssetButton.IsEnabled)
			{
				EditAssetButton.ToolTip = toolTip;
			}
			if (!DeleteAssetButton.IsEnabled)
			{
				DeleteAssetButton.ToolTip = toolTip;
			}
			if (!ImportButton.IsEnabled)
			{
				ImportButton.ToolTip = toolTip;
			}
			ApplySelectionButtonState();
			bool Has(string p)
			{
				if (!isAdmin)
				{
					if (permissions != null)
					{
						return permissions.Contains(p);
					}
					return false;
				}
				return true;
			}
		}

		private void ApplySelectionButtonState()
		{
			User current = SessionContext.Instance.Current;
			bool flag = current != null && current.IsAdmin;
			List<string> list = ((current != null) ? current.Permissions : null) ?? new List<string>();
			bool flag2 = AssetsDataGrid.SelectedItem != null;
			bool flag3 = flag || (list?.Contains("Asset:Edit") ?? false);
			bool flag4 = flag || (list?.Contains("Asset:Delete") ?? false);
			EditAssetButton.IsEnabled = flag2 && flag3;
			DeleteAssetButton.IsEnabled = flag2 && flag4;
		}

		private async Task RefreshAssetsAsync()
		{
			try
			{
				List<Asset> list = ApplyFilters(_assetService.GetAllAssets()).ToList();
				AssetsDataGrid.ItemsSource = list;
				UpdateStatistics(list);
			}
			catch (Exception)
			{
			}
		}

		private IEnumerable<Asset> ApplyFilters(IEnumerable<Asset> source)
		{
			string typeTag = (AssetTypeFilter.SelectedItem as ComboBoxItem)?.Tag?.ToString() ?? "";
			string value = (AssetStatusFilter.SelectedItem as ComboBoxItem)?.Tag?.ToString() ?? "";
			IEnumerable<Asset> enumerable = source;
			if (!string.IsNullOrEmpty(typeTag))
			{
				enumerable = enumerable.Where((Asset a) => string.Equals(a.AssetType, typeTag, StringComparison.OrdinalIgnoreCase));
			}
			if (!string.IsNullOrEmpty(value) && Enum.TryParse<AssetStatus>(value, out AssetStatus st))
			{
				enumerable = enumerable.Where((Asset a) => a.Status == st);
			}
			return enumerable;
		}

		private void UpdateStatistics(List<Asset> filteredAssets)
		{
			try
			{
				AssetStatistics statistics = _assetService.GetStatistics();
				if (TotalAssetsText != null)
				{
					TotalAssetsText.Text = filteredAssets.Count.ToString();
				}
				if (OnlineAssetsText != null)
				{
					OnlineAssetsText.Text = filteredAssets.Count((Asset a) => (int)a.Status == 0).ToString();
				}
				if (OfflineAssetsText != null)
				{
					OfflineAssetsText.Text = filteredAssets.Count((Asset a) => (int)a.Status == 1).ToString();
				}
				if (MaintenanceAssetsText != null)
				{
					MaintenanceAssetsText.Text = filteredAssets.Count((Asset a) => (int)a.Status == 2).ToString();
				}
				if (ChangeLogListBox != null)
				{
					ChangeLogListBox.ItemsSource = statistics.RecentChanges.Select((AssetChangeLog c) => $"{c.ChangedAt:MM-dd HH:mm} - {c.ChangedBy}: {c.NewValue ?? c.OldValue}").ToList();
				}
				RenderTypeDistribution(filteredAssets);
			}
			catch (Exception)
			{
			}
		}

		private void RenderTypeDistribution(List<Asset> assets)
		{
			if (TypeDistributionPanel == null)
			{
				return;
			}
			TypeDistributionPanel.Children.Clear();
			var list = (from a in assets
				group a by a.AssetType into g
				select new
				{
					Type = (string.IsNullOrEmpty(g.Key) ? "未分类" : g.Key),
					Count = g.Count()
				} into g
				orderby g.Count descending
				select g).ToList();
			int num = ((list.Count <= 0) ? 1 : list.Max(g => g.Count));
			if (num == 0)
			{
				num = 1;
			}
			int num2 = ((assets.Count == 0) ? 1 : assets.Count);
			foreach (var item in list)
			{
				double value = (double)item.Count / (double)num2 * 100.0;
				StackPanel stackPanel = new StackPanel
				{
					Margin = new Thickness(0.0, 0.0, 0.0, 6.0)
				};
				TextBlock element = new TextBlock
				{
					Text = $"{item.Type}: {item.Count} ({value:0.0}%)",
					FontSize = 11.0,
					Margin = new Thickness(0.0, 0.0, 0.0, 2.0)
				};
				stackPanel.Children.Add(element);
				System.Windows.Controls.ProgressBar element2 = new System.Windows.Controls.ProgressBar
				{
					Height = 8.0,
					Minimum = 0.0,
					Maximum = num,
					Value = item.Count,
					Foreground = (System.Windows.Media.Brush)new BrushConverter().ConvertFromString("#0984e3"),
					Background = (System.Windows.Media.Brush)new BrushConverter().ConvertFromString("#dfe6e9"),
					BorderThickness = new Thickness(0.0)
				};
				stackPanel.Children.Add(element2);
				TypeDistributionPanel.Children.Add(stackPanel);
			}
			if (list.Count == 0)
			{
				TypeDistributionPanel.Children.Add(new TextBlock
				{
					Text = "暂无数据",
					FontSize = 11.0,
					Foreground = (System.Windows.Media.Brush)new BrushConverter().ConvertFromString("#b2bec3")
				});
			}
		}

