		private async void ImportButton_Click(object sender, RoutedEventArgs e)
		{
			User current = SessionContext.Instance.Current;
			string operatorName = ((current != null) ? current.Username : null) ?? "";
			Microsoft.Win32.OpenFileDialog openFileDialog = new Microsoft.Win32.OpenFileDialog
			{
				Filter = "JSON文件|*.json|CSV文件|*.csv|所有文件|*.*",
				Title = "导入资产数据"
			};
			if (openFileDialog.ShowDialog() != true)
			{
				return;
			}
			try
			{
				string text = System.IO.Path.GetExtension(openFileDialog.FileName).ToLower();
				List<NetworkDevice> devices = new List<NetworkDevice>();
				if (text == ".json")
				{
					List<Asset> list = JsonSerializer.Deserialize<List<Asset>>(await File.ReadAllTextAsync(openFileDialog.FileName));
					if (list != null)
					{
						foreach (Asset item in list)
						{
							devices.Add(new NetworkDevice
							{
								Hostname = item.Name,
								IPAddress = item.IPAddress,
								MacAddress = item.MacAddress,
								DeviceType = (DeviceType)(Enum.TryParse<DeviceType>(item.AssetType, out DeviceType result) ? ((int)result) : 13),
								Status = (DeviceStatus)(((int)item.Status == 0) ? 1 : 2)
							});
						}
					}
				}
				else if (text == ".csv")
				{
					foreach (string item2 in (await File.ReadAllLinesAsync(openFileDialog.FileName)).Skip(1))
					{
						string[] array = item2.Split(',');
						if (array.Length >= 2)
						{
							devices.Add(new NetworkDevice
							{
								Hostname = array[0].Trim(),
								IPAddress = array[1].Trim(),
								DeviceType = (DeviceType)((array.Length <= 2 || !Enum.TryParse<DeviceType>(array[2].Trim(), out DeviceType result2)) ? 13 : ((int)result2)),
								Status = (DeviceStatus)1
							});
						}
					}
				}
				if (devices.Count == 0)
				{
					System.Windows.MessageBox.Show("未找到可导入的资产数据！", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
					return;
				}
				int imported = await _assetService.ImportFromScanResultsAsync(devices, operatorName);
				await RefreshAssetsAsync();
				System.Windows.MessageBox.Show($"成功导入 {imported} 个资产！\n（跳过 {devices.Count - imported} 个重复IP）", "导入完成", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
			catch (UnauthorizedAccessException ex)
			{
				System.Windows.MessageBox.Show("无权限: " + ex.Message, "权限不足", MessageBoxButton.OK, MessageBoxImage.Exclamation);
			}
			catch (Exception ex2)
			{
				System.Windows.MessageBox.Show("导入失败: " + ex2.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async void ExportButton_Click(object sender, RoutedEventArgs e)
		{
			_ = 1;
			try
			{
				Microsoft.Win32.SaveFileDialog dialog = new Microsoft.Win32.SaveFileDialog
				{
					Filter = "JSON文件|*.json|CSV文件|*.csv",
					FileName = $"资产清单_{DateTime.Now:yyyyMMdd}",
					Title = "导出资产"
				};
				if (dialog.ShowDialog() != true)
				{
					return;
				}
				List<Asset> allAssets = _assetService.GetAllAssets();
				string text = System.IO.Path.GetExtension(dialog.FileName).ToLower();
				if (text == ".json")
				{
					string contents = JsonSerializer.Serialize(allAssets, new JsonSerializerOptions
					{
						WriteIndented = true
					});
					await File.WriteAllTextAsync(dialog.FileName, contents);
				}
				else if (text == ".csv")
				{
					StringBuilder stringBuilder = new StringBuilder();
					stringBuilder.AppendLine("名称,IP地址,MAC地址,类型,部门,负责人,状态,描述");
					foreach (Asset item in allAssets)
					{
						StringBuilder stringBuilder2 = stringBuilder;
						StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(7, 8, stringBuilder2);
						handler.AppendFormatted(item.Name);
						handler.AppendLiteral(",");
						handler.AppendFormatted(item.IPAddress);
						handler.AppendLiteral(",");
						handler.AppendFormatted(item.MacAddress);
						handler.AppendLiteral(",");
						handler.AppendFormatted(item.AssetType);
						handler.AppendLiteral(",");
						handler.AppendFormatted(item.Department);
						handler.AppendLiteral(",");
						handler.AppendFormatted(item.Owner);
						handler.AppendLiteral(",");
						handler.AppendFormatted<AssetStatus>(item.Status);
						handler.AppendLiteral(",");
						handler.AppendFormatted(item.Description);
						stringBuilder2.AppendLine(ref handler);
					}
					await File.WriteAllTextAsync(dialog.FileName, stringBuilder.ToString());
				}
				System.Windows.MessageBox.Show("资产已导出到:\n" + dialog.FileName, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

