		private void SetPlaceholder(System.Windows.Controls.TextBox textBox, string placeholder)
		{
			System.Windows.Controls.TextBox textBox2 = textBox;
			string placeholder2 = placeholder;
			textBox2.Text = placeholder2;
			textBox2.GotFocus += delegate
			{
				if (textBox2.Text == placeholder2)
				{
					textBox2.Text = "";
					textBox2.Foreground = System.Windows.Media.Brushes.Black;
				}
			};
			textBox2.LostFocus += delegate
			{
				if (string.IsNullOrWhiteSpace(textBox2.Text))
				{
					textBox2.Text = placeholder2;
					textBox2.Foreground = System.Windows.Media.Brushes.Gray;
				}
			};
			textBox2.TextChanged += delegate
			{
				//IL_004a: Unknown result type (might be due to invalid IL or missing references)
				//IL_004f: Unknown result type (might be due to invalid IL or missing references)
				//IL_0068: Expected O, but got Unknown
				if (_allEntries.Count > 0 && textBox2.Text != placeholder2)
				{
					DispatcherTimer debounceTimer = _debounceTimer;
					if (debounceTimer != null)
					{
						debounceTimer.Stop();
					}
					_debounceTimer = new DispatcherTimer
					{
						Interval = TimeSpan.FromMilliseconds(300.0)
					};
					_debounceTimer.Tick += delegate(object? sender2, EventArgs args)
					{
						//IL_001c: Unknown result type (might be due to invalid IL or missing references)
						_debounceTimer.Stop();
						ApplyFilter();
						((DispatcherTimer)sender2).Tick -= null;
					};
					_debounceTimer.Start();
				}
			};
		}

		private async Task LoadAttackLogsAsync()
		{
			try
			{
				_allEntries.Clear();
				List<string> commonLogPaths = GetCommonLogPaths();
				foreach (string item in commonLogPaths)
				{
					if (File.Exists(item))
					{
						List<AttackLogEntry> collection = await ParseLogFile(item);
						_allEntries.AddRange(collection);
					}
				}
				if (_allEntries.Count == 0)
				{
					_allEntries = GenerateDemoData();
				}
				_allEntries = _allEntries.OrderByDescending((AttackLogEntry e) => e.Timestamp).ToList();
				ApplyFilter();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("加载日志失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private List<string> GetCommonLogPaths()
		{
			return new List<string>
			{
				"C:\\inetpub\\logs\\LogFiles\\W3SVC1\\u_ex" + DateTime.Now.ToString("yyMMdd") + ".log",
				"/var/log/nginx/access.log",
				"/var/log/apache2/access.log",
				"/var/log/httpd/access_log"
			};
		}

		private async Task<List<AttackLogEntry>> ParseLogFile(string path)
		{
			_ = 2;
			try
			{
				if (path.Contains("iis", StringComparison.OrdinalIgnoreCase) || path.Contains("W3SVC", StringComparison.OrdinalIgnoreCase))
				{
					return await _logService.ParseIISLog(path);
				}
				if (path.Contains("nginx", StringComparison.OrdinalIgnoreCase) || path.Contains("apache", StringComparison.OrdinalIgnoreCase) || path.Contains("httpd", StringComparison.OrdinalIgnoreCase))
				{
					return await _logService.ParseWebServerLog(path);
				}
				if (path.Contains("firewall", StringComparison.OrdinalIgnoreCase))
				{
					return await _logService.ParseFirewallLog(path);
				}
			}
			catch (Exception)
			{
			}
			return new List<AttackLogEntry>();
		}

		private List<AttackLogEntry> GenerateDemoData()
		{
			//IL_0150: Unknown result type (might be due to invalid IL or missing references)
			//IL_0157: Expected O, but got Unknown
			List<AttackLogEntry> list = new List<AttackLogEntry>();
			Random random = new Random();
			string[] array = new string[7] { "SQL注入", "XSS跨站脚本", "暴力破解", "端口扫描", "DDoS攻击", "目录遍历", "命令注入" };
			string[] array2 = new string[6] { "192.168.1.100", "10.0.0.50", "172.16.0.25", "203.0.113.42", "198.51.100.78", "185.220.101.34" };
			string[] array3 = new string[4] { "192.168.1.1", "192.168.1.10", "10.0.0.1", "172.16.0.1" };
			string[] array4 = new string[7] { "/login", "/admin", "/api/users", "/index.php?id=1", "/wp-admin", "/phpmyadmin", "/api/data?user=admin" };
			string[] array5 = new string[4] { "GET", "POST", "PUT", "DELETE" };
			string[] array6 = new string[4] { "Mozilla/5.0", "python-requests/2.28", "curl/7.83", "sqlmap/1.6" };
			for (int i = 0; i < 80; i++)
			{
				string text = array[random.Next(array.Length)];
				AttackLogEntry val = new AttackLogEntry();
				val.Timestamp = DateTime.Now.AddHours(-random.Next(720));
				val.SourceIP = array2[random.Next(array2.Length)];
				val.TargetIP = array3[random.Next(array3.Length)];
				val.AttackType = text;
				val.RiskLevel = _logService.AssessRiskLevel(text);
				val.RequestURL = array4[random.Next(array4.Length)] + ((random.Next(3) == 0) ? $"&page={random.Next(100)}" : "");
				val.StatusCode = (new int[7] { 200, 301, 400, 401, 403, 404, 500 })[random.Next(7)];
				val.RequestMethod = array5[random.Next(array5.Length)];
				val.Details = $"检测到{text}尝试，请求方法: {array5[random.Next(array5.Length)]}，User-Agent: {array6[random.Next(array6.Length)]}";
				val.UserAgent = array6[random.Next(array6.Length)];
				list.Add(val);
			}
			return list;
		}

		private void ApplyFilter()
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			//IL_003c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0083: Unknown result type (might be due to invalid IL or missing references)
			//IL_0094: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a5: Unknown result type (might be due to invalid IL or missing references)
			//IL_00bc: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d8: Expected O, but got Unknown
			_currentFilter = new AttackLogFilter
			{
				StartDate = (_startDatePicker.SelectedDate?.Date ?? DateTime.MinValue),
				EndDate = (_endDatePicker.SelectedDate?.Date.AddDays(1.0) ?? DateTime.MaxValue),
				AttackType = _attackTypeComboBox.Text,
				RiskLevel = _riskLevelComboBox.Text,
				SourceIPKeyword = GetActualText(_sourceIPTextBox, "搜索来源IP..."),
				TargetIPKeyword = GetActualText(_targetIPTextBox, "搜索目标IP...")
			};
			_filteredEntries = _logService.FilterEntries(_allEntries, _currentFilter);
			_attackLogGrid.ItemsSource = _filteredEntries;
			UpdateStatistics();
			UpdateStatusBar();
		}

		private string GetActualText(System.Windows.Controls.TextBox textBox, string placeholder)
		{
			string text = textBox.Text.Trim();
			if (!(text == placeholder))
			{
				return text;
			}
			return "";
		}

		private void UpdateStatistics()
		{
			AttackLogStatistics val = _logService.CalculateStatistics(_filteredEntries);
			_totalAttacksText.Text = $"攻击总数: {val.TotalAttacks}";
			_attackTypeStatsPanel.Children.Clear();
			foreach (KeyValuePair<string, int> item in val.AttacksByType)
			{
				_attackTypeStatsPanel.Children.Add(CreateStatRow(item.Key, item.Value, val.TotalAttacks, GetAttackTypeColor(item.Key)));
			}
			_riskLevelStatsPanel.Children.Clear();
			foreach (KeyValuePair<string, int> item2 in val.AttacksByRiskLevel)
			{
				string colorHex = item2.Key switch
				{
					"高" => "#E74C3C", 
					"中" => "#F39C12", 
					"低" => "#27AE60", 
					_ => "#95A5A6", 
				};
				_riskLevelStatsPanel.Children.Add(CreateStatRow(item2.Key, item2.Value, val.TotalAttacks, colorHex));
			}
			_topSourceIPsPanel.Children.Clear();
			foreach (KeyValuePair<string, int> topSourceIP in val.TopSourceIPs)
			{
				_topSourceIPsPanel.Children.Add(CreateStatRow(topSourceIP.Key, topSourceIP.Value, val.TotalAttacks, "#3498DB"));
			}
			_timeTrendText.Text = (val.AttacksByTime.Any() ? $"\ud83d\udd50 最早攻击: {val.EarliestAttack:yyyy-MM-dd HH:mm}\n\ud83d\udd50 最新攻击: {val.LatestAttack:yyyy-MM-dd HH:mm}\n\ud83d\udcc5 活跃天数: {val.AttacksByTime.Count} 天\n\ud83d\udcc8 日均攻击: {(double)val.TotalAttacks / (double)Math.Max(val.AttacksByTime.Count, 1):F1} 次" : "暂无攻击记录");
		}

		private string GetAttackTypeColor(string attackType)
		{
			return attackType switch
			{
				"SQL注入" => "#E74C3C", 
				"XSS跨站脚本" => "#9B59B6", 
				"命令注入" => "#C0392B", 
				"暴力破解" => "#F39C12", 
				"DDoS攻击" => "#E67E22", 
				"目录遍历" => "#3498DB", 
				"端口扫描" => "#1ABC9C", 
				_ => "#95A5A6", 
			};
