		private StackPanel CreateStatRow(string label, int count, int total, string colorHex)
		{
			StackPanel obj = new StackPanel
			{
				Orientation = System.Windows.Controls.Orientation.Horizontal,
				Margin = new Thickness(0.0, 4.0, 0.0, 4.0)
			};
			Border element = new Border
			{
				Width = 4.0,
				Height = 18.0,
				CornerRadius = new CornerRadius(2.0),
				Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(colorHex)),
				VerticalAlignment = VerticalAlignment.Center,
				Margin = new Thickness(0.0, 0.0, 6.0, 0.0)
			};
			obj.Children.Add(element);
			obj.Children.Add(new TextBlock
			{
				Text = label,
				Width = 90.0,
				TextTrimming = TextTrimming.CharacterEllipsis,
				VerticalAlignment = VerticalAlignment.Center,
				FontSize = 11.0,
				Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#34495E"))
			});
			System.Windows.Controls.ProgressBar element2 = new System.Windows.Controls.ProgressBar
			{
				Width = 120.0,
				Height = 14.0,
				Maximum = Math.Max(total, 1),
				Value = count,
				Margin = new Thickness(5.0, 0.0, 5.0, 0.0),
				Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#ECF0F1"))
			};
			obj.Children.Add(element2);
			obj.Children.Add(new TextBlock
			{
				Text = $"{count}",
				FontSize = 11.0,
				FontWeight = FontWeights.SemiBold,
				Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(colorHex)),
				VerticalAlignment = VerticalAlignment.Center,
				Width = 30.0
			});
			obj.Children.Add(new TextBlock
			{
				Text = $"{((total > 0) ? ((double)count / (double)total * 100.0) : 0.0):F1}%",
				FontSize = 10.0,
				Foreground = System.Windows.Media.Brushes.Gray,
				VerticalAlignment = VerticalAlignment.Center
			});
			return obj;
		}

