		private void TimeRangeComboBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			if (_timeRangeComboBox != null)
			{
				DateTime now = DateTime.Now;
				switch (_timeRangeComboBox.SelectedIndex)
				{
				case 0:
					_startDatePicker.SelectedDate = now.Date;
					_endDatePicker.SelectedDate = now.Date.AddDays(1.0);
					break;
				case 1:
					_startDatePicker.SelectedDate = now.Date.AddDays(-7.0);
					_endDatePicker.SelectedDate = now.Date.AddDays(1.0);
					break;
				case 2:
					_startDatePicker.SelectedDate = now.Date.AddDays(-30.0);
					_endDatePicker.SelectedDate = now.Date.AddDays(1.0);
					break;
				case 3:
					break;
				}
			}
		}

