		private void ShowLogDetail(AttackLogEntry entry)
		{
			Window window = new Window
			{
				Title = "攻击日志详情",
				Width = 580.0,
				Height = 580.0,
				WindowStartupLocation = WindowStartupLocation.CenterOwner,
				Owner = this,
				ResizeMode = ResizeMode.NoResize
			};
			window.KeyDown += delegate(object s, System.Windows.Input.KeyEventArgs e)
			{
				//IL_0001: Unknown result type (might be due to invalid IL or missing references)
				//IL_0008: Invalid comparison between Unknown and I4
				if ((int)e.Key == 13)
				{
					window.Close();
				}
			};
			Grid grid = new Grid
			{
				Margin = new Thickness(20.0)
			};
			grid.RowDefinitions.Add(new RowDefinition
			{
				Height = GridLength.Auto
			});
			grid.RowDefinitions.Add(new RowDefinition
			{
				Height = new GridLength(1.0, GridUnitType.Star)
			});
			grid.RowDefinitions.Add(new RowDefinition
			{
				Height = GridLength.Auto
			});
			string text = entry.RiskLevel switch
			{
				"高" => "#E74C3C", 
				"中" => "#F39C12", 
				"低" => "#27AE60", 
				_ => "#95A5A6", 
			};
			Border border = new Border
			{
				Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(text)),
				CornerRadius = new CornerRadius(8.0),
				Padding = new Thickness(20.0, 15.0, 20.0, 15.0)
			};
			StackPanel stackPanel = new StackPanel();
			stackPanel.Children.Add(new TextBlock
			{
				Text = "⚠\ufe0f ",
				FontSize = 24.0
			});
			stackPanel.Children.Add(new TextBlock
			{
				Text = entry.AttackType + " - 风险等级: " + entry.RiskLevel,
				FontSize = 18.0,
				FontWeight = FontWeights.Bold,
				Foreground = System.Windows.Media.Brushes.White,
				VerticalAlignment = VerticalAlignment.Center,
				Margin = new Thickness(10.0, 0.0, 0.0, 0.0)
			});
			StackPanel stackPanel2 = new StackPanel
			{
				Orientation = System.Windows.Controls.Orientation.Horizontal
			};
			stackPanel2.Children.Add(stackPanel);
			border.Child = stackPanel2;
			Grid.SetRow(border, 0);
			grid.Children.Add(border);
			StackPanel detailsPanel = new StackPanel
			{
				Margin = new Thickness(0.0, 20.0, 0.0, 0.0)
			};
			AddSectionHeader("基本信息");
			AddDetailRow("发生时间", entry.Timestamp.ToString("yyyy-MM-dd HH:mm:ss.fff"), "\ud83d\udd50");
			AddDetailRow("来源 IP", entry.SourceIP, "\ud83c\udf10");
			AddDetailRow("目标 IP", entry.TargetIP, "\ud83c\udfaf");
			AddDetailRow("请求 URL", entry.RequestURL, "\ud83d\udd17");
			AddSectionHeader("请求信息");
			AddDetailRow("请求方法", entry.RequestMethod ?? "GET", "\ud83d\udce4");
			AddDetailRow("状态码", GetStatusCodeDescription(entry.StatusCode), "\ud83d\udcca", (entry.StatusCode >= 400) ? "#E74C3C" : "#27AE60");
			AddDetailRow("User-Agent", entry.UserAgent ?? "-", "\ud83d\udda5\ufe0f");
			AddSectionHeader("安全分析");
			AddDetailRow("风险等级", entry.RiskLevel, "\ud83d\udea8", text);
			AddDetailRow("攻击类型", entry.AttackType, "⚡");
			AddDetailRow("攻击频率", GetAttackFrequency(entry.SourceIP), "\ud83d\udcc8");
			AddDetailRow("建议操作", GetRecommendation(entry.AttackType), "\ud83d\udca1", "#2980B9");
			Border border2 = new Border
			{
				Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#F8F9FA")),
				CornerRadius = new CornerRadius(6.0),
				Padding = new Thickness(15.0),
				BorderBrush = System.Windows.Media.Brushes.LightGray,
				BorderThickness = new Thickness(1.0)
			};
			border2.Child = detailsPanel;
			Grid.SetRow(border2, 1);
			grid.Children.Add(border2);
			System.Windows.Controls.Button button = new System.Windows.Controls.Button
			{
				Content = "关闭",
				Width = 100.0,
				Height = 32.0,
				HorizontalAlignment = System.Windows.HorizontalAlignment.Right,
				Margin = new Thickness(0.0, 15.0, 0.0, 0.0),
				Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#3498DB")),
				Foreground = System.Windows.Media.Brushes.White,
				BorderThickness = new Thickness(0.0),
				Cursor = System.Windows.Input.Cursors.Hand
			};
			button.Click += delegate
			{
				window.Close();
			};
			Grid.SetRow(button, 2);
			grid.Children.Add(button);
			window.Content = grid;
			window.ShowDialog();
			void AddDetailRow(string label, string value, string icon = "", string valueColor = "#34495E")
			{
				StackPanel stackPanel3 = new StackPanel
				{
					Orientation = System.Windows.Controls.Orientation.Horizontal,
					Margin = new Thickness(0.0, 8.0, 0.0, 0.0)
				};
				stackPanel3.Children.Add(new TextBlock
				{
					Text = icon + " " + label,
					Width = 110.0,
					FontWeight = FontWeights.SemiBold,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2C3E50"))
				});
				stackPanel3.Children.Add(new TextBlock
				{
					Text = value,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(valueColor)),
