				detailsPanel.Children.Add(new TextBlock
				{
					Text = title,
					FontWeight = FontWeights.Bold,
					FontSize = 13.0,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2C3E50")),
					Margin = new Thickness(0.0, 15.0, 0.0, 8.0),
					Padding = new Thickness(5.0, 3.0, 0.0, 3.0),
					Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#ECF0F1"))
				});
			}
		}

