		private void ExportCsvButton_Click(object sender, RoutedEventArgs e)
		{
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Filter = "CSV文件 (*.csv)|*.csv",
				DefaultExt = ".csv",
				FileName = $"攻击日志_{DateTime.Now:yyyyMMdd_HHmmss}.csv"
			};
			if (saveFileDialog.ShowDialog() != true)
			{
				return;
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("时间,来源IP,目标IP,攻击类型,风险等级,请求URL,状态码,请求方法,详情");
			foreach (AttackLogEntry filteredEntry in _filteredEntries)
			{
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(26, 9, stringBuilder2);
				handler.AppendLiteral("\"");
				handler.AppendFormatted(filteredEntry.Timestamp, "yyyy-MM-dd HH:mm:ss");
				handler.AppendLiteral("\",\"");
				handler.AppendFormatted(filteredEntry.SourceIP);
				handler.AppendLiteral("\",\"");
				handler.AppendFormatted(filteredEntry.TargetIP);
				handler.AppendLiteral("\",\"");
				handler.AppendFormatted(filteredEntry.AttackType);
				handler.AppendLiteral("\",\"");
				handler.AppendFormatted(filteredEntry.RiskLevel);
				handler.AppendLiteral("\",\"");
				handler.AppendFormatted(filteredEntry.RequestURL);
				handler.AppendLiteral("\",\"");
				handler.AppendFormatted(filteredEntry.StatusCode);
				handler.AppendLiteral("\",\"");
				handler.AppendFormatted(filteredEntry.RequestMethod);
				handler.AppendLiteral("\",\"");
				handler.AppendFormatted(filteredEntry.Details);
				handler.AppendLiteral("\"");
				stringBuilder2.AppendLine(ref handler);
			}
			File.WriteAllText(saveFileDialog.FileName, stringBuilder.ToString(), Encoding.UTF8);
			System.Windows.MessageBox.Show($"✅ 已成功导出 {_filteredEntries.Count} 条记录到:\n{saveFileDialog.FileName}", "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
		}

		private void ExportExcelButton_Click(object sender, RoutedEventArgs e)
		{
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Filter = "Excel文件 (*.xlsx)|*.xlsx",
				DefaultExt = ".xlsx",
				FileName = $"攻击日志_{DateTime.Now:yyyyMMdd_HHmmss}"
			};
			if (saveFileDialog.ShowDialog() != true)
			{
				return;
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("<html><head><meta charset=\"utf-8\"><style>");
			stringBuilder.AppendLine("table {border-collapse: collapse; width: 100%;}");
			stringBuilder.AppendLine("th, td {border: 1px solid #ddd; padding: 8px; text-align: left;}");
			stringBuilder.AppendLine("th {background-color: #2C3E50; color: white;}");
			stringBuilder.AppendLine("tr:nth-child(even) {background-color: #f2f2f2;}");
			stringBuilder.AppendLine("</style></head><body>");
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder3 = stringBuilder2;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(28, 1, stringBuilder2);
			handler.AppendLiteral("<h2>攻击日志报告</h2><p>生成时间: ");
			handler.AppendFormatted(DateTime.Now, "yyyy-MM-dd HH:mm:ss");
			handler.AppendLiteral("</p>");
			stringBuilder3.AppendLine(ref handler);
			stringBuilder.AppendLine("<table><tr><th>时间</th><th>来源IP</th><th>目标IP</th><th>攻击类型</th><th>风险等级</th><th>请求URL</th><th>状态码</th></tr>");
			foreach (AttackLogEntry filteredEntry in _filteredEntries)
			{
				string value = filteredEntry.RiskLevel switch
				{
					"高" => "color: white; background-color: #E74C3C;", 
					"中" => "color: white; background-color: #F39C12;", 
					"低" => "color: white; background-color: #27AE60;", 
					_ => "", 
				};
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder4 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(81, 8, stringBuilder2);
				handler.AppendLiteral("<tr><td>");
				handler.AppendFormatted(filteredEntry.Timestamp, "yyyy-MM-dd HH:mm:ss");
				handler.AppendLiteral("</td><td>");
				handler.AppendFormatted(filteredEntry.SourceIP);
				handler.AppendLiteral("</td><td>");
				handler.AppendFormatted(filteredEntry.TargetIP);
				handler.AppendLiteral("</td><td>");
				handler.AppendFormatted(filteredEntry.AttackType);
				handler.AppendLiteral("</td><td style=\"");
				handler.AppendFormatted(value);
				handler.AppendLiteral("\">");
				handler.AppendFormatted(filteredEntry.RiskLevel);
				handler.AppendLiteral("</td><td>");
				handler.AppendFormatted(filteredEntry.RequestURL);
				handler.AppendLiteral("</td><td>");
				handler.AppendFormatted(filteredEntry.StatusCode);
				handler.AppendLiteral("</td></tr>");
				stringBuilder4.AppendLine(ref handler);
			}
			stringBuilder.AppendLine("</table></body></html>");
			File.WriteAllText(saveFileDialog.FileName, stringBuilder.ToString(), Encoding.UTF8);
			System.Windows.MessageBox.Show($"✅ 已成功导出 {_filteredEntries.Count} 条记录到:\n{saveFileDialog.FileName}", "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
		}

		private string GetStatusCodeDescription(int statusCode)
		{
			return statusCode switch
			{
				200 => $"{statusCode} (成功)", 
				301 => $"{statusCode} (永久重定向)", 
				400 => $"{statusCode} (错误请求)", 
				401 => $"{statusCode} (未授权)", 
				403 => $"{statusCode} (禁止访问)", 
				404 => $"{statusCode} (未找到)", 
				500 => $"{statusCode} (服务器错误)", 
				_ => $"{statusCode} (未知)", 
			};
		}

		private string GetAttackFrequency(string sourceIP)
		{
			string sourceIP2 = sourceIP;
			int num = _allEntries.Count((AttackLogEntry e) => e.SourceIP == sourceIP2);
			if (num < 20)
			{
				if (num < 10)
				{
					if (num < 5)
					{
						return $"偶尔 ({num}次攻击)";
					}
					return $"中等 ({num}次攻击)";
				}
				return $"频繁 ({num}次攻击)";
			}
			return $"高 ({num}次攻击)";
		}

		private string GetRecommendation(string attackType)
		{
			return attackType switch
			{
				"SQL注入" => "检查输入验证，使用参数化查询，部署WAF", 
				"XSS跨站脚本" => "对输出进行HTML编码，启用CSP策略", 
				"暴力破解" => "启用账户锁定机制，增加验证码", 
				"端口扫描" => "关闭不必要端口，配置防火墙规则", 
				"DDoS攻击" => "启用流量清洗，配置CDN防护", 
				"目录遍历" => "限制目录访问权限，过滤路径字符", 
				"命令注入" => "严格验证用户输入，避免系统命令执行", 
				_ => "记录日志并监控该IP后续活动", 
			};
		}

		private void PrintButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				System.Windows.Controls.PrintDialog printDialog = new System.Windows.Controls.PrintDialog();
				if (printDialog.ShowDialog() != true)
				{
					return;
				}
				StackPanel stackPanel = new StackPanel
				{
					Margin = new Thickness(30.0)
				};
				stackPanel.Children.Add(new TextBlock
				{
					Text = "攻击日志查询报告",
					FontSize = 22.0,
					FontWeight = FontWeights.Bold,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2C3E50")),
					Margin = new Thickness(0.0, 0.0, 0.0, 10.0)
				});
				stackPanel.Children.Add(new TextBlock
				{
					Text = $"生成时间: {DateTime.Now:yyyy-MM-dd HH:mm:ss} | 共 {_filteredEntries.Count} 条记录",
					FontSize = 12.0,
					Foreground = System.Windows.Media.Brushes.Gray,
					Margin = new Thickness(0.0, 0.0, 0.0, 20.0)
				});
				Grid grid = new Grid();
				grid.ColumnDefinitions.Add(new ColumnDefinition
				{
					Width = new GridLength(140.0)
				});
				grid.ColumnDefinitions.Add(new ColumnDefinition
				{
					Width = new GridLength(120.0)
				});
				grid.ColumnDefinitions.Add(new ColumnDefinition
				{
					Width = new GridLength(120.0)
				});
				grid.ColumnDefinitions.Add(new ColumnDefinition
				{
					Width = new GridLength(100.0)
				});
				grid.ColumnDefinitions.Add(new ColumnDefinition
				{
					Width = new GridLength(70.0)
				});
				grid.ColumnDefinitions.Add(new ColumnDefinition
				{
					Width = new GridLength(1.0, GridUnitType.Star)
				});
				grid.ColumnDefinitions.Add(new ColumnDefinition
				{
					Width = new GridLength(60.0)
				});
				AddHeader(new string[7] { "时间", "来源IP", "目标IP", "攻击类型", "风险等级", "请求URL", "状态码" });
				int num = 1;
				foreach (AttackLogEntry item in _filteredEntries.Take(50))
				{
					grid.RowDefinitions.Add(new RowDefinition
					{
						Height = GridLength.Auto
					});
					string[] array = new string[7]
					{
						item.Timestamp.ToString("MM-dd HH:mm"),
						item.SourceIP,
						item.TargetIP,
						item.AttackType,
						item.RiskLevel,
						item.RequestURL,
						item.StatusCode.ToString()
					};
					for (int i = 0; i < array.Length; i++)
					{
						TextBlock element = new TextBlock
						{
							Text = array[i],
							FontSize = 10.0,
							Padding = new Thickness(5.0, 2.0, 5.0, 2.0),
							TextTrimming = TextTrimming.CharacterEllipsis
						};
						Grid.SetRow(element, num);
						Grid.SetColumn(element, i);
						grid.Children.Add(element);
					}
					num++;
				}
				if (_filteredEntries.Count > 50)
				{
					stackPanel.Children.Add(new TextBlock
					{
						Text = $"... 仅显示前 50 条记录（共 {_filteredEntries.Count} 条）",
						FontSize = 11.0,
						FontStyle = FontStyles.Italic,
						Foreground = System.Windows.Media.Brushes.Gray,
						Margin = new Thickness(0.0, 10.0, 0.0, 0.0)
					});
				}
				stackPanel.Children.Add(grid);
				printDialog.PrintVisual(stackPanel, "攻击日志报告");
				void AddHeader(string[] headers)
				{
					for (int j = 0; j < headers.Length; j++)
					{
						TextBlock element2 = new TextBlock
						{
							Text = headers[j],
							FontWeight = FontWeights.Bold,
							FontSize = 11.0,
							Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2C3E50")),
							Foreground = System.Windows.Media.Brushes.White,
							Padding = new Thickness(5.0, 3.0, 5.0, 3.0)
						};
						Grid.SetColumn(element2, j);
						grid.Children.Add(element2);
					}
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("打印失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

