	public class RiskLevelToColorConverter : IValueConverter
	{
		public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
		{
			return value?.ToString() switch
			{
				"高" => new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#E74C3C")), 
				"中" => new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#F39C12")), 
				"低" => new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#27AE60")), 
				_ => new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#95A5A6")), 
			};
		}

		public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
		{
			return System.Windows.Data.Binding.DoNothing;
		}
	}
	public class AttackPathAnalysisWindow : Window, IComponentConnector
	{
		private List<AttackPath> _attackPaths = new List<AttackPath>();

		private List<AttackPath> _allAttackPaths = new List<AttackPath>();

		private ObservableCollection<AttackPathDisplayModel> _attackPathItems = new ObservableCollection<AttackPathDisplayModel>();

		private string _currentFilter = "全部";

		internal System.Windows.Controls.Button RefreshButton;

		internal System.Windows.Controls.Button ExportButton;

		internal System.Windows.Controls.Button CloseButton;

		internal TextBlock PathCountText;

		internal System.Windows.Controls.Button FilterAllButton;

		internal System.Windows.Controls.Button FilterCriticalButton;

		internal System.Windows.Controls.Button FilterHighButton;

		internal System.Windows.Controls.Button FilterMediumButton;

		internal System.Windows.Controls.ListBox AttackPathListBox;

		internal StackPanel EmptyStatePanel;

		internal StackPanel DetailPanel;

		internal TextBlock DetailNameText;

		internal TextBlock DetailDescriptionText;

		internal TextBlock DetailRiskScoreText;

		internal System.Windows.Controls.ProgressBar DetailRiskScoreBar;

		internal TextBlock DetailSuccessProbText;

		internal System.Windows.Controls.ProgressBar DetailSuccessProbBar;

		internal TextBlock DetailEstimatedTimeText;

		internal TextBlock DetailComplexityText;

		internal TextBlock DetailPriorityText;

