		private bool _contentLoaded;

		public AttackPathAnalysisWindow(List<AttackPath> attackPaths = null)
		{
			InitializeComponent();
			_attackPaths = attackPaths ?? new List<AttackPath>();
			_allAttackPaths = new List<AttackPath>(_attackPaths);
			LoadAttackPaths();
			CalculateOverallRiskSummary();
		}

		private void CalculateOverallRiskSummary()
		{
			if (!_attackPaths.Any())
			{
				StatusText.Text = "未检测到攻击路径";
				return;
			}
			int value = _attackPaths.Count((AttackPath p) => p.RiskScore >= 80.0);
			int value2 = _attackPaths.Count((AttackPath p) => p.RiskScore >= 60.0 && p.RiskScore < 80.0);
			int value3 = _attackPaths.Count((AttackPath p) => p.RiskScore >= 40.0 && p.RiskScore < 60.0);
			int value4 = _attackPaths.Count((AttackPath p) => p.RiskScore < 40.0);
			double value5 = _attackPaths.Average((AttackPath p) => p.RiskScore);
			string text = $"严重:{value} | 高危:{value2} | 中危:{value3} | 低危:{value4} | 平均风险:{value5:F0}";
			StatusText.Text = text;
		}

		private void LoadAttackPaths()
		{
			_attackPathItems.Clear();
			foreach (AttackPath item2 in from p in (IEnumerable<AttackPath>)((_currentFilter == "全部") ? ((IList)_attackPaths) : ((IList)_attackPaths.Where((AttackPath p) => GetRiskLevel(p.RiskScore) == _currentFilter).ToList()))
				orderby p.RiskScore descending, p.SuccessProbability descending
				select p)
			{
				AttackPathDisplayModel item = new AttackPathDisplayModel
				{
					PathId = item2.PathId,
					Name = item2.Name,
					Description = item2.Description,
					RiskScore = item2.RiskScore,
					RiskLevel = GetRiskLevel(item2.RiskScore),
					SuccessProbability = item2.SuccessProbability,
					Complexity = item2.Complexity,
					StepCount = item2.Steps.Count,
					EstimatedTime = EstimateAttackTime(item2),
					Priority = GetPriorityLevel(item2)
				};
				_attackPathItems.Add(item);
			}
			AttackPathListBox.ItemsSource = _attackPathItems;
			PathCountText.Text = $"共 {_attackPathItems.Count} 条路径";
			StatusText.Text = $"已加载 {_attackPathItems.Count} 条攻击路径";
			LastUpdateText.Text = $"更新时间: {DateTime.Now:yyyy-MM-dd HH:mm:ss}";
		}

		private void ApplyFilter(string filter)
		{
			_currentFilter = filter;
			LoadAttackPaths();
			FilterAllButton.Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString((filter == "全部") ? "#3498db" : "#e0e0e0"));
			FilterAllButton.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString((filter == "全部") ? "White" : "#2c3e50"));
			FilterCriticalButton.Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString((filter == "严重") ? "#c0392b" : "#e0e0e0"));
			FilterCriticalButton.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString((filter == "严重") ? "White" : "#2c3e50"));
			FilterHighButton.Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString((filter == "高危") ? "#e67e22" : "#e0e0e0"));
			FilterHighButton.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString((filter == "高危") ? "White" : "#2c3e50"));
			FilterMediumButton.Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString((filter == "中危") ? "#f39c12" : "#e0e0e0"));
			FilterMediumButton.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString((filter == "中危") ? "White" : "#2c3e50"));
		}

		private void FilterAllButton_Click(object sender, RoutedEventArgs e)
		{
			ApplyFilter("全部");
		}

		private void FilterCriticalButton_Click(object sender, RoutedEventArgs e)
		{
			ApplyFilter("严重");
		}

		private void FilterHighButton_Click(object sender, RoutedEventArgs e)
		{
			ApplyFilter("高危");
		}

		private void FilterMediumButton_Click(object sender, RoutedEventArgs e)
		{
			ApplyFilter("中危");
		}

		private string EstimateAttackTime(AttackPath path)
		{
			double num = path.Steps.Count * 2;
			double num2 = (double)path.Complexity / 5.0;
			double num3 = (100.0 - path.SuccessProbability) / 100.0;
			double num4 = num * num2 * (1.0 + num3);
			if (num4 < 1.0)
			{
				return "< 1小时";
			}
			if (num4 < 24.0)
			{
				return $"{num4:F0}小时";
			}
			if (num4 < 168.0)
			{
				return $"{num4 / 24.0:F0}天";
			}
			return "> 1周";
		}

		private string GetPriorityLevel(AttackPath path)
		{
			double num = path.RiskScore * 0.4 + path.SuccessProbability * 0.3 + (double)((10 - path.Complexity) * 3);
			if (num >= 70.0)
			{
				return "\ud83d\udd34 紧急";
			}
			if (num >= 50.0)
			{
				return "\ud83d\udfe0 高优";
			}
			if (num >= 30.0)
			{
				return "\ud83d\udfe1 中优";
			}
			return "\ud83d\udfe2 低优";
		}

		private string GetRiskLevel(double riskScore)
		{
			if (riskScore >= 80.0)
			{
				return "严重";
			}
			if (riskScore >= 60.0)
			{
				return "高危";
			}
			if (riskScore >= 40.0)
			{
				return "中危";
			}
			return "低危";
		}

		private void AttackPathListBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			object selectedItem = AttackPathListBox.SelectedItem;
			AttackPathDisplayModel selectedPath = selectedItem as AttackPathDisplayModel;
			if (selectedPath != null)
			{
				AttackPath val = ((IEnumerable<AttackPath>)_attackPaths).FirstOrDefault((Func<AttackPath, bool>)((AttackPath p) => p.PathId == selectedPath.PathId));
				if (val != null)
				{
					ShowAttackPathDetail(val);
				}
			}
		}

		private void ShowAttackPathDetail(AttackPath path)
		{
			EmptyStatePanel.Visibility = Visibility.Collapsed;
			DetailPanel.Visibility = Visibility.Visible;
			DetailNameText.Text = path.Name;
			DetailDescriptionText.Text = path.Description;
			DetailRiskScoreText.Text = path.RiskScore.ToString("F1");
			DetailRiskScoreBar.Value = path.RiskScore;
			DetailSuccessProbText.Text = $"{path.SuccessProbability:F0}%";
			DetailSuccessProbBar.Value = path.SuccessProbability;
			DetailEstimatedTimeText.Text = EstimateAttackTime(path);
			DetailComplexityText.Text = $"复杂度: {path.Complexity}/10";
			DetailPriorityText.Text = GetPriorityLevel(path);
			DetailPriorityText.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(GetPriorityLevel(path).Contains("P0") ? "#c0392b" : (GetPriorityLevel(path).Contains("P1") ? "#e67e22" : (GetPriorityLevel(path).Contains("P2") ? "#f39c12" : "#27ae60"))));
			DetailStepCountText.Text = $"步骤: {path.Steps.Count}";
			DetailImpactText.Text = path.Impact;
			AttackStepsPanel.Children.Clear();
			for (int i = 0; i < path.Steps.Count; i++)
			{
				AttackStep step = path.Steps[i];
				Border element = CreateStepVisual(step, i == path.Steps.Count - 1);
				AttackStepsPanel.Children.Add(element);
			}
			DefenseAdvicePanel.Children.Clear();
			foreach (string item in GenerateDefenseAdvices(path))
			{
				Border element2 = CreateDefenseAdviceItem(item);
				DefenseAdvicePanel.Children.Add(element2);
			}
			StatusText.Text = "正在查看: " + path.Name;
		}

