		private List<string> GenerateDefenseAdvices(AttackPath path)
		{
			List<string> list = new List<string>();
			List<string> source = (from s in path.Steps
				where !string.IsNullOrEmpty(s.TargetPort)
				select s.TargetPort).Distinct().ToList();
			List<string> source2 = (from s in path.Steps
				where !string.IsNullOrEmpty(s.RequiredVulnerability)
				select s.RequiredVulnerability).Distinct().ToList();
			if (path.Name.Contains("Web", StringComparison.OrdinalIgnoreCase))
			{
				list.Add("部署Web应用防火墙(WAF)，配置OWASP核心规则集");
				list.Add("启用HTTPS加密传输，配置TLS 1.3及以上版本，禁用弱加密算法");
				list.Add("实施内容安全策略(CSP)，防止XSS攻击");
				if (source2.Any((string v) => v.Contains("SQL", StringComparison.OrdinalIgnoreCase)))
				{
					list.Add("使用参数化查询和ORM框架，彻底消除SQL注入风险");
				}
				if (source2.Any((string v) => v.Contains("上传", StringComparison.OrdinalIgnoreCase)))
				{
					list.Add("配置严格的文件上传验证，限制类型、大小并使用独立域名存储");
				}
				list.Add("定期进行渗透测试和代码审计");
			}
			if (path.Name.Contains("远程", StringComparison.OrdinalIgnoreCase))
			{
				list.Add("强制启用双因素认证(2FA)，禁用纯密码认证");
				list.Add("配置IP白名单和地理围栏，限制SSH/RDP访问来源");
				list.Add("使用fail2ban等工具配置失败登录自动封禁");
				if (source.Any((string p) => p.Contains("23")))
				{
					list.Add("立即禁用Telnet服务，改用SSH加密通信");
				}
				if (source.Any((string p) => p.Contains("22")))
				{
					list.Add("禁用SSH密码登录，仅允许密钥认证，修改默认端口");
				}
				list.Add("配置sudo最小权限，禁止root直接远程登录");
			}
			if (path.Name.Contains("数据库", StringComparison.OrdinalIgnoreCase))
			{
				list.Add("数据库端口禁止对外暴露，仅允许应用服务器通过内网访问");
				list.Add("实施最小权限原则，为每个应用创建独立数据库账户");
				list.Add("启用数据库审计日志，实时监控异常SQL查询和访问模式");
				list.Add("配置定期自动备份，验证备份恢复流程");
				if (source.Any((string p) => p.Contains("6379") || p.Contains("27017")))
				{
					list.Add("Redis/MongoDB等NoSQL数据库必须配置认证密码并绑定内网IP");
				}
			}
			if (path.Name.Contains("文件", StringComparison.OrdinalIgnoreCase))
			{
				list.Add("关闭FTP匿名访问，使用SFTP或FTPS替代明文FTP");
				if (source.Any((string p) => p.Contains("445") || p.Contains("139")))
				{
					list.Add("更新SMB服务补丁，禁用SMBv1协议，配置访问控制列表");
				}
				list.Add("配置文件完整性监控，定期扫描恶意文件和后门");
				list.Add("限制文件上传目录执行权限，防止WebShell执行");
			}
			if (path.Name.Contains("组合", StringComparison.OrdinalIgnoreCase))
			{
				list.Add("实施纵深防御策略，单一防护层被突破仍有其他防护");
				list.Add("部署网络入侵检测系统(IDS)，监控异常流量和攻击特征");
				list.Add("实施网络分段和微隔离，限制攻击者横向移动");
				list.Add("建立安全事件响应中心(SOC)，实现7x24小时安全监控");
				list.Add("制定漏洞修复SLA，高风险漏洞24小时内必须修复");
			}
			if (list.Count == 0)
			{
				list.Add("定期进行安全评估和漏洞扫描");
				list.Add("及时更新系统和应用程序安全补丁");
				list.Add("配置防火墙规则，遵循最小开放原则");
				list.Add("部署入侵检测和防御系统(IDS/IPS)");
				list.Add("建立安全事件响应流程和应急预案");
			}
			return list;
		}

		private void RefreshButton_Click(object sender, RoutedEventArgs e)
		{
			LoadAttackPaths();
			StatusText.Text = "已刷新攻击路径列表";
