	public class AuditLogWindow : Window, IComponentConnector
	{
		private readonly AuthService _authService;

		private List<AuditEntry> _all = new List<AuditEntry>();

		internal TextBlock InfoText;

		internal System.Windows.Controls.ComboBox ActionFilter;

		internal System.Windows.Controls.TextBox TargetFilter;

		internal DataGrid AuditGrid;

		internal TextBlock StatusText;

		internal System.Windows.Controls.Button ClearButton;

		private bool _contentLoaded;

		public AuditLogWindow()
		{
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Expected O, but got Unknown
			InitializeComponent();
			_authService = new AuthService();
			base.Loaded += AuditLogWindow_Loaded;
		}

		private void AuditLogWindow_Loaded(object sender, RoutedEventArgs e)
		{
			User current = SessionContext.Instance.Current;
			if (current == null || !current.IsAdmin)
			{
				System.Windows.MessageBox.Show("此功能仅限管理员使用。", "权限不足", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				Close();
				return;
			}
			ActionFilter.Items.Add("全部");
			string[] array = new string[7] { "APPROVE", "REJECT", "SET_PERMS", "DISABLE", "ENABLE", "RESET_PWD", "CLEAR_AUDIT" };
			foreach (string newItem in array)
			{
				ActionFilter.Items.Add(newItem);
			}
			ActionFilter.SelectedIndex = 0;
			LoadAll();
		}

		private void LoadAll()
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Expected O, but got Unknown
			try
			{
				AuthService val = new AuthService();
				_all = val.GetAuditEntries(2000);
				InfoText.Text = $"共 {_all.Count} 条审计记录（最近 2000 条）";
				ApplyFilter();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("加载审计日志失败：" + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private void ApplyFilter()
		{
			string action = (ActionFilter.SelectedItem as string) ?? "全部";
			string target = TargetFilter.Text?.Trim() ?? "";
			IEnumerable<AuditEntry> source = _all.AsEnumerable();
			if (action != "全部")
			{
				source = source.Where((AuditEntry x) => x.Action == action);
			}
			if (!string.IsNullOrEmpty(target))
			{
				source = source.Where((AuditEntry x) => (x.Target ?? "").Contains(target, StringComparison.OrdinalIgnoreCase) || (x.Actor ?? "").Contains(target, StringComparison.OrdinalIgnoreCase));
			}
			List<AuditEntry> list = source.ToList();
			AuditGrid.ItemsSource = list;
			StatusText.Text = $"显示 {list.Count} / {_all.Count} 条";
		}

		private void Filter_Changed(object sender, EventArgs e)
		{
			if (base.IsLoaded)
			{
				ApplyFilter();
			}
		}

		private void RefreshButton_Click(object sender, RoutedEventArgs e)
		{
			LoadAll();
		}

		private void ExportButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
				{
					Filter = "JSON文件|*.json|CSV文件|*.csv",
					FileName = $"审计日志_{DateTime.Now:yyyyMMdd_HHmmss}",
					Title = "导出审计日志"
				};
				if (saveFileDialog.ShowDialog() != true)
				{
					return;
				}
				List<AuditEntry> list = (AuditGrid.ItemsSource as IEnumerable<AuditEntry>)?.ToList() ?? new List<AuditEntry>();
				if (list.Count == 0)
				{
					list = _all;
				}
				if (System.IO.Path.GetExtension(saveFileDialog.FileName).ToLower() == ".json")
				{
					string contents = JsonSerializer.Serialize(list, new JsonSerializerOptions
					{
						WriteIndented = true
					});
					File.WriteAllText(saveFileDialog.FileName, contents);
				}
				else
				{
					StringBuilder stringBuilder = new StringBuilder();
					stringBuilder.AppendLine("时间,操作者,动作,目标,结果,详情");
					foreach (AuditEntry item in list)
					{
						StringBuilder stringBuilder2 = stringBuilder;
						StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(7, 6, stringBuilder2);
						handler.AppendFormatted(item.AtDisplay);
						handler.AppendLiteral(",");
						handler.AppendFormatted(item.Actor);
						handler.AppendLiteral(",");
						handler.AppendFormatted(item.Action);
						handler.AppendLiteral(",");
						handler.AppendFormatted(item.Target);
						handler.AppendLiteral(",");
						handler.AppendFormatted(item.Success ? "成功" : "失败");
						handler.AppendLiteral(",\"");
						handler.AppendFormatted(item.Detail.Replace("\"", "\"\""));
						handler.AppendLiteral("\"");
						stringBuilder2.AppendLine(ref handler);
					}
					File.WriteAllText(saveFileDialog.FileName, stringBuilder.ToString());
				}
				System.Windows.MessageBox.Show($"已导出 {list.Count} 条审计记录到：\n{saveFileDialog.FileName}", "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出失败：" + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async void ClearButton_Click(object sender, RoutedEventArgs e)
		{
			if (System.Windows.MessageBox.Show("确定清空全部审计日志吗？\n此操作不可恢复！", "确认清空", MessageBoxButton.YesNo, MessageBoxImage.Exclamation) != MessageBoxResult.Yes)
			{
				return;
			}
			try
			{
				User current = SessionContext.Instance.Current;
				if (await _authService.ClearAuditLogAsync(current.Username))
				{
					LoadAll();
					System.Windows.MessageBox.Show("审计日志已清空。", "完成", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("清空失败：" + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

