		private bool _contentLoaded;

		public BatchScanWindow()
		{
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0017: Expected O, but got Unknown
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Expected O, but got Unknown
			//IL_0083: Unknown result type (might be due to invalid IL or missing references)
			//IL_0088: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a1: Expected O, but got Unknown
			InitializeComponent();
			_batchScanManager = new BatchScanManager();
			_historyService = new ScanHistoryService();
			_parsedTargets = new List<string>();
			_ipItems = new ObservableCollection<IpScanItem>();
			_totalStopwatch = new Stopwatch();
			IpListView.ItemsSource = _ipItems;
			ConcurrencySlider.ValueChanged += delegate
			{
				ConcurrencyValueTextBlock.Text = ConcurrencySlider.Value.ToString("F0");
			};
			TimeoutSlider.ValueChanged += delegate
			{
				TimeoutValueTextBlock.Text = TimeoutSlider.Value.ToString("F0");
			};
			_elapsedTimer = new DispatcherTimer
			{
				Interval = TimeSpan.FromSeconds(1.0)
			};
			_elapsedTimer.Tick += delegate
			{
				if (_totalStopwatch.IsRunning)
				{
					ElapsedTimeTextBlock.Text = $"已用时间: {_totalStopwatch.Elapsed:hh\\:mm\\:ss}";
					if (_completedCount > 0)
					{
						TimeSpan value = TimeSpan.FromMilliseconds(_totalStopwatch.Elapsed.TotalMilliseconds / (double)_completedCount * (double)(_parsedTargets.Count - _completedCount - _failedCount));
						RemainingTimeTextBlock.Text = $"预计剩余: {value:hh\\:mm\\:ss}";
					}
				}
			};
			BatchTargetTypeComboBox.SelectedIndex = 0;
		}

		private void BatchTargetTypeComboBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			if (BatchTargetTypeComboBox?.SelectedItem is ComboBoxItem { Tag: var tag })
			{
				string text = tag?.ToString();
				TextBlock batchTargetHintTextBlock = BatchTargetHintTextBlock;
				batchTargetHintTextBlock.Text = text switch
				{
					"Range" => "提示：输入 IP 段，如 192.168.1.1-192.168.1.254", 
					"CIDR" => "提示：输入 CIDR 格式，如 192.168.1.0/24", 
					"File" => "提示：点击'导入目标文件'按钮选择文件", 
					"List" => "提示：每行输入一个 IP 地址", 
					_ => "提示：输入目标值", 
				};
				ImportFileButton.Visibility = ((!(text == "File")) ? Visibility.Collapsed : Visibility.Visible);
			}
		}

		private void ImportFileButton_Click(object sender, RoutedEventArgs e)
		{
			Microsoft.Win32.OpenFileDialog openFileDialog = new Microsoft.Win32.OpenFileDialog
			{
				Filter = "文本文件|*.txt|所有文件|*.*",
				Title = "选择目标列表文件"
			};
			if (openFileDialog.ShowDialog() == true)
			{
				BatchTargetValueTextBox.Text = openFileDialog.FileName;
			}
