		private void ParseTargetsButton_Click(object sender, RoutedEventArgs e)
		{
			//IL_0094: Unknown result type (might be due to invalid IL or missing references)
			//IL_00aa: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ac: Unknown result type (might be due to invalid IL or missing references)
			//IL_00af: Unknown result type (might be due to invalid IL or missing references)
			//IL_0099: Unknown result type (might be due to invalid IL or missing references)
			//IL_009e: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a8: Unknown result type (might be due to invalid IL or missing references)
			try
			{
				string text = BatchTargetValueTextBox.Text.Trim();
				if (string.IsNullOrEmpty(text))
				{
					System.Windows.MessageBox.Show("请输入目标值", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
				else
				{
					if (!(BatchTargetTypeComboBox.SelectedItem is ComboBoxItem { Tag: var tag }))
					{
						return;
					}
					_parsedTargets = TargetParser.ParseTargets(text, (TargetType)(tag?.ToString() switch
					{
						"Range" => 1, 
						"CIDR" => 2, 
						"File" => 3, 
						"List" => 0, 
						_ => 0, 
					}));
					if (_parsedTargets.Any())
					{
						_ipItems.Clear();
						foreach (string parsedTarget in _parsedTargets)
						{
							_ipItems.Add(new IpScanItem
							{
								IpAddress = parsedTarget,
								Status = "等待中",
								StatusIcon = "...",
								ProgressText = "0%",
								DurationText = "00:00"
							});
						}
						ParsedTargetCountTextBlock.Text = $"已解析: {_parsedTargets.Count} 个目标";
						ParsedTargetCountTextBlock.Foreground = System.Windows.Media.Brushes.Green;
						TotalTargetsTextBlock.Text = $"总目标: {_parsedTargets.Count}";
						System.Windows.MessageBox.Show($"成功解析 {_parsedTargets.Count} 个扫描目标", "解析成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					}
					else
					{
						ParsedTargetCountTextBlock.Text = "已解析: 0 个目标";
						ParsedTargetCountTextBlock.Foreground = System.Windows.Media.Brushes.Red;
						System.Windows.MessageBox.Show("未能解析到有效的扫描目标", "解析失败", MessageBoxButton.OK, MessageBoxImage.Exclamation);
					}
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("解析目标失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async void StartBatchScanButton_Click(object sender, RoutedEventArgs e)
		{
			if (!_parsedTargets.Any())
			{
				System.Windows.MessageBox.Show("请先解析扫描目标", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			_completedCount = 0;
			_failedCount = 0;
			_totalVulns = 0;
			_totalCritical = 0;
			_cancellationTokenSource = new CancellationTokenSource();
			CancellationToken token = _cancellationTokenSource.Token;
			StartBatchScanButton.IsEnabled = false;
			StopBatchScanButton.IsEnabled = true;
			ExportBatchReportButton.IsEnabled = false;
			_totalStopwatch.Restart();
			_elapsedTimer.Start();
			int concurrency = (int)ConcurrencySlider.Value;
			int timeoutMs = (int)TimeoutSlider.Value * 1000;
			PortScanner portScanner = new PortScanner();
			VulnerabilityScanner vulnScanner = new VulnerabilityScanner();
			try
			{
				await vulnScanner.InitializeAsync(token);
				SemaphoreSlim semaphore = new SemaphoreSlim(concurrency);
				await Task.WhenAll(_parsedTargets.Select((string ip, int index) => ScanSingleTargetAsync(ip, index, semaphore, timeoutMs, token, portScanner, vulnScanner)).ToList());
			}
			catch (OperationCanceledException)
			{
			}
			finally
			{
				_totalStopwatch.Stop();
				_elapsedTimer.Stop();
				StartBatchScanButton.IsEnabled = true;
				StopBatchScanButton.IsEnabled = false;
				ExportBatchReportButton.IsEnabled = true;
				BatchScanStatusTextBlock.Text = "扫描完成";
				ElapsedTimeTextBlock.Text = $"已用时间: {_totalStopwatch.Elapsed:hh\\:mm\\:ss}";
				RemainingTimeTextBlock.Text = "预计剩余: 00:00:00";
				System.Windows.MessageBox.Show($"批量扫描完成！\n\n总目标: {_parsedTargets.Count}\n已完成: {_completedCount}\n失败: {_failedCount}\n总漏洞: {_totalVulns}\n严重漏洞: {_totalCritical}\n耗时: {_totalStopwatch.Elapsed:hh\\:mm\\:ss}", "扫描完成", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
		}

		private async Task ScanSingleTargetAsync(string ip, int index, SemaphoreSlim semaphore, int timeoutMs, CancellationToken token, PortScanner portScanner, VulnerabilityScanner vulnScanner)
		{
			string ip2 = ip;
			await semaphore.WaitAsync(token);
			Stopwatch itemStopwatch = new Stopwatch();
			try
			{
				((DispatcherObject)this).Dispatcher.BeginInvoke((Delegate)(Action)delegate
				{
					_ipItems[index].Status = "扫描中";
					_ipItems[index].StatusIcon = "-->";
					CurrentScanningTargetTextBlock.Text = "当前: " + ip2;
					BatchScanStatusTextBlock.Text = "正在扫描 " + ip2 + "...";
				}, Array.Empty<object>());
				itemStopwatch.Start();
				List<int> list = new List<int>
				{
					21, 22, 23, 25, 53, 80, 110, 135, 139, 143,
					443, 445, 993, 995, 1433, 1521, 3306, 3389, 5432, 5900,
					6379, 8080, 8443, 9200, 27017
				};
				Progress<int> progress = new Progress<int>(delegate(int p)
				{
					((DispatcherObject)this).Dispatcher.BeginInvoke((Delegate)(Action)delegate
					{
						_ipItems[index].ProgressText = $"{p}%";
						_ipItems[index].DurationText = itemStopwatch.Elapsed.ToString("mm\\:ss");
					}, Array.Empty<object>());
				});
				List<PortScanResult> openPorts = (await portScanner.ScanTcpPortsAsync(ip2, list, (IProgress<int>)progress, token, (ScanPolicy)null)).Where((PortScanResult x) => x.Status == "开放").ToList();
				List<VulnerabilityResult> vulnResults = new List<VulnerabilityResult>();
				if (openPorts.Count > 0)
				{
					vulnResults = (await vulnScanner.ScanVulnerabilitiesAsync(ip2, openPorts, token)).ToList();
				}
				itemStopwatch.Stop();
				((DispatcherObject)this).Dispatcher.BeginInvoke((Delegate)(Action)delegate
				{
					_ipItems[index].Status = "已完成";
					_ipItems[index].StatusIcon = "OK";
					_ipItems[index].ProgressText = "100%";
					_ipItems[index].DurationText = itemStopwatch.Elapsed.ToString("mm\\:ss");
					_ipItems[index].PortResults = openPorts;
					_ipItems[index].VulnResults = vulnResults;
					_ipItems[index].OpenPortsCount = openPorts.Count;
					_ipItems[index].VulnCount = vulnResults.Count;
					_ipItems[index].CriticalCount = vulnResults.Count((VulnerabilityResult v) => v.RiskLevel == "严重" || v.RiskLevel == "严重风险");
					_ipItems[index].HighCount = vulnResults.Count((VulnerabilityResult v) => v.RiskLevel == "高" || v.RiskLevel == "高危" || v.RiskLevel == "高风险");
					if (_ipItems[index].CriticalCount > 0)
					{
						_ipItems[index].ThreatLevel = "Critical";
					}
					else if (_ipItems[index].HighCount > 0)
					{
						_ipItems[index].ThreatLevel = "High";
					}
					else if (_ipItems[index].VulnCount > 0)
					{
						_ipItems[index].ThreatLevel = "Medium";
					}
					else if (_ipItems[index].OpenPortsCount > 0)
					{
						_ipItems[index].ThreatLevel = "Low";
					}
					else
					{
						_ipItems[index].ThreatLevel = "None";
					}
					Interlocked.Increment(ref _completedCount);
					Interlocked.Add(ref _totalVulns, vulnResults.Count);
					Interlocked.Add(ref _totalCritical, _ipItems[index].CriticalCount);
					UpdateGlobalStatistics();
					UpdateProgressBar();
				}, Array.Empty<object>());
			}
			catch (OperationCanceledException)
			{
				throw;
			}
			catch (Exception ex3)
			{
				Exception ex4 = ex3;
				Exception ex = ex4;
				itemStopwatch.Stop();
				((DispatcherObject)this).Dispatcher.BeginInvoke((Delegate)(Action)delegate
				{
					_ipItems[index].Status = "失败";
					_ipItems[index].StatusIcon = "X";
					_ipItems[index].ProgressText = "失败";
					_ipItems[index].DurationText = itemStopwatch.Elapsed.ToString("mm\\:ss");
					_ipItems[index].ErrorMessage = ex.Message;
					Interlocked.Increment(ref _failedCount);
					UpdateGlobalStatistics();
					UpdateProgressBar();
				}, Array.Empty<object>());
			}
			finally
			{
				semaphore.Release();
			}
		}

		private void UpdateGlobalStatistics()
		{
			CompletedTargetsTextBlock.Text = $"已完成: {_completedCount}";
			FailedTargetsTextBlock.Text = $"失败: {_failedCount}";
			TotalVulnerabilitiesTextBlock.Text = $"总漏洞: {_totalVulns}";
			TotalCriticalTextBlock.Text = $"严重: {_totalCritical}";
		}

		private void UpdateProgressBar()
		{
			int count = _parsedTargets.Count;
			int num = _completedCount + _failedCount;
			BatchScanProgressBar.Value = ((count > 0) ? ((double)num / (double)count * 100.0) : 0.0);
			BatchScanProgressTextBlock.Text = $"{num}/{count}";
		}

		private void IpListView_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			if (IpListView.SelectedItem is IpScanItem ipScanItem)
			{
				SelectedIpTextBlock.Text = ipScanItem.IpAddress;
				SelectedIpStatusTextBlock.Text = "状态: " + ipScanItem.Status;
				SelectedIpPortsTextBlock.Text = $"开放端口: {ipScanItem.OpenPortsCount}";
				SelectedIpVulnsTextBlock.Text = $"漏洞: {ipScanItem.VulnCount}";
				PortResultDataGrid.ItemsSource = ipScanItem.PortResults;
				VulnResultDataGrid.ItemsSource = ipScanItem.VulnResults;
			}
		}

		private void StopBatchScanButton_Click(object sender, RoutedEventArgs e)
		{
			_cancellationTokenSource?.Cancel();
			BatchScanStatusTextBlock.Text = "正在停止...";
		}

		private async void ExportBatchReportButton_Click(object sender, RoutedEventArgs e)
		{
			await ExportBatchReportAsync();
		}

		private async Task ExportBatchReportAsync()
		{
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Filter = "HTML文件|*.html|CSV文件|*.csv",
				FileName = $"批量扫描报告_{DateTime.Now:yyyyMMdd_HHmmss}",
				Title = "保存批量扫描报告"
			};
			if (saveFileDialog.ShowDialog() != true)
			{
				return;
			}
			try
			{
				string filePath = saveFileDialog.FileName;
				if (System.IO.Path.GetExtension(filePath).ToLower() == ".html")
				{
					string contents = GenerateHtmlReport();
					await File.WriteAllTextAsync(filePath, contents);
				}
				else
				{
					string contents2 = GenerateCsvReport();
					await File.WriteAllTextAsync(filePath, contents2);
				}
				System.Windows.MessageBox.Show("报告已保存到:\n" + filePath, "报告生成成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("生成报告失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private string GenerateHtmlReport()
		{
