			}
			stringBuilder.AppendLine("<p style='text-align:center;color:#7f8c8d;margin-top:40px'>由 NetSecurityScanner 生成</p></body></html>");
			return stringBuilder.ToString();
		}

		private string GenerateCsvReport()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("IP地址,状态,开放端口数,漏洞数,严重,高危,扫描时长,错误信息");
			foreach (IpScanItem ipItem in _ipItems)
			{
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(7, 8, stringBuilder2);
				handler.AppendFormatted(ipItem.IpAddress);
				handler.AppendLiteral(",");
				handler.AppendFormatted(ipItem.Status);
				handler.AppendLiteral(",");
				handler.AppendFormatted(ipItem.OpenPortsCount);
