			{
				"Critical" => new SolidColorBrush(System.Windows.Media.Color.FromRgb(231, 76, 60)), 
				"High" => new SolidColorBrush(System.Windows.Media.Color.FromRgb(230, 126, 34)), 
				"Medium" => new SolidColorBrush(System.Windows.Media.Color.FromRgb(241, 196, 15)), 
				"Low" => new SolidColorBrush(System.Windows.Media.Color.FromRgb(byte.MaxValue, 235, 156)), 
				null => System.Windows.Media.Brushes.Transparent, 
				_ => System.Windows.Media.Brushes.Transparent, 
			};
		}

		public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
		{
			throw new NotImplementedException();
		}
	}
	public class ThreatLevelToForegroundConverter : IValueConverter
	{
		public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
		{
			if (value is string text && text != "None")
			{
				return System.Windows.Media.Brushes.White;
			}
			return new SolidColorBrush(System.Windows.Media.Color.FromRgb(44, 62, 80));
		}

		public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
		{
			throw new NotImplementedException();
		}
	}
