				List<CameraVulnerability> list = _camera.Vulnerabilities ?? new List<CameraVulnerability>();
				int value = list.Count((CameraVulnerability v) => MatchesLevel(v.Severity, "严重"));
				int value2 = list.Count((CameraVulnerability v) => MatchesLevel(v.Severity, "高"));
				int value3 = list.Count((CameraVulnerability v) => MatchesLevel(v.Severity, "中"));
				VulnTotalText.Text = $"漏洞总数: {list.Count}";
				VulnCriticalText.Text = $"严重: {value}";
				VulnHighText.Text = $"高危: {value2}";
