		private void BuildBasicInfo()
		{
			BasicInfoGrid.Children.Clear();
			List<(string, string)> obj = new List<(string, string)>
			{
				("IP", _camera.Ip ?? "--"),
				("IP 类型", _camera.IpType ?? "--"),
				("厂商", _camera.Vendor ?? "--"),
				("型号", _camera.Model ?? "--"),
				("固件版本", _camera.FirmwareVersion ?? "--"),
				("序列号", _camera.SerialNumber ?? "--"),
				("MAC 地址", _camera.Mac ?? "--"),
				("在线状态", _camera.IsOnline ? "在线" : "离线"),
				("开放端口", (_camera.OpenPorts?.Count ?? 0).ToString()),
				("扫描时间", (_camera.ScanTime == default(DateTime)) ? "--" : _camera.ScanTime.ToString("yyyy-MM-dd HH:mm:ss")),
				("响应时间", $"{_camera.ResponseTimeMs} ms")
			};
			CameraRiskAssessment riskAssessment = _camera.RiskAssessment;
			obj.Add(("风险等级", ((riskAssessment != null) ? riskAssessment.RiskLevel : null) ?? "--"));
			List<(string, string)> list = obj;
			Style style = new Style(typeof(TextBlock));
			style.Setters.Add(new Setter(TextBlock.FontWeightProperty, FontWeights.SemiBold));
			style.Setters.Add(new Setter(TextBlock.ForegroundProperty, new SolidColorBrush(System.Windows.Media.Color.FromRgb(51, 65, 85))));
			style.Setters.Add(new Setter(FrameworkElement.MarginProperty, new Thickness(0.0, 6.0, 8.0, 6.0)));
			Style style2 = new Style(typeof(TextBlock));
			style2.Setters.Add(new Setter(TextBlock.ForegroundProperty, new SolidColorBrush(System.Windows.Media.Color.FromRgb(30, 41, 59))));
			style2.Setters.Add(new Setter(FrameworkElement.MarginProperty, new Thickness(0.0, 6.0, 0.0, 6.0)));
			style2.Setters.Add(new Setter(TextBlock.TextWrappingProperty, TextWrapping.Wrap));
			for (int i = 0; i < list.Count; i++)
			{
				(string, string) tuple = list[i];
				string item = tuple.Item1;
				string item2 = tuple.Item2;
				TextBlock element = new TextBlock
				{
					Text = item,
					Style = style
				};
				TextBlock element2 = new TextBlock
				{
					Text = item2,
					Style = style2
				};
				Grid.SetRow(element, i);
				Grid.SetColumn(element, 0);
				Grid.SetRow(element2, i);
				Grid.SetColumn(element2, 1);
				BasicInfoGrid.Children.Add(element);
				BasicInfoGrid.Children.Add(element2);
			}
		}

		private static bool MatchesLevel(string? severity, string keyword)
		{
			if (string.IsNullOrEmpty(severity))
			{
				return false;
			}
			string text = severity.Trim();
			if (text.Equals(keyword, StringComparison.OrdinalIgnoreCase))
			{
				return true;
			}
			return text.Contains(keyword);
		}

		private static System.Windows.Media.Brush LevelToBrush(string level)
		{
			if (string.IsNullOrEmpty(level))
			{
				return new SolidColorBrush(System.Windows.Media.Color.FromRgb(149, 165, 166));
			}
			if (level.Contains("严重"))
			{
				return new SolidColorBrush(System.Windows.Media.Color.FromRgb(192, 57, 43));
			}
			if (level.Contains("高"))
			{
				return new SolidColorBrush(System.Windows.Media.Color.FromRgb(230, 126, 34));
			}
			if (level.Contains("中"))
			{
				return new SolidColorBrush(System.Windows.Media.Color.FromRgb(243, 156, 18));
			}
			if (level.Contains("低"))
			{
				return new SolidColorBrush(System.Windows.Media.Color.FromRgb(39, 174, 96));
			}
			return new SolidColorBrush(System.Windows.Media.Color.FromRgb(52, 152, 219));
		}

