			stackPanel.Children.Add(new TextBlock
			{
				Text = "监控间隔（分钟）:",
				FontWeight = FontWeights.Bold,
				Margin = new Thickness(0.0, 0.0, 0.0, 6.0)
			});
			System.Windows.Controls.ComboBox intervalCombo = new System.Windows.Controls.ComboBox
			{
				Name = "IntervalCombo",
				Padding = new Thickness(6.0),
				FontSize = 13.0
			};
			int[] array = new int[6] { 5, 10, 15, 30, 60, 120 };
			foreach (int num in array)
			{
				intervalCombo.Items.Add(num);
			}
			intervalCombo.SelectedIndex = 3;
			stackPanel.Children.Add(intervalCombo);
			System.Windows.Controls.CheckBox soundCheck = new System.Windows.Controls.CheckBox
			{
				Content = "启用声音告警",
				Margin = new Thickness(0.0, 12.0, 0.0, 0.0),
				IsChecked = false
			};
			stackPanel.Children.Add(soundCheck);
			StackPanel stackPanel2 = new StackPanel
			{
				Orientation = System.Windows.Controls.Orientation.Horizontal,
				HorizontalAlignment = System.Windows.HorizontalAlignment.Right,
				Margin = new Thickness(0.0, 20.0, 0.0, 0.0)
			};
			System.Windows.Controls.Button button = new System.Windows.Controls.Button
			{
				Content = "启动",
				Width = 80.0,
				Height = 30.0,
				Margin = new Thickness(0.0, 0.0, 8.0, 0.0),
				IsDefault = true
			};
			button.Click += delegate
			{
				if (intervalCombo.SelectedItem is int intervalMinutes)
				{
					cameraMonitorDialog.IntervalMinutes = intervalMinutes;
				}
				cameraMonitorDialog.EnableSound = soundCheck.IsChecked == true;
				cameraMonitorDialog.DialogResult = true;
				cameraMonitorDialog.Close();
			};
			System.Windows.Controls.Button element = new System.Windows.Controls.Button
			{
				Content = "取消",
				Width = 80.0,
				Height = 30.0,
				IsCancel = true
			};
			stackPanel2.Children.Add(button);
			stackPanel2.Children.Add(element);
			stackPanel.Children.Add(stackPanel2);
			base.Content = stackPanel;
		}
	}
