				Directory.CreateDirectory(text);
				string path = System.IO.Path.Combine(text, $"app_{DateTime.Now:yyyyMMdd}.log");
				string text2 = $"CameraSecurityScannerWindow InitializeComponent失败: {ex.GetType().FullName}: {ex.Message}\n堆栈: {ex.StackTrace}";
				if (ex.InnerException != null)
				{
					text2 += $"\n内部异常: {ex.InnerException.GetType().FullName}: {ex.InnerException.Message}\n内部堆栈: {ex.InnerException.StackTrace}";
				}
				File.AppendAllText(path, $"[{DateTime.Now:HH:mm:ss.fff}] {text2}{Environment.NewLine}");
				throw;
			}
			UpdateStatusBar();
		}

		private void LoadTemplates()
		{
			//IL_0019: Unknown result type (might be due to invalid IL or missing references)
			if (TemplateComboBox == null)
			{
				return;
			}
			TemplateComboBox.Items.Clear();
			foreach (CameraScanTemplate template in new CameraScanTemplateService().Templates)
			{
				TemplateComboBox.Items.Add(template.Name + " - " + template.Description);
			}
			TemplateComboBox.SelectedIndex = -1;
		}

		private void TemplateComboBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			System.Windows.Controls.ComboBox templateComboBox = TemplateComboBox;
			if (templateComboBox == null || templateComboBox.SelectedIndex >= 0)
			{
				List<CameraScanTemplate> defaultTemplates = CameraScanTemplate.GetDefaultTemplates();
				if (TemplateComboBox.SelectedIndex < defaultTemplates.Count)
				{
					CameraScanTemplate val = defaultTemplates[TemplateComboBox.SelectedIndex];
					ScanStatusText.Text = "状态: 已选择模板 [" + val.Name + "] - 端口: " + string.Join(",", val.Ports);
				}
			}
		}

		private void LoadTagFilter()
		{
			try
			{
				if (TagFilterComboBox == null)
				{
					return;
				}
				_cachedTags = _tagService.GetAll();
				TagFilterComboBox.Items.Clear();
				TagFilterComboBox.Items.Add(new ComboBoxItem
				{
					Content = "（全部）",
					Tag = string.Empty,
					IsSelected = true
				});
				foreach (CameraTag cachedTag in _cachedTags)
				{
					TagFilterComboBox.Items.Add(new ComboBoxItem
					{
						Content = cachedTag.Name,
						Tag = cachedTag.TagId
					});
				}
				TagFilterComboBox.DisplayMemberPath = "Content";
			}
			catch (Exception ex)
			{
				WriteDiagLog("LoadTagFilter 异常: " + ex.Message);
			}
		}

