		private void ContextCopyCve_Click(object sender, RoutedEventArgs e)
		{
			object obj = CameraDataGrid?.SelectedItem;
			CameraScanResult val = (CameraScanResult)((obj is CameraScanResult) ? obj : null);
			if (val == null)
			{
				return;
			}
			List<string> list = (from v in val.Vulnerabilities?.Where((CameraVulnerability v) => !string.IsNullOrWhiteSpace(v.CveId))
				select v.CveId).Distinct().ToList();
			if (list == null || list.Count == 0)
			{
				System.Windows.MessageBox.Show("当前设备无 CVE 漏洞可复制", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			try
			{
				System.Windows.Clipboard.SetText(string.Join(Environment.NewLine, list));
				ScanStatusText.Text = $"状态: 已复制 {list.Count} 个 CVE";
			}
			catch
			{
			}
		}

