		private void ContextOpenNvd_Click(object sender, RoutedEventArgs e)
		{
			object obj = CameraDataGrid?.SelectedItem;
			CameraScanResult val = (CameraScanResult)((obj is CameraScanResult) ? obj : null);
			if (val == null)
			{
				return;
			}
			string text = (from v in val.Vulnerabilities?.Where((CameraVulnerability v) => !string.IsNullOrWhiteSpace(v.CveId))
				select v.CveId).FirstOrDefault();
			if (string.IsNullOrEmpty(text))
			{
				System.Windows.MessageBox.Show("当前设备无 CVE 可跳转", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			try
			{
				string fileName = "https://nvd.nist.gov/vuln/detail/" + text;
				Process.Start(new ProcessStartInfo
				{
					FileName = fileName,
					UseShellExecute = true
				});
				ScanStatusText.Text = "状态: 已打开 NVD 详情 - " + text;
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("无法打开浏览器: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

