		private async void MonitorButton_Click(object sender, RoutedEventArgs e)
		{
			string text = TargetInputTextBox?.Text?.Trim();
			if (string.IsNullOrEmpty(text))
			{
				System.Windows.MessageBox.Show("请先输入要监控的 IP 列表", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			CameraMonitorDialog cameraMonitorDialog = new CameraMonitorDialog();
			if (cameraMonitorDialog.ShowDialog() != true)
			{
				return;
			}
			CameraMonitorService val = new CameraMonitorService();
			val.OnAlert += delegate(object? s, CameraAlert alert)
			{
				CameraAlert alert2 = alert;
				((DispatcherObject)this).Dispatcher.Invoke<string>((Func<string>)(() => ScanStatusText.Text = "\ud83d\udd14 告警: " + alert2.Title + " - " + alert2.Message));
			};
			CameraMonitorTask val2 = new CameraMonitorTask();
			val2.Name = "监控-" + text;
			val2.TargetIps = (from s in text.Split(',', ';')
				select s.Trim()).ToList();
			val2.IntervalMinutes = cameraMonitorDialog.IntervalMinutes;
			val2.Preset = _currentPresetName;
			val2.NotifyOnOffline = true;
			val2.NotifyOnNewVulnerability = true;
			val2.SoundAlert = cameraMonitorDialog.EnableSound;
			CameraMonitorTask val3 = val2;
			val.AddTask(val3);
			val.Start();
			ScanStatusText.Text = $"状态: 已启动持续监控，每 {cameraMonitorDialog.IntervalMinutes} 分钟扫描一次";
			System.Windows.MessageBox.Show($"持续监控已启动，间隔 {cameraMonitorDialog.IntervalMinutes} 分钟\n任务ID: {val3.TaskId}", "监控中", MessageBoxButton.OK, MessageBoxImage.Asterisk);
		}

		private void AlertsButton_Click(object sender, RoutedEventArgs e)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			List<CameraAlert> recent = new CameraAlertService().GetRecent(50);
			if (recent.Count == 0)
			{
				System.Windows.MessageBox.Show("暂无告警", "告警历史", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			StringBuilder stringBuilder = new StringBuilder();
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder3 = stringBuilder2;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(20, 1, stringBuilder2);
			handler.AppendLiteral("=== 告警历史 (共 ");
			handler.AppendFormatted(recent.Count);
			handler.AppendLiteral(" 条) ===\n");
			stringBuilder3.AppendLine(ref handler);
			foreach (CameraAlert item in recent.Take(20))
			{
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder4 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(3, 2, stringBuilder2);
				handler.AppendLiteral("[");
				handler.AppendFormatted(item.Level);
				handler.AppendLiteral("] ");
				handler.AppendFormatted(item.Title);
				stringBuilder4.AppendLine(ref handler);
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder5 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(9, 2, stringBuilder2);
				handler.AppendLiteral("  IP: ");
				handler.AppendFormatted(item.Ip);
				handler.AppendLiteral(" | ");
				handler.AppendFormatted(item.CreatedTime, "yyyy-MM-dd HH:mm:ss");
				stringBuilder5.AppendLine(ref handler);
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder6 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(3, 1, stringBuilder2);
				handler.AppendLiteral("  ");
				handler.AppendFormatted(item.Message);
				handler.AppendLiteral("\n");
				stringBuilder6.AppendLine(ref handler);
			}
			System.Windows.MessageBox.Show(stringBuilder.ToString(), "告警历史", MessageBoxButton.OK, MessageBoxImage.Asterisk);
		}

		private void LoadPresets()
		{
			if (PresetComboBox == null)
			{
				return;
			}
			PresetComboBox.Items.Clear();
			foreach (CameraScanPreset defaultPreset in CameraScanPreset.GetDefaultPresets())
			{
				PresetComboBox.Items.Add(defaultPreset.Name);
			}
			PresetComboBox.SelectedIndex = 1;
		}

		private void ApplyPreset(int index)
		{
			List<CameraScanPreset> defaultPresets = CameraScanPreset.GetDefaultPresets();
			if (index >= 0 && index < defaultPresets.Count)
			{
				CameraScanPreset val = defaultPresets[index];
				_currentPresetName = val.Name;
				if (FingerprintCheck != null)
				{
					FingerprintCheck.IsChecked = val.EnableFingerprint;
				}
				if (VulnScanCheck != null)
				{
					VulnScanCheck.IsChecked = val.EnableVulnerabilityScan;
				}
				if (WeakPasswordCheck != null)
				{
					WeakPasswordCheck.IsChecked = val.EnableWeakPasswordScan;
				}
				if (AggressiveScanCheck != null)
				{
					AggressiveScanCheck.IsChecked = val.EnableAggressiveScan;
				}
				if (ConcurrencyTextBox != null)
				{
					ConcurrencyTextBox.Text = val.MaxConcurrency.ToString();
				}
				if (TimeoutTextBox != null)
				{
					TimeoutTextBox.Text = val.TimeoutMs.ToString();
				}
			}
		}

		private void PresetComboBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			if (PresetComboBox?.SelectedItem is string text)
			{
				ApplyPreset(PresetComboBox.SelectedIndex);
				ScanStatusText.Text = "状态: 已选择扫描预设 [" + text + "]";
			}
		}

		private void RecommendButton_Click(object sender, RoutedEventArgs e)
		{
			//IL_003c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0041: Unknown result type (might be due to invalid IL or missing references)
			//IL_0052: Unknown result type (might be due to invalid IL or missing references)
			//IL_0064: Unknown result type (might be due to invalid IL or missing references)
			//IL_007b: Expected O, but got Unknown
			string text = TargetInputTextBox.Text?.Trim() ?? string.Empty;
			int num = ScanModeComboBox?.SelectedIndex ?? 0;
			int num2 = 0;
			try
			{
				num2 = CameraScannerService.EstimateIpCount(new CameraScanOptions
				{
					TargetIp = ((num == 0) ? text : string.Empty),
					IpRange = ((num == 1) ? text : string.Empty),
					CidrNotation = ((num == 2) ? text : string.Empty)
				});
			}
