		private async void StartScan_Click(object sender, RoutedEventArgs e)
		{
			WriteDiagLog("=== 点击开始扫描 ===");
			try
			{
				if (TargetInputTextBox == null)
				{
					WriteDiagLog("严重错误: TargetInputTextBox 为 null");
					System.Windows.MessageBox.Show("界面未初始化完成", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
					return;
				}
				if (ScanModeComboBox == null)
				{
					WriteDiagLog("严重错误: ScanModeComboBox 为 null");
					System.Windows.MessageBox.Show("界面未初始化完成", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
					return;
				}
				int selectedIndex = ScanModeComboBox.SelectedIndex;
				string text = TargetInputTextBox.Text?.Trim() ?? string.Empty;
				WriteDiagLog($"目标: '{text}', 模式: {selectedIndex}, UI线程: {((DispatcherObject)this).Dispatcher.CheckAccess()}");
				string text2 = string.Empty;
				string text3 = string.Empty;
				string text4 = string.Empty;
				switch (selectedIndex)
				{
				case 0:
					text2 = text;
					break;
				case 1:
					text3 = text;
					break;
				case 2:
					text4 = text;
					break;
				}
				if (string.IsNullOrEmpty(text2) && string.IsNullOrEmpty(text3) && string.IsNullOrEmpty(text4))
				{
					WriteDiagLog("用户输入为空, 提示错误并返回");
					System.Windows.MessageBox.Show("请输入目标（单IP、IP段 或 CIDR）", "输入错误", MessageBoxButton.OK, MessageBoxImage.Exclamation);
					return;
				}
				int result;
				int result2;
				CameraScanOptions options = new CameraScanOptions
				{
					TargetIp = text2,
					IpRange = text3,
					CidrNotation = text4,
					Ipv6Cidr = (text4.Contains(":") ? text4 : string.Empty),
					EnableFingerprint = (FingerprintCheck?.IsChecked ?? true),
					EnableVulnerabilityScan = (VulnScanCheck?.IsChecked ?? true),
					EnableWeakPasswordScan = (WeakPasswordCheck?.IsChecked ?? true),
					MaxConcurrency = (int.TryParse(ConcurrencyTextBox?.Text, out result) ? result : 30),
					TimeoutMs = (int.TryParse(TimeoutTextBox?.Text, out result2) ? result2 : 3000),
					UseDefaultPorts = true
				};
				WriteDiagLog($"扫描选项构建完成: TP='{text2}', IR='{text3}', CIDR='{text4}'");
				SetScanningUIState(isScanning: true);
				_allResults.Clear();
				ClearResults();
				_cts = new CancellationTokenSource();
				_elapsedTimer = Stopwatch.StartNew();
				WriteDiagLog("CTS 创建, 计时器启动, 进入扫描循环");
				try
				{
					WriteDiagLog("实例化 CameraScannerService...");
					CameraScannerService service = new CameraScannerService();
					try
					{
						Progress<CameraScanProgress> progress = new Progress<CameraScanProgress>(delegate(CameraScanProgress p)
						{
							CameraScanProgress p2 = p;
							((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
							{
								UpdateProgress(p2);
							});
						});
						WriteDiagLog("调用 Task.Run 启动 ScanCamerasAsync...");
						List<CameraScanResult> results = await Task.Run(() => service.ScanCamerasAsync(options, (IProgress<CameraScanProgress>)progress, _cts.Token));
						WriteDiagLog($"ScanCamerasAsync 返回, 共 {results?.Count ?? 0} 个结果");
						_allResults.AddRange(results ?? new List<CameraScanResult>());
						_currentTargetIps = ExtractTargetIps(options);
						CameraSecurityScannerWindow cameraSecurityScannerWindow = this;
						string obj = $"目标 IP 解析: {_currentTargetIps?.Count ?? 0} 个";
						List<string> currentTargetIps = _currentTargetIps;
						cameraSecurityScannerWindow.WriteDiagLog(obj + ((currentTargetIps != null && currentTargetIps.Count > 0) ? (" (前5: " + string.Join(",", _currentTargetIps.Take(5)) + ((_currentTargetIps.Count > 5) ? "..." : "") + ")") : ""));
						await ((DispatcherObject)this).Dispatcher.InvokeAsync((Action)delegate
						{
							DisplayResults(results ?? new List<CameraScanResult>());
							ScanStatusText.Text = "状态: 扫描完成";
							ScanProgressBar.Value = 100.0;
							ScanProgressText.Text = "100%";
							ExportReportButton.IsEnabled = results?.Any((CameraScanResult r) => r.IsOnline) ?? false;
							ExportCsvButton.IsEnabled = results?.Any((CameraScanResult r) => r.IsOnline) ?? false;
							ExportDetailJsonButton.IsEnabled = results?.Any((CameraScanResult r) => r.IsOnline) ?? false;
						});
						WriteDiagLog("UI 更新完成");
						if (results != null && results.Any((CameraScanResult r) => r.IsOnline))
						{
							SaveToHistoryAsync();
							WriteDiagLog("已触发自动保存历史");
						}
					}
					finally
					{
						service.Dispose();
						WriteDiagLog("Service 已释放");
					}
				}
				catch (OperationCanceledException)
				{
					WriteDiagLog("=== 扫描已取消 ===");
					ScanStatusText.Text = "状态: 扫描已取消";
				}
				catch (Exception ex2)
				{
					string text5 = "扫描失败: " + ex2.GetType().FullName + ": " + ex2.Message;
					WriteDiagLog("=== 扫描异常 === " + text5);
					WriteDiagLog("堆栈: " + ex2.StackTrace);
					if (ex2.InnerException != null)
					{
						WriteDiagLog("内部异常: " + ex2.InnerException.GetType().FullName + ": " + ex2.InnerException.Message);
						WriteDiagLog("内部堆栈: " + ex2.InnerException.StackTrace);
					}
					ScanStatusText.Text = "状态: 扫描失败";
					System.Windows.MessageBox.Show(text5, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				}
				finally
				{
					_cts?.Dispose();
					_cts = null;
					_elapsedTimer?.Stop();
					SetScanningUIState(isScanning: false);
					UpdateStatusBar();
					WriteDiagLog("=== 扫描流程结束 (finally) ===");
				}
			}
			catch (Exception ex3)
			{
				WriteDiagLog("=== StartScan_Click 顶层异常 === " + ex3.GetType().FullName + ": " + ex3.Message);
				WriteDiagLog("堆栈: " + ex3.StackTrace);
				try
				{
					System.Windows.MessageBox.Show("启动扫描失败: " + ex3.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				}
				catch
				{
				}
			}
		}

		private void WriteDiagLog(string message)
		{
			try
			{
				string text = System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "logs");
				Directory.CreateDirectory(text);
				string path = System.IO.Path.Combine(text, "camera_diag.log");
				string contents = $"[{DateTime.Now:HH:mm:ss.fff}] {message}{Environment.NewLine}";
				File.AppendAllText(path, contents);
			}
			catch
			{
			}
		}

		private void StopScan_Click(object sender, RoutedEventArgs e)
		{
			WriteDiagLog("=== 点击停止扫描 ===");
			if (_cts == null)
			{
				WriteDiagLog("停止忽略: _cts 为 null (无正在进行的扫描)");
				return;
			}
			try
			{
				_cts.Cancel();
				WriteDiagLog("已调用 _cts.Cancel()，等待子任务响应...");
			}
			catch (ObjectDisposedException)
			{
				WriteDiagLog("停止忽略: _cts 已被释放");
			}
			ScanStatusText.Text = "状态: 正在停止...";
		}

		private void ImportTargets_Click(object sender, RoutedEventArgs e)
		{
			Microsoft.Win32.OpenFileDialog openFileDialog = new Microsoft.Win32.OpenFileDialog
			{
				Filter = "文本文件 (*.txt)|*.txt|CSV文件 (*.csv)|*.csv|所有文件 (*.*)|*.*",
				Title = "导入IP目标列表"
			};
			if (openFileDialog.ShowDialog() != true)
			{
				return;
			}
			try
			{
				string[] array = File.ReadAllLines(openFileDialog.FileName);
				List<string> list = new List<string>();
				string[] array2 = array;
				for (int i = 0; i < array2.Length; i++)
				{
					string text = array2[i].Trim();
					if (!string.IsNullOrEmpty(text) && !text.StartsWith("#") && !text.StartsWith("//"))
					{
						list.Add(text);
					}
				}
				if (list.Count == 0)
				{
					System.Windows.MessageBox.Show("文件中未找到有效的IP地址", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				ScanModeComboBox.SelectedIndex = 1;
				TargetInputTextBox.Text = string.Join(",", list);
				ScanStatusText.Text = $"状态: 已导入 {list.Count} 个目标IP";
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导入失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async void AutoDiscover_Click(object sender, RoutedEventArgs e)
		{
			AutoDiscoverButton.IsEnabled = false;
			SetScanningUIState(isScanning: true);
			ScanStatusText.Text = "状态: 正在自动发现摄像头...";
			ScanPhaseText.Text = "自动发现";
			ScanProgressBar.IsIndeterminate = true;
			_allResults.Clear();
			ClearResults();
			try
			{
				CameraDiscoveryService discoveryService = new CameraDiscoveryService();
				try
				{
					List<DiscoveredCamera> discoveredCameras = new List<DiscoveredCamera>();
					discoveryService.CameraDiscovered += delegate(DiscoveredCamera camera)
					{
						DiscoveredCamera camera2 = camera;
						((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
						{
							discoveredCameras.Add(camera2);
							ScanStatusText.Text = $"状态: 发现 {discoveredCameras.Count} 台设备 - {camera2.Ip} ({camera2.DiscoveryMethod})";
						});
					};
					CancellationTokenSource cts = new CancellationTokenSource(TimeSpan.FromSeconds(30.0));
					List<DiscoveredCamera> list = await Task.Run(() => discoveryService.DiscoverAsync(15000, cts.Token));
					if (list.Count == 0)
					{
						System.Windows.MessageBox.Show("未发现摄像头设备。\n\n可能原因：\n1. 网络中没有启用了UPnP/ONVIF的摄像头\n2. 防火墙或VLAN隔离了发现协议\n3. 摄像头未接入同一局域网\n\n建议：手动输入IP范围进行扫描", "自动发现结果", MessageBoxButton.OK, MessageBoxImage.Asterisk);
						return;
					}
					StringBuilder stringBuilder = new StringBuilder();
					StringBuilder stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder3 = stringBuilder2;
					StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(17, 1, stringBuilder2);
					handler.AppendLiteral("自动发现完成，共发现 ");
					handler.AppendFormatted(list.Count);
					handler.AppendLiteral(" 台设备：\n");
					stringBuilder3.AppendLine(ref handler);
					foreach (DiscoveredCamera item in list)
					{
						stringBuilder2 = stringBuilder;
						StringBuilder stringBuilder4 = stringBuilder2;
						handler = new StringBuilder.AppendInterpolatedStringHandler(12, 5, stringBuilder2);
						handler.AppendLiteral("  ");
						handler.AppendFormatted(item.Ip);
						handler.AppendLiteral("  [");
						handler.AppendFormatted(item.DiscoveryMethod);
						handler.AppendLiteral("]  ");
						handler.AppendFormatted(string.IsNullOrEmpty(item.Vendor) ? "" : item.Vendor);
						handler.AppendLiteral("  ");
						handler.AppendFormatted(string.IsNullOrEmpty(item.DeviceName) ? "" : item.DeviceName);
						handler.AppendLiteral("  ");
						handler.AppendFormatted(string.IsNullOrEmpty(item.Model) ? "" : item.Model);
						stringBuilder4.AppendLine(ref handler);
					}
					stringBuilder.AppendLine("\n是否立即对发现的设备执行完整扫描？");
					if (System.Windows.MessageBox.Show(stringBuilder.ToString(), "自动发现结果", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
					{
						ScanModeComboBox.SelectedIndex = 0;
						string text = string.Join(",", list.Select((DiscoveredCamera r) => r.Ip));
						TargetInputTextBox.Text = ((list.Count == 1) ? list[0].Ip : text);
						if (list.Count == 1)
						{
							StartScan_Click(sender, e);
							return;
						}
						ImportTargets_Click(sender, e);
						StartScan_Click(sender, e);
					}
					else
					{
						ScanStatusText.Text = $"状态: 发现 {list.Count} 台设备（就绪）";
						SetScanningUIState(isScanning: false);
					}
				}
				finally
				{
					if (discoveryService != null)
					{
						((IDisposable)discoveryService).Dispose();
					}
				}
			}
			catch (OperationCanceledException)
			{
				ScanStatusText.Text = "状态: 自动发现超时";
				SetScanningUIState(isScanning: false);
			}
			catch (Exception ex2)
			{
				ScanStatusText.Text = "状态: 自动发现失败";
				System.Windows.MessageBox.Show("自动发现失败: " + ex2.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				SetScanningUIState(isScanning: false);
			}
			finally
			{
				ScanProgressBar.IsIndeterminate = false;
				AutoDiscoverButton.IsEnabled = true;
			}
		}

		private static int GetCidrFromMask(IPAddress mask)
		{
			uint num = BitConverter.ToUInt32(mask.GetAddressBytes(), 0);
			int num2 = 0;
			while (num != 0)
			{
				num2++;
				num <<= 1;
			}
			return num2;
		}

		private List<string> ExtractTargetIps(CameraScanOptions options)
		{
			try
			{
				List<string> allTargetIps = CameraScannerService.GetAllTargetIps(options);
				if (allTargetIps.Count > 0)
				{
					return allTargetIps;
				}
			}
			catch (Exception ex)
			{
				WriteDiagLog("ExtractTargetIps 解析失败: " + ex.Message);
			}
			return new List<string> { options.TargetIp };
		}

		private async Task SaveToHistoryAsync()
		{
			try
			{
				TimeSpan timeSpan = _elapsedTimer?.Elapsed ?? TimeSpan.Zero;
				var (flag, text) = await _historyService.SaveToHistoryAsync(_currentPresetName, _currentTargetIps, _allResults, timeSpan);
				if (flag)
				{
					ScanStatusText.Text = "状态: " + text;
				}
			}
			catch (Exception ex)
			{
				ScanStatusText.Text = "状态: 保存历史失败 - " + ex.Message;
			}
		}

		private async void ExportCsvButton_Click(object sender, RoutedEventArgs e)
		{
