			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async void DiagnoseButton_Click(object sender, RoutedEventArgs e)
		{
			if (!_allResults.Any((CameraScanResult r) => r.IsOnline))
			{
				System.Windows.MessageBox.Show("请先扫描摄像头，诊断需要在线摄像头数据", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			object obj = CameraDataGrid?.SelectedItem;
			CameraScanResult val = (CameraScanResult)((obj is CameraScanResult) ? obj : null);
			CameraScanResult target;
			if (val != null)
			{
				target = val;
			}
			else
			{
				target = ((IEnumerable<CameraScanResult>)_allResults).FirstOrDefault((Func<CameraScanResult, bool>)((CameraScanResult r) => r.IsOnline));
				if (target != null)
				{
					CameraDataGrid.SelectedItem = target;
				}
			}
			if (target == null)
			{
				System.Windows.MessageBox.Show("未找到在线摄像头", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			DiagnoseButton.IsEnabled = false;
			ScanStatusText.Text = "状态: 正在诊断 " + target.Ip + "...";
			try
			{
				CameraScannerService service = new CameraScannerService();
				try
				{
					CameraScanDiagnosis val2 = await service.DiagnoseAsync(target, CancellationToken.None);
					StringBuilder stringBuilder = new StringBuilder();
					stringBuilder.AppendLine("=== 摄像头扫描诊断报告 ===");
					StringBuilder stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder3 = stringBuilder2;
					StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(6, 1, stringBuilder2);
					handler.AppendLiteral("目标IP: ");
					handler.AppendFormatted(val2.Ip);
					stringBuilder3.AppendLine(ref handler);
					stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder4 = stringBuilder2;
					handler = new StringBuilder.AppendInterpolatedStringHandler(4, 1, stringBuilder2);
					handler.AppendLiteral("厂商: ");
					handler.AppendFormatted(string.IsNullOrEmpty(val2.Vendor) ? "(未识别)" : val2.Vendor);
					stringBuilder4.AppendLine(ref handler);
					stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder5 = stringBuilder2;
					handler = new StringBuilder.AppendInterpolatedStringHandler(4, 1, stringBuilder2);
					handler.AppendLiteral("固件: ");
					handler.AppendFormatted(string.IsNullOrEmpty(val2.FirmwareVersion) ? "(未知)" : val2.FirmwareVersion);
					stringBuilder5.AppendLine(ref handler);
					stringBuilder.AppendLine();
					stringBuilder.AppendLine("【诊断步骤】");
					foreach (string step in val2.Steps)
					{
						stringBuilder2 = stringBuilder;
						StringBuilder stringBuilder6 = stringBuilder2;
						handler = new StringBuilder.AppendInterpolatedStringHandler(2, 1, stringBuilder2);
						handler.AppendLiteral("  ");
						handler.AppendFormatted(step);
						stringBuilder6.AppendLine(ref handler);
					}
					stringBuilder.AppendLine();
					stringBuilder.AppendLine("【修复建议】");
					if (val2.Suggestions.Any())
					{
						foreach (string suggestion in val2.Suggestions)
						{
							stringBuilder2 = stringBuilder;
							StringBuilder stringBuilder7 = stringBuilder2;
							handler = new StringBuilder.AppendInterpolatedStringHandler(4, 1, stringBuilder2);
							handler.AppendLiteral("  ✓ ");
							handler.AppendFormatted(suggestion);
							stringBuilder7.AppendLine(ref handler);
						}
					}
					else
					{
						stringBuilder.AppendLine("  (无)");
					}
					if (val2.DetectedVulnerabilities.Any())
					{
						stringBuilder.AppendLine();
						stringBuilder.AppendLine("【检出漏洞】");
						foreach (CameraVulnerability detectedVulnerability in val2.DetectedVulnerabilities)
						{
							stringBuilder2 = stringBuilder;
							StringBuilder stringBuilder8 = stringBuilder2;
							handler = new StringBuilder.AppendInterpolatedStringHandler(15, 3, stringBuilder2);
							handler.AppendLiteral("  - ");
							handler.AppendFormatted(detectedVulnerability.CveId);
							handler.AppendLiteral(": ");
							handler.AppendFormatted(detectedVulnerability.Name);
							handler.AppendLiteral(" (CVSS: ");
							handler.AppendFormatted(detectedVulnerability.CvssScore);
							handler.AppendLiteral(")");
							stringBuilder8.AppendLine(ref handler);
						}
					}
					System.Windows.MessageBox.Show(stringBuilder.ToString(), "诊断报告 - " + target.Ip, MessageBoxButton.OK, MessageBoxImage.Asterisk);
					ScanStatusText.Text = $"状态: 诊断完成 - {target.Ip} | 漏洞: {val2.DetectedVulnerabilities.Count} 个";
				}
				finally
				{
					((IDisposable)service)?.Dispose();
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("诊断失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			finally
			{
				DiagnoseButton.IsEnabled = _allResults.Any((CameraScanResult r) => r.IsOnline);
			}
		}

		private async void ExportDetailedJsonButton_Click(object sender, RoutedEventArgs e)
		{
