				await _exportService.SaveJsonAsync(dialog.FileName, _currentPresetName, _currentTargetIps, _allResults, timeSpan);
				System.Windows.MessageBox.Show("JSON报告已保存到:\n" + dialog.FileName, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				ScanStatusText.Text = "状态: JSON报告已导出 - " + dialog.FileName;
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

