		private void ApplyFilter()
		{
			//IL_0199: Unknown result type (might be due to invalid IL or missing references)
			try
			{
				if (CameraDataGrid == null || CameraDataGrid.ItemsSource == null)
				{
					return;
				}
				string filter = FilterTextBox?.Text?.Trim() ?? string.Empty;
				if (filter == "\ud83d\udd0d 搜索过滤（IP / 厂商 / 型号 / 风险等级）...")
				{
					filter = string.Empty;
				}
				string tagId = null;
				if (TagFilterComboBox?.SelectedItem is ComboBoxItem comboBoxItem)
				{
					tagId = comboBoxItem.Tag?.ToString();
					if (string.IsNullOrEmpty(tagId))
					{
						tagId = null;
					}
				}
				System.Windows.Controls.CheckBox groupByTagCheck = GroupByTagCheck;
				bool flag = groupByTagCheck != null && groupByTagCheck.IsChecked == true;
				Dictionary<string, List<CameraTag>> dictionary = ((tagId != null || flag) ? BuildTagMap() : new Dictionary<string, List<CameraTag>>());
				string riskFilter = "all";
				if (RiskFilterComboBox?.SelectedItem is ComboBoxItem comboBoxItem2)
				{
					riskFilter = comboBoxItem2.Tag?.ToString() ?? "all";
				}
				ICollectionView defaultView = CollectionViewSource.GetDefaultView(CameraDataGrid.ItemsSource);
				if (defaultView == null)
				{
					return;
				}
				defaultView.Filter = delegate(object item)
				{
					CameraScanResult val = (CameraScanResult)((item is CameraScanResult) ? item : null);
					if (val == null)
					{
						return false;
					}
					if (tagId != null)
					{
						try
						{
							IReadOnlyList<string> ipsForTag = _tagService.GetIpsForTag(tagId);
							if (ipsForTag == null || !ipsForTag.Contains(val.Ip))
							{
								return false;
							}
						}
						catch
						{
						}
					}
					if (riskFilter != "all")
					{
						try
						{
							CameraRiskAssessment riskAssessment = val.RiskAssessment;
							string a = ((riskAssessment != null) ? riskAssessment.RiskLevel : null) ?? string.Empty;
							bool flag2 = (val.Vulnerabilities?.Count ?? 0) > 0;
							bool flag3 = (val.WeakPasswords?.Count ?? 0) > 0;
							switch (riskFilter)
							{
							case "严重":
							case "高危":
							case "中危":
							case "低危":
								if (!string.Equals(a, riskFilter, StringComparison.Ordinal))
								{
									return false;
								}
								break;
							case "安全":
								if (flag2 || flag3)
								{
									return false;
								}
								break;
							case "weakpwd":
								if (!flag3 || flag2)
								{
									return false;
								}
								break;
							}
						}
						catch
						{
						}
					}
					if (string.IsNullOrEmpty(filter))
					{
						return true;
					}
					string ip = val.Ip;
					if (ip == null || !ip.Contains(filter, StringComparison.OrdinalIgnoreCase))
					{
						string ipType = val.IpType;
						if (ipType == null || !ipType.Contains(filter, StringComparison.OrdinalIgnoreCase))
						{
							string vendor = val.Vendor;
							if (vendor == null || !vendor.Contains(filter, StringComparison.OrdinalIgnoreCase))
							{
								string model = val.Model;
								if (model == null || !model.Contains(filter, StringComparison.OrdinalIgnoreCase))
								{
									string firmwareVersion = val.FirmwareVersion;
									if (firmwareVersion == null || !firmwareVersion.Contains(filter, StringComparison.OrdinalIgnoreCase))
									{
										CameraRiskAssessment riskAssessment2 = val.RiskAssessment;
										if (!((riskAssessment2 == null) ? null : riskAssessment2.RiskLevel?.Contains(filter, StringComparison.OrdinalIgnoreCase)).GetValueOrDefault())
										{
											return val.SerialNumber?.Contains(filter, StringComparison.OrdinalIgnoreCase) ?? false;
										}
									}
								}
							}
						}
					}
					return true;
				};
				if (flag && dictionary != null)
				{
					((Collection<SortDescription>)(object)defaultView.SortDescriptions).Clear();
					((Collection<SortDescription>)(object)defaultView.SortDescriptions).Add(new SortDescription("Ip", ListSortDirection.Ascending));
				}
				RefreshToolbarStats(defaultView);
			}
			catch (Exception ex)
			{
				WriteDiagLog("ApplyFilter 异常: " + ex.GetType().Name + ": " + ex.Message);
			}
		}

		private void RefreshToolbarStats(ICollectionView? view = null)
		{
			try
			{
				if (_allResults == null)
				{
					UpdateStatRuns(0, 0, 0, 0);
					return;
				}
				int num = 0;
				int num2 = 0;
				int num3 = 0;
				int num4 = 0;
				foreach (CameraScanResult allResult in _allResults)
				{
					if (allResult != null)
					{
						num++;
						CameraRiskAssessment riskAssessment = allResult.RiskAssessment;
						string a = ((riskAssessment != null) ? riskAssessment.RiskLevel : null) ?? string.Empty;
						if (string.Equals(a, "高危", StringComparison.Ordinal))
						{
							num2++;
						}
						else if (string.Equals(a, "中危", StringComparison.Ordinal))
						{
							num3++;
						}
						else if (string.Equals(a, "低危", StringComparison.Ordinal))
						{
							num4++;
						}
					}
				}
				UpdateStatRuns(num, num2, num3, num4);
			}
			catch (Exception ex)
			{
				WriteDiagLog("RefreshToolbarStats 异常: " + ex.Message);
			}
		}

		private void UpdateStatRuns(int total, int high, int mid, int low)
		{
			if (StatTotalRun != null)
			{
				StatTotalRun.Text = total.ToString();
			}
			if (StatHighRun != null)
			{
				StatHighRun.Text = high.ToString();
			}
			if (StatMediumRun != null)
			{
				StatMediumRun.Text = mid.ToString();
			}
			if (StatLowRun != null)
			{
				StatLowRun.Text = low.ToString();
			}
		}

		private Dictionary<string, List<CameraTag>> BuildTagMap()
		{
			Dictionary<string, List<CameraTag>> dictionary = new Dictionary<string, List<CameraTag>>(StringComparer.Ordinal);
			if (_cachedTags == null || _cachedTags.Count == 0)
			{
				return dictionary;
			}
			foreach (CameraTag cachedTag in _cachedTags)
			{
				foreach (string item in _tagService.GetIpsForTag(cachedTag.TagId))
				{
					if (!dictionary.TryGetValue(item, out var value))
					{
						value = (dictionary[item] = new List<CameraTag>());
					}
					value.Add(cachedTag);
				}
			}
			return dictionary;
		}

		private void CameraDataGrid_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			try
			{
				object obj = CameraDataGrid?.SelectedItem;
				CameraScanResult val = (CameraScanResult)((obj is CameraScanResult) ? obj : null);
