				{
					_lastShownCamera = val;
					_lastDetailUpdate = DateTime.Now;
					ShowCameraDetail(val);
				}
			}
			catch (Exception ex)
			{
				WriteDiagLog("CameraDataGrid_SelectionChanged 异常: " + ex.GetType().Name + ": " + ex.Message);
			}
		}

		private void UpdateProgress(CameraScanProgress progress)
		{
			ScanPhaseText.Text = progress.Phase;
			ScanStatusText.Text = "状态: " + progress.Phase + " - " + progress.Message;
			if (progress.TotalCount > 0)
			{
				double num = (double)progress.CompletedCount / (double)progress.TotalCount * 100.0;
				ScanProgressBar.Value = Math.Min(num, 100.0);
				ScanProgressText.Text = $"{num:F0}%";
			}
		}

		private void DisplayResults(List<CameraScanResult> results)
		{
			List<CameraScanResult> list = results.Where((CameraScanResult r) => r.IsOnline).ToList();
			CameraDataGrid.ItemsSource = new ObservableCollection<CameraScanResult>(list);
			ApplyFilter();
			TotalFoundText.Text = $"已发现: {list.Count}";
			OnlineCountText.Text = list.Count.ToString();
			int num = list.Sum((CameraScanResult c) => c.RiskAssessment.CriticalCount);
			int num2 = list.Sum((CameraScanResult c) => c.RiskAssessment.HighCount);
			CriticalCountText.Text = num.ToString();
			HighCountText.Text = num2.ToString();
			MediumCountText.Text = list.Sum((CameraScanResult c) => c.RiskAssessment.MediumCount).ToString();
			try
			{
				CameraScanStatistics stat = CameraScanStatisticsService.Compute((IList<CameraScanResult>)results);
				UpdateDashboard(stat);
			}
			catch (Exception ex)
			{
				WriteDiagLog("DisplayResults UpdateDashboard 异常: " + ex.Message);
			}
			try
			{
				int num3 = results.Sum((CameraScanResult r) => r.Vulnerabilities?.Count ?? 0);
				int num4 = results.Sum((CameraScanResult r) => r.Vulnerabilities?.Count((CameraVulnerability v) => v.Severity == "高" || v.Severity == "严重" || v.Severity.Equals("High", StringComparison.OrdinalIgnoreCase) || v.Severity.Equals("Critical", StringComparison.OrdinalIgnoreCase)) ?? 0);
				_trendService.RecordSummary(Guid.NewGuid().ToString("N"), DateTime.Now, results.Count, list.Count, num3, num4);
				LoadTrendPreview();
			}
			catch (Exception ex2)
			{
				WriteDiagLog("RecordSummary 异常: " + ex2.Message);
			}
			if (!list.Any())
			{
				return;
			}
			ObservableCollection<CameraPortInfoEx> observableCollection = new ObservableCollection<CameraPortInfoEx>();
			foreach (CameraScanResult item in list)
			{
				foreach (CameraPortInfo openPort in item.OpenPorts)
				{
					observableCollection.Add(new CameraPortInfoEx
					{
						Ip = item.Ip,
						Port = openPort.Port,
						Protocol = openPort.Protocol,
						Service = openPort.Service,
						Status = openPort.Status,
						Banner = openPort.Banner,
						IsDefaultPort = openPort.IsDefaultPort,
						RiskLevel = openPort.RiskLevel
					});
				}
			}
			PortDataGrid.ItemsSource = observableCollection;
			ObservableCollection<CameraVulnerabilityRecord> observableCollection2 = new ObservableCollection<CameraVulnerabilityRecord>();
			foreach (CameraScanResult item2 in list)
			{
				foreach (CameraVulnerability vulnerability in item2.Vulnerabilities)
				{
					observableCollection2.Add(new CameraVulnerabilityRecord
					{
						CameraIp = item2.Ip,
						CveId = vulnerability.CveId,
						Name = vulnerability.Name,
						Severity = vulnerability.Severity,
						CvssScore = vulnerability.CvssScore,
						AffectedVendor = vulnerability.AffectedVendor,
						AffectedVersions = vulnerability.AffectedVersions,
						FixedVersion = vulnerability.FixedVersion,
						IsVerified = vulnerability.IsVerified,
						Solution = vulnerability.Solution
					});
				}
			}
			VulnDataGrid.ItemsSource = observableCollection2;
			ObservableCollection<CameraWeakPasswordRecord> observableCollection3 = new ObservableCollection<CameraWeakPasswordRecord>();
			foreach (CameraScanResult item3 in list)
			{
				foreach (CameraWeakPassword weakPassword in item3.WeakPasswords)
				{
					observableCollection3.Add(new CameraWeakPasswordRecord
					{
						CameraIp = item3.Ip,
						ServiceType = weakPassword.ServiceType,
						Port = weakPassword.Port,
						Username = weakPassword.Username,
						Password = weakPassword.Password,
						RiskLevel = weakPassword.RiskLevel,
						Suggestion = weakPassword.Suggestion
					});
				}
			}
			WeakPasswordDataGrid.ItemsSource = observableCollection3;
		}

		private void ShowCameraDetail(CameraScanResult camera)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("==============================");
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder3 = stringBuilder2;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(7, 1, stringBuilder2);
			handler.AppendLiteral("摄像头详情: ");
			handler.AppendFormatted(camera.Ip);
			stringBuilder3.AppendLine(ref handler);
			stringBuilder.AppendLine("==============================");
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder4 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(6, 1, stringBuilder2);
			handler.AppendLiteral("IP类型: ");
			handler.AppendFormatted(camera.IpType);
			stringBuilder4.AppendLine(ref handler);
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder5 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(4, 1, stringBuilder2);
			handler.AppendLiteral("厂商: ");
			handler.AppendFormatted(camera.Vendor);
			stringBuilder5.AppendLine(ref handler);
