							handler = new StringBuilder.AppendInterpolatedStringHandler(18, 4, stringBuilder2);
							handler.AppendLiteral("    [");
							handler.AppendFormatted(vulnerability2.Severity);
							handler.AppendLiteral("] ");
							handler.AppendFormatted(vulnerability2.CveId);
							handler.AppendLiteral(" - ");
							handler.AppendFormatted(vulnerability2.Name);
							handler.AppendLiteral(" (CVSS ");
							handler.AppendFormatted(vulnerability2.CvssScore);
							handler.AppendLiteral(")");
							stringBuilder22.AppendLine(ref handler);
						}
					}
					if (!item4.WeakPasswords.Any())
					{
						continue;
					}
					stringBuilder.AppendLine("  弱口令:");
					foreach (CameraWeakPassword weakPassword2 in item4.WeakPasswords)
					{
						stringBuilder2 = stringBuilder;
						StringBuilder stringBuilder23 = stringBuilder2;
						handler = new StringBuilder.AppendInterpolatedStringHandler(7, 4, stringBuilder2);
						handler.AppendLiteral("    ");
						handler.AppendFormatted(weakPassword2.ServiceType);
						handler.AppendLiteral(":");
						handler.AppendFormatted(weakPassword2.Port);
						handler.AppendLiteral(" ");
						handler.AppendFormatted(weakPassword2.Username);
						handler.AppendLiteral(":");
						handler.AppendFormatted(weakPassword2.Password);
						stringBuilder23.AppendLine(ref handler);
					}
				}
			}
			return stringBuilder.ToString();
		}

		private async void DeepScanMenuItem_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				if (!(sender is MenuItem menuItem) || !(menuItem.DataContext is DataGridRow))
				{
					return;
				}
				DataGrid dataGrid = FindVisualParent<DataGrid>((DependencyObject)(object)menuItem);
				if (dataGrid == null || dataGrid.SelectedItem == null)
				{
					return;
				}
				object selectedItem = dataGrid.SelectedItem;
				string targetIp = null;
				List<int> list = new List<int>();
				Type type = selectedItem.GetType();
				PropertyInfo propertyInfo = type.GetProperty("Ip") ?? type.GetProperty("TargetIp") ?? type.GetProperty("IPAddress") ?? type.GetProperty("Host") ?? type.GetProperty("Target");
				if (propertyInfo != null)
				{
					targetIp = propertyInfo.GetValue(selectedItem)?.ToString();
				}
				if (type.GetProperty("OpenPorts")?.GetValue(selectedItem) is IEnumerable enumerable)
				{
					foreach (object item in enumerable)
					{
						if (item == null)
						{
							continue;
						}
						Type type2 = item.GetType();
						PropertyInfo propertyInfo2 = type2.GetProperty("Port") ?? type2.GetProperty("PortNumber");
						if (propertyInfo2 != null)
						{
							object value = propertyInfo2.GetValue(item);
							if (value != null)
							{
								list.Add(Convert.ToInt32(value));
							}
						}
					}
				}
				if (string.IsNullOrEmpty(targetIp))
				{
					System.Windows.MessageBox.Show("无法获取目标 IP", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
					return;
				}
				string value2 = ((list.Count > 0) ? string.Join(",", list) : "默认");
				if (System.Windows.MessageBox.Show($"将使用所有适用插件重新扫描 {targetIp} (端口: {value2})，是否继续？", "插件深挖", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
				{
					Mouse.OverrideCursor = System.Windows.Input.Cursors.Wait;
					List<VulnerabilityResult> list2 = await PluginOrchestrator.Instance.ScanTargetAsync(targetIp, list, (IEnumerable<string>)null, default(CancellationToken), (string)null);
					Mouse.OverrideCursor = null;
					ScanStatusText.Text = $"状态: 深挖 {targetIp} 完成，发现 {list2.Count} 个漏洞";
					System.Windows.MessageBox.Show($"深挖完成：发现 {list2.Count} 个漏洞", "完成", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
			catch (Exception ex)
			{
				Mouse.OverrideCursor = null;
				System.Windows.MessageBox.Show("深挖失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private static T? FindVisualParent<T>(DependencyObject child) where T : DependencyObject
		{
			DependencyObject parent = VisualTreeHelper.GetParent(child);
			while (parent != null && !(parent is T))
			{
				parent = VisualTreeHelper.GetParent(parent);
			}
			return (T)(object)((parent is T) ? parent : null);
		}

