	public class TagListConverter : IValueConverter
	{
		private static readonly CameraTagService _tagService = new CameraTagService();

		private static List<CameraTag> _tagCache = new List<CameraTag>();

		private static DateTime _cacheTime = DateTime.MinValue;

		private static readonly object _lock = new object();

		public object? Convert(object? value, Type targetType, object? parameter, CultureInfo culture)
		{
			CameraScanResult val = (CameraScanResult)((value is CameraScanResult) ? value : null);
			if (val == null)
			{
				return new List<TagViewModel>();
			}
			EnsureCache();
			_tagService.GetIpsForTag(string.Empty);
			HashSet<string> hashSet = new HashSet<string>(_tagService.GetTagsForIp(val.Ip));
			List<TagViewModel> list = new List<TagViewModel>();
			foreach (CameraTag item in _tagCache)
			{
				if (hashSet.Contains(item.TagId))
				{
					System.Windows.Media.Brush color2;
					try
					{
						color2 = new SolidColorBrush((System.Windows.Media.ColorConverter.ConvertFromString(string.IsNullOrWhiteSpace(item.Color) ? "#3498DB" : item.Color) is System.Windows.Media.Color color) ? color : Colors.SteelBlue);
					}
					catch
					{
						color2 = System.Windows.Media.Brushes.SteelBlue;
					}
					list.Add(new TagViewModel
					{
						Name = item.Name,
						Color = color2,
						Description = item.Description
					});
				}
			}
			return list;
		}

		public object? ConvertBack(object? value, Type targetType, object? parameter, CultureInfo culture)
		{
			throw new NotSupportedException();
		}

		private static void EnsureCache()
		{
			lock (_lock)
			{
				if ((DateTime.Now - _cacheTime).TotalSeconds > 5.0)
				{
					_tagCache = _tagService.GetAll();
					_cacheTime = DateTime.Now;
				}
			}
		}
	}
	public class CameraTagManageWindow : Window, IComponentConnector
	{
		private readonly CameraTagService _tagService = new CameraTagService();

		private List<TagItem> _allTags = new List<TagItem>();

		private string? _currentTagId;

		internal System.Windows.Controls.ListView TagListView;

		internal TextBlock CurrentTagTitle;

		internal System.Windows.Controls.TextBox NewIpTextBox;

		internal System.Windows.Controls.ListView IpListView;

		internal TextBlock StatusText;

		private bool _contentLoaded;

		public CameraTagManageWindow()
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_000b: Expected O, but got Unknown
			InitializeComponent();
			base.Loaded += delegate
			{
				RefreshTagList();
			};
		}

		private void RefreshTagList()
		{
			try
			{
				List<CameraTag> all = _tagService.GetAll();
				_allTags = all.Select((CameraTag t) => new TagItem
				{
					TagId = t.TagId,
					Name = t.Name,
					Color = t.Color,
					Description = t.Description,
					IpCount = _tagService.GetIpsForTag(t.TagId).Count
				}).ToList();
				TagListView.ItemsSource = _allTags;
				StatusText.Text = $"共 {_allTags.Count} 个标签";
			}
			catch (Exception ex)
			{
				StatusText.Text = "加载失败: " + ex.Message;
			}
		}

		private void TagListView_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			if (TagListView.SelectedItem is TagItem tagItem)
			{
				_currentTagId = tagItem.TagId;
				CurrentTagTitle.Text = "标签「" + tagItem.Name + "」下的 IP";
				IReadOnlyList<string> ipsForTag = _tagService.GetIpsForTag(tagItem.TagId);
				IpListView.ItemsSource = ipsForTag.ToList();
				StatusText.Text = $"标签 {tagItem.Name} 已分配 {ipsForTag.Count} 个 IP";
			}
			else
			{
				_currentTagId = null;
				CurrentTagTitle.Text = "该标签下的 IP";
				IpListView.ItemsSource = null;
			}
		}

		private void NewTag_Click(object sender, RoutedEventArgs e)
		{
			TagEditDialog tagEditDialog = new TagEditDialog();
			if (tagEditDialog.ShowDialog() == true && tagEditDialog.ResultTag != null)
			{
				_tagService.Add(tagEditDialog.ResultTag);
				RefreshTagList();
				StatusText.Text = "已新建标签 " + tagEditDialog.ResultTag.Name;
			}
		}

		private void EditTag_Click(object sender, RoutedEventArgs e)
		{
			object selectedItem = TagListView.SelectedItem;
			TagItem item = selectedItem as TagItem;
			if (item == null)
			{
				System.Windows.MessageBox.Show("请先选择要编辑的标签", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			CameraTag val = ((IEnumerable<CameraTag>)_tagService.GetAll()).FirstOrDefault((Func<CameraTag, bool>)((CameraTag t) => t.TagId == item.TagId));
			if (val != null)
			{
				TagEditDialog tagEditDialog = new TagEditDialog(val);
				if (tagEditDialog.ShowDialog() == true && tagEditDialog.ResultTag != null)
				{
					_tagService.Update(tagEditDialog.ResultTag);
					RefreshTagList();
					StatusText.Text = "已更新标签 " + tagEditDialog.ResultTag.Name;
				}
			}
		}

		private void DeleteTag_Click(object sender, RoutedEventArgs e)
		{
			if (!(TagListView.SelectedItem is TagItem tagItem))
			{
				System.Windows.MessageBox.Show("请先选择要删除的标签", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
			else if (System.Windows.MessageBox.Show("确认删除标签「" + tagItem.Name + "」？\n该标签下所有 IP 关联都会被清除。", "删除确认", MessageBoxButton.YesNo, MessageBoxImage.Exclamation) == MessageBoxResult.Yes)
			{
				_tagService.Remove(tagItem.TagId);
				RefreshTagList();
				IpListView.ItemsSource = null;
				_currentTagId = null;
				StatusText.Text = "已删除标签 " + tagItem.Name;
			}
		}

		private void AddIp_Click(object sender, RoutedEventArgs e)
		{
			if (string.IsNullOrWhiteSpace(_currentTagId))
			{
				System.Windows.MessageBox.Show("请先选择标签", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			string text = NewIpTextBox.Text.Trim();
			if (string.IsNullOrEmpty(text))
			{
				System.Windows.MessageBox.Show("请输入 IP", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			_tagService.Assign(text, _currentTagId);
			NewIpTextBox.Clear();
			RefreshCurrentIps();
			StatusText.Text = "已为标签分配 IP " + text;
		}

		private void RemoveIp_Click(object sender, RoutedEventArgs e)
		{
			if (string.IsNullOrWhiteSpace(_currentTagId))
			{
				System.Windows.MessageBox.Show("请先选择标签", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			List<string> list = IpListView.SelectedItems.Cast<string>().ToList();
			if (list.Count == 0)
			{
				System.Windows.MessageBox.Show("请先选择要移除的 IP", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			foreach (string item in list)
			{
				_tagService.Unassign(item, _currentTagId);
			}
			RefreshCurrentIps();
			StatusText.Text = $"已移除 {list.Count} 个 IP";
		}

		private void RefreshCurrentIps()
		{
			if (!string.IsNullOrWhiteSpace(_currentTagId))
			{
				IReadOnlyList<string> ipsForTag = _tagService.GetIpsForTag(_currentTagId);
				IpListView.ItemsSource = ipsForTag.ToList();
				if (TagListView.SelectedItem is TagItem tagItem)
				{
					tagItem.IpCount = ipsForTag.Count;
				}
			}
		}

