		private static TextBlock MakeLabel(string text, int row)
		{
			TextBlock obj = new TextBlock
			{
				Text = text,
				Margin = new Thickness(0.0, 6.0, 0.0, 4.0),
				Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(51, 65, 85))
			};
			Grid.SetRow(obj, row * 2);
			return obj;
		}

		private static Border MakeTextBox(System.Windows.Controls.TextBox box, int row)
		{
			box.BorderBrush = new SolidColorBrush(System.Windows.Media.Color.FromRgb(203, 213, 225));
			Border obj = new Border
			{
				Child = box,
				BorderBrush = new SolidColorBrush(System.Windows.Media.Color.FromRgb(203, 213, 225)),
				BorderThickness = new Thickness(1.0)
			};
			Grid.SetRow(obj, row * 2 + 1);
			return obj;
		}
	}
