		private static TextBlock MakeTitleBlock(string text, byte r, byte g, byte b)
		{
			return new TextBlock
			{
				Text = text,
				FontWeight = FontWeights.SemiBold,
				Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(r, g, b)),
				Margin = new Thickness(0.0, 0.0, 12.0, 0.0),
				VerticalAlignment = VerticalAlignment.Center
			};
		}

		private int GetSelectedDays()
		{
			if (_rangeCombo.SelectedItem is ComboBoxItem { Tag: var tag } && int.TryParse(tag?.ToString(), out var result))
			{
				return result;
			}
			return 30;
		}

		private void Refresh()
		{
			try
			{
				List<TrendSessionInfo> list = _service.ListRecentSessions(50);
				_sessionCombo.Items.Clear();
				_sessionCombo.Items.Add(new ComboBoxItem
				{
					Content = "（汇总视图）",
					IsSelected = true,
					Tag = ""
				});
				foreach (TrendSessionInfo item in list)
				{
					_sessionCombo.Items.Add(new ComboBoxItem
					{
						Content = item.Display,
						Tag = item.ScanId
					});
				}
				_sessionCombo.DisplayMemberPath = "Content";
				int selectedDays = GetSelectedDays();
				_currentPoints = _service.GetTrend(selectedDays);
				RedrawCharts();
				_statusText.Text = $"显示最近 {selectedDays} 天，共 {_currentPoints.Count} 个数据点；DB：{_service.DbPath}";
			}
			catch (Exception ex)
			{
				_statusText.Text = "加载失败: " + ex.Message;
			}
		}

		private void RedrawCharts()
		{
			List<CameraTrendPoint> source = _currentPoints ?? new List<CameraTrendPoint>();
			_totalChart.SetSeries(new SeriesDefinition[1]
			{
				new SeriesDefinition
				{
					Name = "总数",
					Color = System.Windows.Media.Color.FromRgb(37, 99, 235),
					Values = source.Select((CameraTrendPoint p) => ((DateTime Date, double))(Date: p.Date, p.Total)).ToList()
				}
			});
			_onlineChart.SetSeries(new SeriesDefinition[1]
			{
				new SeriesDefinition
				{
					Name = "在线",
					Color = System.Windows.Media.Color.FromRgb(16, 185, 129),
					Values = source.Select((CameraTrendPoint p) => ((DateTime Date, double))(Date: p.Date, p.Online)).ToList()
				}
			});
			_vulnChart.SetSeries(new SeriesDefinition[1]
			{
				new SeriesDefinition
				{
					Name = "漏洞",
					Color = System.Windows.Media.Color.FromRgb(239, 68, 68),
					Values = source.Select((CameraTrendPoint p) => ((DateTime Date, double))(Date: p.Date, p.VulnTotal)).ToList()
				}
			});
		}

		private void RangeCombo_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			Refresh();
		}

		private void SessionCombo_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			//IL_00bf: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c4: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d9: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e5: Unknown result type (might be due to invalid IL or missing references)
			//IL_00f1: Unknown result type (might be due to invalid IL or missing references)
			//IL_0102: Expected O, but got Unknown
			if (!(_sessionCombo.SelectedItem is ComboBoxItem comboBoxItem))
			{
				return;
			}
			string tag = comboBoxItem.Tag?.ToString() ?? string.Empty;
			if (string.IsNullOrEmpty(tag))
			{
				RedrawCharts();
				_statusText.Text = $"汇总视图：{_currentPoints.Count} 个聚合点";
				return;
			}
			TrendSessionInfo val = ((IEnumerable<TrendSessionInfo>)_service.ListRecentSessions(50)).FirstOrDefault((Func<TrendSessionInfo, bool>)((TrendSessionInfo x) => x.ScanId == tag));
			if (val != null)
			{
				List<CameraTrendPoint> source = new List<CameraTrendPoint>
				{
					new CameraTrendPoint
					{
						Date = val.ScanTime.Date,
						Total = val.Total,
						Online = val.Online,
						VulnTotal = val.VulnTotal
					}
				};
				_totalChart.SetSeries(new SeriesDefinition[1]
				{
					new SeriesDefinition
					{
						Name = "总数",
						Color = System.Windows.Media.Color.FromRgb(37, 99, 235),
						Values = source.Select((CameraTrendPoint p) => ((DateTime Date, double))(Date: p.Date, p.Total)).ToList()
					}
				});
				_onlineChart.SetSeries(new SeriesDefinition[1]
				{
					new SeriesDefinition
					{
						Name = "在线",
						Color = System.Windows.Media.Color.FromRgb(16, 185, 129),
						Values = source.Select((CameraTrendPoint p) => ((DateTime Date, double))(Date: p.Date, p.Online)).ToList()
					}
				});
				_vulnChart.SetSeries(new SeriesDefinition[1]
				{
					new SeriesDefinition
					{
						Name = "漏洞",
						Color = System.Windows.Media.Color.FromRgb(239, 68, 68),
						Values = source.Select((CameraTrendPoint p) => ((DateTime Date, double))(Date: p.Date, p.VulnTotal)).ToList()
					}
				});
				_statusText.Text = "单会话视图：" + val.Display;
			}
		}

		private void Refresh_Click(object sender, RoutedEventArgs e)
		{
			Refresh();
		}
	}
