			stackPanel2.Children.Add(MakeButton("导出 TXT", "#6366F1", Export_Click));
			Grid.SetRow(stackPanel2, 3);
			grid.Children.Add(stackPanel2);
			_statusText.Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(100, 116, 139));
			_statusText.FontSize = 12.0;
			_statusText.Margin = new Thickness(0.0, 8.0, 0.0, 0.0);
			Grid.SetRow(_statusText, 4);
			grid.Children.Add(_statusText);
			base.Content = grid;
		}

		private static System.Windows.Controls.Button MakeButton(string text, string colorHex, RoutedEventHandler handler)
		{
			System.Windows.Controls.Button button = new System.Windows.Controls.Button();
			button.Content = text;
			button.MinWidth = 90.0;
			button.Margin = new Thickness(0.0, 0.0, 8.0, 0.0);
			button.Padding = new Thickness(12.0, 6.0, 12.0, 6.0);
			button.Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(colorHex));
			button.Foreground = System.Windows.Media.Brushes.White;
			button.BorderThickness = new Thickness(0.0);
			button.Cursor = System.Windows.Input.Cursors.Hand;
			button.Click += handler;
			return button;
		}

		private void RefreshList()
		{
			try
			{
				_builtInEnabledCheck.IsChecked = _service.BuiltInEnabled;
				_builtInCountText.Text = _service.BuiltInCount.ToString();
				_customCountText.Text = _service.CustomCount.ToString();
				_totalCountText.Text = _service.Count.ToString();
				List<string> list = (_service.BuiltInEnabled ? CameraWeakPasswordDictService.BuiltInPasswords.ToList() : new List<string>());
				List<string> list2 = _service.GetCustom().ToList();
				_items = list.Select((string p) => new PasswordItem
				{
					Value = p,
					IsCustom = false
				}).ToList();
				_items.AddRange(list2.Select((string p) => new PasswordItem
				{
					Value = p,
					IsCustom = true
				}));
				for (int i = 0; i < _items.Count; i++)
				{
					_items[i].Index = i + 1;
				}
				_passwordList.ItemsSource = null;
				_passwordList.ItemsSource = _items;
				_statusText.Text = $"当前共 {_items.Count} 条（内置 {list.Count} + 自定义 {list2.Count}）";
			}
			catch (Exception ex)
			{
				_statusText.Text = "加载失败: " + ex.Message;
			}
		}

		private void BuiltInEnabled_Changed(object sender, RoutedEventArgs e)
		{
			_service.BuiltInEnabled = _builtInEnabledCheck.IsChecked == true;
			RefreshList();
		}

		private void Add_Click(object sender, RoutedEventArgs e)
		{
			PasswordInputDialog passwordInputDialog = new PasswordInputDialog();
			if (passwordInputDialog.ShowDialog() == true && !string.IsNullOrWhiteSpace(passwordInputDialog.InputPassword))
			{
				if (_service.Add(passwordInputDialog.InputPassword))
				{
					RefreshList();
					_statusText.Text = "已添加口令";
				}
				else
				{
					_statusText.Text = "已存在或无效，未添加";
				}
			}
		}

		private void Remove_Click(object sender, RoutedEventArgs e)
		{
			List<PasswordItem> list = _passwordList.SelectedItems.Cast<PasswordItem>().ToList();
			if (list.Count == 0)
			{
				System.Windows.MessageBox.Show("请先选择要移除的口令", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			List<PasswordItem> list2 = list.Where((PasswordItem x) => x.IsCustom).ToList();
			if (list2.Count == 0)
			{
				System.Windows.MessageBox.Show("内置字典条目不可移除；如需忽略请取消「启用内置字典」", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			foreach (PasswordItem item in list2)
			{
				_service.Remove(item.Value);
			}
			RefreshList();
			_statusText.Text = $"已移除 {list2.Count} 条自定义口令";
		}

		private void Clear_Click(object sender, RoutedEventArgs e)
		{
			if (_service.CustomCount == 0)
			{
				_statusText.Text = "没有自定义口令可清空";
			}
			else if (System.Windows.MessageBox.Show("确认清空所有自定义口令？此操作不可恢复。", "清空确认", MessageBoxButton.YesNo, MessageBoxImage.Exclamation) == MessageBoxResult.Yes)
			{
				_service.Clear();
				RefreshList();
				_statusText.Text = "已清空自定义口令";
			}
		}

		private void Import_Click(object sender, RoutedEventArgs e)
		{
			Microsoft.Win32.OpenFileDialog openFileDialog = new Microsoft.Win32.OpenFileDialog
			{
				Filter = "文本文件 (*.txt)|*.txt|所有文件 (*.*)|*.*",
				Title = "选择要导入的弱口令文件"
			};
			if (openFileDialog.ShowDialog(this) == true)
			{
				try
				{
					int value = _service.ImportTxt(openFileDialog.FileName);
					RefreshList();
					_statusText.Text = $"已导入，新增 {value} 条";
				}
				catch (Exception ex)
				{
					System.Windows.MessageBox.Show("导入失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				}
			}
		}

		private void Export_Click(object sender, RoutedEventArgs e)
		{
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Filter = "文本文件 (*.txt)|*.txt",
				Title = "导出弱口令到文件",
				FileName = $"camera_weak_passwords_{DateTime.Now:yyyyMMdd_HHmmss}.txt"
			};
			if (saveFileDialog.ShowDialog(this) == true)
			{
				try
				{
					int value = _service.ExportTxt(saveFileDialog.FileName);
					_statusText.Text = $"已导出 {value} 条到 {System.IO.Path.GetFileName(saveFileDialog.FileName)}";
				}
				catch (Exception ex)
				{
					System.Windows.MessageBox.Show("导出失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				}
			}
		}
	}
	public class PasswordItem
	{
		public int Index { get; set; }

		public string Value { get; set; } = string.Empty;


		public bool IsCustom { get; set; }

		public string OriginText
		{
			get
			{
				if (!IsCustom)
				{
					return "内置";
				}
				return "自定义";
			}
		}

		public string OriginColor
		{
			get
			{
				if (!IsCustom)
				{
					return "#2563EB";
				}
				return "#10B981";
			}
		}
	}
