	public class ComplianceCheckWindow : Window, IComponentConnector
	{
		private readonly ComplianceCheckService _complianceService;

		private ComplianceReport? _currentReport;

		internal System.Windows.Controls.TextBox TargetTextBox;

		internal System.Windows.Controls.ComboBox CheckTypeComboBox;

		internal System.Windows.Controls.Button StartCheckButton;

		internal TextBlock ResultCountTextBlock;

		internal DataGrid ResultsDataGrid;

		internal TextBlock ComplianceScoreText;

		internal TextBlock ScoreDescriptionText;

		internal TextBlock PassCountText;

		internal TextBlock FailCountText;

		internal TextBlock WarningCountText;

		internal TextBlock NaCountText;

		internal StackPanel DetailPanel;

		internal TextBlock StatusTextBlock;

		internal System.Windows.Controls.ProgressBar CheckProgressBar;

		internal System.Windows.Controls.Button ExportReportButton;

		internal System.Windows.Controls.Button CloseButton;

		private bool _contentLoaded;

		public ComplianceCheckWindow()
		{
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0017: Expected O, but got Unknown
			InitializeComponent();
			_complianceService = new ComplianceCheckService();
			ResultsDataGrid.SelectionChanged += ResultsDataGrid_SelectionChanged;
		}

		private async void StartCheckButton_Click(object sender, RoutedEventArgs e)
		{
			string text = TargetTextBox.Text.Trim();
			if (string.IsNullOrEmpty(text))
			{
				System.Windows.MessageBox.Show("请输入检查目标", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			StartCheckButton.IsEnabled = false;
			CheckProgressBar.Visibility = Visibility.Visible;
			StatusTextBlock.Text = "正在执行合规性检查...";
			try
			{
				ComplianceCheckContext val = new ComplianceCheckContext
				{
					Target = text,
					OpenPorts = new List<int>()
				};
				try
				{
					string path = System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "port_scan_results.json");
					if (File.Exists(path))
					{
						JsonElement jsonElement = JsonSerializer.Deserialize<JsonElement>(File.ReadAllText(path));
						if (jsonElement.ValueKind == JsonValueKind.Array)
						{
							List<int> list = new List<int>();
							foreach (JsonElement item in jsonElement.EnumerateArray())
							{
								if (item.TryGetProperty("Status", out var value) && (value.GetString() == "开放" || value.GetString() == "Open") && item.TryGetProperty("Port", out var value2))
								{
									list.Add(value2.GetInt32());
								}
							}
							val.OpenPorts = list.Distinct().ToList();
						}
					}
				}
				catch (Exception)
				{
				}
				_currentReport = (ComplianceReport?)(CheckTypeComboBox.SelectedIndex switch
				{
					1 => await _complianceService.RunChecksByTypeAsync((ComplianceType)0, val), 
					2 => await _complianceService.RunChecksByTypeAsync((ComplianceType)1, val), 
					_ => await _complianceService.RunAllChecksAsync(val), 
				});
				DisplayResults();
				StatusTextBlock.Text = $"检查完成，合规评分: {_currentReport.ComplianceScore:F1}%";
				ExportReportButton.IsEnabled = true;
			}
			catch (Exception ex2)
			{
				StatusTextBlock.Text = "检查失败: " + ex2.Message;
				System.Windows.MessageBox.Show("检查失败: " + ex2.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			finally
			{
				StartCheckButton.IsEnabled = true;
				CheckProgressBar.Visibility = Visibility.Collapsed;
			}
		}

		private void DisplayResults()
		{
			if (_currentReport != null)
			{
				ResultsDataGrid.ItemsSource = _currentReport.Results;
				ResultCountTextBlock.Text = $"({_currentReport.TotalChecks})";
				ComplianceScoreText.Text = $"{_currentReport.ComplianceScore:F1}";
				ScoreDescriptionText.Text = ((_currentReport.ComplianceScore >= 80.0) ? "优秀" : ((_currentReport.ComplianceScore >= 60.0) ? "良好" : "需改进"));
				PassCountText.Text = _currentReport.PassCount.ToString();
				FailCountText.Text = _currentReport.FailCount.ToString();
				WarningCountText.Text = _currentReport.WarningCount.ToString();
				NaCountText.Text = _currentReport.NotApplicableCount.ToString();
			}
		}

		private void ResultsDataGrid_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			object selectedItem = ResultsDataGrid.SelectedItem;
			ComplianceCheckResult val = (ComplianceCheckResult)((selectedItem is ComplianceCheckResult) ? selectedItem : null);
			if (val != null)
			{
				DisplayDetail(val);
			}
		}

		private void DisplayDetail(ComplianceCheckResult result)
		{
			//IL_007c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0081: Unknown result type (might be due to invalid IL or missing references)
			//IL_0082: Unknown result type (might be due to invalid IL or missing references)
			//IL_0094: Expected I4, but got Unknown
			//IL_00df: Unknown result type (might be due to invalid IL or missing references)
			DetailPanel.Children.Clear();
			DetailPanel.Children.Add(new TextBlock
			{
				Text = result.Item,
				FontSize = 18.0,
				FontWeight = FontWeights.Bold,
				Margin = new Thickness(0.0, 0.0, 0.0, 10.0)
			});
			ComplianceStatus status = result.Status;
			SolidColorBrush foreground = (int)status switch
			{
				0 => System.Windows.Media.Brushes.Green, 
				1 => System.Windows.Media.Brushes.Red, 
				2 => System.Windows.Media.Brushes.Orange, 
				_ => System.Windows.Media.Brushes.Gray, 
			};
			DetailPanel.Children.Add(new TextBlock
			{
				Text = $"状态: {result.Status}",
				FontWeight = FontWeights.Bold,
				Foreground = foreground,
				Margin = new Thickness(0.0, 0.0, 0.0, 10.0)
			});
			AddDetailItem("检查ID:", result.CheckId);
			AddDetailItem("类别:", result.Category);
			AddDetailItem("要求:", result.Requirement);
			AddDetailItem("检查方法:", result.CheckMethod);
			AddDetailItem("备注:", result.Remark);
		}

		private void AddDetailItem(string label, string value)
		{
			StackPanel stackPanel = new StackPanel
			{
				Orientation = System.Windows.Controls.Orientation.Vertical,
				Margin = new Thickness(0.0, 5.0, 0.0, 5.0)
			};
			stackPanel.Children.Add(new TextBlock
			{
				Text = label,
				FontWeight = FontWeights.SemiBold,
				FontSize = 12.0
			});
			stackPanel.Children.Add(new TextBlock
			{
				Text = value,
				TextWrapping = TextWrapping.Wrap,
				Margin = new Thickness(0.0, 2.0, 0.0, 0.0)
			});
			DetailPanel.Children.Add(stackPanel);
		}

		private async void ExportReportButton_Click(object sender, RoutedEventArgs e)
		{
			if (_currentReport == null)
			{
				return;
			}
			try
			{
				Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
				{
					Filter = "JSON文件|*.json|CSV文件|*.csv|HTML文件|*.html",
					FileName = $"合规性报告_{DateTime.Now:yyyyMMdd_HHmmss}",
					Title = "导出合规性报告"
				};
				if (saveFileDialog.ShowDialog() == true)
				{
					string filePath = saveFileDialog.FileName;
					switch (System.IO.Path.GetExtension(filePath).ToLower())
					{
					case ".json":
						await ExportToJsonAsync(filePath);
						break;
					case ".csv":
						await ExportToCsvAsync(filePath);
						break;
					case ".html":
						await ExportToHtmlAsync(filePath);
						break;
					}
					System.Windows.MessageBox.Show("报告已导出到:\n" + filePath, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async Task ExportToJsonAsync(string filePath)
		{
			string contents = JsonSerializer.Serialize<ComplianceReport>(_currentReport, new JsonSerializerOptions
			{
				WriteIndented = true
			});
			await File.WriteAllTextAsync(filePath, contents);
		}

		private async Task ExportToCsvAsync(string filePath)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("检查ID,类别,检查项,要求,检查方法,状态,备注");
			foreach (ComplianceCheckResult result in _currentReport.Results)
			{
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(6, 7, stringBuilder2);
				handler.AppendFormatted(result.CheckId);
				handler.AppendLiteral(",");
				handler.AppendFormatted(result.Category);
				handler.AppendLiteral(",");
				handler.AppendFormatted(result.Item);
				handler.AppendLiteral(",");
				handler.AppendFormatted(result.Requirement);
				handler.AppendLiteral(",");
				handler.AppendFormatted(result.CheckMethod);
				handler.AppendLiteral(",");
				handler.AppendFormatted<ComplianceStatus>(result.Status);
				handler.AppendLiteral(",");
				handler.AppendFormatted(result.Remark);
				stringBuilder2.AppendLine(ref handler);
			}
			await File.WriteAllTextAsync(filePath, stringBuilder.ToString());
		}

		private async Task ExportToHtmlAsync(string filePath)
		{
			string contents = GenerateHtmlReport();
			await File.WriteAllTextAsync(filePath, contents);
		}

