	public class DatabaseSettingsWindow : Window, IComponentConnector
	{
		private string _settingsPath;

		private DatabaseSettings _settings;

		internal System.Windows.Controls.CheckBox AutoUpdateEnabledCheckBox;

		internal System.Windows.Controls.ComboBox UpdateIntervalComboBox;

		internal System.Windows.Controls.ComboBox AutoUpdateTimeComboBox;

		internal System.Windows.Controls.TextBox NvdApiKeyTextBox;

		internal System.Windows.Controls.TextBox CnnvdApiKeyTextBox;

		internal System.Windows.Controls.TextBox CncertApiKeyTextBox;

		internal System.Windows.Controls.CheckBox IncrementalUpdateCheckBox;

		internal System.Windows.Controls.CheckBox AutoBackupCheckBox;

		internal System.Windows.Controls.CheckBox NotifyOnCompleteCheckBox;

		internal System.Windows.Controls.CheckBox KeepUpdateLogCheckBox;

		internal System.Windows.Controls.Button SaveButton;

		private bool _contentLoaded;

		public DatabaseSettingsWindow()
		{
			InitializeComponent();
			InitializePaths();
			LoadSettings();
		}

		private void InitializePaths()
		{
			string text = System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "NetSecurityScanner");
			Directory.CreateDirectory(text);
			_settingsPath = System.IO.Path.Combine(text, "update_settings.json");
		}

		private void LoadSettings()
		{
			try
			{
				if (File.Exists(_settingsPath))
				{
					string json = File.ReadAllText(_settingsPath);
					_settings = JsonSerializer.Deserialize<DatabaseSettings>(json);
				}
			}
			catch (Exception)
			{
				_settings = new DatabaseSettings();
			}
			if (_settings == null)
			{
				_settings = new DatabaseSettings();
			}
			AutoUpdateEnabledCheckBox.IsChecked = _settings.AutoUpdateEnabled;
			UpdateIntervalComboBox.SelectedIndex = GetIntervalIndex(_settings.UpdateIntervalDays);
			AutoUpdateTimeComboBox.SelectedIndex = GetTimeIndex(_settings.AutoUpdateTime);
			CnnvdApiKeyTextBox.Text = _settings.CnnvdApiKey ?? "";
			CncertApiKeyTextBox.Text = _settings.CncertApiKey ?? "";
			IncrementalUpdateCheckBox.IsChecked = _settings.IncrementalUpdate;
			AutoBackupCheckBox.IsChecked = _settings.AutoBackup;
			NotifyOnCompleteCheckBox.IsChecked = _settings.NotifyOnComplete;
			KeepUpdateLogCheckBox.IsChecked = _settings.KeepUpdateLog;
		}

		private int GetIntervalIndex(int days)
		{
			return days switch
			{
				1 => 0, 
				3 => 1, 
				7 => 2, 
				15 => 3, 
				30 => 4, 
				_ => 2, 
			};
		}

		private int GetTimeIndex(string time)
		{
			return time switch
			{
				"00:00" => 0, 
				"02:00" => 1, 
				"04:00" => 2, 
				"06:00" => 3, 
				"08:00" => 4, 
				"12:00" => 5, 
				"18:00" => 6, 
				"22:00" => 7, 
				_ => 2, 
			};
		}

		private int GetIntervalFromIndex(int index)
		{
			return index switch
			{
				0 => 1, 
				1 => 3, 
				2 => 7, 
				3 => 15, 
				4 => 30, 
				_ => 7, 
			};
		}

		private string GetTimeFromIndex(int index)
		{
			return index switch
			{
				0 => "00:00", 
				1 => "02:00", 
				2 => "04:00", 
				3 => "06:00", 
				4 => "08:00", 
				5 => "12:00", 
				6 => "18:00", 
				7 => "22:00", 
				_ => "04:00", 
			};
		}

		private void SaveButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				_settings.AutoUpdateEnabled = AutoUpdateEnabledCheckBox.IsChecked == true;
				_settings.UpdateIntervalDays = GetIntervalFromIndex(UpdateIntervalComboBox.SelectedIndex);
				_settings.AutoUpdateTime = GetTimeFromIndex(AutoUpdateTimeComboBox.SelectedIndex);
				_settings.CnnvdApiKey = CnnvdApiKeyTextBox.Text.Trim();
				_settings.CncertApiKey = CncertApiKeyTextBox.Text.Trim();
				_settings.IncrementalUpdate = IncrementalUpdateCheckBox.IsChecked == true;
				_settings.AutoBackup = AutoBackupCheckBox.IsChecked == true;
				_settings.NotifyOnComplete = NotifyOnCompleteCheckBox.IsChecked == true;
				_settings.KeepUpdateLog = KeepUpdateLogCheckBox.IsChecked == true;
				string contents = JsonSerializer.Serialize(_settings, new JsonSerializerOptions
				{
					WriteIndented = true
				});
				File.WriteAllText(_settingsPath, contents);
				System.Windows.MessageBox.Show("设置已保存成功！", "成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				base.DialogResult = true;
				Close();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("保存设置失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private void CancelButton_Click(object sender, RoutedEventArgs e)
		{
			base.DialogResult = false;
			Close();
		}

		private void ResetButton_Click(object sender, RoutedEventArgs e)
		{
			if (System.Windows.MessageBox.Show("确定要恢复默认设置吗？", "确认", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
			{
				_settings = new DatabaseSettings();
				AutoUpdateEnabledCheckBox.IsChecked = _settings.AutoUpdateEnabled;
				UpdateIntervalComboBox.SelectedIndex = 2;
				AutoUpdateTimeComboBox.SelectedIndex = 2;
				CnnvdApiKeyTextBox.Text = "";
				CncertApiKeyTextBox.Text = "";
				IncrementalUpdateCheckBox.IsChecked = false;
				AutoBackupCheckBox.IsChecked = true;
				NotifyOnCompleteCheckBox.IsChecked = true;
				KeepUpdateLogCheckBox.IsChecked = true;
				System.Windows.MessageBox.Show("已恢复默认设置，请点击保存按钮应用更改", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
		}

