	public class EmailConfigWindow : Window, IComponentConnector
	{
		private readonly string _configPath;

		internal System.Windows.Controls.TextBox SmtpServerTextBox;

		internal System.Windows.Controls.TextBox SmtpPortTextBox;

		internal System.Windows.Controls.CheckBox EnableSslCheckBox;

		internal System.Windows.Controls.TextBox FromEmailTextBox;

		internal System.Windows.Controls.TextBox FromNameTextBox;

		internal System.Windows.Controls.TextBox UsernameTextBox;

		internal PasswordBox PasswordBox;

		internal System.Windows.Controls.TextBox TestRecipientTextBox;

		internal System.Windows.Controls.Button TestConnectionButton;

		internal System.Windows.Controls.Button SaveConfigButton;

		internal System.Windows.Controls.Button CancelButton;

		private bool _contentLoaded;

		public EmailConfigWindow()
		{
			InitializeComponent();
			_configPath = System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "NetSecurityScanner", "email_config.json");
			base.Loaded += EmailConfigWindow_Loaded;
		}

		private void EmailConfigWindow_Loaded(object sender, RoutedEventArgs e)
		{
			LoadConfig();
		}

		private void LoadConfig()
		{
			try
			{
				if (File.Exists(_configPath))
				{
					EmailConfig emailConfig = JsonSerializer.Deserialize<EmailConfig>(File.ReadAllText(_configPath));
					if (emailConfig != null)
					{
						SmtpServerTextBox.Text = emailConfig.SmtpServer ?? "";
						SmtpPortTextBox.Text = emailConfig.SmtpPort.ToString();
						EnableSslCheckBox.IsChecked = emailConfig.EnableSsl;
						FromEmailTextBox.Text = emailConfig.FromEmail ?? "";
						FromNameTextBox.Text = emailConfig.FromName ?? "网络安全扫描器";
						UsernameTextBox.Text = emailConfig.Username ?? "";
						PasswordBox.Password = emailConfig.Password ?? "";
					}
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("加载配置失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private void QQEmailTemplate_Click(object sender, RoutedEventArgs e)
		{
			SmtpServerTextBox.Text = "smtp.qq.com";
			SmtpPortTextBox.Text = "587";
			EnableSslCheckBox.IsChecked = true;
		}

		private void NeteaseEmailTemplate_Click(object sender, RoutedEventArgs e)
		{
			SmtpServerTextBox.Text = "smtp.163.com";
			SmtpPortTextBox.Text = "25";
			EnableSslCheckBox.IsChecked = true;
		}

		private void GmailTemplate_Click(object sender, RoutedEventArgs e)
		{
			SmtpServerTextBox.Text = "smtp.gmail.com";
			SmtpPortTextBox.Text = "587";
			EnableSslCheckBox.IsChecked = true;
		}

		private void OutlookTemplate_Click(object sender, RoutedEventArgs e)
		{
			SmtpServerTextBox.Text = "smtp.office365.com";
			SmtpPortTextBox.Text = "587";
			EnableSslCheckBox.IsChecked = true;
		}

		private async void TestConnectionButton_Click(object sender, RoutedEventArgs e)
		{
			EmailConfig configFromUI = GetConfigFromUI();
			if (configFromUI == null)
			{
				return;
			}
			string text = TestRecipientTextBox.Text.Trim();
			if (string.IsNullOrEmpty(text))
			{
				System.Windows.MessageBox.Show("请输入测试收件人邮箱", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			try
			{
				TestConnectionButton.IsEnabled = false;
				TestConnectionButton.Content = "发送中...";
				await new EmailNotificationService(configFromUI.SmtpServer, configFromUI.SmtpPort, configFromUI.Username, configFromUI.Password, configFromUI.FromEmail).SendScanNotificationAsync(text, "测试邮件", 0, 0);
				System.Windows.MessageBox.Show("测试邮件发送成功！", "成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("测试邮件发送失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			finally
			{
				TestConnectionButton.IsEnabled = true;
				TestConnectionButton.Content = "\ud83e\uddea 测试连接";
			}
		}

		private void SaveConfigButton_Click(object sender, RoutedEventArgs e)
		{
			EmailConfig configFromUI = GetConfigFromUI();
			if (configFromUI == null)
			{
				return;
			}
			try
			{
				string directoryName = System.IO.Path.GetDirectoryName(_configPath);
				if (!Directory.Exists(directoryName))
				{
					Directory.CreateDirectory(directoryName);
				}
				string contents = JsonSerializer.Serialize(configFromUI, new JsonSerializerOptions
				{
					WriteIndented = true
				});
				File.WriteAllText(_configPath, contents);
				System.Windows.MessageBox.Show("邮件配置已保存", "成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				base.DialogResult = true;
				Close();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("保存配置失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private void CancelButton_Click(object sender, RoutedEventArgs e)
		{
			base.DialogResult = false;
			Close();
		}

		private EmailConfig? GetConfigFromUI()
		{
			if (string.IsNullOrWhiteSpace(SmtpServerTextBox.Text))
			{
				System.Windows.MessageBox.Show("请输入SMTP服务器地址", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return null;
			}
			if (!int.TryParse(SmtpPortTextBox.Text, out var result))
			{
				System.Windows.MessageBox.Show("请输入有效的端口号", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return null;
			}
			return new EmailConfig
			{
				SmtpServer = SmtpServerTextBox.Text.Trim(),
				SmtpPort = result,
				EnableSsl = (EnableSslCheckBox.IsChecked ?? true),
				FromEmail = FromEmailTextBox.Text.Trim(),
				FromName = FromNameTextBox.Text.Trim(),
				Username = UsernameTextBox.Text.Trim(),
				Password = PasswordBox.Password
			};
		}

