		}

		private void ExpertModeWindow_Loaded(object sender, RoutedEventArgs e)
		{
			try
			{
				InitializeControls();
				RealTimePortResultsDataGrid.MouseDoubleClick += RealTimePortResultsDataGrid_MouseDoubleClick;
				RealTimeVulnResultsDataGrid.MouseDoubleClick += RealTimeVulnResultsDataGrid_MouseDoubleClick;
				LoadDefaultConfig();
				UpdateConfigSummary();
				ParseTargetCount();
				UpdateScanPlanPreview();
				try
				{
					string text = RustScannerClient.FindRustScannerExecutable();
					_useRustScanner = text != null;
					RustEngineRadio.IsChecked = _useRustScanner;
					BuiltInEngineRadio.IsChecked = !_useRustScanner;
					RefreshRustEngineStatus();
				}
				catch
				{
					_useRustScanner = false;
				}
				TargetInputTextBox.TextChanged += delegate
				{
					ParseTargetCount();
					UpdateScanPlanPreview();
				};
				TargetInputTextBox.TextChanged += delegate
				{
					UpdateStartButtonState();
				};
				if (CustomPortsTextBox != null)
				{
					CustomPortsTextBox.TextChanged += delegate
					{
						UpdateStartButtonState();
					};
				}
				if (CustomPortsRadio != null)
				{
					CustomPortsRadio.Checked += delegate
					{
						UpdateStartButtonState();
					};
				}
				if (CommonPortsRadio != null)
				{
					CommonPortsRadio.Checked += delegate
					{
						UpdateStartButtonState();
					};
				}
				if (SensitivePortsRadio != null)
				{
					SensitivePortsRadio.Checked += delegate
					{
						UpdateStartButtonState();
					};
				}
				if (AllPortsRadio != null)
				{
					AllPortsRadio.Checked += delegate
					{
						UpdateStartButtonState();
					};
				}
				UpdateStartButtonState();
				LoadPocPlugins();
				try
				{
					string path = System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "NetSecurityScanner", "expert_last_config.json");
					if (File.Exists(path))
					{
						JsonDocument jsonDocument = JsonDocument.Parse(File.ReadAllText(path, Encoding.UTF8));
						if (jsonDocument.RootElement.TryGetProperty("Config", out var value))
						{
							ExpertScanConfiguration expertScanConfiguration = JsonSerializer.Deserialize<ExpertScanConfiguration>(value.GetRawText(), new JsonSerializerOptions
							{
								PropertyNameCaseInsensitive = true
							});
							if (expertScanConfiguration != null)
							{
								ApplyConfig(expertScanConfiguration);
								AppendLog("已恢复上次使用的配置");
							}
						}
						if (jsonDocument.RootElement.TryGetProperty("SelectedTab", out var value2))
						{
							int @int = value2.GetInt32();
							if (ExpertTabControl != null && @int >= 0 && @int < ExpertTabControl.Items.Count)
							{
								ExpertTabControl.SelectedIndex = @int;
							}
						}
						if (jsonDocument.RootElement.TryGetProperty("UseRustScanner", out var value3))
						{
							_useRustScanner = value3.GetBoolean();
							if (RustEngineRadio != null)
							{
								RustEngineRadio.IsChecked = _useRustScanner;
							}
							if (BuiltInEngineRadio != null)
							{
								BuiltInEngineRadio.IsChecked = !_useRustScanner;
							}
						}
					}
				}
				catch
				{
				}
				RegisterNmapTemplates();
				RefreshCustomTemplateList();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("窗口加载时发生错误: " + ex.Message + "\n\n" + ex.StackTrace, "加载错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

