		private void ParseTargetCount()
		{
			try
			{
				if (TargetInputTextBox == null || TargetCountTextBlock == null)
				{
					return;
				}
				string text = TargetInputTextBox.Text?.Trim() ?? "";
				int num = 0;
				if (string.IsNullOrEmpty(text))
				{
					num = 0;
				}
				else
				{
					System.Windows.Controls.RadioButton singleIpRadio = SingleIpRadio;
					if (singleIpRadio == null || singleIpRadio.IsChecked != true)
					{
						System.Windows.Controls.RadioButton regexRadio = RegexRadio;
						if (regexRadio == null || regexRadio.IsChecked != true)
						{
							System.Windows.Controls.RadioButton ipRangeRadio = IpRangeRadio;
							if (ipRangeRadio != null && ipRangeRadio.IsChecked == true)
							{
								string[] array = text.Split('-');
								if (array.Length == 2 && IPAddress.TryParse(array[0].Trim(), out IPAddress address) && IPAddress.TryParse(array[1].Trim(), out address))
								{
									long num2 = IPToLong(array[0].Trim());
									num = (int)(IPToLong(array[1].Trim()) - num2 + 1);
									if (num > 65536)
									{
										num = 65536;
									}
								}
								else
								{
									num = 0;
								}
							}
							else
							{
								System.Windows.Controls.RadioButton cidrRadio = CidrRadio;
								if (cidrRadio != null && cidrRadio.IsChecked == true)
								{
									if (text.Contains('/') && int.TryParse(text.Split('/')[1], out var result))
									{
										switch (result)
										{
										case 0:
											num = 65536;
											break;
										case 1:
										case 2:
										case 3:
										case 4:
										case 5:
										case 6:
										case 7:
										case 8:
										case 9:
										case 10:
										case 11:
										case 12:
										case 13:
										case 14:
										case 15:
										case 16:
										case 17:
										case 18:
										case 19:
										case 20:
										case 21:
										case 22:
										case 23:
										case 24:
										case 25:
										case 26:
										case 27:
										case 28:
										case 29:
										case 30:
										case 31:
										case 32:
										{
											int num3 = 32 - result;
											num = (int)Math.Min(1L << num3, 65536L);
											break;
										}
										}
									}
								}
								else
								{
									System.Windows.Controls.RadioButton fileRadio = FileRadio;
									num = ((fileRadio == null || fileRadio.IsChecked != true) ? text.Split(new char[3] { ',', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries).Length : text.Split(new char[2] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries).Length);
								}
							}
							goto IL_0237;
						}
					}
					num = ((!string.IsNullOrWhiteSpace(text)) ? 1 : 0);
				}
				goto IL_0237;
				IL_0237:
				TargetCountTextBlock.Text = $"目标数量: {num}";
			}
			catch
			{
				if (TargetCountTextBlock != null)
				{
					TargetCountTextBlock.Text = "目标数量: -";
				}
			}
		}

		private long IPToLong(string ip)
		{
			byte[] addressBytes = IPAddress.Parse(ip).GetAddressBytes();
			return (long)(((ulong)addressBytes[0] << 24) | ((ulong)addressBytes[1] << 16) | ((ulong)addressBytes[2] << 8) | addressBytes[3]);
		}

		private void ImportFileButton_Click(object sender, RoutedEventArgs e)
		{
			Microsoft.Win32.OpenFileDialog openFileDialog = new Microsoft.Win32.OpenFileDialog
			{
				Filter = "文本文件 (*.txt;*.csv)|*.txt;*.csv|所有文件 (*.*)|*.*",
				Title = "导入目标列表"
			};
			if (openFileDialog.ShowDialog() != true)
			{
				return;
			}
			try
			{
				List<string> list = (from l in File.ReadAllLines(openFileDialog.FileName)
					where !string.IsNullOrWhiteSpace(l)
					select l.Trim()).ToList();
				TargetInputTextBox.Text = string.Join(Environment.NewLine, list);
				FileRadio.IsChecked = true;
				ParseTargetCount();
				System.Windows.MessageBox.Show($"成功导入 {list.Count} 个目标", "导入成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导入文件失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

