		private void LoadPresetButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				string path = System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "NetSecurityScanner", "expert_presets");
				if (!Directory.Exists(path))
				{
					System.Windows.MessageBox.Show("暂无已保存的预设", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				string[] files = Directory.GetFiles(path, "*.json");
				if (files.Length == 0)
				{
					System.Windows.MessageBox.Show("暂无已保存的预设", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				Dictionary<string, string> presetList = new Dictionary<string, string>();
				string[] array = files;
				foreach (string text in array)
				{
					presetList[System.IO.Path.GetFileNameWithoutExtension(text)] = text;
				}
				Window dialog = new Window
				{
					Title = "加载预设",
					Width = 400.0,
					Height = 350.0,
					WindowStartupLocation = WindowStartupLocation.CenterOwner,
					Owner = this,
					ResizeMode = ResizeMode.NoResize
				};
				StackPanel stackPanel = new StackPanel
				{
					Margin = new Thickness(15.0)
				};
				stackPanel.Children.Add(new TextBlock
				{
					Text = "选择要加载的预设:",
					FontSize = 14.0,
					FontWeight = FontWeights.Bold,
					Margin = new Thickness(0.0, 0.0, 0.0, 10.0)
				});
				System.Windows.Controls.ListBox listBox = new System.Windows.Controls.ListBox
				{
					Height = 200.0
				};
				foreach (string key in presetList.Keys)
				{
					listBox.Items.Add(key);
				}
				stackPanel.Children.Add(listBox);
				StackPanel stackPanel2 = new StackPanel
				{
					Orientation = System.Windows.Controls.Orientation.Horizontal,
					HorizontalAlignment = System.Windows.HorizontalAlignment.Right,
					Margin = new Thickness(0.0, 10.0, 0.0, 0.0)
				};
				System.Windows.Controls.Button button = new System.Windows.Controls.Button
				{
					Content = "加载",
					Width = 80.0,
					Height = 30.0,
					Background = new SolidColorBrush(System.Windows.Media.Color.FromRgb(39, 174, 96)),
					Foreground = System.Windows.Media.Brushes.White,
					BorderThickness = new Thickness(0.0),
					Margin = new Thickness(5.0, 0.0, 0.0, 0.0)
				};
				System.Windows.Controls.Button button2 = new System.Windows.Controls.Button
				{
					Content = "删除",
					Width = 80.0,
					Height = 30.0,
					Background = new SolidColorBrush(System.Windows.Media.Color.FromRgb(231, 76, 60)),
					Foreground = System.Windows.Media.Brushes.White,
					BorderThickness = new Thickness(0.0),
					Margin = new Thickness(5.0, 0.0, 0.0, 0.0)
				};
				System.Windows.Controls.Button button3 = new System.Windows.Controls.Button
				{
					Content = "取消",
					Width = 80.0,
					Height = 30.0,
					Margin = new Thickness(5.0, 0.0, 0.0, 0.0)
				};
				stackPanel2.Children.Add(button);
				stackPanel2.Children.Add(button2);
				stackPanel2.Children.Add(button3);
				stackPanel.Children.Add(stackPanel2);
				dialog.Content = stackPanel;
				button.Click += delegate
				{
					if (listBox.SelectedItem != null)
					{
						string text3 = listBox.SelectedItem.ToString();
						ExpertScanConfiguration expertScanConfiguration = JsonSerializer.Deserialize<ExpertScanConfiguration>(File.ReadAllText(presetList[text3], Encoding.UTF8), new JsonSerializerOptions
						{
							PropertyNameCaseInsensitive = true
						});
						if (expertScanConfiguration != null)
						{
							ApplyConfig(expertScanConfiguration);
							UpdateConfigSummary();
							AppendLog("已加载预设: " + text3);
						}
						dialog.DialogResult = true;
						dialog.Close();
					}
				};
				button2.Click += delegate
				{
					if (listBox.SelectedItem != null)
					{
						string text2 = listBox.SelectedItem.ToString();
						if (System.Windows.MessageBox.Show("确认删除预设 \"" + text2 + "\"？", "确认", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
						{
							File.Delete(presetList[text2]);
							listBox.Items.Remove(text2);
							presetList.Remove(text2);
							AppendLog("已删除预设: " + text2);
						}
					}
				};
				button3.Click += delegate
				{
					dialog.Close();
				};
				dialog.ShowDialog();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("加载预设失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

