				if (!string.IsNullOrWhiteSpace(text))
				{
					try
					{
						ExpertScanConfiguration value = CollectConfig();
						string text2 = System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "NetSecurityScanner", "expert_presets");
						Directory.CreateDirectory(text2);
						string text3 = string.Join("_", text.Split(System.IO.Path.GetInvalidFileNameChars()));
						string path = System.IO.Path.Combine(text2, text3 + ".json");
						string contents = JsonSerializer.Serialize(value, new JsonSerializerOptions
						{
							WriteIndented = true
						});
						File.WriteAllText(path, contents, Encoding.UTF8);
						System.Windows.MessageBox.Show("预设已保存: " + text, "保存成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
						AppendLog("已保存预设: " + text);
					}
					catch (Exception ex)
					{
						System.Windows.MessageBox.Show("保存预设失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
					}
					inputDialog.DialogResult = true;
					inputDialog.Close();
				}
			};
			button2.Click += delegate
			{
				inputDialog.Close();
			};
			inputDialog.ShowDialog();
		}

		private void ImportConfigButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				Microsoft.Win32.OpenFileDialog openFileDialog = new Microsoft.Win32.OpenFileDialog
				{
					Filter = "配置文件 (*.json)|*.json|所有文件 (*.*)|*.*",
					Title = "导入配置文件"
				};
				if (openFileDialog.ShowDialog() == true)
				{
					ExpertScanConfiguration expertScanConfiguration = JsonSerializer.Deserialize<ExpertScanConfiguration>(File.ReadAllText(openFileDialog.FileName, Encoding.UTF8), new JsonSerializerOptions
					{
						PropertyNameCaseInsensitive = true
					});
					if (expertScanConfiguration == null)
					{
						System.Windows.MessageBox.Show("配置文件解析失败，请检查文件格式是否正确。", "导入失败", MessageBoxButton.OK, MessageBoxImage.Hand);
						return;
					}
					ApplyConfig(expertScanConfiguration);
					UpdateConfigSummary();
					UpdateScanPlanPreview();
					System.Windows.MessageBox.Show("配置已从文件导入:\n" + openFileDialog.FileName + "\n\n提示：目标、端口模式、并发、超时、输出格式等设置已更新。", "导入成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					AppendLog("已导入配置文件: " + System.IO.Path.GetFileName(openFileDialog.FileName));
				}
			}
			catch (JsonException ex)
			{
				System.Windows.MessageBox.Show("JSON 格式错误: " + ex.Message + "\n\n请确保文件是有效的 ExpertScanConfiguration 格式。", "导入失败", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			catch (Exception ex2)
			{
				System.Windows.MessageBox.Show("导入失败: " + ex2.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private void ExportConfigButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				ExpertScanConfiguration value = CollectConfig();
				Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
				{
					Filter = "配置文件 (*.json)|*.json",
					FileName = $"expert_config_{DateTime.Now:yyyyMMdd_HHmmss}.json",
					Title = "导出配置文件"
				};
				if (saveFileDialog.ShowDialog() == true)
				{
					string contents = JsonSerializer.Serialize(value, new JsonSerializerOptions
					{
						WriteIndented = true,
						Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
					});
					File.WriteAllText(saveFileDialog.FileName, contents, new UTF8Encoding(encoderShouldEmitUTF8Identifier: true));
					System.Windows.MessageBox.Show("配置已导出到:\n" + saveFileDialog.FileName + "\n\n可使用「导入配置」功能在其他环境加载此配置。", "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					AppendLog("已导出配置到: " + saveFileDialog.FileName);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出配置失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private ExpertScanConfiguration CollectConfig()
		{
			ExpertScanConfiguration expertScanConfiguration = new ExpertScanConfiguration();
			System.Windows.Controls.RadioButton singleIpRadio = SingleIpRadio;
			if (singleIpRadio != null && singleIpRadio.IsChecked == true)
			{
				expertScanConfiguration.TargetType = "Single";
			}
			else
			{
				System.Windows.Controls.RadioButton ipRangeRadio = IpRangeRadio;
				if (ipRangeRadio != null && ipRangeRadio.IsChecked == true)
				{
					expertScanConfiguration.TargetType = "Range";
