			System.Windows.Controls.CheckBox saveOutputCheckBox = SaveOutputCheckBox;
			expertScanConfiguration.SaveOutput = saveOutputCheckBox != null && saveOutputCheckBox.IsChecked == true;
			expertScanConfiguration.OutputDir = OutputDirTextBox?.Text?.Trim() ?? "";
