		private void StartExpertScanButton_Click(object sender, RoutedEventArgs e)
		{
			//IL_032e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0333: Unknown result type (might be due to invalid IL or missing references)
			//IL_034c: Expected O, but got Unknown
			if (StartExpertScanButton != null && !StartExpertScanButton.IsEnabled)
			{
				return;
			}
			if (_isScanning)
			{
				AppendLog("扫描进行中，请先点击「停止」或等待当前扫描完成");
				return;
			}
			ExpertScanConfiguration config = CollectConfig();
			if (string.IsNullOrWhiteSpace(config.TargetValue))
			{
				System.Windows.MessageBox.Show("请输入扫描目标", "输入错误", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			if (config.PortMode == "Custom" && string.IsNullOrWhiteSpace(config.CustomPorts))
			{
				System.Windows.MessageBox.Show("已选择「自定义端口」模式，请填写至少一个端口", "输入错误", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				if (CustomPortsTextBox != null)
				{
					CustomPortsTextBox.Focus();
				}
				return;
			}
			_currentConfig = config;
			if (config.TargetType == "Regex")
			{
				try
				{
					new Regex(config.TargetValue ?? "");
				}
				catch (ArgumentException ex)
				{
					System.Windows.MessageBox.Show("正则表达式无效: " + ex.Message + "\n\n请检查括号、字符类、转义符等。", "目标配置错误", MessageBoxButton.OK, MessageBoxImage.Hand);
					AppendLog("❌ 正则预校验失败: " + ex.Message);
					return;
				}
			}
			if (config.SaveOutput && string.IsNullOrWhiteSpace(config.OutputDir) && System.Windows.MessageBox.Show("已勾选「保存扫描输出到文件」，但输出目录为空。\n\n是否继续扫描（结果将只显示在界面，不保存到文件）？", "输出目录未设置", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.No)
			{
				return;
			}
			List<string> list = ResolveTargets(config);
			if ((list.Count > 256 && System.Windows.MessageBox.Show($"目标数量较多({list.Count}个)，扫描可能耗时较长。\n\n是否继续？", "目标数量警告", MessageBoxButton.YesNo, MessageBoxImage.Exclamation) == MessageBoxResult.No) || System.Windows.MessageBox.Show($"即将开始专家模式扫描\n\n目标: {config.TargetValue}\n端口模式: {GetPortModeText()}\nTCP并发: {config.TcpConcurrency}, UDP并发: {config.UdpConcurrency}\nTCP超时: {config.TcpTimeout}ms, UDP超时: {config.UdpTimeout}ms\n\n是否确认开始扫描？", "确认扫描", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.No)
			{
				return;
			}
			_cancellationTokenSource?.Dispose();
			_cancellationTokenSource = new CancellationTokenSource();
			_scanStartTime = DateTime.Now;
			_isScanning = true;
			_userRequestedCancel = false;
			DispatcherTimer? elapsedTimer = _elapsedTimer;
			if (elapsedTimer != null)
			{
				elapsedTimer.Stop();
			}
			_elapsedTimer = new DispatcherTimer
			{
				Interval = TimeSpan.FromSeconds(1.0)
			};
			_elapsedTimer.Tick += delegate
			{
				TimeSpan value = DateTime.Now - _scanStartTime;
				if (ElapsedTextBlock != null)
				{
					ElapsedTextBlock.Text = $"已用: {value:hh\\:mm\\:ss}";
				}
				if (_totalScannedTargets > 0 && ExpertScanProgressBar.Value > 0.0)
				{
					double num = ExpertScanProgressBar.Value / 100.0;
					if (num > 0.01)
					{
						TimeSpan value2 = TimeSpan.FromTicks((long)((double)value.Ticks / num * (1.0 - num)));
						if (RemainingTextBlock != null)
						{
							RemainingTextBlock.Text = $"预计剩余: {value2:hh\\:mm\\:ss}";
						}
					}
				}
			};
			_elapsedTimer.Start();
			if (ExpertTabControl != null)
			{
				ExpertTabControl.SelectedIndex = 4;
			}
			StartExpertScanButton.IsEnabled = false;
			StartExpertScanButton.Content = "⏳ 扫描中...";
			CancelExpertButton.IsEnabled = true;
			SetControlsEnabledWhileScanning(enabled: false);
			_scanTaskCompletionSource = new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);
			Task.Run(async delegate
			{
				try
				{
					await ExecuteExpertScanAsync(config, _cancellationTokenSource.Token);
				}
				catch (Exception ex2)
				{
					AppendLog("❌ 后台扫描任务异常: " + ex2.GetType().Name + " - " + ex2.Message);
				}
				finally
				{
					_scanTaskCompletionSource?.TrySetResult(result: true);
				}
			});
		}

		private void SetControlsEnabledWhileScanning(bool enabled)
		{
			if (LoadPresetButton != null)
			{
				LoadPresetButton.IsEnabled = enabled;
			}
			if (SavePresetButton != null)
			{
				SavePresetButton.IsEnabled = enabled;
			}
			if (ExportNmapButton != null)
			{
				ExportNmapButton.IsEnabled = enabled;
			}
			if (ValidateConfigButton != null)
			{
				ValidateConfigButton.IsEnabled = enabled;
			}
		}

		private string GetPortModeText()
		{
			if (AllPortsRadio.IsChecked == true)
			{
				return "全部端口(1-65535)";
			}
			if (SensitivePortsRadio.IsChecked == true)
			{
				return "敏感端口";
			}
			if (CustomPortsRadio.IsChecked == true)
			{
				return "自定义端口";
			}
			return "常用端口(Top 1000)";
		}

		private async Task ExecuteExpertScanAsync(ExpertScanConfiguration config, CancellationToken cancellationToken)
		{
			_ = 6;
			try
			{
				config.StartTime = DateTime.Now;
				try
				{
					if (RealTimePortResultsDataGrid != null)
					{
						List<PortScanResult> itemsSource;
						lock (_resultsLock)
						{
							itemsSource = _allPortScanResults?.ToList() ?? new List<PortScanResult>();
						}
						RealTimePortResultsDataGrid.ItemsSource = itemsSource;
						RealTimePortResultsDataGrid.Items.Refresh();
					}
					if (RealTimeVulnResultsDataGrid != null)
					{
						List<VulnerabilityResult> itemsSource2;
						lock (_resultsLock)
						{
							itemsSource2 = _allVulnResults?.ToList() ?? new List<VulnerabilityResult>();
						}
						RealTimeVulnResultsDataGrid.ItemsSource = itemsSource2;
						RealTimeVulnResultsDataGrid.Items.Refresh();
					}
					AppendLog("已自动重置端口/漏洞结果筛选，新结果将立即可见");
				}
				catch (Exception ex3)
				{
					AppendLog("重置筛选失败: " + ex3.Message);
				}
				_allPortScanResults = new List<PortScanResult>();
