		private async Task<List<PortScanResult>> ExecuteRustScanAsync(string target, List<int> ports, ExpertScanConfiguration config, CancellationToken cancellationToken)
		{
			List<PortScanResult> allResults = new List<PortScanResult>();
			try
			{
				if (_rustClient == null)
				{
					_rustClient = new RustScannerClient();
					_rustClient.OnLog += delegate(object? s, string msg)
					{
						AppendLog("[Rust] " + msg);
					};
					_rustClient.OnProgressChanged += delegate(object? s, RustScanProgress p)
					{
						RustScanProgress p2 = p;
						((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
						{
							if (p2.ProgressPercent > 0.0)
							{
								ExpertScanProgressBar.Value = p2.ProgressPercent;
							}
						});
					};
				}
				ScanProfileConfig val = new ScanProfileConfig
				{
					TcpConcurrency = config.TcpConcurrency,
					UdpConcurrency = config.UdpConcurrency,
					TimeoutMs = config.TcpTimeout,
					RetryCount = config.RetryCount,
					EnableServiceDetection = config.ServiceDetection,
					EnablePingProbe = config.HostDiscovery
				};
				string text = ((config.TcpScan && config.UdpScan) ? "tcp,udp" : (config.UdpScan ? "udp" : "tcp"));
				List<RustPortResult> list = await _rustClient.ScanPortsAsync(new List<string> { target }, ports, text, config.TcpConcurrency, config.TcpTimeout, config.UdpTimeout, config.ServiceDetection, true, cancellationToken, val);
				foreach (RustPortResult item in list)
				{
					string confidence = ((item.Status == "open") ? "高" : "低");
					allResults.Add(new PortScanResult
					{
						TargetIp = item.TargetIp,
						PortNumber = item.Port,
						Status = ((item.Status == "open") ? "开放" : "关闭"),
						Service = (item.Service ?? ""),
						ServiceVersion = (item.Version ?? ""),
						ResponseTime = ((item.ScanTimeMs > 0) ? item.ScanTimeMs.ToString() : "-"),
						Confidence = confidence,
						ScanDurationMs = item.ScanTimeMs
					});
				}
				AppendLog($"  Rust扫描完成: {target} - {list.Count((RustPortResult r2) => r2.Status == "open")} 个开放端口");
			}
			catch (Exception ex)
			{
				AppendLog("  Rust引擎扫描失败，降级到内置扫描器: " + ex.Message);
				Progress<int> progress = new Progress<int>(delegate
				{
				});
				allResults = await ExecuteNativeScanAsync(target, ports, config, progress, cancellationToken);
			}
			return allResults;
		}

		private async Task<List<PortScanResult>> ExecuteNativeScanAsync(string target, List<int> ports, ExpertScanConfiguration config, IProgress<int> progress, CancellationToken cancellationToken)
		{
			List<PortScanResult> result = new List<PortScanResult>();
			List<PortScanResult> tcpResults = new List<PortScanResult>();
			List<PortScanResult> udpResults = new List<PortScanResult>();
			List<Task> list = new List<Task>();
			if (config.TcpScan)
			{
				list.Add(_portScanner.ScanTcpPortsAsync(target, ports, progress, cancellationToken, (ScanPolicy)null).ContinueWith(delegate(Task<List<PortScanResult>> t)
				{
					if (t.Status == TaskStatus.RanToCompletion)
					{
						lock (tcpResults)
						{
							tcpResults.AddRange(t.Result);
						}
					}
				}, TaskScheduler.Default));
			}
			if (config.UdpScan)
			{
				list.Add(_portScanner.ScanUdpPortsAsync(target, ports, progress, cancellationToken, (ScanPolicy)null).ContinueWith(delegate(Task<List<PortScanResult>> t)
				{
					if (t.Status == TaskStatus.RanToCompletion)
					{
						lock (udpResults)
						{
							udpResults.AddRange(t.Result);
						}
					}
				}, TaskScheduler.Default));
			}
			if (list.Count > 0)
			{
				try
				{
					await Task.WhenAll(list);
				}
				catch (Exception ex)
				{
					AppendLog("  扫描任务执行异常: " + ex.Message);
				}
				Dictionary<int, PortScanResult> dictionary = new Dictionary<int, PortScanResult>();
				foreach (PortScanResult item in tcpResults)
				{
					dictionary[item.PortNumber] = item;
				}
				foreach (PortScanResult item2 in udpResults)
				{
					if (!dictionary.ContainsKey(item2.PortNumber))
					{
						dictionary[item2.PortNumber] = item2;
					}
				}
				result = dictionary.Values.ToList();
			}
			return result;
		}

		private string CalculateRiskLevel(int openPortCount, int vulnerabilityCount)
		{
			int num = openPortCount * 5 + vulnerabilityCount * 10;
			if (num >= 50 || vulnerabilityCount >= 5)
			{
				return "高";
			}
			if (num >= 20)
			{
				return "中";
			}
			return "低";
		}

		private async Task<string> ResolveHostnameAsync(string ip, CancellationToken cancellationToken)
		{
			try
			{
				using CancellationTokenSource cts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
				cts.CancelAfter(3000);
				IPHostEntry iPHostEntry = await Dns.GetHostEntryAsync(ip).ConfigureAwait(continueOnCapturedContext: false);
				if (!string.IsNullOrWhiteSpace(iPHostEntry.HostName))
				{
					return iPHostEntry.HostName;
				}
				if (iPHostEntry.Aliases != null && iPHostEntry.Aliases.Length != 0)
				{
					return iPHostEntry.Aliases[0];
				}
				return null;
			}
			catch (OperationCanceledException)
			{
				return "__TIMEOUT__";
			}
			catch (SocketException ex2)
			{
				return $"__SOCKERR:{ex2.SocketErrorCode}";
			}
			catch (ArgumentException)
			{
				return "__INVALID_IP__";
			}
			catch (Exception ex4)
			{
				return "__ERR:" + ex4.GetType().Name;
			}
		}

		private async Task<bool> IsHostAliveAsync(string target, CancellationToken cancellationToken)
		{
			string target2 = target;
			int[] source = new int[6] { 80, 443, 22, 21, 3389, 8080 };
			CancellationTokenSource cts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
			try
			{
				cts.CancelAfter(2000);
				List<Task<bool>> tasks = source.Select((int p) => Task.Run(async delegate
				{
					try
					{
						using TcpClient tcp = new TcpClient();
						Task connectTask = tcp.ConnectAsync(target2, p);
						Task task = Task.Delay(1500, cts.Token);
						if (await Task.WhenAny(connectTask, task) == connectTask && tcp.Connected)
						{
							return true;
						}
						return false;
					}
					catch
					{
						return false;
					}
				}, cts.Token)).ToList();
				try
				{
					return (await Task.WhenAll(tasks)).Any((bool r) => r);
				}
				catch (Exception ex)
				{
					AppendLog("  ⚠\ufe0f 主机存活探测异常: " + ex.GetType().Name + " - " + ex.Message);
					return false;
				}
			}
			finally
			{
				if (cts != null)
				{
					((IDisposable)cts).Dispose();
				}
			}
		}

		private List<string> ResolveTargets(ExpertScanConfiguration config)
		{
			List<string> list = new List<string>();
			switch (config.TargetType)
			{
			case "Single":
				if (!string.IsNullOrWhiteSpace(config.TargetValue))
				{
					list.Add(config.TargetValue.Trim());
				}
				break;
			case "Range":
			{
				string[] array = config.TargetValue.Split('-');
				if (array.Length == 2 && IPAddress.TryParse(array[0].Trim(), out IPAddress _) && IPAddress.TryParse(array[1].Trim(), out IPAddress _))
				{
					long num = IPToLong(array[0].Trim());
					long num2 = IPToLong(array[1].Trim());
					if (num2 < num)
					{
						long num3 = num2;
						long num4 = num;
						num = num3;
						num2 = num4;
					}
					long num5 = num2 - num + 1;
					if (num5 > 65536)
					{
						AppendLog($"⚠\ufe0f IP段范围过大({num5}个)，将截断到 65536 个");
						num2 = num + 65535;
					}
					for (long num6 = num; num6 <= num2; num6++)
					{
						list.Add(LongToIP(num6));
					}
				}
				break;
			}
			case "CIDR":
			{
				if (!config.TargetValue.Contains('/'))
				{
					break;
				}
				string[] array4 = config.TargetValue.Split('/');
				if (!IPAddress.TryParse(array4[0], out IPAddress _) || !int.TryParse(array4[1], out var result))
				{
					break;
				}
				if (result < 0 || result > 32)
				{
					AppendLog($"⚠\ufe0f CIDR 前缀长度 {result} 无效，必须在 0-32 之间");
					break;
				}
				long num7 = IPToLong(array4[0]);
				int num8 = 32 - result;
				long num9 = ((num8 == 32) ? uint.MaxValue : ((1L << num8) - 1));
				long num10 = num7 & ~num9;
				long num11 = num10 | num9;
				long num12 = num11 - num10 + 1;
				long num13 = ((result >= 31) ? num10 : (num10 + 1));
				long num14 = ((result == 32) ? num10 : (num11 - 1));
				if (num12 > 65536)
				{
					AppendLog($"⚠\ufe0f CIDR 网段过大({num12}个)，将截断到 65536 个");
					num14 = num13 + 65535;
				}
				for (long num15 = num13; num15 <= num14; num15++)
				{
					list.Add(LongToIP(num15));
				}
				break;
			}
			case "File":
			{
				string[] source = config.TargetValue.Split(new char[2] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
				list.AddRange(from l in source
					select l.Trim() into l
					where !string.IsNullOrEmpty(l)
					select l);
				break;
			}
			case "Regex":
				try
				{
					Regex regex = new Regex(config.TargetValue);
					List<string> list2 = new List<string>();
					string[] array2 = new string[6] { "192.168.1.", "192.168.0.", "10.0.0.", "10.0.1.", "172.16.0.", "172.16.1." };
					for (int i = 0; i < 256; i++)
					{
						string[] array3 = array2;
						foreach (string value in array3)
						{
							list2.Add($"{value}{i}");
						}
					}
					foreach (string item in list2)
					{
						if (regex.IsMatch(item) && !list.Contains(item))
						{
							list.Add(item);
							if (list.Count >= 1000)
							{
								break;
							}
						}
					}
					if (list.Count == 0)
					{
						AppendLog("⚠\ufe0f 正则 '" + config.TargetValue + "' 未匹配任何地址，将按字面量作为目标");
						list.Add(config.TargetValue);
						break;
					}
					AppendLog($"ℹ\ufe0f 正则匹配到 {list.Count} 个目标");
				}
				catch (Exception ex)
				{
					AppendLog("⚠\ufe0f 正则表达式解析失败: " + ex.Message);
					if (!string.IsNullOrWhiteSpace(config.TargetValue))
					{
						list.Add(config.TargetValue.Trim());
					}
				}
				break;
			default:
				if (!string.IsNullOrWhiteSpace(config.TargetValue))
				{
					list.Add(config.TargetValue.Trim());
				}
				break;
			}
			if (!string.IsNullOrWhiteSpace(config.ExcludeHosts))
			{
				HashSet<string> excluded = (from s in config.ExcludeHosts.Split(new char[2] { ',', ' ' }, StringSplitOptions.RemoveEmptyEntries)
					select s.Trim()).ToHashSet();
				list.RemoveAll((string t) => excluded.Contains(t));
			}
			if (config.Randomize)
			{
				Random rnd = new Random();
				list = list.OrderBy((string t) => rnd.Next()).ToList();
			}
			return list;
		}

		private string LongToIP(long ipLong)
		{
			return $"{(ipLong >> 24) & 0xFF}.{(ipLong >> 16) & 0xFF}.{(ipLong >> 8) & 0xFF}.{ipLong & 0xFF}";
		}

		private List<int> ResolvePorts(ExpertScanConfiguration config)
		{
			List<int> list = new List<int>();
			switch (config.PortMode)
			{
			case "Common":
				list = Enumerable.Range(1, 1000).ToList();
				break;
			case "Sensitive":
				list = new int[28]
				{
					21, 22, 23, 25, 53, 110, 135, 139, 143, 443,
					445, 993, 995, 1433, 1521, 3306, 3389, 5432, 5900, 6379,
					8080, 8443, 9200, 27017, 5000, 5001, 8888, 9090
				}.ToList();
				break;
			case "All":
				list = Enumerable.Range(1, 65535).ToList();
				break;
			case "Custom":
			{
				if (string.IsNullOrWhiteSpace(config.CustomPorts))
				{
					break;
				}
				string[] array = config.CustomPorts.Split(new char[4] { ',', ' ', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
				foreach (string text in array)
				{
					int result3;
					if (text.Contains('-'))
					{
						string[] array2 = text.Split('-');
						if (array2.Length == 2 && int.TryParse(array2[0].Trim(), out var result) && int.TryParse(array2[1].Trim(), out var result2))
						{
							int num = Math.Max(1, Math.Min(result, result2));
							int num2 = Math.Min(65535, Math.Max(result, result2)) - num + 1;
							if (num2 > 0)
							{
								list.AddRange(Enumerable.Range(num, num2));
							}
							else
							{
								AppendLog("⚠\ufe0f 端口范围 '" + text + "' 无效，已跳过");
							}
						}
						else
						{
							AppendLog("⚠\ufe0f 端口范围 '" + text + "' 解析失败，已跳过");
						}
					}
					else if (int.TryParse(text, out result3))
					{
						if (result3 >= 1 && result3 <= 65535)
						{
							list.Add(result3);
						}
						else
						{
							AppendLog("⚠\ufe0f 端口 '" + text + "' 超出 1-65535 范围，已跳过");
						}
					}
					else
					{
						AppendLog("⚠\ufe0f 无法解析的端口值 '" + text + "'，已跳过");
					}
				}
				break;
			}
			}
			if (!string.IsNullOrWhiteSpace(config.ExcludePorts))
			{
				int result4;
				HashSet<int> excluded = (from s in config.ExcludePorts.Split(new char[2] { ',', ' ' }, StringSplitOptions.RemoveEmptyEntries)
					where int.TryParse(s, out result4)
					select s).Select(int.Parse).ToHashSet();
				list.RemoveAll((int p) => excluded.Contains(p));
			}
			List<int> source = list.Distinct().ToList();
			if (config.RandomPortOrder)
			{
				Random rnd = new Random();
				return source.OrderBy((int p) => rnd.Next()).ToList();
			}
			return source.OrderBy((int p) => p).ToList();
		}

