		private void CustomTemplateComboBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			try
			{
				object obj = CustomTemplateComboBox?.SelectedItem;
				CustomNmapTemplate val = (CustomNmapTemplate)((obj is CustomNmapTemplate) ? obj : null);
				if (val == null)
				{
					return;
				}
				ExpertScanConfiguration expertScanConfiguration = CollectConfig();
				Type typeFromHandle = typeof(ExpertScanConfiguration);
				foreach (KeyValuePair<string, object> item in val.Config)
				{
					PropertyInfo property = typeFromHandle.GetProperty(item.Key);
					if (property == null || !property.CanWrite)
					{
						continue;
					}
					try
					{
						object obj2 = null;
						obj2 = ((!(item.Value is JsonElement jsonElement)) ? Convert.ChangeType(item.Value, property.PropertyType) : JsonSerializer.Deserialize(jsonElement.GetRawText(), property.PropertyType));
						if (obj2 != null)
						{
							property.SetValue(expertScanConfiguration, obj2);
						}
					}
					catch
					{
					}
				}
				ApplyConfig(expertScanConfiguration);
				AppendLog("✅ 已应用自定义模板: " + val.Name);
			}
			catch (Exception ex)
			{
				AppendLog("❌ 应用自定义模板失败: " + ex.Message);
			}
		}

