		private static string? PromptForText(string title, string prompt, string defaultText = "")
		{
			try
			{
				Window win = new Window
				{
					Title = title,
					Width = 420.0,
					Height = 200.0,
					WindowStartupLocation = WindowStartupLocation.CenterOwner,
					ResizeMode = ResizeMode.NoResize,
					ShowInTaskbar = false
				};
				StackPanel stackPanel = new StackPanel
				{
					Margin = new Thickness(10.0)
				};
				stackPanel.Children.Add(new TextBlock
				{
					Text = prompt,
					Margin = new Thickness(0.0, 0.0, 0.0, 8.0)
				});
				System.Windows.Controls.TextBox tb = new System.Windows.Controls.TextBox
				{
					Text = defaultText,
					Margin = new Thickness(0.0, 0.0, 0.0, 8.0)
				};
				stackPanel.Children.Add(tb);
				StackPanel stackPanel2 = new StackPanel
				{
					Orientation = System.Windows.Controls.Orientation.Horizontal,
					HorizontalAlignment = System.Windows.HorizontalAlignment.Right
				};
				System.Windows.Controls.Button button = new System.Windows.Controls.Button
				{
					Content = "确定",
					Width = 80.0,
					Margin = new Thickness(0.0, 0.0, 8.0, 0.0),
					IsDefault = true
				};
				System.Windows.Controls.Button element = new System.Windows.Controls.Button
				{
					Content = "取消",
					Width = 80.0,
					IsCancel = true
				};
				string result = null;
				button.Click += delegate
				{
					result = tb.Text;
					win.DialogResult = true;
				};
				stackPanel2.Children.Add(button);
				stackPanel2.Children.Add(element);
				stackPanel.Children.Add(stackPanel2);
				win.Content = stackPanel;
				return (win.ShowDialog() == true) ? result : null;
			}
			catch
			{
				return null;
			}
		}

