		private string GenerateNmapCommand(ExpertScanConfiguration config)
		{
			List<string> list = new List<string> { "nmap" };
			if (config.SynScan)
			{
				list.Add("-sS");
			}
			else if (config.UdpScan && !config.TcpScan)
			{
				list.Add("-sU");
			}
			else if (config.UdpScan && config.TcpScan)
			{
				list.Add("-sS -sU");
			}
			if (config.ServiceDetection)
			{
				list.Add("-sV");
			}
			if (config.OsDetection)
			{
				list.Add("-O");
			}
			if (config.ScriptScan)
			{
				list.Add("-sC");
			}
			if (config.PortMode == "All")
			{
				list.Add("-p-");
			}
			else if (config.PortMode == "Sensitive")
			{
				list.Add("--top-ports 100");
			}
			else if (config.PortMode == "Custom" && !string.IsNullOrWhiteSpace(config.CustomPorts))
			{
				list.Add("-p " + config.CustomPorts);
			}
			else
			{
				list.Add("--top-ports 1000");
			}
			if (config.RateLimit)
			{
				list.Add($"--max-rate {config.PacketRate}");
			}
			if (config.StealthMode)
			{
				list.Add("-T2");
				list.Add("--max-retries 2");
			}
			if (config.Randomize)
			{
				list.Add("--randomize-hosts");
			}
			if (config.FragmentPackets)
			{
				list.Add("-f");
			}
			if (config.DecoyScan && !string.IsNullOrWhiteSpace(config.DecoyIps))
			{
				list.Add("-D " + config.DecoyIps);
			}
			if (!string.IsNullOrWhiteSpace(config.SourcePort) && int.TryParse(config.SourcePort, out var _))
			{
				list.Add("--source-port " + config.SourcePort);
			}
			if (config.TcpTimeout != 500)
			{
				list.Add($"--max-rtt-timeout {config.TcpTimeout}ms");
			}
			if (config.TcpConcurrency != 50)
			{
				list.Add($"--max-parallelism {config.TcpConcurrency}");
			}
			if (config.RetryCount != 1)
			{
				list.Add($"--max-retries {config.RetryCount}");
			}
			if (config.Verbosity == 0)
			{
				list.Add("-q");
			}
			else if (config.Verbosity >= 2)
			{
				list.Add("-v");
			}
			if (config.Verbosity == 3)
			{
				list.Add("-vv");
			}
			if (config.SaveOutput && !string.IsNullOrWhiteSpace(config.OutputDir))
			{
				string text = $"scan_{DateTime.Now:yyyyMMdd_HHmmss}";
				list.Add("-oN \"" + System.IO.Path.Combine(config.OutputDir, text + ".txt") + "\"");
			}
			if (config.ServiceDetection && config.ServiceIntensity > 0)
			{
				list.Add($"--version-intensity {config.ServiceIntensity}");
			}
			if (config.OsDetection && config.TcpScan)
			{
				list.Add("--osscan-limit");
			}
			if (!config.HostDiscovery)
			{
				list.Add("-Pn");
			}
			if (config.ShowOpenOnly)
			{
				list.Add("--open");
			}
			if (config.RateLimit && config.PacketRate > 0)
			{
				int num = Math.Max(1, config.PacketRate / 10);
				if (num < config.PacketRate)
				{
					list.Add($"--min-rate {num}");
				}
			}
			list.Add("--stats-every 5s");
			list.Add(config.TargetValue);
			return string.Join(" ", list);
		}

		private void ValidateConfigButton_Click(object sender, RoutedEventArgs e)
		{
			List<string> list = new List<string>();
			List<string> list2 = new List<string>();
			string text = TargetInputTextBox.Text.Trim();
			IPAddress address;
			if (string.IsNullOrWhiteSpace(text))
			{
				list.Add("未输入扫描目标");
			}
			else if (SingleIpRadio.IsChecked == true)
			{
				if (!IPAddress.TryParse(text, out address) && !IsValidHostname(text))
				{
					list2.Add("目标 '" + text + "' 可能不是有效的IP地址或主机名");
				}
			}
			else if (IpRangeRadio.IsChecked == true)
			{
				string[] array = text.Split('-');
				if (array.Length != 2 || !IPAddress.TryParse(array[0].Trim(), out address) || !IPAddress.TryParse(array[1].Trim(), out address))
				{
					list.Add("IP段范围格式错误，应为: 起始IP-结束IP");
				}
			}
			else if (CidrRadio.IsChecked == true && (!text.Contains('/') || !IPAddress.TryParse(text.Split('/')[0], out address)))
			{
				list.Add("CIDR格式错误，应为: IP/前缀长度");
			}
			if (CustomPortsRadio.IsChecked == true)
			{
				string text2 = CustomPortsTextBox.Text.Trim();
				string error;
				if (string.IsNullOrWhiteSpace(text2))
				{
					list.Add("自定义端口模式但未输入端口列表");
				}
				else if (!ValidatePortList(text2, out error))
				{
					list.Add(error);
				}
			}
			if (TcpConcurrencySlider.Value > 200.0)
			{
				list2.Add($"TCP并发数({(int)TcpConcurrencySlider.Value})较高，可能导致网络拥塞或触发IDS告警");
			}
			if (TcpTimeoutSlider.Value < 100.0)
			{
				list2.Add($"TCP超时({(int)TcpTimeoutSlider.Value}ms)过短，可能导致误判端口关闭");
			}
			if (StealthModeCheckBox.IsChecked == true && TcpConcurrencySlider.Value > 20.0)
			{
				list2.Add("Stealth模式建议降低并发数(≤20)以保持隐蔽性");
			}
			if (RateLimitCheckBox.IsChecked == true && PacketRateSlider.Value > 5000.0)
			{
				list2.Add($"速率限制({(int)PacketRateSlider.Value}pps)仍然较高，建议降低");
			}
			string text3 = "";
			if (list.Count == 0 && list2.Count == 0)
			{
				text3 = "✅ 配置验证通过！\n\n所有设置均正确，可以开始扫描。";
				System.Windows.MessageBox.Show(text3, "验证通过", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			if (list.Count > 0)
			{
				text3 = text3 + "❌ 错误:\n" + string.Join("\n", list.Select((string e) => "  • " + e)) + "\n\n";
			}
			if (list2.Count > 0)
			{
				text3 = text3 + "⚠\ufe0f 警告:\n" + string.Join("\n", list2.Select((string w) => "  • " + w));
			}
			System.Windows.MessageBox.Show(text3, "验证结果", MessageBoxButton.OK, (list.Count > 0) ? MessageBoxImage.Hand : MessageBoxImage.Exclamation);
		}

		private bool IsValidHostname(string hostname)
		{
			if (string.IsNullOrWhiteSpace(hostname))
			{
				return false;
			}
			if (hostname.Length > 253)
			{
				return false;
			}
			return Regex.IsMatch(hostname, "^[a-zA-Z0-9]([a-zA-Z0-9\\-]{0,61}[a-zA-Z0-9])?(\\.[a-zA-Z0-9]([a-zA-Z0-9\\-]{0,61}[a-zA-Z0-9])?)*$");
		}

		private bool ValidatePortList(string portList, out string error)
		{
			error = "";
			string[] array = portList.Split(new char[4] { ',', ' ', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
			foreach (string text in array)
			{
				int result3;
				if (text.Contains('-'))
				{
					string[] array2 = text.Split('-');
					if (array2.Length != 2 || !int.TryParse(array2[0], out var result) || !int.TryParse(array2[1], out var result2))
					{
						error = "端口范围 '" + text + "' 格式错误";
						return false;
					}
					if (result < 1 || result2 > 65535 || result > result2)
					{
						error = "端口范围 '" + text + "' 无效 (应在1-65535之间且起始≤结束)";
						return false;
					}
				}
				else if (!int.TryParse(text, out result3) || result3 < 1 || result3 > 65535)
				{
					error = "端口 '" + text + "' 无效 (应为1-65535之间的整数)";
					return false;
				}
			}
			return true;
		}

		private void UpdateScanPlanPreview()
		{
			try
			{
				if (TargetCountPreviewText != null && PortCountPreviewText != null)
				{
					ExpertScanConfiguration expertScanConfiguration = CollectConfig();
					List<string> list = ResolveTargets(expertScanConfiguration);
					List<int> list2 = ResolvePorts(expertScanConfiguration);
					int count = list.Count;
					int count2 = list2.Count;
					long num = (long)count * (long)count2;
					double num2 = (double)expertScanConfiguration.TcpTimeout / (double)Math.Max(1, expertScanConfiguration.TcpConcurrency);
					double num3 = (double)num * num2;
					string text = ((num3 < 1000.0) ? $"{(int)num3}毫秒" : ((num3 < 60000.0) ? $"{num3 / 1000.0:F1}秒" : ((!(num3 < 3600000.0)) ? $"{num3 / 3600000.0:F1}小时" : $"{num3 / 60000.0:F1}分钟")));
					TargetCountPreviewText.Text = count.ToString("N0");
					PortCountPreviewText.Text = count2.ToString("N0");
					EstimatedTimePreviewText.Text = text;
					TotalScansPreviewText.Text = num.ToString("N0");
					if (num > 100000)
					{
						TotalScansPreviewText.Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(231, 76, 60));
					}
					else if (num > 10000)
					{
						TotalScansPreviewText.Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(230, 126, 34));
					}
					else
					{
						TotalScansPreviewText.Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(155, 89, 182));
					}
				}
			}
			catch (Exception)
			{
			}
		}

