				System.Windows.MessageBox.Show("暂无扫描结果可导出", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Filter = "CSV文件 (*.csv)|*.csv",
				FileName = $"ExpertScan_Report_{DateTime.Now:yyyyMMdd_HHmmss}.csv",
				Title = "导出CSV报告"
			};
			if (saveFileDialog.ShowDialog() == true)
			{
				try
				{
					string contents = GenerateCsvReport();
					File.WriteAllText(saveFileDialog.FileName, contents, new UTF8Encoding(encoderShouldEmitUTF8Identifier: true));
					System.Windows.MessageBox.Show("CSV报告已保存到:\n" + saveFileDialog.FileName, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
				catch (Exception ex)
				{
					System.Windows.MessageBox.Show("导出失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				}
			}
		}

