		private void ExportByTargetButton_Click(object sender, RoutedEventArgs e)
		{
			if (_allPortScanResults.Count == 0 && _allVulnResults.Count == 0)
			{
				System.Windows.MessageBox.Show("暂无扫描结果可导出", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			List<string> list = (from t in _allPortScanResults.Select((PortScanResult r) => r.TargetIp).Concat(_allVulnResults.Select((VulnerabilityResult v) => v.Target))
				where !string.IsNullOrEmpty(t)
				select t).Distinct().ToList();
			if (list.Count <= 1)
			{
				if (System.Windows.MessageBox.Show("当前仅扫描了 1 个目标(" + (list.FirstOrDefault() ?? "无") + ")，按目标导出与普通导出效果相同。\n\n选择「是」调用普通导出（HTML/CSV/JSON 三选一）\n选择「否」取消导出", "提示", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
				{
					ExportWithFormatSelection();
				}
				return;
			}
			Window formatDialog = new Window
			{
				Title = "选择导出格式（按目标分类）",
				Width = 320.0,
				Height = 250.0,
				WindowStartupLocation = WindowStartupLocation.CenterOwner,
				Owner = this,
				ResizeMode = ResizeMode.NoResize
			};
			StackPanel formatPanel = new StackPanel
			{
				Margin = new Thickness(20.0)
			};
			formatPanel.Children.Add(new TextBlock
			{
				Text = $"\ud83d\udcca 检测到 {list.Count} 个目标\n\n请选择导出格式：",
				FontSize = 13.0,
				Margin = new Thickness(0.0, 0.0, 0.0, 15.0)
			});
			string chosenFormat = null;
			AddFormatButton("\ud83d\udcc4 HTML（按目标分章节）", "html");
			AddFormatButton("\ud83d\udcca CSV（多目标列表）", "csv");
			AddFormatButton("\ud83d\udcbe JSON（按目标分组）", "json");
			System.Windows.Controls.Button button = new System.Windows.Controls.Button
			{
				Content = "取消",
				Height = 30.0,
				Margin = new Thickness(0.0, 5.0, 0.0, 0.0)
			};
			button.Click += delegate
			{
				formatDialog.Close();
			};
			formatPanel.Children.Add(button);
			formatDialog.Content = formatPanel;
			formatDialog.ShowDialog();
			if (string.IsNullOrEmpty(chosenFormat))
			{
				return;
			}
			try
			{
				switch (chosenFormat)
				{
				case "html":
					ExportByTargetHtml();
					break;
				case "csv":
					ExportByTargetCsv();
					break;
				case "json":
					ExportByTargetJson();
					break;
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("按目标导出失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			void AddFormatButton(string label, string format)
			{
				string format2 = format;
				System.Windows.Controls.Button button2 = new System.Windows.Controls.Button
				{
					Content = label,
					Height = 35.0,
					Margin = new Thickness(0.0, 0.0, 0.0, 8.0),
					Background = new SolidColorBrush(System.Windows.Media.Color.FromRgb(22, 160, 133)),
					Foreground = System.Windows.Media.Brushes.White,
					BorderThickness = new Thickness(0.0),
					FontSize = 13.0
				};
				button2.Click += delegate
				{
