		private string GenerateCsvReport()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("报告类型,目标IP,端口,状态,服务,版本,风险等级,CVE,描述");
			foreach (PortScanResult allPortScanResult in _allPortScanResults)
			{
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder3 = stringBuilder2;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(12, 5, stringBuilder2);
				handler.AppendLiteral("端口扫描,");
				handler.AppendFormatted(allPortScanResult.TargetIp);
				handler.AppendLiteral(",");
				handler.AppendFormatted(allPortScanResult.PortNumber);
				handler.AppendLiteral(",");
				handler.AppendFormatted(allPortScanResult.Status);
				handler.AppendLiteral(",");
				handler.AppendFormatted(EscapeCsv(allPortScanResult.Service));
				handler.AppendLiteral(",");
				handler.AppendFormatted(EscapeCsv(allPortScanResult.ServiceVersion));
				handler.AppendLiteral(",,,");
				stringBuilder3.AppendLine(ref handler);
			}
			foreach (VulnerabilityResult allVulnResult in _allVulnResults)
			{
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder4 = stringBuilder2;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(11, 6, stringBuilder2);
				handler.AppendLiteral("漏洞扫描,");
				handler.AppendFormatted(allVulnResult.Target);
				handler.AppendLiteral(",");
				handler.AppendFormatted(allVulnResult.Port);
				handler.AppendLiteral(",,");
				handler.AppendFormatted(EscapeCsv(allVulnResult.Service));
				handler.AppendLiteral(",");
				handler.AppendFormatted(allVulnResult.RiskLevel);
				handler.AppendLiteral(",");
				handler.AppendFormatted(EscapeCsv(allVulnResult.CveId));
				handler.AppendLiteral(",");
				handler.AppendFormatted(EscapeCsv(allVulnResult.Description));
				stringBuilder4.AppendLine(ref handler);
			}
			return stringBuilder.ToString();
		}

		private string EscapeCsv(string value)
		{
			if (string.IsNullOrEmpty(value))
			{
				return "";
			}
			if (value.Contains(",") || value.Contains("\"") || value.Contains("\n"))
			{
				return "\"" + value.Replace("\"", "\"\"") + "\"";
			}
			return value;
		}

		private void AppendLog(string message)
		{
			string message2 = message;
			if (ScanLogTextBox != null)
			{
				((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
				{
					string value = DateTime.Now.ToString("HH:mm:ss");
					ScanLogTextBox.AppendText($"[{value}] {message2}\r\n");
					ScanLogTextBox.ScrollToEnd();
				});
			}
		}

