		private void ExportLogButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				if (ScanLogTextBox == null || string.IsNullOrWhiteSpace(ScanLogTextBox.Text))
				{
					System.Windows.MessageBox.Show("暂无日志可导出", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
				{
					Filter = "文本文件 (*.txt)|*.txt|日志文件 (*.log)|*.log",
					FileName = $"expert_scan_log_{DateTime.Now:yyyyMMdd_HHmmss}.log",
					Title = "导出扫描日志"
				};
				if (saveFileDialog.ShowDialog() == true)
				{
					string text = ScanLogTextBox.Text;
					StringBuilder stringBuilder = new StringBuilder();
					stringBuilder.AppendLine("=== 专家模式扫描日志 ===");
					StringBuilder stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder3 = stringBuilder2;
					StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(6, 1, stringBuilder2);
					handler.AppendLiteral("导出时间: ");
					handler.AppendFormatted(DateTime.Now, "yyyy-MM-dd HH:mm:ss");
					stringBuilder3.AppendLine(ref handler);
					stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder4 = stringBuilder2;
					handler = new StringBuilder.AppendInterpolatedStringHandler(6, 1, stringBuilder2);
					handler.AppendLiteral("日志行数: ");
					handler.AppendFormatted(text.Split(new char[2] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries).Length);
					stringBuilder4.AppendLine(ref handler);
					stringBuilder.AppendLine("==========================================");
					stringBuilder.AppendLine();
					stringBuilder.AppendLine(text);
					File.WriteAllText(saveFileDialog.FileName, stringBuilder.ToString(), Encoding.UTF8);
					System.Windows.MessageBox.Show("日志已导出到:\n" + saveFileDialog.FileName, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					AppendLog("已导出扫描日志到 " + saveFileDialog.FileName);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出日志失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

