		private void DeleteSelectedRows_Click(object sender, RoutedEventArgs e)
		{
			if (RealTimePortResultsDataGrid == null || _allPortScanResults == null)
			{
				return;
			}
			try
			{
				List<PortScanResult> list = RealTimePortResultsDataGrid.SelectedItems?.Cast<PortScanResult>().ToList();
				if (list == null || list.Count == 0)
				{
					AppendLog("未选中任何端口结果");
					return;
				}
				lock (_resultsLock)
				{
					foreach (PortScanResult item in list)
					{
						_allPortScanResults.Remove(item);
					}
				}
				RealTimePortResultsDataGrid.Items.Refresh();
				AppendLog($"已删除 {list.Count} 行端口结果");
			}
			catch (Exception ex)
			{
				AppendLog("删除失败: " + ex.Message);
			}
		}

