		private void PortPresetComboBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			if (PresetDescriptionTextBlock == null)
			{
				return;
			}
			if (PortPresetComboBox?.SelectedItem is ComboBoxItem { Tag: not null } comboBoxItem)
			{
				string text = comboBoxItem.Tag.ToString() ?? "";
				PortPreset preset;
				if (text == "-1")
				{
					PresetDescriptionTextBlock.Text = "";
				}
				else if (Enum.TryParse<PortPreset>(text, out preset))
				{
					PortPresetInfo val = ((IEnumerable<PortPresetInfo>)PortServiceMapping.GetAllPresets()).FirstOrDefault((Func<PortPresetInfo, bool>)((PortPresetInfo p) => p.Preset == preset));
					if (val != null)
					{
						PresetDescriptionTextBlock.Text = $"{val.Name}: {val.Description}（{val.Ports.Count} 个端口）";
					}
				}
			}
			else
			{
				PresetDescriptionTextBlock.Text = "";
			}
		}

		private void ApplyPresetButton_Click(object sender, RoutedEventArgs e)
		{
			//IL_009f: Unknown result type (might be due to invalid IL or missing references)
			if (PortPresetComboBox?.SelectedItem is ComboBoxItem { Tag: not null } comboBoxItem)
			{
				string text = comboBoxItem.Tag.ToString() ?? "";
				if (text == "-1" || !Enum.TryParse<PortPreset>(text, out PortPreset preset))
				{
					System.Windows.MessageBox.Show("请先选择一个预设场景", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				CustomPortsRadio.IsChecked = true;
				CustomPortsTextBox.IsEnabled = true;
				List<int> presetPorts = PortServiceMapping.GetPresetPorts(preset);
				if (presetPorts == null || presetPorts.Count == 0)
				{
					System.Windows.MessageBox.Show("该预设场景没有可用端口", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
					return;
				}
				List<int> list = (from p in presetPorts.Distinct()
					orderby p
					select p).ToList();
				CustomPortsTextBox.Text = string.Join(",", list);
				PortPresetInfo val = ((IEnumerable<PortPresetInfo>)PortServiceMapping.GetAllPresets()).FirstOrDefault((Func<PortPresetInfo, bool>)((PortPresetInfo p) => p.Preset == preset));
				string value = ((val != null) ? (val.Name + "（" + val.Description + "）") : ((object)(PortPreset)(ref preset)).ToString());
				AppendLog($"已应用端口预设: {value}，共 {list.Count} 个端口");
			}
			else
			{
				System.Windows.MessageBox.Show("请先选择一个预设场景", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
		}

		private void CopyVulnSelectedRows_Click(object sender, RoutedEventArgs e)
		{
			if (RealTimeVulnResultsDataGrid == null)
			{
				return;
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("序号\t漏洞名称\tCVE\t风险等级\t端口\t服务\t目标\t描述");
			foreach (object selectedItem in RealTimeVulnResultsDataGrid.SelectedItems)
			{
				VulnerabilityResult val = (VulnerabilityResult)((selectedItem is VulnerabilityResult) ? selectedItem : null);
				if (val != null)
				{
					StringBuilder stringBuilder2 = stringBuilder;
					StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(7, 8, stringBuilder2);
					handler.AppendFormatted(val.Id);
					handler.AppendLiteral("\t");
					handler.AppendFormatted(val.Name);
					handler.AppendLiteral("\t");
					handler.AppendFormatted(val.CveId);
					handler.AppendLiteral("\t");
					handler.AppendFormatted(val.RiskLevel);
					handler.AppendLiteral("\t");
					handler.AppendFormatted(val.Port);
					handler.AppendLiteral("\t");
					handler.AppendFormatted(val.Service);
					handler.AppendLiteral("\t");
					handler.AppendFormatted(val.Target);
					handler.AppendLiteral("\t");
					handler.AppendFormatted(val.Description);
					stringBuilder2.AppendLine(ref handler);
				}
			}
			SafeSetClipboard(stringBuilder.ToString());
			AppendLog($"已复制 {RealTimeVulnResultsDataGrid.SelectedItems.Count} 行漏洞结果");
		}

