		private async void DeepScanPort_Click(object sender, RoutedEventArgs e)
		{
			if (_isScanning)
			{
				AppendLog("⚠\ufe0f 扫描进行中，请等待扫描完成后再触发深度漏洞扫描");
				return;
			}
			if (RealTimePortResultsDataGrid == null || _allVulnResults == null || _vulnerabilityScanner == null)
			{
				AppendLog("⚠\ufe0f 深度扫描所需组件尚未初始化");
				return;
			}
			object selectedItem = RealTimePortResultsDataGrid.SelectedItem;
			PortScanResult val = (PortScanResult)((selectedItem is PortScanResult) ? selectedItem : null);
			if (val != null && val.Status == "开放")
			{
				AppendLog($"开始深度漏洞扫描: {val.TargetIp}:{val.PortNumber}");
				try
				{
					List<VulnerabilityResult> list = await _vulnerabilityScanner.ScanVulnerabilitiesAsync(val.TargetIp, new List<PortScanResult> { val }, CancellationToken.None);
					List<VulnerabilityResult> snapshot;
					lock (_resultsLock)
					{
						foreach (VulnerabilityResult item in list)
						{
							_allVulnResults.Add(item);
						}
						snapshot = _allVulnResults.ToList();
					}
					((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
					{
						RealTimeVulnResultsDataGrid.ItemsSource = snapshot;
						RealTimeVulnResultsDataGrid.Items.Refresh();
						VulnerabilitiesStat.Text = snapshot.Count.ToString();
					});
					AppendLog($"深度扫描完成: 发现 {list.Count} 个漏洞");
					return;
				}
				catch (Exception ex)
				{
					System.Windows.MessageBox.Show("深度漏洞扫描失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
					return;
				}
			}
			System.Windows.MessageBox.Show("请选择一个开放端口的行进行深度扫描", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
		}

		private void ExportPdfButton_Click(object sender, RoutedEventArgs e)
		{
			if (_allPortScanResults.Count == 0 && _allVulnResults.Count == 0)
			{
				System.Windows.MessageBox.Show("暂无扫描结果可导出", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Filter = "PDF文件 (*.pdf)|*.pdf",
				FileName = $"ExpertScan_Report_{DateTime.Now:yyyyMMdd_HHmmss}.pdf",
				Title = "导出PDF报告"
			};
			if (saveFileDialog.ShowDialog() != true)
			{
				return;
			}
			string text = System.IO.Path.Combine(System.IO.Path.GetTempPath(), $"expert_report_{Guid.NewGuid():N}.html");
			try
			{
				string contents = GenerateHtmlReport();
				File.WriteAllText(text, contents, Encoding.UTF8);
				object obj = null;
				try
				{
					Type type = Assembly.GetExecutingAssembly().GetType("NetSecurityScanner.Services.ReportEngine") ?? Assembly.GetEntryAssembly()?.GetType("NetSecurityScanner.Services.ReportEngine");
					if (!(type != null))
					{
						throw new InvalidOperationException("ReportEngine not available");
					}
					obj = Activator.CreateInstance(type);
					dynamic val = obj;
					val.GeneratePdfFromHtml(text, saveFileDialog.FileName);
				}
				catch
				{
					string text2 = System.IO.Path.ChangeExtension(saveFileDialog.FileName, ".html");
					if (string.IsNullOrEmpty(text2))
					{
						text2 = saveFileDialog.FileName + ".html";
					}
					File.Copy(text, text2, overwrite: true);
					System.Windows.MessageBox.Show("PDF引擎不可用，已导出为HTML格式。可使用浏览器打印为PDF。", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				finally
				{
					if (obj is IDisposable disposable)
					{
						try
						{
							disposable.Dispose();
						}
						catch
						{
						}
					}
				}
				if (File.Exists(saveFileDialog.FileName))
				{
					System.Windows.MessageBox.Show("PDF报告已保存到:\n" + saveFileDialog.FileName, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出PDF失败: " + ex.Message + "\n\n建议使用「导出HTML」后在浏览器中打印为PDF。", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			finally
			{
				try
				{
					if (File.Exists(text))
					{
						File.Delete(text);
					}
				}
				catch
				{
				}
			}
		}

		private void SafeSetClipboard(string text)
		{
			string text2 = text;
			Thread thread = new Thread((ThreadStart)delegate
			{
				for (int i = 0; i < 4; i++)
				{
					Thread.Sleep((new int[4] { 0, 30, 60, 120 })[i]);
					try
					{
						((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
						{
							System.Windows.Clipboard.SetText(text2);
						});
						return;
					}
					catch
					{
					}
				}
				((DispatcherObject)this).Dispatcher.Invoke<MessageBoxResult>((Func<MessageBoxResult>)(() => System.Windows.MessageBox.Show("剪贴板复制失败，请手动复制：\n\n" + text2, "复制", MessageBoxButton.OK, MessageBoxImage.Asterisk)));
			});
			thread.SetApartmentState(ApartmentState.STA);
			thread.Start();
		}

		private async void ExpertModeWindow_Closing(object? sender, CancelEventArgs e)
		{
			try
			{
				DispatcherTimer? elapsedTimer = _elapsedTimer;
				if (elapsedTimer != null)
				{
					elapsedTimer.Stop();
				}
			}
			catch
			{
			}
			try
			{
				DispatcherTimer? templateNotificationTimer = _templateNotificationTimer;
				if (templateNotificationTimer != null)
				{
					templateNotificationTimer.Stop();
				}
			}
			catch
			{
			}
			if (_isScanning)
			{
				if (System.Windows.MessageBox.Show("扫描正在进行中，确定要关闭窗口吗？\n\n选择「是」会等待后台任务完成后再关闭（最多 3 秒）。", "确认关闭", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.No)
				{
					e.Cancel = true;
					return;
				}
				e.Cancel = true;
				try
				{
					_cancellationTokenSource?.Cancel();
				}
				catch
				{
				}
				AppendLog("\ud83d\uded1 等待后台扫描任务完成...");
				try
				{
					if (_scanTaskCompletionSource != null)
					{
						await _scanTaskCompletionSource.Task.WaitAsync(TimeSpan.FromSeconds(3.0));
					}
				}
				catch (TimeoutException)
				{
					AppendLog("⚠\ufe0f 后台任务未在 3 秒内结束，强制关闭");
				}
				catch (Exception)
				{
				}
				_isScanning = false;
				SafeDispose();
				Close();
				return;
			}
			try
			{
				ExpertScanConfiguration config = CollectConfig();
				string path = System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "NetSecurityScanner", "expert_last_config.json");
				string directoryName = System.IO.Path.GetDirectoryName(path);
				if (!string.IsNullOrEmpty(directoryName) && !Directory.Exists(directoryName))
				{
					Directory.CreateDirectory(directoryName);
				}
				string contents = JsonSerializer.Serialize(new
				{
					Config = config,
					SelectedTab = (ExpertTabControl?.SelectedIndex ?? 0),
					UseRustScanner = _useRustScanner
				}, new JsonSerializerOptions
				{
					WriteIndented = true
				});
				File.WriteAllText(path, contents, Encoding.UTF8);
			}
			catch (Exception)
			{
			}
			SafeDispose();
		}

		private void SafeDispose()
		{
			try
			{
				_cancellationTokenSource?.Dispose();
				_cancellationTokenSource = null;
			}
			catch
			{
			}
			try
			{
				RustScannerClient? rustClient = _rustClient;
				if (rustClient != null)
				{
					rustClient.Dispose();
				}
				_rustClient = null;
			}
			catch
			{
			}
			try
			{
				PortScanner portScanner = _portScanner;
				if (portScanner != null)
				{
					portScanner.Dispose();
				}
			}
			catch
			{
			}
			try
			{
				VulnerabilityScanner vulnerabilityScanner = _vulnerabilityScanner;
				if (vulnerabilityScanner != null)
				{
					vulnerabilityScanner.Dispose();
				}
			}
			catch
			{
			}
			try
			{
				WeakPasswordPlugin weakPasswordPlugin = _weakPasswordPlugin;
				if (weakPasswordPlugin != null)
				{
					weakPasswordPlugin.InitializeAsync(new Dictionary<string, object>()).Wait(100);
				}
			}
			catch
			{
			}
			_weakPasswordPlugin = null;
			_jsonDatabaseService = null;
			try
			{
				DispatcherTimer? elapsedTimer = _elapsedTimer;
				if (elapsedTimer != null)
				{
					elapsedTimer.Stop();
				}
			}
			catch
			{
			}
			_elapsedTimer = null;
			try
			{
				DispatcherTimer? templateNotificationTimer = _templateNotificationTimer;
				if (templateNotificationTimer != null)
				{
					templateNotificationTimer.Stop();
				}
			}
			catch
			{
			}
			_templateNotificationTimer = null;
		}

		private void PasteFromClipboardButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				if (!System.Windows.Clipboard.ContainsText())
				{
					System.Windows.MessageBox.Show("剪贴板中没有文本内容", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				string text = System.Windows.Clipboard.GetText();
				if (string.IsNullOrWhiteSpace(text))
				{
					System.Windows.MessageBox.Show("剪贴板内容为空或仅含空白字符", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				if (text.Length > 100000)
				{
					if (System.Windows.MessageBox.Show($"剪贴板内容过长（{text.Length:N0} 字符），将仅粘贴前 {100000:N0} 字符，是否继续？", "内容过长", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes)
					{
						return;
					}
					text = text.Substring(0, 100000);
				}
				TargetInputTextBox.Text = text;
				ParseTargetCount();
				UpdateScanPlanPreview();
				int value = text.Split(new char[2] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries).Length;
				AppendLog($"已从剪贴板粘贴 {value} 行目标，共 {TargetCountTextBlock.Text}");
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("粘贴失败: " + ex.Message + "\n\n（剪贴板可能被其他程序占用，请稍后重试）", "错误", MessageBoxButton.OK, MessageBoxImage.Exclamation);
			}
		}

		private void RecommendButton_Click(object sender, RoutedEventArgs e)
		{
			//IL_01c2: Unknown result type (might be due to invalid IL or missing references)
			try
			{
				ExpertScanConfiguration config = CollectConfig();
				int count = ResolveTargets(config).Count;
				if (count == 0)
				{
					RecommendResultTextBlock.Text = "⚠\ufe0f 当前未解析到任何目标，请先输入有效的扫描目标（IP/CIDR/范围/文件/正则）。";
					RecommendResultTextBlock.Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(230, 126, 34));
					ApplyRecommendButton.Visibility = Visibility.Collapsed;
					_recommendedConfig = null;
					return;
				}
				if (count <= 5)
				{
					_recommendedConfig = ScanProfileConfigFactory.GetDefault((ScanProfile)2);
					_recommendReason = $"目标数较少({count}个)，推荐深度扫描以获得最全面的结果";
				}
				else if (count <= 50)
				{
					_recommendedConfig = ScanProfileConfigFactory.GetDefault((ScanProfile)1);
					_recommendReason = $"目标数适中({count}个)，推荐标准扫描以平衡速度和精度";
				}
				else
				{
					_recommendedConfig = ScanProfileConfigFactory.GetDefault((ScanProfile)0);
					_recommendReason = $"目标数较多({count}个)，推荐快速扫描以缩短耗时，可按需对重点目标深度扫描";
				}
				if (_recommendedConfig == null)
				{
					RecommendResultTextBlock.Text = "⚠\ufe0f 推荐配置生成失败（Factory 返回空）";
					RecommendResultTextBlock.Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(231, 76, 60));
					ApplyRecommendButton.Visibility = Visibility.Collapsed;
					return;
				}
				RecommendResultTextBlock.Text = $"\ud83d\udcca {_recommendReason}\n推荐模式: {_recommendedConfig.Profile} | TCP并发: {_recommendedConfig.TcpConcurrency} | 超时: {_recommendedConfig.TimeoutMs}ms | 重试: {_recommendedConfig.RetryCount}";
				RecommendResultTextBlock.Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(26, 188, 156));
				ApplyRecommendButton.Visibility = Visibility.Visible;
			}
			catch (Exception ex)
			{
				RecommendResultTextBlock.Text = "推荐失败: " + ex.Message;
				RecommendResultTextBlock.Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(231, 76, 60));
				ApplyRecommendButton.Visibility = Visibility.Collapsed;
				_recommendedConfig = null;
			}
		}

		private void ApplyRecommendButton_Click(object sender, RoutedEventArgs e)
		{
			//IL_0502: Unknown result type (might be due to invalid IL or missing references)
			if (_recommendedConfig == null)
			{
				return;
			}
			try
			{
				if ((TcpConcurrencySlider.Value != (double)_recommendedConfig.TcpConcurrency || TcpTimeoutSlider.Value != (double)_recommendedConfig.TimeoutMs || RetrySlider.Value != (double)_recommendedConfig.RetryCount) && System.Windows.MessageBox.Show($"应用推荐模式将覆盖当前的扫描参数设置：\n\n• TCP并发: {(int)TcpConcurrencySlider.Value} → {_recommendedConfig.TcpConcurrency}\n• UDP并发: {(int)UdpConcurrencySlider.Value} → {_recommendedConfig.UdpConcurrency}\n• TCP超时: {(int)TcpTimeoutSlider.Value}ms → {_recommendedConfig.TimeoutMs}ms\n• 重试次数: {(int)RetrySlider.Value} → {_recommendedConfig.RetryCount}\n\n是否继续？", "应用推荐", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes)
				{
					return;
				}
				if (TcpConcurrencySlider != null)
				{
					TcpConcurrencySlider.Value = _recommendedConfig.TcpConcurrency;
				}
				if (UdpConcurrencySlider != null)
				{
					UdpConcurrencySlider.Value = _recommendedConfig.UdpConcurrency;
				}
				if (TcpTimeoutSlider != null)
				{
					TcpTimeoutSlider.Value = _recommendedConfig.TimeoutMs;
				}
				if (UdpTimeoutSlider != null)
				{
					UdpTimeoutSlider.Value = _recommendedConfig.TimeoutMs;
				}
				if (RetrySlider != null)
				{
					RetrySlider.Value = _recommendedConfig.RetryCount;
				}
				if (ServiceVersionCheckBox != null)
				{
					ServiceVersionCheckBox.IsChecked = _recommendedConfig.EnableServiceDetection;
				}
				if (HostDiscoveryCheckBox != null)
				{
					HostDiscoveryCheckBox.IsChecked = _recommendedConfig.EnablePingProbe;
				}
				try
				{
					PropertyInfo[] properties = ((object)_recommendedConfig).GetType().GetProperties();
					foreach (PropertyInfo propertyInfo in properties)
					{
						if (propertyInfo.Name == "TcpConcurrency" || propertyInfo.Name == "UdpConcurrency" || propertyInfo.Name == "TimeoutMs" || propertyInfo.Name == "RetryCount" || propertyInfo.Name == "EnableServiceDetection" || propertyInfo.Name == "EnablePingProbe" || !(FindName(propertyInfo.Name) is FrameworkElement frameworkElement))
						{
							continue;
						}
						try
						{
							if (frameworkElement is System.Windows.Controls.CheckBox checkBox && propertyInfo.PropertyType == typeof(bool))
							{
								if (propertyInfo.GetValue(_recommendedConfig) is bool value)
								{
									checkBox.IsChecked = value;
								}
							}
							else if (frameworkElement is Slider slider && (propertyInfo.PropertyType == typeof(int) || propertyInfo.PropertyType == typeof(double)))
							{
								object value2 = propertyInfo.GetValue(_recommendedConfig);
								if (value2 != null)
								{
									slider.Value = Convert.ToDouble(value2);
								}
							}
							else if (frameworkElement is System.Windows.Controls.ComboBox comboBox && propertyInfo.PropertyType == typeof(int))
							{
								if (propertyInfo.GetValue(_recommendedConfig) is int selectedIndex)
								{
									comboBox.SelectedIndex = selectedIndex;
								}
							}
							else if (frameworkElement is System.Windows.Controls.TextBox textBox && propertyInfo.PropertyType == typeof(string))
							{
								textBox.Text = (propertyInfo.GetValue(_recommendedConfig) as string) ?? "";
							}
						}
						catch
						{
						}
					}
				}
				catch (Exception ex)
				{
					AppendLog("推荐模式部分字段应用失败: " + ex.Message);
				}
				UpdateConfigSummary();
				UpdateScanPlanPreview();
				AppendLog($"✅ 已应用推荐模式: {_recommendedConfig.Profile}（已同步所有可匹配字段）");
			}
			catch (Exception ex2)
			{
				System.Windows.MessageBox.Show("应用推荐失败: " + ex2.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

