		private void FinalizeScan()
		{
			try
			{
				_isScanning = false;
			}
			catch
			{
			}
			try
			{
				_cancellationTokenSource?.Dispose();
				_cancellationTokenSource = null;
			}
			catch
			{
			}
			try
			{
				DispatcherTimer? elapsedTimer = _elapsedTimer;
				if (elapsedTimer != null)
				{
					elapsedTimer.Stop();
				}
			}
			catch
			{
			}
			if (StartExpertScanButton != null)
			{
				StartExpertScanButton.IsEnabled = true;
				StartExpertScanButton.Content = "\ud83d\ude80 开始专家扫描";
			}
			if (CancelExpertButton != null)
			{
				CancelExpertButton.IsEnabled = false;
				CancelExpertButton.Content = "❌ 取消";
			}
			if (ElapsedTextBlock != null)
			{
				ElapsedTextBlock.Text = "已用: 00:00:00";
			}
			if (RemainingTextBlock != null)
			{
				RemainingTextBlock.Text = "预计剩余: --:--:--";
			}
			try
			{
				SetControlsEnabledWhileScanning(enabled: true);
			}
			catch
			{
			}
		}

