		private string BuildCronExpression(string mode, string time)
		{
			string[] array = time.Split(':');
			int value = ((array.Length != 0 && int.TryParse(array[0], out var result)) ? result : 2);
			int value2 = ((array.Length > 1 && int.TryParse(array[1], out var result2)) ? result2 : 0);
			value = Math.Clamp(value, 0, 23);
			value2 = Math.Clamp(value2, 0, 59);
			return mode switch
			{
				"once" => BuildOnceCron(value, value2), 
				"daily" => $"{value2} {value} * * *", 
				"weekly" => $"{value2} {value} * * {DateTime.Now.DayOfWeek}", 
				"custom" => CronExpressionTextBox?.Text?.Trim() ?? "0 2 * * *", 
				_ => $"{value2} {value} * * *", 
			};
		}

		private string BuildOnceCron(int hour, int minute)
		{
			DateTime now = DateTime.Now;
			DateTime dateTime = new DateTime(now.Year, now.Month, now.Day, hour, minute, 0);
			DateTime dateTime2 = ((dateTime > now) ? dateTime : dateTime.AddDays(1.0));
			if (dateTime2.Day == 1 && dateTime <= now)
			{
				return $"{minute} {hour} {dateTime2.Day} {dateTime2.Month} *";
			}
			return $"{minute} {hour} {dateTime2.Day} {dateTime2.Month} *";
		}

		private async void CreateScheduleButton_Click(object sender, RoutedEventArgs e)
		{
			string target = ScheduledTargetTextBox?.Text?.Trim();
			if (string.IsNullOrWhiteSpace(target))
			{
				System.Windows.MessageBox.Show("请输入扫描目标", "输入错误", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			string name = ScheduledTaskNameTextBox?.Text?.Trim();
			if (string.IsNullOrWhiteSpace(name))
			{
				name = $"专家扫描-{target}-{DateTime.Now:yyyyMMdd_HHmmss}";
			}
			string mode = (ScheduleModeComboBox?.SelectedItem as ComboBoxItem)?.Tag?.ToString() ?? "once";
			string time = ScheduleTimeTextBox?.Text?.Trim() ?? "02:00";
			string cron = BuildCronExpression(mode, time);
			try
			{
				if (_scheduler == null)
				{
					PluginGovernor governor = PluginGovernor.Instance;
					if (!governor.IsInitialized)
					{
						PluginManager manager = new PluginManager();
						await manager.LoadAllPluginsAsync();
						PluginOrchestrator orchestrator = PluginOrchestrator.Instance;
						if (!orchestrator.IsInitialized)
						{
							await orchestrator.InitializeAsync(default(CancellationToken));
						}
						await governor.InitializeAsync(manager, orchestrator, "1.0.1.0");
					}
					_scheduler = governor.Scheduler;
				}
				ScheduledTask val = new ScheduledTask
				{
					Name = name,
					TargetIp = target,
					CronExpression = cron,
					Enabled = true,
					MaxRetries = 3
				};
				_scheduler.AddTask(val);
				await RefreshScheduledTasksAsync();
				AppendLog($"已创建定时扫描任务: {name} (Cron: {cron})");
				System.Windows.MessageBox.Show("定时扫描任务已创建\n名称: " + name + "\nCron: " + cron, "创建成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("创建定时任务失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async void RefreshScheduleButton_Click(object sender, RoutedEventArgs e)
		{
			await RefreshScheduledTasksAsync();
		}

		private async Task RefreshScheduledTasksAsync()
		{
			try
			{
				if (_scheduler == null)
				{
					PluginGovernor governor = PluginGovernor.Instance;
					if (!governor.IsInitialized)
					{
						PluginManager manager = new PluginManager();
						await manager.LoadAllPluginsAsync();
						PluginOrchestrator orchestrator = PluginOrchestrator.Instance;
						if (!orchestrator.IsInitialized)
						{
							await orchestrator.InitializeAsync(default(CancellationToken));
						}
						await governor.InitializeAsync(manager, orchestrator, "1.0.1.0");
					}
					_scheduler = governor.Scheduler;
				}
				if (_scheduler == null)
				{
					AppendLog("⚠\ufe0f 调度器未就绪，无法刷新任务列表");
					return;
				}
				List<ScheduledTaskViewModel> tasks = _scheduler.Tasks.Select((ScheduledTask t) => new ScheduledTaskViewModel
				{
					Id = (t.Id ?? string.Empty),
					Name = (t.Name ?? string.Empty),
					Target = (t.TargetIp ?? string.Empty),
					CronExpression = (t.CronExpression ?? string.Empty),
					Status = (t.Enabled ? "启用" : "禁用"),
					LastRunAt = t.LastRunAt,
					TotalRuns = t.TotalRuns
				}).ToList();
				((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
				{
					ScheduledTasksDataGrid.ItemsSource = tasks;
				});
			}
			catch (Exception ex)
			{
				AppendLog("刷新定时任务失败: " + ex.Message);
			}
		}

