		private async Task<bool> ApplyScheduledTaskStatusAsync(object sender, bool enable)
		{
			try
			{
				DataGrid dataGrid = (((sender as MenuItem)?.Parent is ContextMenu contextMenu) ? (contextMenu.PlacementTarget as DataGrid) : null);
				if (dataGrid == null)
				{
					dataGrid = ScheduledTasksDataGrid;
				}
				if (dataGrid == null)
				{
					return false;
				}
				object selectedItem = dataGrid.SelectedItem;
				ScheduledTaskViewModel vm = selectedItem as ScheduledTaskViewModel;
				if (vm == null)
				{
					AppendLog("⚠\ufe0f 请先在任务列表中选择一条任务");
					return false;
				}
				if (string.IsNullOrEmpty(vm.Id))
				{
					AppendLog("⚠\ufe0f 选中任务的 Id 为空，无法操作");
					return false;
				}
				PluginScheduler? scheduler = _scheduler;
				ScheduledTask val = ((scheduler != null) ? ((IEnumerable<ScheduledTask>)scheduler.Tasks).FirstOrDefault((Func<ScheduledTask, bool>)((ScheduledTask t) => t.Id == vm.Id)) : null);
				if (val == null)
				{
					AppendLog("⚠\ufe0f 未在调度器中找到任务 " + vm.Id);
					return false;
				}
				val.Enabled = enable;
				PluginScheduler? scheduler2 = _scheduler;
				if (scheduler2 != null)
				{
					scheduler2.UpdateTask(val);
				}
				await RefreshScheduledTasksAsync();
				return true;
			}
			catch (Exception ex)
			{
				AppendLog("切换任务状态失败: " + ex.Message);
				return false;
			}
		}

		private async void DeleteScheduledTask_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				DataGrid dataGrid = (((sender as MenuItem)?.Parent is ContextMenu contextMenu) ? (contextMenu.PlacementTarget as DataGrid) : null);
				if (dataGrid == null)
				{
					dataGrid = ScheduledTasksDataGrid;
				}
				if (dataGrid == null)
				{
					return;
				}
				object selectedItem = dataGrid.SelectedItem;
				if (!(selectedItem is ScheduledTaskViewModel vm))
				{
					AppendLog("⚠\ufe0f 请先在任务列表中选择一条任务");
				}
				else if (string.IsNullOrEmpty(vm.Id))
				{
					AppendLog("⚠\ufe0f 选中任务的 Id 为空，无法删除");
				}
				else if (System.Windows.MessageBox.Show("确认删除定时任务「" + vm.Name + "」？", "确认删除", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
				{
					PluginScheduler? scheduler = _scheduler;
					if (scheduler != null)
					{
						scheduler.RemoveTask(vm.Id);
					}
					await RefreshScheduledTasksAsync();
					AppendLog("已删除定时任务: " + vm.Name);
				}
			}
			catch (Exception ex)
			{
				AppendLog("删除定时任务失败: " + ex.Message);
			}
		}

