		private async void CompareScansButton_Click(object sender, RoutedEventArgs e)
		{
			if (ScanHistoryDataGrid.SelectedItems.Count == 0)
			{
				System.Windows.MessageBox.Show("请先在历史记录中选择两条扫描进行对比。\n\n操作方法：\n1. 按住 Ctrl 键\n2. 依次点击两条记录\n3. 点击「对比选中」按钮", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			if (ScanHistoryDataGrid.SelectedItems.Count == 1)
			{
				System.Windows.MessageBox.Show("当前只选择了 1 条记录，请再选择 1 条（按住 Ctrl 多选）后进行对比。", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			if (ScanHistoryDataGrid.SelectedItems.Count > 2)
			{
				System.Windows.MessageBox.Show($"当前选择了 {ScanHistoryDataGrid.SelectedItems.Count} 条记录，对比功能仅支持 2 条。请重新选择恰好 2 条。", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			List<ScanHistoryItem> list = ScanHistoryDataGrid.SelectedItems.Cast<ScanHistoryItem>().ToList();
			ScanHistoryItem val = list[0];
			ScanHistoryItem item2 = list[1];
			if (!string.Equals(val.TargetIp, item2.TargetIp, StringComparison.OrdinalIgnoreCase) && System.Windows.MessageBox.Show($"所选两条记录的目标不同：\n  1) {val.TargetIp}\n  2) {item2.TargetIp}\n\n" + "对不同目标的扫描结果做差异对比意义不大，建议选择同一目标的两次扫描。\n\n是否仍然继续？", "目标不一致", MessageBoxButton.YesNo, MessageBoxImage.Exclamation) != MessageBoxResult.Yes)
			{
				return;
			}
			CompleteScanResult scan1 = await _jsonDatabaseService.GetScanResultByIdAsync(val.ScanId);
			CompleteScanResult val2 = await _jsonDatabaseService.GetScanResultByIdAsync(item2.ScanId);
			if (scan1 == null || val2 == null)
			{
				System.Windows.MessageBox.Show("无法加载完整的扫描结果数据，请确认记录文件存在。\n\n可能是早期版本的扫描记录，与当前数据格式不兼容。", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				return;
			}
			try
			{
				ScanDiffWindow scanDiffWindow = new ScanDiffWindow(scan1, val2);
				scanDiffWindow.Owner = this;
				scanDiffWindow.ShowDialog();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("打开对比窗口失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

