		private void DrawPieChart(Canvas canvas, Dictionary<string, int> data, Dictionary<string, System.Windows.Media.Color> colors)
		{
			//IL_0228: Unknown result type (might be due to invalid IL or missing references)
			//IL_02a7: Unknown result type (might be due to invalid IL or missing references)
			//IL_02b2: Unknown result type (might be due to invalid IL or missing references)
			//IL_02b8: Unknown result type (might be due to invalid IL or missing references)
			if (canvas == null)
			{
				return;
			}
			canvas.Children.Clear();
			Dictionary<string, int> dictionary = data.Where<KeyValuePair<string, int>>((KeyValuePair<string, int> kv) => kv.Value > 0).ToDictionary((KeyValuePair<string, int> kv) => kv.Key, (KeyValuePair<string, int> kv) => kv.Value);
			double num = dictionary.Values.Sum();
			if (num == 0.0)
			{
				double num2 = canvas.Width / 2.0;
				double num3 = canvas.Height / 2.0;
				double num4 = Math.Min(num2, num3) - 10.0;
				if (num4 < 1.0)
				{
					num2 = 100.0;
					num3 = 100.0;
					num4 = 90.0;
				}
				Ellipse element = new Ellipse
				{
					Width = num4 * 2.0,
					Height = num4 * 2.0,
					Fill = new SolidColorBrush(System.Windows.Media.Color.FromRgb(236, 240, 241))
				};
				Canvas.SetLeft(element, num2 - num4);
				Canvas.SetTop(element, num3 - num4);
				canvas.Children.Add(element);
				return;
			}
			double num5 = canvas.Width / 2.0;
			double num6 = canvas.Height / 2.0;
			double num7 = Math.Min(num5, num6) - 10.0;
			if (num7 < 1.0)
			{
				num5 = 100.0;
				num6 = 100.0;
				num7 = 90.0;
			}
			double num8 = -90.0;
			Point point = default(Point);
			Point point2 = default(Point);
			foreach (KeyValuePair<string, int> item in dictionary)
			{
				double num9 = (double)item.Value / num * 360.0;
				if (!(num9 <= 0.0))
				{
					StreamGeometry streamGeometry = new StreamGeometry();
					using (StreamGeometryContext streamGeometryContext = streamGeometry.Open())
					{
						streamGeometryContext.BeginFigure(new Point(num5, num6), isFilled: true, isClosed: true);
						double num10 = num8 * Math.PI / 180.0;
						double num11 = (num8 + num9) * Math.PI / 180.0;
						((Point)(ref point))..ctor(num5 + num7 * Math.Cos(num10), num6 + num7 * Math.Sin(num10));
						((Point)(ref point2))..ctor(num5 + num7 * Math.Cos(num11), num6 + num7 * Math.Sin(num11));
						streamGeometryContext.LineTo(point, isStroked: true, isSmoothJoin: false);
						streamGeometryContext.ArcTo(point2, new Size(num7, num7), 0.0, num9 > 180.0, SweepDirection.Clockwise, isStroked: true, isSmoothJoin: false);
					}
					((Freezable)streamGeometry).Freeze();
					System.Windows.Shapes.Path element2 = new System.Windows.Shapes.Path
					{
						Fill = new SolidColorBrush(colors.ContainsKey(item.Key) ? colors[item.Key] : System.Windows.Media.Color.FromRgb(149, 165, 166)),
						Data = streamGeometry
					};
					canvas.Children.Add(element2);
					num8 += num9;
				}
			}
		}

		private void DrawBarChart(Canvas canvas, Dictionary<string, int> data, System.Windows.Media.Color barColor)
		{
			if (canvas == null)
			{
				return;
			}
			canvas.Children.Clear();
			double width = canvas.Width;
			double height = canvas.Height;
			double num = 30.0;
			double num2 = width - num * 2.0;
			double num3 = height - num * 2.0;
			if (data.Count == 0)
			{
				return;
			}
			int num4 = Math.Max(1, data.Values.Max());
			int count = data.Count;
			double num5 = Math.Max(10.0, num2 / (double)count - 5.0);
			double num6 = 5.0;
			int num7 = 0;
			foreach (KeyValuePair<string, int> datum in data)
			{
				double num8 = (double)datum.Value / (double)num4 * num3;
				double length = num + (double)num7 * (num5 + num6);
				double num9 = height - num - num8;
				System.Windows.Shapes.Rectangle element = new System.Windows.Shapes.Rectangle
				{
					Width = num5,
					Height = num8,
					Fill = new SolidColorBrush(barColor)
				};
				Canvas.SetLeft(element, length);
				Canvas.SetTop(element, num9);
				canvas.Children.Add(element);
				TextBlock element2 = new TextBlock
				{
					Text = datum.Key,
					FontSize = 10.0,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(127, 140, 141)),
					TextTrimming = TextTrimming.CharacterEllipsis,
					Width = num5,
					TextAlignment = TextAlignment.Center
				};
				Canvas.SetLeft(element2, length);
				Canvas.SetTop(element2, height - num + 2.0);
				canvas.Children.Add(element2);
				TextBlock element3 = new TextBlock
				{
					Text = datum.Value.ToString(),
					FontSize = 10.0,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(44, 62, 80)),
					FontWeight = FontWeights.Bold,
					TextAlignment = TextAlignment.Center,
					Width = num5
				};
				Canvas.SetLeft(element3, length);
				Canvas.SetTop(element3, num9 - 15.0);
				canvas.Children.Add(element3);
				num7++;
			}
		}

		private void ExportChartImageButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				System.Windows.Controls.TabControl expertTabControl = ExpertTabControl;
				if (expertTabControl == null || expertTabControl.SelectedIndex != 8)
				{
					AppendLog("ℹ\ufe0f 已自动切换到「数据可视化」Tab");
					ExpertTabControl.SelectedIndex = 8;
					ExpertTabControl.UpdateLayout();
					((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
					{
					}, (DispatcherPriority)6);
				}
				if (!(ExpertTabControl?.SelectedContent is ScrollViewer { Content: StackPanel content } scrollViewer))
				{
					return;
				}
				Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
				{
					Filter = "PNG图片 (*.png)|*.png",
					FileName = $"chart_export_{DateTime.Now:yyyyMMdd_HHmmss}.png",
					Title = "导出图表图片"
				};
				if (saveFileDialog.ShowDialog() == true)
				{
					content.UpdateLayout();
					double num = content.ActualWidth;
					double num2 = content.ActualHeight;
					if (num < 1.0 || num2 < 1.0)
					{
						num = ((scrollViewer.ActualWidth > 0.0) ? scrollViewer.ActualWidth : 1100.0);
						num2 = ((scrollViewer.ActualHeight > 0.0) ? scrollViewer.ActualHeight : 800.0);
					}
					RenderTargetBitmap renderTargetBitmap = new RenderTargetBitmap((int)num, (int)num2, 96.0, 96.0, PixelFormats.Pbgra32);
					renderTargetBitmap.Render(content);
					PngBitmapEncoder pngBitmapEncoder = new PngBitmapEncoder();
					pngBitmapEncoder.Frames.Add(BitmapFrame.Create(renderTargetBitmap));
					using (FileStream stream = File.Create(saveFileDialog.FileName))
					{
						pngBitmapEncoder.Save(stream);
					}
					System.Windows.MessageBox.Show("图表已导出到: " + saveFileDialog.FileName, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出图片失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private void DeduplicateButton_Click(object sender, RoutedEventArgs e)
		{
			if (TargetInputTextBox == null || TargetCountTextBlock == null)
			{
				return;
			}
			try
			{
				string text = TargetInputTextBox.Text ?? "";
				if (string.IsNullOrWhiteSpace(text))
				{
					System.Windows.MessageBox.Show("目标列表为空，无需去重", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				List<string> list = (from l in text.Split(new char[2] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries)
					select l.Trim() into l
					where !string.IsNullOrEmpty(l)
					select l).ToList();
				int count = list.Count;
				if (count == 0)
				{
					System.Windows.MessageBox.Show("目标列表为空，无需去重", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				List<string> list2 = list.Distinct<string>(StringComparer.OrdinalIgnoreCase).ToList();
				int count2 = list2.Count;
				TargetInputTextBox.Text = string.Join(Environment.NewLine, list2);
				ParseTargetCount();
				UpdateScanPlanPreview();
				if (count == count2)
				{
					System.Windows.MessageBox.Show($"目标列表无重复项，共 {count2} 条", "去重完成", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
				else
				{
					System.Windows.MessageBox.Show($"去重完成：原 {count} 条 → 现 {count2} 条（已移除 {count - count2} 条重复）", "去重完成", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
				AppendLog($"目标去重：{count} → {count2}");
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("去重失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

