		private async void StartWeakPasswordScanButton_Click(object sender, RoutedEventArgs e)
		{
			if (WeakPasswordTargetTextBox == null || WeakPasswordStatusTextBlock == null)
			{
				return;
			}
			string target = WeakPasswordTargetTextBox.Text.Trim();
			if (string.IsNullOrEmpty(target))
			{
				System.Windows.MessageBox.Show("请输入目标地址", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			string service = ((!(WeakPasswordServiceComboBox?.SelectedItem is ComboBoxItem { Content: var content })) ? null : content?.ToString()) ?? "SSH";
			int port = service switch
			{
				"SSH" => 22, 
				"FTP" => 21, 
				"MySQL" => 3306, 
				"MSSQL" => 1433, 
				"Redis" => 6379, 
				"Telnet" => 23, 
				"MongoDB" => 27017, 
				_ => 22, 
			};
			WeakPasswordStatusTextBlock.Text = $"状态：正在检测 {target}:{port} ({service})...";
			StartWeakPasswordScanButton.IsEnabled = false;
			List<WeakPasswordResult> results = new List<WeakPasswordResult>();
			try
			{
				ScanContext val = new ScanContext
				{
					Target = target,
					Port = port,
					ServiceName = service,
					Timeout = 3000
				};
				List<VulnerabilityResult> list = await _weakPasswordPlugin.ScanAsync(val, CancellationToken.None);
				foreach (VulnerabilityResult item in list)
				{
					(string, string) tuple = ExtractRealCredentials(item, service);
					results.Add(new WeakPasswordResult
					{
						Username = tuple.Item1,
						Password = tuple.Item2,
						Service = service,
						Target = target,
						Port = port,
						Vulnerability = item.Name
					});
				}
				if (list.Count == 0)
				{
					results.Add(new WeakPasswordResult
					{
						Username = "(无)",
						Password = "(无)",
						Service = service,
						Target = target,
						Port = port,
						Vulnerability = "未发现弱口令"
					});
				}
			}
			catch (Exception ex)
			{
				WeakPasswordStatusTextBlock.Text = "状态：检测失败 - " + ex.Message;
				StartWeakPasswordScanButton.IsEnabled = true;
				return;
			}
			WeakPasswordResultDataGrid.ItemsSource = results;
			WeakPasswordStatusTextBlock.Text = ((results.Count > 0 && results[0].Vulnerability != "未发现弱口令") ? $"状态：发现 {results.Count} 个弱口令漏洞" : "状态：未发现弱口令漏洞");
			StartWeakPasswordScanButton.IsEnabled = true;
			AppendLog($"[弱口令检测] {target}:{port} ({service}) - 共 {results.Count} 条结果");
		}

		private (string username, string password) ExtractRealCredentials(VulnerabilityResult v, string service)
		{
			if (v == null)
			{
				return (username: "(未知)", password: "(无凭证)");
			}
			if (service == "FTP" && !string.IsNullOrEmpty(v.Name) && v.Name.Contains("匿名登录"))
			{
				return (username: "anonymous", password: "anonymous@");
			}
			if (service == "SSH" && !string.IsNullOrEmpty(v.Name) && v.Name.Contains("SSH"))
			{
				return (username: "(Banner探测)", password: "(无凭证尝试)");
			}
			if (service == "Telnet")
			{
				return (username: "(协议特征)", password: "(明文传输)");
			}
			if (service == "MySQL" && !string.IsNullOrEmpty(v.Name) && v.Name.Contains("MySQL"))
			{
				return (username: "(未验证)", password: "(无凭证尝试)");
			}
			if (service == "Redis" && !string.IsNullOrEmpty(v.Name) && v.Name.Contains("未授权"))
			{
				return (username: "(空认证)", password: "(无密码)");
			}
			if (service == "MSSQL")
			{
				return (username: "(未实现)", password: "(插件不支持MSSQL)");
			}
			return (username: "(探测)", password: "(无凭证)");
		}

		private async void StartDirScanButton_Click(object sender, RoutedEventArgs e)
		{
			if (DirScanUrlTextBox == null || DirScanStatusTextBlock == null)
			{
				return;
			}
			string url = DirScanUrlTextBox.Text.Trim();
			if (string.IsNullOrEmpty(url))
			{
				System.Windows.MessageBox.Show("请输入目标URL", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			if (!url.StartsWith("http://") && !url.StartsWith("https://"))
			{
				url = "http://" + url;
			}
			string dictName = ((!(DirScanDictComboBox?.SelectedItem is ComboBoxItem { Content: var content })) ? null : content?.ToString()) ?? "常用目录字典";
			List<string> paths = GetDirectoryWordlist(dictName);
			if (paths == null || paths.Count == 0)
			{
				DirScanStatusTextBlock.Text = "状态：字典为空，无法扫描";
				System.Windows.MessageBox.Show("所选字典「" + dictName + "」没有可用路径，请选择其他字典。", "字典为空", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			DirScanStatusTextBlock.Text = $"状态：正在扫描 {url} ({paths.Count} 条路径)...";
			StartDirScanButton.IsEnabled = false;
			List<string> foundPaths = new List<string>();
			try
			{
				using HttpClient httpClient = new HttpClient();
				httpClient.Timeout = TimeSpan.FromSeconds(5.0);
				string baseUrl = url.TrimEnd('/');
				int checkedCount = 0;
				foreach (string item in paths)
				{
					if (checkedCount++ % 10 == 0)
					{
						DirScanStatusTextBlock.Text = $"状态：扫描中 {checkedCount}/{paths.Count}...";
					}
					try
					{
						string testUrl = baseUrl + "/" + item.TrimStart('/');
						HttpResponseMessage httpResponseMessage = await httpClient.GetAsync(testUrl);
						if (httpResponseMessage.StatusCode == HttpStatusCode.OK || httpResponseMessage.StatusCode == HttpStatusCode.Forbidden || httpResponseMessage.StatusCode == HttpStatusCode.Unauthorized || httpResponseMessage.StatusCode == HttpStatusCode.MovedPermanently || httpResponseMessage.StatusCode == HttpStatusCode.Found)
						{
							foundPaths.Add($"[{httpResponseMessage.StatusCode}] {testUrl}");
						}
					}
					catch
					{
					}
				}
			}
			catch (Exception ex)
			{
				DirScanStatusTextBlock.Text = "状态：扫描失败 - " + ex.Message;
				StartDirScanButton.IsEnabled = true;
				return;
			}
			DirScanResultListBox.ItemsSource = foundPaths;
			DirScanStatusTextBlock.Text = ((foundPaths.Count > 0) ? $"状态：发现 {foundPaths.Count} 个可访问路径" : "状态：未发现可访问路径");
			StartDirScanButton.IsEnabled = true;
			AppendLog($"[目录扫描] {url} ({dictName}) - 发现 {foundPaths.Count} 个路径");
		}

		private async void StartPocVerifyButton_Click(object sender, RoutedEventArgs e)
		{
			if (PocTargetTextBox == null || PocStatusTextBlock == null)
			{
				return;
			}
			string target = PocTargetTextBox.Text.Trim();
			if (string.IsNullOrEmpty(target))
			{
				System.Windows.MessageBox.Show("请输入目标地址", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
			}
			else
			{
				if (!IPAddress.TryParse(target, out IPAddress _) && !IsValidHostname(target) && System.Windows.MessageBox.Show("目标「" + target + "」不是有效的 IP 或域名，是否继续？", "格式提示", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes)
				{
					return;
				}
				PocStatusTextBlock.Text = "状态：正在验证 " + target + "...";
				StartPocVerifyButton.IsEnabled = false;
				List<string> pocResults = new List<string>();
				int hitCount = 0;
				try
				{
					List<string> list = (from string s in PocPluginListBox?.SelectedItems?
						where !string.IsNullOrEmpty(s)
						select s).ToList() ?? new List<string>();
					bool num = list.Count == 0;
					Dictionary<int, string> portPocMap = new Dictionary<int, string>
					{
						{ 80, "HTTP Banner POC" },
						{ 443, "HTTPS Banner POC" },
						{ 22, "SSH Banner POC" },
						{ 21, "FTP Anonymous POC" },
						{ 3306, "MySQL Connect POC" },
						{ 6379, "Redis Unauthorized POC" },
						{ 8080, "Tomcat Default POC" },
						{ 8443, "HTTPS Alt POC" },
						{ 9200, "Elasticsearch POC" },
						{ 27017, "MongoDB Unauthorized POC" }
					};
					int checkedCount = 0;
					List<int> portsToCheck = portPocMap.Keys.ToList();
					if (!num)
					{
						List<string> keywords = (from p in list
							select p.ReplaceIgnoreCase("POC", "").ReplaceIgnoreCase("PoC", "").Trim() into k
							where !string.IsNullOrEmpty(k)
							select k).ToList();
						portsToCheck = (from kv in portPocMap
							where keywords.Any((string kw) => kv.Value.Contains(kw, StringComparison.OrdinalIgnoreCase))
							select kv.Key).ToList();
						if (portsToCheck.Count == 0)
						{
							AppendLog("⚠\ufe0f 所选 POC 未匹配任何内置端口，将扫描全部内置端口");
							portsToCheck = portPocMap.Keys.ToList();
						}
					}
					if (portsToCheck.Count == 0)
					{
						pocResults.Add("无可扫描的端口（POC 列表为空）");
					}
					else
					{
						foreach (int port in portsToCheck)
						{
							if (checkedCount++ % 2 == 0)
							{
								PocStatusTextBlock.Text = $"状态：扫描中 {checkedCount}/{portsToCheck.Count}...";
							}
							try
							{
								using TcpClient client = new TcpClient();
								Task task = client.ConnectAsync(target, port);
								Task timeoutTask = Task.Delay(2000);
								if (await Task.WhenAny(task, timeoutTask) == timeoutTask)
								{
									continue;
								}
								string banner = "";
								try
								{
									client.ReceiveTimeout = 1500;
									byte[] buffer = new byte[128];
									using NetworkStream stream = client.GetStream();
									int num2 = await stream.ReadAsync(buffer, 0, buffer.Length);
									if (num2 > 0)
									{
										banner = Encoding.ASCII.GetString(buffer, 0, num2).Trim();
									}
								}
								catch
								{
								}
								string value = portPocMap[port];
								if (string.IsNullOrEmpty(banner))
								{
									pocResults.Add($"[命中] {target}:{port} - {value}（端口开放）");
								}
								else
								{
									pocResults.Add($"[命中] {target}:{port} - {value} - Banner: {banner.Split('\n')[0]}");
								}
								hitCount++;
								client.Close();
							}
							catch
							{
							}
						}
					}
					if (hitCount > 0)
					{
						pocResults.Add("──────────────");
						pocResults.Add($"汇总：目标 {target} 共发现 {hitCount} 个端口开放，建议对命中端口进行深度漏洞扫描。");
					}
					else
					{
						pocResults.Add($"目标 {target} 未检测到常见服务端口开放（共检查 {portsToCheck.Count} 个端口）。");
					}
				}
				catch (Exception ex)
				{
					pocResults.Add("POC验证失败: " + ex.Message);
				}
				PocResultTextBox.Text = string.Join("\n", pocResults);
				PocStatusTextBlock.Text = ((hitCount > 0) ? $"状态：验证完成 - 命中 {hitCount} 个端口" : "状态：验证完成 - 未发现开放端口");
				StartPocVerifyButton.IsEnabled = true;
				AppendLog($"[POC验证] {target} - 命中 {hitCount} 个端口");
			}
		}

