		private void PocSelectInvertButton_Click(object sender, RoutedEventArgs e)
		{
			if (PocPluginListBox == null || PocPluginListBox.Items.Count == 0)
			{
				return;
			}
			List<object> list = PocPluginListBox.SelectedItems.Cast<object>().ToList();
			PocPluginListBox.SelectedItems.Clear();
			foreach (object item in (IEnumerable)PocPluginListBox.Items)
			{
				if (!list.Contains(item))
				{
					PocPluginListBox.SelectedItems.Add(item);
				}
			}
			AppendLog($"[POC] 已反选，当前选中 {PocPluginListBox.SelectedItems.Count} 个插件");
		}

		private void LoadPocPlugins()
		{
			try
			{
				if (PocPluginListBox == null)
				{
					return;
				}
				PocPluginListBox.Items.Clear();
				List<string> list = new List<string> { "HTTP Banner POC", "HTTPS Banner POC", "SSH Banner POC", "FTP Anonymous POC", "MySQL Connect POC", "Redis Unauthorized POC", "Tomcat Default POC", "HTTPS Alt POC", "Elasticsearch POC", "MongoDB Unauthorized POC" };
				try
				{
					PluginOrchestrator instance = PluginOrchestrator.Instance;
					if (instance.IsInitialized)
					{
						IEnumerable<IVulnerabilityScannerPlugin> enumerable = instance.LoadedPlugins?.Values;
						if (enumerable != null)
						{
							foreach (string item in (from p in enumerable
								where p != null && p.Name != null && (p.Name.Contains("POC", StringComparison.OrdinalIgnoreCase) || p.Name.Contains("PoC", StringComparison.OrdinalIgnoreCase))
								select p.Name into n
								where !string.IsNullOrEmpty(n)
								select n).ToList())
							{
								if (!list.Contains(item))
								{
									list.Add(item);
								}
							}
						}
					}
				}
				catch
				{
				}
				foreach (string item2 in list)
				{
					PocPluginListBox.Items.Add(item2);
				}
				AppendLog($"已加载 {list.Count} 个 POC 插件");
			}
			catch (Exception)
			{
			}
		}

		private async void StartCmsIdentifyButton_Click(object sender, RoutedEventArgs e)
		{
			if (CmsIdentifyUrlTextBox == null || CmsStatusTextBlock == null)
			{
				return;
			}
			string url = CmsIdentifyUrlTextBox.Text.Trim();
			if (string.IsNullOrEmpty(url))
			{
				System.Windows.MessageBox.Show("请输入目标URL", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			if (!url.StartsWith("http://") && !url.StartsWith("https://"))
			{
				url = "http://" + url;
			}
			CmsStatusTextBlock.Text = "状态：正在识别 " + url + "...";
			StartCmsIdentifyButton.IsEnabled = false;
			string text3;
			try
			{
				using HttpClient httpClient = new HttpClient();
				httpClient.Timeout = TimeSpan.FromSeconds(10.0);
				httpClient.DefaultRequestHeaders.Add("User-Agent", "Mozilla/5.0");
				HttpResponseMessage response = await httpClient.GetAsync(url);
				string text = await response.Content.ReadAsStringAsync();
				string text2 = response.Headers.ToString();
				string content = (text + " " + text2).ToLower();
				Dictionary<string, List<string>> obj = new Dictionary<string, List<string>>
				{
					{
						"WordPress",
						new List<string> { "wp-content", "wp-includes", "wordpress" }
					},
					{
						"Drupal",
						new List<string> { "drupal", "sites/all", "sites/default" }
					},
					{
						"Joomla",
						new List<string> { "joomla", "components/com_", "media/system/js" }
					},
					{
						"DedeCMS",
						new List<string> { "dede", "dedecms", "/templets/" }
					},
					{
						"Discuz",
						new List<string> { "discuz", "forum.php", "uc_client" }
					},
					{
						"ThinkPHP",
						new List<string> { "thinkphp", "think\\", "/index.php/" }
					},
					{
						"Spring Boot",
						new List<string> { "whitelabel error", "spring", "actuator" }
					},
					{
						"Tomcat",
						new List<string> { "tomcat", "coyote", "jsp" }
					},
					{
						"Nginx",
						new List<string> { "nginx" }
					},
					{
						"Apache",
						new List<string> { "apache" }
					}
				};
				string value = "未知";
				int num = 0;
				foreach (KeyValuePair<string, List<string>> item in obj)
				{
					int num2 = item.Value.Count((string sig) => content.Contains(sig));
					if (num2 > num)
					{
						num = num2;
						value = item.Key;
					}
				}
				string value2 = "";
				if (response.Headers.Server != null)
				{
					value2 = response.Headers.Server.ToString();
				}
				text3 = $"CMS识别结果：{value}\n匹配特征数：{num}\n服务器：{value2}\nHTTP状态码：{response.StatusCode}\n页面大小：{text.Length} 字节";
			}
			catch (Exception ex)
			{
				text3 = "CMS识别失败: " + ex.Message;
			}
			CmsResultTextBlock.Text = text3;
			CmsStatusTextBlock.Text = "状态：识别完成";
			StartCmsIdentifyButton.IsEnabled = true;
			AppendLog("[CMS识别] " + url + " - " + text3.Split('\n')[0]);
		}

		private List<string> GetDirectoryWordlist(string dictName)
		{
			List<string> list = new List<string>
			{
				"admin", "login", "index.php", "index.html", "robots.txt", "sitemap.xml", ".git", ".env", ".svn", "backup",
				"config", "test", "api", "wp-admin", "wp-login.php", "phpmyadmin", "phpinfo.php", "info.php", "console", "dashboard",
				"manage", "system", "upload", "uploads", "images", "img", "css", "js", "lib", "static",
				"assets", "public", "private", "data", "db", "database", "sql", "log", "logs", "temp",
				"tmp", "docs", "doc", "help", "readme", "readme.txt", "readme.md", "license", "changelog", "version",
				"status", "health", ".htaccess", "web.config", "crossdomain.xml", ".well-known", "vendor", "node_modules", "composer.json", "package.json",
				"WEB-INF", "META-INF", "swagger", "swagger-ui", "api-docs", "actuator", "actuator/health", "actuator/env", "actuator/info", "cgi-bin",
				"scripts", "bin", "include", "includes", "templates"
			};
			return dictName switch
			{
				"PHP字典" => list.Where(delegate(string p)
				{
					if (!p.EndsWith(".php") && !p.Contains("php") && !p.StartsWith("."))
					{
						switch (p)
						{
						default:
							return p == "temp";
						case "admin":
						case "login":
						case "config":
						case "upload":
						case "backup":
						case "test":
						case "api":
							break;
						}
					}
					return true;
				}).ToList(), 
				"ASP字典" => list.Select((string p) => p.Replace(".php", ".asp").Replace(".html", ".aspx")).ToList(), 
				"JSP字典" => list.Select((string p) => p.Replace(".php", ".jsp").Replace(".html", ".jsp")).ToList(), 
				_ => list, 
			};
		}

