	internal static class StringExtensions
	{
		public static string ReplaceIgnoreCase(this string source, string oldValue, string newValue)
		{
			if (string.IsNullOrEmpty(source))
			{
				return source ?? string.Empty;
			}
			if (string.IsNullOrEmpty(oldValue))
			{
				return source;
			}
			if (newValue == null)
			{
				newValue = string.Empty;
			}
			StringBuilder stringBuilder = new StringBuilder(source.Length);
			int num = 0;
			int num2;
			while ((num2 = source.IndexOf(oldValue, num, StringComparison.OrdinalIgnoreCase)) >= 0)
			{
				stringBuilder.Append(source, num, num2 - num);
				stringBuilder.Append(newValue);
				num = num2 + oldValue.Length;
			}
			stringBuilder.Append(source, num, source.Length - num);
			return stringBuilder.ToString();
		}
	}
