			if (string.IsNullOrEmpty(text))
			{
				UsernameErrorText.Text = "请输入用户名";
				UsernameTextBox.Focus();
				return;
			}
			if (string.IsNullOrEmpty(text2))
			{
				PasswordErrorText.Text = "请输入密码";
				PasswordBox.Focus();
				return;
			}
			_isSubmitting = true;
			LoginButton.IsEnabled = false;
			try
			{
				LoginResult val = await _authService.LoginAsync(text, text2, RememberMeCheckBox.IsChecked == true);
				if (val.IsSuccess)
				{
					base.DialogResult = true;
					Close();
				}
				else
				{
					PasswordErrorText.Text = val.Message;
					PasswordBox.SelectAll();
					PasswordBox.Focus();
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("登录失败：" + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			finally
			{
				_isSubmitting = false;
				LoginButton.IsEnabled = true;
			}
		}

