		private async void StartDiscoveryButton_Click(object sender, RoutedEventArgs e)
		{
			string text = NetworkRangeTextBox.Text.Trim();
			if (string.IsNullOrEmpty(text))
			{
				System.Windows.MessageBox.Show("请输入网络范围", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			StartDiscoveryButton.IsEnabled = false;
			StopDiscoveryButton.IsEnabled = true;
			DiscoveryProgressBar.Visibility = Visibility.Visible;
			StatusTextBlock.Text = "正在扫描网络...";
			_cancellationTokenSource = new CancellationTokenSource();
			_discoveredDevices = new List<NetworkDevice>();
			TopologyCanvas.Children.Clear();
			_topologyNodes.Clear();
			_topologyEdges.Clear();
			try
			{
				Progress<string> progress = new Progress<string>(delegate(string message)
				{
					StatusTextBlock.Text = message;
				});
				_discoveredDevices = await _topologyService.DiscoverNetworkAsync(text, (IProgress<string>)progress, _cancellationTokenSource.Token);
				DisplayResults();
				UpdateStatistics();
				BuildAndRenderTopology();
				UpdateSubnetInfoPanel();
				StatusTextBlock.Text = $"扫描完成，发现 {_discoveredDevices.Count} 个设备";
				ExportButton.IsEnabled = true;
			}
			catch (OperationCanceledException)
			{
				StatusTextBlock.Text = "扫描已取消";
				if (_discoveredDevices.Count > 0)
				{
					DisplayResults();
					UpdateStatistics();
					BuildAndRenderTopology();
					UpdateSubnetInfoPanel();
					ExportButton.IsEnabled = true;
				}
			}
			catch (Exception ex2)
			{
				StatusTextBlock.Text = "扫描失败: " + ex2.Message;
				System.Windows.MessageBox.Show("扫描失败: " + ex2.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			finally
			{
				StartDiscoveryButton.IsEnabled = true;
				StopDiscoveryButton.IsEnabled = false;
				DiscoveryProgressBar.Visibility = Visibility.Collapsed;
			}
		}

		private void StopDiscoveryButton_Click(object sender, RoutedEventArgs e)
		{
			_cancellationTokenSource?.Cancel();
			StatusTextBlock.Text = "正在停止扫描...";
		}

		private void DisplayResults()
		{
			List<DeviceDisplayInfo> itemsSource = _discoveredDevices.Select(delegate(NetworkDevice d)
			{
				//IL_001f: Unknown result type (might be due to invalid IL or missing references)
				//IL_0024: Unknown result type (might be due to invalid IL or missing references)
				//IL_005f: Unknown result type (might be due to invalid IL or missing references)
				//IL_0064: Unknown result type (might be due to invalid IL or missing references)
				DeviceDisplayInfo obj = new DeviceDisplayInfo
				{
					IPAddress = d.IPAddress,
					Hostname = d.Hostname
				};
				DeviceType deviceType = d.DeviceType;
				obj.DeviceType = ((object)(DeviceType)(ref deviceType)).ToString();
				obj.MacAddress = d.MacAddress ?? "N/A";
				obj.OpenPortsCount = d.OpenPorts.Count;
				DeviceStatus status = d.Status;
				obj.Status = ((object)(DeviceStatus)(ref status)).ToString();
				obj.OriginalDevice = d;
				return obj;
			}).ToList();
			DevicesDataGrid.ItemsSource = itemsSource;
			DeviceCountTextBlock.Text = $"({_discoveredDevices.Count})";
		}

		private void UpdateStatistics()
		{
			NetworkStatistics networkStatistics = _topologyService.GetNetworkStatistics(_discoveredDevices);
			TotalDevicesText.Text = networkStatistics.TotalDevices.ToString();
			OnlineDevicesText.Text = networkStatistics.OnlineDevices.ToString();
			TotalPortsText.Text = networkStatistics.TotalOpenPorts.ToString();
			SubnetCountText.Text = networkStatistics.SubnetDistribution.Count.ToString();
