		private void ResetViewButton_Click(object sender, RoutedEventArgs e)
		{
			_zoomLevel = 1.0;
			TopologyScaleTransform.ScaleX = 1.0;
			TopologyScaleTransform.ScaleY = 1.0;
			TopologyTranslateTransform.X = 0.0;
			TopologyTranslateTransform.Y = 0.0;
			TopologyScrollViewer.ScrollToHome();
			if (_discoveredDevices != null && _discoveredDevices.Count > 0)
			{
				BuildAndRenderTopology();
			}
		}

		private void BuildAndRenderTopology()
		{
			if (_discoveredDevices == null || _discoveredDevices.Count == 0)
			{
				return;
			}
			TopologyCanvas.Children.Clear();
			_topologyNodes.Clear();
			_topologyEdges.Clear();
			double width = TopologyCanvas.Width;
			double height = TopologyCanvas.Height;
			double num = width / 2.0;
			double num2 = height / 2.0;
			if (_discoveredDevices.Count == 1)
			{
				NetworkDevice val = _discoveredDevices[0];
				_topologyNodes[val.IPAddress] = new TopologyNode
				{
					Device = val,
					X = num,
					Y = num2,
					Vx = 0.0,
					Vy = 0.0
				};
			}
			else
			{
				double num3 = Math.Min(width, height) * 0.35;
				for (int i = 0; i < _discoveredDevices.Count; i++)
				{
					NetworkDevice val2 = _discoveredDevices[i];
					double num4 = Math.PI * 2.0 * (double)i / (double)_discoveredDevices.Count - Math.PI / 2.0;
					_topologyNodes[val2.IPAddress] = new TopologyNode
					{
						Device = val2,
						X = num + num3 * Math.Cos(num4),
						Y = num2 + num3 * Math.Sin(num4),
						Vx = 0.0,
						Vy = 0.0
					};
				}
			}
			HashSet<string> hashSet = new HashSet<string>();
			foreach (NetworkDevice discoveredDevice in _discoveredDevices)
			{
				if (!string.IsNullOrEmpty(discoveredDevice.Gateway))
				{
					string item = ((discoveredDevice.IPAddress.CompareTo(discoveredDevice.Gateway) < 0) ? (discoveredDevice.IPAddress + "-" + discoveredDevice.Gateway) : (discoveredDevice.Gateway + "-" + discoveredDevice.IPAddress));
					if (!hashSet.Contains(item))
					{
						hashSet.Add(item);
						_topologyEdges.Add(new TopologyEdge
						{
							Source = discoveredDevice.IPAddress,
							Target = discoveredDevice.Gateway,
							RelationshipType = "网关"
						});
					}
				}
				foreach (string dependency in discoveredDevice.Dependencies)
				{
					string item2 = ((discoveredDevice.IPAddress.CompareTo(dependency) < 0) ? (discoveredDevice.IPAddress + "-" + dependency) : (dependency + "-" + discoveredDevice.IPAddress));
					if (!hashSet.Contains(item2))
					{
						hashSet.Add(item2);
						_topologyEdges.Add(new TopologyEdge
						{
							Source = discoveredDevice.IPAddress,
							Target = dependency,
							RelationshipType = GetDependencyType(discoveredDevice, dependency)
						});
					}
				}
			}
			RunForceDirectedLayout(100);
			DrawSubnetBackgrounds();
			DrawTopology();
			UpdateSubnetInfoPanel();
		}

		private void DrawSubnetBackgrounds()
		{
			List<IGrouping<string, NetworkDevice>> list = (from d in _discoveredDevices
				group d by GetSubnet(d.IPAddress)).ToList();
			if (list.Count <= 1)
			{
				return;
			}
			System.Windows.Media.Color[] array = new System.Windows.Media.Color[8]
			{
				System.Windows.Media.Color.FromArgb(21, 0, 184, 148),
				System.Windows.Media.Color.FromArgb(21, 9, 132, 227),
				System.Windows.Media.Color.FromArgb(21, 225, 112, 85),
				System.Windows.Media.Color.FromArgb(21, 108, 92, 231),
				System.Windows.Media.Color.FromArgb(21, 243, 156, 18),
				System.Windows.Media.Color.FromArgb(21, 231, 76, 60),
				System.Windows.Media.Color.FromArgb(21, 52, 152, 219),
				System.Windows.Media.Color.FromArgb(21, 46, 204, 113)
			};
			int num = 0;
			foreach (IGrouping<string, NetworkDevice> item in list)
			{
				HashSet<string> hashSet = item.Select((NetworkDevice d) => d.IPAddress).ToHashSet();
				double num2 = double.MaxValue;
				double num3 = double.MinValue;
				double num4 = double.MaxValue;
				double num5 = double.MinValue;
				foreach (TopologyNode value in _topologyNodes.Values)
				{
					if (hashSet.Contains(value.Device.IPAddress))
					{
						if (value.X < num2)
						{
							num2 = value.X;
						}
						if (value.X > num3)
						{
							num3 = value.X;
						}
						if (value.Y < num4)
						{
							num4 = value.Y;
						}
						if (value.Y > num5)
						{
							num5 = value.Y;
						}
					}
				}
				if (num2 != double.MaxValue)
				{
					double num6 = 50.0;
					System.Windows.Shapes.Rectangle element = new System.Windows.Shapes.Rectangle
					{
						Width = num3 - num2 + num6 * 2.0,
						Height = num5 - num4 + num6 * 2.0,
						Fill = new SolidColorBrush(array[num % array.Length]),
						RadiusX = 15.0,
						RadiusY = 15.0
					};
					Canvas.SetLeft(element, num2 - num6);
					Canvas.SetTop(element, num4 - num6);
					System.Windows.Controls.Panel.SetZIndex(element, -10);
					TopologyCanvas.Children.Add(element);
					num++;
				}
			}
		}

		private void RunForceDirectedLayout(int maxIterations)
		{
			List<TopologyNode> list = _topologyNodes.Values.ToList();
			int count = list.Count;
			if (count < 2)
			{
				return;
			}
			double num = Math.Sqrt(TopologyCanvas.Width * TopologyCanvas.Height / (double)count) * 0.8;
			double num2 = num * num;
			double num3 = 50.0;
			for (int i = 0; i < maxIterations; i++)
			{
				double val = num3 * (1.0 - (double)i / (double)maxIterations);
				for (int j = 0; j < count; j++)
				{
					list[j].Fx = 0.0;
					list[j].Fy = 0.0;
				}
				for (int k = 0; k < count; k++)
				{
					for (int l = k + 1; l < count; l++)
					{
						double num4 = list[k].X - list[l].X;
						double num5 = list[k].Y - list[l].Y;
						double num6 = num4 * num4 + num5 * num5;
						if (num6 < 0.01)
						{
							num6 = 0.01;
						}
						double num7 = Math.Sqrt(num6);
						double num8 = num2 / num6;
						double num9 = num8 * num4 / num7;
						double num10 = num8 * num5 / num7;
						list[k].Fx += num9;
						list[k].Fy += num10;
						list[l].Fx -= num9;
						list[l].Fy -= num10;
					}
				}
				foreach (TopologyEdge topologyEdge in _topologyEdges)
				{
					if (_topologyNodes.ContainsKey(topologyEdge.Source) && _topologyNodes.ContainsKey(topologyEdge.Target))
					{
						TopologyNode topologyNode = _topologyNodes[topologyEdge.Source];
						TopologyNode topologyNode2 = _topologyNodes[topologyEdge.Target];
						double num11 = topologyNode2.X - topologyNode.X;
						double num12 = topologyNode2.Y - topologyNode.Y;
						double num13 = Math.Sqrt(num11 * num11 + num12 * num12);
						if (num13 < 0.01)
						{
							num13 = 0.01;
						}
						double num14 = (num13 * num13 - num2) / (num * num13);
						topologyNode.Fx += num14 * num11;
						topologyNode.Fy += num14 * num12;
						topologyNode2.Fx -= num14 * num11;
						topologyNode2.Fy -= num14 * num12;
					}
				}
				double num15 = TopologyCanvas.Width / 2.0;
				double num16 = TopologyCanvas.Height / 2.0;
				foreach (TopologyNode item in list)
				{
					double num17 = item.X - num15;
					double num18 = item.Y - num16;
					item.Fx -= num17 * 0.01;
					item.Fy -= num18 * 0.01;
				}
				foreach (TopologyNode item2 in list)
				{
					double num19 = Math.Min(Math.Abs(item2.Fx), val) * (double)Math.Sign(item2.Fx);
					double num20 = Math.Min(Math.Abs(item2.Fy), val) * (double)Math.Sign(item2.Fy);
					if (item2 != _draggingNode)
					{
						item2.X += num19;
						item2.Y += num20;
						item2.X = Math.Max(80.0, Math.Min(TopologyCanvas.Width - 80.0, item2.X));
						item2.Y = Math.Max(60.0, Math.Min(TopologyCanvas.Height - 60.0, item2.Y));
					}
				}
			}
		}

