					TopologyNode topologyNode = _topologyNodes[topologyEdge.Source];
					TopologyNode topologyNode2 = _topologyNodes[topologyEdge.Target];
					Line element = new Line
					{
						X1 = topologyNode.X,
						Y1 = topologyNode.Y,
						X2 = topologyNode2.X,
						Y2 = topologyNode2.Y,
						Stroke = new SolidColorBrush(System.Windows.Media.Color.FromArgb(170, 52, 152, 219)),
						StrokeThickness = 2.0,
						Tag = topologyEdge
					};
					TopologyCanvas.Children.Add(element);
					double num = (topologyNode.X + topologyNode2.X) / 2.0;
					double num2 = (topologyNode.Y + topologyNode2.Y) / 2.0;
					TextBlock element2 = new TextBlock
					{
						Text = topologyEdge.RelationshipType,
						FontSize = 10.0,
						Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(127, 140, 141)),
						Background = new SolidColorBrush(System.Windows.Media.Color.FromArgb(224, byte.MaxValue, byte.MaxValue, byte.MaxValue))
					};
					Canvas.SetLeft(element2, num - 20.0);
					Canvas.SetTop(element2, num2 - 8.0);
					TopologyCanvas.Children.Add(element2);
				}
			}
		}

