		private string GetDependencyType(NetworkDevice device, string targetIp)
		{
			//IL_0044: Unknown result type (might be due to invalid IL or missing references)
			//IL_004a: Invalid comparison between Unknown and I4
			//IL_0053: Unknown result type (might be due to invalid IL or missing references)
			//IL_005a: Invalid comparison between Unknown and I4
			//IL_0063: Unknown result type (might be due to invalid IL or missing references)
			//IL_0069: Invalid comparison between Unknown and I4
			//IL_0072: Unknown result type (might be due to invalid IL or missing references)
			//IL_0078: Invalid comparison between Unknown and I4
			string targetIp2 = targetIp;
			NetworkDevice val = ((IEnumerable<NetworkDevice>)_discoveredDevices).FirstOrDefault((Func<NetworkDevice, bool>)((NetworkDevice d) => d.IPAddress == targetIp2));
			if (val == null)
			{
				return "依赖";
			}
			if (val.OpenPorts.Contains(53))
			{
				return "DNS";
			}
			if ((int)val.DeviceType == 7)
			{
				return "数据库";
			}
			if ((int)val.DeviceType == 9)
			{
				return "邮件";
			}
			if ((int)val.DeviceType == 8)
			{
				return "DNS";
			}
			if ((int)val.DeviceType == 6)
			{
				return "HTTP";
			}
			if (val.OpenPorts.Contains(443))
			{
				return "HTTPS";
			}
			if (val.OpenPorts.Contains(80))
			{
				return "HTTP";
			}
			if (val.OpenPorts.Contains(22))
			{
				return "SSH";
			}
			if (val.OpenPorts.Contains(3389))
			{
				return "RDP";
			}
			if (device.Gateway == targetIp2)
			{
				return "网关";
			}
			return "依赖";
		}

