		private async void ExportButton_Click(object sender, RoutedEventArgs e)
		{
			_ = 1;
			try
			{
				if (_discoveredDevices == null || _discoveredDevices.Count == 0)
				{
					System.Windows.MessageBox.Show("没有可导出的数据", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
				{
					Filter = "JSON文件|*.json|CSV文件|*.csv",
					FileName = $"网络拓扑_{DateTime.Now:yyyyMMdd_HHmmss}",
					Title = "导出网络拓扑"
				};
				if (saveFileDialog.ShowDialog() == true)
				{
					string filePath = saveFileDialog.FileName;
					string text = System.IO.Path.GetExtension(filePath).ToLower();
					if (text == ".json")
					{
						await ExportToJsonAsync(filePath);
					}
					else if (text == ".csv")
					{
						await ExportToCsvAsync(filePath);
					}
					System.Windows.MessageBox.Show("网络拓扑已导出到:\n" + filePath, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

