		private void ContextMenuHighlight_Click(object sender, RoutedEventArgs e)
		{
			if (_contextMenuNode == null)
			{
				return;
			}
			HashSet<string> hashSet = new HashSet<string> { _contextMenuNode.Device.IPAddress };
			foreach (TopologyEdge topologyEdge2 in _topologyEdges)
			{
				if (topologyEdge2.Source == _contextMenuNode.Device.IPAddress)
				{
					hashSet.Add(topologyEdge2.Target);
				}
				if (topologyEdge2.Target == _contextMenuNode.Device.IPAddress)
				{
					hashSet.Add(topologyEdge2.Source);
				}
			}
			foreach (Border item in TopologyCanvas.Children.OfType<Border>())
			{
				if (item.Tag is TopologyNode topologyNode)
				{
					if (hashSet.Contains(topologyNode.Device.IPAddress))
					{
						item.Opacity = 1.0;
						item.BorderBrush = new SolidColorBrush(Colors.Gold);
						item.BorderThickness = new Thickness(3.0);
					}
					else
					{
						item.Opacity = 0.3;
					}
				}
			}
			foreach (Line item2 in TopologyCanvas.Children.OfType<Line>())
			{
				if (item2.Tag is TopologyEdge topologyEdge)
				{
					if (topologyEdge.Source == _contextMenuNode.Device.IPAddress || topologyEdge.Target == _contextMenuNode.Device.IPAddress)
					{
						item2.Opacity = 1.0;
						item2.StrokeThickness = 3.0;
						item2.Stroke = new SolidColorBrush(System.Windows.Media.Color.FromRgb(231, 76, 60));
					}
					else
					{
						item2.Opacity = 0.1;
					}
				}
			}
		}

		private void ContextMenuHide_Click(object sender, RoutedEventArgs e)
		{
			if (_contextMenuNode == null)
			{
				return;
			}
			string iPAddress = _contextMenuNode.Device.IPAddress;
			if (_hiddenNodes.ContainsKey(iPAddress) && _hiddenNodes[iPAddress])
			{
				_hiddenNodes[iPAddress] = false;
			}
			else
			{
				_hiddenNodes[iPAddress] = true;
			}
			foreach (Border item in TopologyCanvas.Children.OfType<Border>())
			{
				if (item.Tag is TopologyNode topologyNode && topologyNode.Device.IPAddress == iPAddress)
				{
					item.Visibility = (_hiddenNodes[iPAddress] ? Visibility.Collapsed : Visibility.Visible);
				}
			}
			foreach (Line item2 in TopologyCanvas.Children.OfType<Line>())
			{
				if (item2.Tag is TopologyEdge topologyEdge)
				{
					bool flag = _hiddenNodes.ContainsKey(topologyEdge.Source) && _hiddenNodes[topologyEdge.Source];
					bool flag2 = _hiddenNodes.ContainsKey(topologyEdge.Target) && _hiddenNodes[topologyEdge.Target];
					item2.Visibility = ((flag || flag2) ? Visibility.Collapsed : Visibility.Visible);
				}
			}
		}

