		private async Task ExportTopologyAsImageAsync()
		{
			try
			{
				Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
				{
					Filter = "PNG图片|*.png|JPEG图片|*.jpg",
					FileName = $"网络拓扑图_{DateTime.Now:yyyyMMdd_HHmmss}",
					Title = "导出拓扑图为图片"
				};
				if (saveFileDialog.ShowDialog() != true)
				{
					return;
				}
				double width = TopologyCanvas.Width;
				double height = TopologyCanvas.Height;
				double num = 0.0;
				double num2 = 0.0;
				foreach (Border item in TopologyCanvas.Children.OfType<Border>())
				{
					double num3 = Canvas.GetLeft(item) + item.Width;
					double num4 = Canvas.GetTop(item) + item.Height;
					if (num3 > num)
					{
						num = num3;
					}
					if (num4 > num2)
					{
						num2 = num4;
					}
				}
				double num5 = 50.0;
				TopologyCanvas.Width = num + num5 * 2.0;
				TopologyCanvas.Height = num2 + num5 * 2.0;
				RenderTargetBitmap renderTargetBitmap = new RenderTargetBitmap((int)TopologyCanvas.Width, (int)TopologyCanvas.Height, 96.0, 96.0, PixelFormats.Pbgra32);
				TopologyCanvas.Measure(new Size(TopologyCanvas.Width, TopologyCanvas.Height));
				TopologyCanvas.Arrange(new Rect(0.0, 0.0, TopologyCanvas.Width, TopologyCanvas.Height));
				renderTargetBitmap.Render(TopologyCanvas);
				BitmapEncoder bitmapEncoder = ((!saveFileDialog.FileName.EndsWith(".png", StringComparison.OrdinalIgnoreCase)) ? ((BitmapEncoder)new JpegBitmapEncoder
				{
					QualityLevel = 95
				}) : ((BitmapEncoder)new PngBitmapEncoder()));
				bitmapEncoder.Frames.Add(BitmapFrame.Create(renderTargetBitmap));
				using FileStream stream = File.Create(saveFileDialog.FileName);
				bitmapEncoder.Save(stream);
				TopologyCanvas.Width = width;
				TopologyCanvas.Height = height;
				System.Windows.MessageBox.Show("拓扑图已导出到:\n" + saveFileDialog.FileName, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出图片失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

