		private string GetSubnet(string ipAddress)
		{
			string[] array = ipAddress.Split('.');
			if (array.Length == 4)
			{
				return $"{array[0]}.{array[1]}.{array[2]}.0/24";
			}
			return "未知子网";
		}

		private async Task ExportToJsonAsync(string filePath)
		{
			string contents = JsonSerializer.Serialize(_discoveredDevices, new JsonSerializerOptions
			{
				WriteIndented = true
			});
			await File.WriteAllTextAsync(filePath, contents);
		}

		private async Task ExportToCsvAsync(string filePath)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("IP地址,主机名,设备类型,MAC地址,开放端口,子网,网关,发现时间");
			foreach (NetworkDevice discoveredDevice in _discoveredDevices)
			{
				string value = string.Join(";", discoveredDevice.OpenPorts);
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(7, 8, stringBuilder2);
				handler.AppendFormatted(discoveredDevice.IPAddress);
				handler.AppendLiteral(",");
				handler.AppendFormatted(discoveredDevice.Hostname);
				handler.AppendLiteral(",");
				handler.AppendFormatted<DeviceType>(discoveredDevice.DeviceType);
				handler.AppendLiteral(",");
				handler.AppendFormatted(discoveredDevice.MacAddress);
				handler.AppendLiteral(",");
				handler.AppendFormatted(value);
				handler.AppendLiteral(",");
				handler.AppendFormatted(discoveredDevice.Subnet);
				handler.AppendLiteral(",");
				handler.AppendFormatted(discoveredDevice.Gateway);
				handler.AppendLiteral(",");
				handler.AppendFormatted(discoveredDevice.DiscoveryTime, "yyyy-MM-dd HH:mm:ss");
				stringBuilder2.AppendLine(ref handler);
			}
			await File.WriteAllTextAsync(filePath, stringBuilder.ToString());
		}

