		private static Border BuildStatCard(string title, string value, string valueColor, out TextBlock valueText)
		{
			Border obj = new Border
			{
				Background = System.Windows.Media.Brushes.White,
				CornerRadius = new CornerRadius(8.0),
				BorderBrush = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#E2E8F0")),
				BorderThickness = new Thickness(1.0),
				Padding = new Thickness(15.0, 12.0, 15.0, 12.0),
				Margin = new Thickness(5.0, 0.0, 5.0, 0.0)
			};
			StackPanel stackPanel = new StackPanel
			{
				Children = { (UIElement)new TextBlock
				{
					Text = title,
					FontSize = 12.0,
					FontWeight = FontWeights.SemiBold,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#7F8C8D"))
				} }
			};
			valueText = new TextBlock
			{
				Text = value,
				FontSize = 28.0,
				FontWeight = FontWeights.Bold,
				Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(valueColor)),
				Margin = new Thickness(0.0, 6.0, 0.0, 0.0)
			};
			stackPanel.Children.Add(valueText);
			obj.Child = stackPanel;
			return obj;
		}

