		private int GetSelectedDays()
		{
			if (_timeRangeComboBox?.SelectedItem is ComboBoxItem { Tag: var tag } && tag is int val)
			{
				return Math.Max(1, val);
			}
			return 7;
		}

		private async Task ReloadAsync()
		{
			int days = GetSelectedDays();
			try
			{
				if (_refreshButton != null)
				{
					_refreshButton.IsEnabled = false;
				}
				if (_clearButton != null)
				{
					_clearButton.IsEnabled = false;
				}
				if (_timeRangeComboBox != null)
				{
					_timeRangeComboBox.IsEnabled = false;
				}
				PluginExecutionStatistics stats = await _logService.GetStatisticsAsync(days, default(CancellationToken));
				List<PluginExecutionEntry> list = (_currentEntries = await _logService.GetRecentEntriesAsync(days, 50, default(CancellationToken)));
				ApplyEntries(list);
				ApplyStats(stats, list.Count);
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("刷新执行日志失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			finally
			{
				if (_refreshButton != null)
				{
					_refreshButton.IsEnabled = true;
				}
				if (_clearButton != null)
				{
					_clearButton.IsEnabled = true;
				}
				if (_timeRangeComboBox != null)
				{
					_timeRangeComboBox.IsEnabled = true;
				}
			}
		}

		private void ApplyEntries(List<PluginExecutionEntry> entries)
		{
			List<PluginExecutionRow> list = entries.Select((PluginExecutionEntry e) => new PluginExecutionRow
			{
				PluginId = e.PluginId,
				PluginName = e.PluginName,
				Target = e.Target,
				Port = e.Port,
				ServiceType = e.ServiceType,
				StartTimeText = e.StartTime,
				StartTime = e.StartTime,
				EndTime = e.EndTime,
				DurationMs = e.DurationMs,
				VulnCount = e.VulnCount,
				ErrorMessage = (e.ErrorMessage ?? string.Empty),
				StatusRaw = e.Status,
				StatusText = StatusToText(e.Status),
				StatusColor = StatusToColor(e.Status)
			}).ToList();
			_logDataGrid.ItemsSource = list;
			if (_recordCountText != null)
			{
				_recordCountText.Text = $"共 {list.Count} 条";
			}
		}

		private void ApplyStats(PluginExecutionStatistics stats, int displayedCount)
		{
			if (_totalExecValueText != null)
			{
				_totalExecValueText.Text = stats.TotalExecutions.ToString();
			}
			if (_successRateValueText != null)
			{
				double num = stats.SuccessRate * 100.0;
				_successRateValueText.Text = $"{num:F1}%";
				_successRateValueText.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString((num >= 80.0) ? "#27AE60" : ((num >= 50.0) ? "#F39C12" : "#E74C3C")));
			}
			if (_avgDurationValueText != null)
			{
				_avgDurationValueText.Text = $"{(int)Math.Round(stats.AverageDurationMs)} ms";
			}
			if (_failedCountValueText != null)
			{
				_failedCountValueText.Text = (stats.FailedCount + stats.TimeoutCount).ToString();
			}
		}

		private static string StatusToText(PluginExecutionStatus status)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0016: Expected I4, but got Unknown
			return (int)status switch
			{
				0 => "成功", 
				1 => "失败", 
				2 => "超时", 
				3 => "取消", 
				_ => ((object)(PluginExecutionStatus)(ref status)).ToString(), 
			};
		}

		private static string StatusToColor(PluginExecutionStatus status)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0016: Expected I4, but got Unknown
			return (int)status switch
			{
				0 => "#27AE60", 
				1 => "#E74C3C", 
				2 => "#C0392B", 
				3 => "#F39C12", 
				_ => "#95A5A6", 
			};
		}

		private async void RefreshButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				await ReloadAsync();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("刷新失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async void ReRunButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				object obj = _logDataGrid?.SelectedItem;
				if (!(obj is PluginExecutionRow row))
				{
					System.Windows.MessageBox.Show("请先选择一条日志记录", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				}
				else if (string.IsNullOrEmpty(row.Target))
				{
					System.Windows.MessageBox.Show("该日志条目缺少目标信息，无法重新执行", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				}
				else if (System.Windows.MessageBox.Show($"将重新执行插件扫描:\n目标: {row.Target}\n端口: {row.Port}\n插件: {row.PluginName}", "重新执行", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
				{
					Mouse.OverrideCursor = System.Windows.Input.Cursors.Wait;
					try
					{
						List<VulnerabilityResult> list = await PluginOrchestrator.Instance.ScanTargetAsync(row.Target, new List<int> { row.Port }, (IEnumerable<string>)null, default(CancellationToken), (string)null);
						System.Windows.MessageBox.Show($"重新执行完成：发现 {list.Count} 个漏洞（{row.PluginName} @ {row.Target}:{row.Port}）", "完成", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					}
					finally
					{
						Mouse.OverrideCursor = null;
					}
				}
			}
			catch (Exception ex)
			{
				Mouse.OverrideCursor = null;
				System.Windows.MessageBox.Show("重新执行失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async void ClearButton_Click(object sender, RoutedEventArgs e)
		{
			_ = 1;
			try
			{
				if (System.Windows.MessageBox.Show("确定要清空所有插件执行日志吗？\n\n此操作不可撤销。", "二次确认", MessageBoxButton.YesNo, MessageBoxImage.Exclamation) == MessageBoxResult.Yes)
				{
					await _logService.ClearAllAsync();
					await ReloadAsync();
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("清空失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async void TimeRangeComboBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			try
			{
				if (base.IsLoaded)
				{
					await ReloadAsync();
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("切换时间范围失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

