			base.Title = "插件管控中心";
			base.Width = 1200.0;
			base.Height = 760.0;
			base.WindowStartupLocation = WindowStartupLocation.CenterOwner;
			base.Background = System.Windows.Media.Brushes.White;
			base.MinWidth = 1000.0;
			base.MinHeight = 600.0;
			_governor = PluginGovernor.Instance;
			BuildUI();
			_dashboardTimer = new DispatcherTimer
			{
				Interval = TimeSpan.FromSeconds(5.0)
			};
			_dashboardTimer.Tick += async delegate
			{
				try
				{
					await ReloadRuntimeDashboardAsync();
				}
				catch (Exception)
				{
				}
			};
			_dashboardTimer.Start();
			base.KeyDown += delegate(object s, System.Windows.Input.KeyEventArgs e)
			{
				//IL_0001: Unknown result type (might be due to invalid IL or missing references)
				//IL_0008: Invalid comparison between Unknown and I4
				//IL_0013: Unknown result type (might be due to invalid IL or missing references)
				//IL_001a: Invalid comparison between Unknown and I4
				if ((int)e.Key == 94)
				{
					ReloadAllAsync();
				}
				else if ((int)e.Key == 13)
				{
					Close();
				}
			};
			base.Loaded += async delegate
			{
				try
				{
					await ReloadAllAsync();
				}
				catch (Exception ex)
				{
					System.Windows.MessageBox.Show("加载管控中心失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				}
			};
			base.Closed += delegate
