		private void BuildStringGridEditor(DockPanel parent, DataGrid grid, string policyKey)
		{
			DataGrid grid2 = grid;
			StackPanel stackPanel = new StackPanel
			{
				Orientation = System.Windows.Controls.Orientation.Horizontal,
				Margin = new Thickness(3.0, 3.0, 3.0, 3.0)
			};
			System.Windows.Controls.Button button = new System.Windows.Controls.Button
			{
				Content = "➕ 添加",
				Width = 80.0,
				Height = 26.0,
				Margin = new Thickness(0.0, 0.0, 5.0, 0.0)
			};
			button.Click += delegate
			{
				List<string> list2 = (grid2.ItemsSource as List<string>) ?? new List<string>();
				list2.Add("");
				grid2.ItemsSource = null;
				grid2.ItemsSource = list2;
			};
			System.Windows.Controls.Button button2 = new System.Windows.Controls.Button
			{
				Content = "➖ 删除选中",
				Width = 100.0,
				Height = 26.0
			};
			button2.Click += delegate
			{
				if (grid2.SelectedItem is string item)
				{
					List<string> list = (grid2.ItemsSource as List<string>) ?? new List<string>();
					list.Remove(item);
					grid2.ItemsSource = null;
					grid2.ItemsSource = list;
				}
			};
			stackPanel.Children.Add(button);
			stackPanel.Children.Add(button2);
			DockPanel.SetDock(stackPanel, Dock.Top);
			parent.Children.Add(stackPanel);
			parent.Children.Add(grid2);
		}

