		private void RollbackBtn_Click(object sender, RoutedEventArgs e)
		{
			if (((FrameworkElement)sender).DataContext is BackupRecordInfo backupRecordInfo && System.Windows.MessageBox.Show($"确定回滚 {backupRecordInfo.PluginId} 到 {backupRecordInfo.Version} 吗？", "回滚确认", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
			{
				RollbackAsync(backupRecordInfo.PluginId, backupRecordInfo.Version);
			}
		}

		private async Task RollbackAsync(string id, string version)
		{
			_ = 1;
			try
			{
				bool flag = await _governor.VersionManager.RollbackAsync(id, version);
				System.Windows.MessageBox.Show(flag ? "回滚成功！" : "回滚失败！", "提示", MessageBoxButton.OK, flag ? MessageBoxImage.Asterisk : MessageBoxImage.Hand);
				await ReloadVersionTabAsync();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("回滚失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async void UpgradeButton_Click(object sender, RoutedEventArgs e)
		{
			if (_versionPluginSelector.SelectedItem is string text)
			{
				bool flag = await _governor.VersionManager.UpgradeAsync(text, true);
				System.Windows.MessageBox.Show(flag ? "升级成功！" : "升级失败（请检查 core 版本要求）", "提示", MessageBoxButton.OK, flag ? MessageBoxImage.Asterisk : MessageBoxImage.Exclamation);
				await ReloadVersionTabAsync();
			}
		}

		private async Task RecheckUpdatesAsync()
		{
			_ = 3;
			try
			{
				PluginManager val = ((PluginOrchestrator.Instance.LoadedPlugins.Count <= 0) ? (await EnsurePluginManager()).Item1 : null);
				val = val;
				if (val == null)
				{
					val = (await EnsurePluginManager()).Item1;
				}
				PluginManager val2 = val;
				await _governor.VersionManager.CheckUpdatesAsync(val2, "1.0.1.0");
				await ReloadVersionTabAsync();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("检查更新失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async Task<(PluginManager, PluginOrchestrator)> EnsurePluginManager()
		{
			PluginOrchestrator orchestrator = PluginOrchestrator.Instance;
			if (!orchestrator.IsInitialized)
			{
				await orchestrator.InitializeAsync(default(CancellationToken));
			}
			PluginManager pm = new PluginManager();
			await pm.LoadAllPluginsAsync();
			return (pm, orchestrator);
		}

