		private async Task ReloadAllAsync()
		{
			await ReloadSecurityTabAsync();
			await ReloadVersionTabAsync();
			await ReloadHealthTabAsync();
			await ReloadSchedulerTabAsync();
			await ReloadRuntimeDashboardAsync();
			await ReloadPermissionApprovalTabAsync();
			await ReloadAlertTemplateTabAsync();
			UpdateStatusBar();
		}

		private void UpdateStatusBar()
		{
			try
			{
				List<PluginHealthSnapshot> allSnapshots = _governor.Health.GetAllSnapshots();
				int num = ((allSnapshots.Count > 0) ? ((int)allSnapshots.Average((PluginHealthSnapshot s) => s.HealthScore)) : 100);
				_statusHealthText.Text = $"平均健康度: {num}";
				_statusHealthText.Foreground = ((num < 60) ? new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#E74C3C")) : new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#1ABC9C")));
				int count = _governor.VersionManager.PendingUpdates.Count;
				_statusPendingText.Text = $"待更新: {count}";
				int count2 = _governor.Health.GetQuarantined().Count;
				_statusIsolatedText.Text = $"已隔离: {count2}";
				int value = _governor.Scheduler.Tasks.Count((ScheduledTask t) => t.Enabled);
				_statusTasksText.Text = $"调度任务: {value}";
			}
			catch
			{
			}
		}

		private async Task ReloadSecurityTabAsync()
		{
			try
			{
				PluginPolicy currentPolicy = _governor.Security.CurrentPolicy;
				_whitelistGrid.ItemsSource = new List<string>(currentPolicy.Whitelist);
				_blacklistGrid.ItemsSource = new List<string>(currentPolicy.Blacklist);
				_dangerousOpsTextBox.Text = string.Join(",", currentPolicy.DangerousOpBlockList);
				_policyModifiedText.Text = $"最后修改: {currentPolicy.LastModified:yyyy-MM-dd HH:mm:ss} by {currentPolicy.LastModifiedBy}";
				_permissionMatrixGrid.ItemsSource = currentPolicy.PermissionMatrix.Select((KeyValuePair<string, List<string>> kv) => new PermissionRow
				{
					PluginId = kv.Key,
					PermissionsText = string.Join(",", kv.Value ?? new List<string>())
				}).ToList();
			}
			catch (Exception)
			{
			}
			ReloadAuditGrid();
			await Task.CompletedTask;
		}

		private void ReloadAuditGrid()
		{
			try
			{
				DateTime dateTime = _auditDatePicker.SelectedDate ?? DateTime.Today;
				List<PluginAuditEntry> auditEntries = _governor.Security.GetAuditEntries(dateTime);
				_auditGrid.ItemsSource = auditEntries.OrderByDescending((PluginAuditEntry e) => e.Timestamp).ToList();
			}
			catch (Exception)
			{
			}
		}

		private async Task ReloadVersionTabAsync()
		{
			try
			{
				IReadOnlyDictionary<string, PluginMarketPlugin> pending = _governor.VersionManager.PendingUpdates;
				_pendingUpdateBadge.Text = $"● 待更新 {pending.Count}";
				IReadOnlyDictionary<string, IVulnerabilityScannerPlugin> loadedPlugins = PluginOrchestrator.Instance.LoadedPlugins;
				List<VersionRow> itemsSource = loadedPlugins.Values.Select(delegate(IVulnerabilityScannerPlugin p)
				{
					PluginMarketPlugin value;
					bool flag = pending.TryGetValue(p.PluginId, out value);
					return new VersionRow
					{
						PluginId = p.PluginId,
						LocalVersion = p.Version,
						RemoteVersion = (flag ? value.Version : "-"),
						StatusText = (flag ? "可升级" : "最新"),
						MinCoreVersion = (flag ? (value.MinCoreVersion ?? "-") : "-")
					};
				}).ToList();
				_versionGrid.ItemsSource = itemsSource;
				string text = _versionPluginSelector.SelectedItem as string;
				_versionPluginSelector.ItemsSource = loadedPlugins.Keys.OrderBy((string k) => k).ToList();
				if (text != null && loadedPlugins.ContainsKey(text))
				{
					_versionPluginSelector.SelectedItem = text;
				}
				else if (_versionPluginSelector.Items.Count > 0)
				{
					_versionPluginSelector.SelectedIndex = 0;
				}
				Dictionary<string, List<string>> dictionary = _governor.VersionManager.ListBackups();
				List<BackupRecordInfo> list = new List<BackupRecordInfo>();
				foreach (KeyValuePair<string, List<string>> item in dictionary)
				{
					foreach (string item2 in item.Value)
					{
						list.Add(new BackupRecordInfo
						{
							PluginId = item.Key,
							Version = item2,
							Action = "已备份",
							Timestamp = DateTime.Now
						});
					}
				}
				_backupsGrid.ItemsSource = list.OrderByDescending((BackupRecordInfo r) => r.Timestamp).ToList();
			}
			catch (Exception)
			{
			}
			await Task.CompletedTask;
		}

		private void ReloadDependencyTree()
		{
			try
			{
				if (_versionPluginSelector.SelectedItem is string key && PluginOrchestrator.Instance.LoadedPlugins.TryGetValue(key, out var value))
				{
					Plugin val = ToPluginModel(value);
					List<Plugin> list = PluginOrchestrator.Instance.LoadedPlugins.Values.Select(ToPluginModel).ToList();
					PluginDependencyGraph val2 = _governor.VersionManager.ResolveDependency(val, (IEnumerable<Plugin>)list);
					_dependencyTreeView.Items.Clear();
					_dependencyTreeView.Items.Add(BuildDepNode(val2.Root));
				}
			}
			catch (Exception)
			{
			}
		}

		private static Plugin ToPluginModel(IVulnerabilityScannerPlugin p)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0005: Unknown result type (might be due to invalid IL or missing references)
			//IL_0011: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0032: Unknown result type (might be due to invalid IL or missing references)
			//IL_0047: Unknown result type (might be due to invalid IL or missing references)
			//IL_005c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0068: Expected O, but got Unknown
			return new Plugin
			{
				Id = p.PluginId,
				Name = p.Name,
				Version = (p.Version ?? "1.0.0"),
				Author = (p.Author ?? string.Empty),
				Description = (p.Description ?? string.Empty),
				Dependencies = new List<string>()
			};
		}

		private TreeViewItem BuildDepNode(PluginDependencyNode node)
		{
			//IL_001a: Unknown result type (might be due to invalid IL or missing references)
			//IL_001f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			//IL_0034: Expected I4, but got Unknown
			//IL_019c: Unknown result type (might be due to invalid IL or missing references)
			//IL_01a2: Invalid comparison between Unknown and I4
			PluginDependencyNode node2 = node;
			DependencyStatus status = node2.Status;
			string header = (int)status switch
			{
				0 => $"\ud83d\udfe2 {node2.PluginId} ({node2.Version})", 
				1 => "\ud83d\udd34 " + node2.PluginId + " [缺失]", 
				2 => $"\ud83d\udfe1 {node2.PluginId} ({node2.Version} < {node2.MinRequiredVersion})", 
				_ => node2.PluginId, 
			};
			TreeViewItem treeViewItem = new TreeViewItem
			{
				Header = header
			};
			foreach (PluginDependencyNode child in node2.Children)
			{
				treeViewItem.Items.Add(BuildDepNode(child));
			}
			if ((int)node2.Status == 1)
			{
				TreeViewItem treeViewItem2 = new TreeViewItem
				{
					Header = "⚡ 一键安装"
				};
				treeViewItem2.MouseDoubleClick += async delegate
				{
					await _governor.VersionManager.InstallDependenciesAsync(new List<string> { node2.PluginId });
					ReloadDependencyTree();
				};
				treeViewItem.Items.Add(treeViewItem2);
			}
			return treeViewItem;
		}

		private async Task ReloadHealthTabAsync()
		{
			try
			{
				List<PluginHealthSnapshot> allSnapshots = _governor.Health.GetAllSnapshots();
				_healthRankingGrid.ItemsSource = allSnapshots.Select((PluginHealthSnapshot s) => new HealthRow
				{
					PluginId = s.PluginId,
					HealthScore = s.HealthScore,
					TotalExecutions = s.TotalExecutions,
					TotalFailures = s.TotalFailures,
					TotalTimeouts = s.TotalTimeouts,
					PeakMemoryText = $"{(double)s.PeakMemoryBytes / 1024.0 / 1024.0:F1} MB",
					TotalElapsedMs = s.TotalElapsedMs,
					StatusText = (s.IsQuarantined ? "\ud83d\udd34 已隔离" : ((s.HealthScore < 60) ? "⚠ 低健康度" : "\ud83d\udfe2 正常"))
				}).ToList();
				_quarantinedGrid.ItemsSource = allSnapshots.Where((PluginHealthSnapshot s) => s.IsQuarantined).ToList();
				if (allSnapshots.Count > 0)
				{
					int value = (int)allSnapshots.Average((PluginHealthSnapshot s) => s.HealthScore);
					_healthAvgText.Text = $"平均健康度: {value}";
				}
				else
				{
					_healthAvgText.Text = "平均健康度: --";
				}
				_healthIsolatedText.Text = $"已隔离: {allSnapshots.Count((PluginHealthSnapshot s) => s.IsQuarantined)}";
			}
			catch (Exception)
			{
			}
			await Task.CompletedTask;
		}

		private async Task ReloadSchedulerTabAsync()
		{
			try
			{
				IReadOnlyList<ScheduledTask> tasks = _governor.Scheduler.Tasks;
				_tasksGrid.ItemsSource = tasks.Select((ScheduledTask t) => new TaskRow
				{
					Id = t.Id,
					Name = t.Name,
					CronExpression = t.CronExpression,
					TargetIp = t.TargetIp,
					PortsText = ((t.Ports == null) ? "" : string.Join(",", t.Ports)),
					TotalRuns = t.TotalRuns,
					TotalFailures = t.TotalFailures,
					EnabledText = (t.Enabled ? "✅" : "❌")
				}).ToList();
				IReadOnlyList<AlertRule> alertRules = _governor.Scheduler.AlertRules;
				_alertRulesGrid.ItemsSource = alertRules.Select(delegate(AlertRule r)
				{
					//IL_001f: Unknown result type (might be due to invalid IL or missing references)
					//IL_0024: Unknown result type (might be due to invalid IL or missing references)
					AlertRow obj = new AlertRow
					{
						Id = r.Id,
						Name = r.Name
					};
					AlertType type = r.Type;
					obj.TypeText = ((object)(AlertType)(ref type)).ToString();
					obj.Threshold = r.Threshold;
					obj.TimeWindowMinutes = r.TimeWindowMinutes;
					obj.ChannelsText = string.Join(",", r.NotificationChannels);
					obj.EnabledText = (r.Enabled ? "✅" : "❌");
					return obj;
				}).ToList();
			}
			catch (Exception)
			{
			}
			await Task.CompletedTask;
		}

