				BorderBrush = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#BDC3C7")),
				BorderThickness = new Thickness(1.0),
				CornerRadius = new CornerRadius(4.0),
				Padding = new Thickness(15.0, 10.0, 15.0, 10.0),
				Margin = new Thickness(0.0, 0.0, 10.0, 0.0),
				Width = 220.0
			};
			StackPanel stackPanel = new StackPanel
			{
				Children = { (UIElement)new TextBlock
				{
					Text = title,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#7F8C8D")),
					FontSize = 12.0
				} }
			};
			valueText = new TextBlock
			{
				Text = value,
				FontSize = 28.0,
				FontWeight = FontWeights.Bold,
				Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(colorHex)),
				Margin = new Thickness(0.0, 4.0, 0.0, 0.0)
			};
			stackPanel.Children.Add(valueText);
			obj.Child = stackPanel;
			return obj;
		}

		private void EventStreamList_MouseDoubleClick(object sender, MouseButtonEventArgs e)
		{
			if (!(_eventStreamList.SelectedItem is EventStreamRow eventStreamRow) || string.IsNullOrEmpty(eventStreamRow.PluginId))
			{
				return;
			}
			if (_healthRankingGrid != null)
			{
				_healthRankingGrid.Items.Refresh();
				foreach (object item in (IEnumerable)_healthRankingGrid.Items)
				{
					if (item is HealthRow healthRow && healthRow.PluginId == eventStreamRow.PluginId)
					{
						_healthRankingGrid.SelectedItem = healthRow;
						_healthRankingGrid.ScrollIntoView(healthRow);
						break;
					}
				}
			}
			System.Windows.MessageBox.Show("已在「健康监控」Tab 中定位插件: " + eventStreamRow.PluginId, "跳转", MessageBoxButton.OK, MessageBoxImage.Asterisk);
		}

		private async Task ReloadRuntimeDashboardAsync()
		{
			try
			{
				List<PluginHealthSnapshot> allSnapshots = _governor.Health.GetAllSnapshots();
				int num = ((allSnapshots.Count > 0) ? ((int)allSnapshots.Average((PluginHealthSnapshot s) => s.HealthScore)) : 100);
				if (_kpiHealthText != null)
				{
					_kpiHealthText.Text = num.ToString();
				}
				int count = _governor.VersionManager.PendingUpdates.Count;
				if (_kpiPendingText != null)
				{
					_kpiPendingText.Text = count.ToString();
				}
				int count2 = _governor.Health.GetQuarantined().Count;
				if (_kpiIsolatedText != null)
				{
					_kpiIsolatedText.Text = count2.ToString();
				}
				int num2 = _governor.Scheduler.Tasks.Count((ScheduledTask t) => t.Enabled);
				if (_kpiTasksText != null)
				{
					_kpiTasksText.Text = num2.ToString();
				}
				DrawHealthBarChart(allSnapshots.OrderByDescending((PluginHealthSnapshot s) => s.HealthScore).Take(5).ToList());
				DateTime today = DateTime.Today;
				List<EventStreamRow> list = (from e in (from e in _governor.Security.GetAuditEntries(today)
						where e.Action == "Quarantined" || e.Action == "MemoryLimitExceeded" || e.Action == "PluginBlocked" || e.Action == "DangerousOpBlocked" || e.Action == "SignatureFailed" || e.Action.StartsWith("Permission") || e.Result == "Blocked" || e.Result == "Failed"
						orderby e.Timestamp descending
						select e).Take(100)
					select new EventStreamRow
					{
						Timestamp = e.Timestamp,
						TimeText = e.Timestamp.ToString("HH:mm:ss"),
						PluginId = e.PluginId,
						Action = e.Action,
						Result = e.Result,
						Detail = (e.Detail ?? ""),
						SeverityText = ((e.Result == "Blocked" || e.Result == "Failed") ? "⚠ 异常" : "ℹ 信息")
					}).ToList();
				_eventStream.Clear();
				foreach (EventStreamRow item in list)
				{
					_eventStream.Add(item);
				}
			}
			catch (Exception)
			{
			}
			await Task.CompletedTask;
		}

		private void DrawHealthBarChart(List<PluginHealthSnapshot> top5)
		{
			if (_healthBarCanvas == null)
			{
				return;
			}
			_healthBarCanvas.Children.Clear();
			if (top5.Count == 0)
			{
				TextBlock element = new TextBlock
				{
					Text = "暂无插件健康度数据",
					Foreground = System.Windows.Media.Brushes.Gray,
					FontSize = 12.0
				};
				Canvas.SetLeft(element, 20.0);
				Canvas.SetTop(element, 100.0);
				_healthBarCanvas.Children.Add(element);
				return;
			}
			for (int i = 0; i < top5.Count; i++)
			{
				PluginHealthSnapshot val = top5[i];
				double num = 10.0 + (double)i * 42.0;
				TextBlock element2 = new TextBlock
				{
					Text = Truncate(val.PluginId, 18),
					FontSize = 12.0,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2C3E50")),
					Width = 120.0,
					TextAlignment = TextAlignment.Right,
					VerticalAlignment = VerticalAlignment.Center
				};
				Canvas.SetLeft(element2, 0.0);
				Canvas.SetTop(element2, num + 5.0);
				_healthBarCanvas.Children.Add(element2);
				double num2 = Math.Max(2.0, 320.0 * (double)val.HealthScore / 100.0);
				int healthScore = val.HealthScore;
				string text = ((healthScore >= 80) ? "#27AE60" : ((healthScore < 60) ? "#E74C3C" : "#F39C12"));
				string value = text;
				System.Windows.Shapes.Rectangle element3 = new System.Windows.Shapes.Rectangle
				{
					Width = num2,
					Height = 28.0,
					Fill = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(value)),
					RadiusX = 2.0,
					RadiusY = 2.0,
					Stroke = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#7F8C8D")),
					StrokeThickness = 0.5
				};
				Canvas.SetLeft(element3, 130.0);
				Canvas.SetTop(element3, num);
				_healthBarCanvas.Children.Add(element3);
				TextBlock element4 = new TextBlock
				{
					Text = val.HealthScore.ToString(),
					FontWeight = FontWeights.Bold,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2C3E50")),
					FontSize = 12.0
				};
				Canvas.SetLeft(element4, 130.0 + num2 + 6.0);
				Canvas.SetTop(element4, num + 5.0);
				_healthBarCanvas.Children.Add(element4);
			}
		}

		private static string Truncate(string s, int max)
		{
			if (string.IsNullOrEmpty(s))
			{
				return "";
			}
			if (s.Length > max)
			{
				return s.Substring(0, max - 1) + "…";
			}
			return s;
		}

