		private async void PermissionDecisionBtn_Click(object sender, RoutedEventArgs e)
		{
			_ = 3;
			try
			{
				if (!(sender is System.Windows.Controls.Button { DataContext: var dataContext } button))
				{
					return;
				}
				PermissionRequestRow row = dataContext as PermissionRequestRow;
				if (row == null)
				{
					return;
				}
				bool isApprove = button.Tag as string == "approve";
				PermissionRequest val = ((IEnumerable<PermissionRequest>)_governor.PermissionRequest.GetAll()).FirstOrDefault((Func<PermissionRequest, bool>)((PermissionRequest r) => r.Id == row.Id));
				if (val == null)
				{
					System.Windows.MessageBox.Show("该申请已被处理或不存在。", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					await ReloadPermissionApprovalTabAsync();
					return;
				}
				PermissionRequestDialog permissionRequestDialog = new PermissionRequestDialog(val)
				{
					Owner = this
				};
				if (permissionRequestDialog.ShowDialog() == true)
				{
					User current = SessionContext.Instance.Current;
					string text = ((current != null) ? current.Username : null) ?? "admin";
					string text2 = permissionRequestDialog.OperatorNote ?? "";
					if (!isApprove)
					{
						await _governor.PermissionRequest.RejectAsync(val.Id, text, text2);
					}
					else
					{
						await _governor.PermissionRequest.ApproveAsync(val.Id, text, text2);
					}
					System.Windows.MessageBox.Show(isApprove ? "已通过" : "已拒绝", "完成", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					await ReloadPermissionApprovalTabAsync();
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("处理失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async Task ReloadPermissionApprovalTabAsync()
		{
			try
			{
				List<PermissionRequest> pending = _governor.PermissionRequest.GetPending();
				_permissionRequests.Clear();
				foreach (PermissionRequest item in pending)
				{
					_permissionRequests.Add(new PermissionRequestRow
					{
						Id = item.Id,
						PluginId = item.PluginId,
						Permission = item.Permission,
						Reason = item.Reason,
						RequestedAt = item.RequestedAt,
						RequestedAtText = item.RequestedAt.ToString("yyyy-MM-dd HH:mm:ss")
					});
				}
				if (_permissionRequestSummary != null)
				{
					_permissionRequestSummary.Text = $"待审批权限申请: {pending.Count}";
				}
			}
			catch (Exception)
			{
			}
			await Task.CompletedTask;
		}

