		private async void EnableAlertTemplateBtn_Click(object sender, RoutedEventArgs e)
		{
			_ = 1;
			try
			{
				if (sender is System.Windows.Controls.Button button)
				{
					string text = button.Tag as string;
					if (!string.IsNullOrEmpty(text))
					{
						User current = SessionContext.Instance.Current;
						string text2 = ((current != null) ? current.Username : null) ?? "admin";
						AlertRule val = _governor.AlertTemplate.EnableTemplate(text, text2, (Dictionary<string, object>)null);
						_templateEnabledCache[text] = true;
						System.Windows.MessageBox.Show($"已根据模板 [{val.Name}] 创建告警规则（阈值={val.Threshold}）", "启用成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
						await ReloadAlertTemplateTabAsync();
						await ReloadSchedulerTabAsync();
					}
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("启用失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async Task ReloadAlertTemplateTabAsync()
		{
			try
			{
				List<AlertTemplate> source = _governor.AlertTemplate.ListTemplates();
				HashSet<string> existingRuleTemplateIds = new HashSet<string>(from r in _governor.Scheduler.AlertRules
					where !string.IsNullOrEmpty(r.TemplateId)
					select r.TemplateId);
				List<AlertTemplateCard> itemsSource = source.Select((AlertTemplate t) => new AlertTemplateCard
				{
					Id = t.Id,
					Name = t.Name,
					Description = t.Description,
					Icon = t.Icon,
					ChannelsText = "推荐渠道: " + string.Join(" · ", t.RecommendedChannels),
					IsEnabled = (existingRuleTemplateIds.Contains(t.Id) || _templateEnabledCache.ContainsKey(t.Id)),
					ButtonText = ((existingRuleTemplateIds.Contains(t.Id) || _templateEnabledCache.ContainsKey(t.Id)) ? "✅ 已启用" : "启用")
				}).ToList();
				if (_alertTemplateItems != null)
				{
					_alertTemplateItems.ItemsSource = itemsSource;
				}
			}
			catch (Exception)
			{
			}
			await Task.CompletedTask;
		}

		private async void SavePolicyButton_Click(object sender, RoutedEventArgs e)
		{
			_ = 1;
			try
			{
				PluginPolicy currentPolicy = _governor.Security.CurrentPolicy;
				currentPolicy.Whitelist = ((List<string>)_whitelistGrid.ItemsSource) ?? new List<string>();
				currentPolicy.Blacklist = ((List<string>)_blacklistGrid.ItemsSource) ?? new List<string>();
				currentPolicy.DangerousOpBlockList = (string.IsNullOrWhiteSpace(_dangerousOpsTextBox.Text) ? new List<string>() : (from s in _dangerousOpsTextBox.Text.Split(',')
					select s.Trim() into s
					where !string.IsNullOrEmpty(s)
					select s).ToList());
				List<PermissionRow> obj = (_permissionMatrixGrid.ItemsSource as IEnumerable<PermissionRow>)?.ToList() ?? new List<PermissionRow>();
				Dictionary<string, List<string>> dictionary = new Dictionary<string, List<string>>();
				foreach (PermissionRow item in obj)
				{
					if (!string.IsNullOrWhiteSpace(item.PluginId))
					{
						dictionary[item.PluginId] = (string.IsNullOrWhiteSpace(item.PermissionsText) ? new List<string>() : (from s in item.PermissionsText.Split(',')
							select s.Trim() into s
							where !string.IsNullOrEmpty(s)
							select s).ToList());
					}
				}
				currentPolicy.PermissionMatrix = dictionary;
				User current2 = SessionContext.Instance.Current;
				string op = ((current2 != null) ? current2.Username : null) ?? "admin";
				await _governor.Security.SavePolicyAsync(currentPolicy, op);
				_policyModifiedText.Text = $"最后修改: {DateTime.Now:yyyy-MM-dd HH:mm:ss} by {op}";
				System.Windows.MessageBox.Show("策略已保存并立即生效！", "成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				await ReloadSecurityTabAsync();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("保存失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

