		private Window BuildTaskEditDialog(ScheduledTask task, bool isNew)
		{
			ScheduledTask task2 = task;
			Window dialog = new Window
			{
				Title = (isNew ? "新建定时任务" : "编辑定时任务"),
				Width = 460.0,
				Height = 380.0,
				WindowStartupLocation = WindowStartupLocation.CenterOwner,
				Owner = this,
				ResizeMode = ResizeMode.NoResize
			};
			Grid grid = new Grid
			{
				Margin = new Thickness(20.0)
			};
			grid.RowDefinitions.Add(new RowDefinition
			{
				Height = GridLength.Auto
			});
			grid.RowDefinitions.Add(new RowDefinition
			{
				Height = new GridLength(1.0, GridUnitType.Star)
			});
			grid.RowDefinitions.Add(new RowDefinition
			{
				Height = GridLength.Auto
			});
			StackPanel stackPanel = new StackPanel();
			System.Windows.Controls.TextBox nameBox = new System.Windows.Controls.TextBox
			{
				Text = task2.Name,
				Margin = new Thickness(0.0, 2.0, 0.0, 8.0)
			};
			stackPanel.Children.Add(new TextBlock
			{
				Text = "任务名称"
			});
			stackPanel.Children.Add(nameBox);
			System.Windows.Controls.TextBox cronBox = new System.Windows.Controls.TextBox
			{
				Text = task2.CronExpression,
				Margin = new Thickness(0.0, 2.0, 0.0, 8.0)
			};
			stackPanel.Children.Add(new TextBlock
			{
				Text = "Cron 表达式（5 段: 分 时 日 月 周）"
			});
			stackPanel.Children.Add(cronBox);
			System.Windows.Controls.TextBox ipBox = new System.Windows.Controls.TextBox
			{
				Text = task2.TargetIp,
				Margin = new Thickness(0.0, 2.0, 0.0, 8.0)
			};
			stackPanel.Children.Add(new TextBlock
			{
				Text = "目标 IP"
			});
			stackPanel.Children.Add(ipBox);
			System.Windows.Controls.TextBox portsBox = new System.Windows.Controls.TextBox
			{
				Text = string.Join(",", task2.Ports),
				Margin = new Thickness(0.0, 2.0, 0.0, 8.0)
			};
			stackPanel.Children.Add(new TextBlock
			{
				Text = "端口（逗号分隔）"
			});
			stackPanel.Children.Add(portsBox);
			System.Windows.Controls.TextBox retryBox = new System.Windows.Controls.TextBox
			{
				Text = task2.MaxRetries.ToString(),
				Margin = new Thickness(0.0, 2.0, 0.0, 8.0)
			};
			stackPanel.Children.Add(new TextBlock
			{
				Text = "最大重试次数（0-5）"
			});
			stackPanel.Children.Add(retryBox);
			System.Windows.Controls.CheckBox enableBox = new System.Windows.Controls.CheckBox
			{
				Content = "启用",
				IsChecked = task2.Enabled,
				Margin = new Thickness(0.0, 4.0, 0.0, 0.0)
			};
			stackPanel.Children.Add(enableBox);
			ScrollViewer element = new ScrollViewer
			{
				Content = stackPanel,
				VerticalScrollBarVisibility = ScrollBarVisibility.Auto
			};
			Grid.SetRow(element, 1);
			grid.Children.Add(element);
			StackPanel stackPanel2 = new StackPanel
			{
				Orientation = System.Windows.Controls.Orientation.Horizontal,
				HorizontalAlignment = System.Windows.HorizontalAlignment.Right,
				Margin = new Thickness(0.0, 12.0, 0.0, 0.0)
			};
			System.Windows.Controls.Button button = new System.Windows.Controls.Button
			{
				Content = "保存",
				Width = 80.0,
				Height = 30.0,
				Margin = new Thickness(0.0, 0.0, 5.0, 0.0),
				Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#27AE60")),
				Foreground = System.Windows.Media.Brushes.White,
				BorderThickness = new Thickness(0.0)
			};
			System.Windows.Controls.Button button2 = new System.Windows.Controls.Button
			{
				Content = "取消",
				Width = 80.0,
				Height = 30.0
			};
			button.Click += delegate
			{
				task2.Name = nameBox.Text.Trim();
				task2.CronExpression = cronBox.Text.Trim();
				task2.TargetIp = ipBox.Text.Trim();
				task2.Ports = (string.IsNullOrWhiteSpace(portsBox.Text) ? new List<int>() : (from p in portsBox.Text.Split(',')
					select int.TryParse(p.Trim(), out var result2) ? result2 : 0 into n
					where n > 0 && n <= 65535
					select n).ToList());
				task2.MaxRetries = (int.TryParse(retryBox.Text, out var result) ? Math.Clamp(result, 0, 5) : 0);
				task2.Enabled = enableBox.IsChecked == true;
				dialog.DialogResult = true;
				dialog.Close();
			};
			button2.Click += delegate
			{
				dialog.Close();
			};
			stackPanel2.Children.Add(button);
			stackPanel2.Children.Add(button2);
			Grid.SetRow(stackPanel2, 2);
			grid.Children.Add(stackPanel2);
			dialog.Content = grid;
			return dialog;
		}

