	public class PluginManagerWindow : Window, IComponentConnector
	{
		private readonly PluginManager _pluginManager;

		private IVulnerabilityScannerPlugin? _selectedPlugin;

		private Dictionary<string, bool> _pluginEnabledStates = new Dictionary<string, bool>();

		private DataGrid _pluginsDataGrid;

		private StackPanel _pluginDetailPanel;

