		public PluginManagerWindow()
		{
			//IL_004d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0057: Expected O, but got Unknown
			base.Title = "插件管理器";
			base.Width = 1050.0;
			base.Height = 700.0;
			base.WindowStartupLocation = WindowStartupLocation.CenterOwner;
			base.Background = System.Windows.Media.Brushes.White;
			_pluginManager = new PluginManager();
			BuildUI();
			base.KeyDown += Window_KeyDown;
			base.Loaded += async delegate
			{
				try
				{
					await _pluginManager.LoadAllPluginsAsync();
					foreach (IVulnerabilityScannerPlugin value2 in _pluginManager.Plugins.Values)
					{
						Dictionary<string, object> pluginConfig = _pluginManager.GetPluginConfig(value2.PluginId);
						if (pluginConfig != null && pluginConfig.TryGetValue("IsEnabled", out var value))
						{
							_pluginEnabledStates[value2.PluginId] = Convert.ToBoolean(value);
						}
						else
						{
							_pluginEnabledStates[value2.PluginId] = true;
						}
					}
					RefreshPluginList();
				}
				catch (Exception ex)
				{
					System.Windows.MessageBox.Show("加载插件失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				}
			};
		}

		private void Window_KeyDown(object sender, System.Windows.Input.KeyEventArgs e)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0007: Invalid comparison between Unknown and I4
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			//IL_001f: Invalid comparison between Unknown and I4
			if ((int)e.Key == 6)
			{
				RefreshPluginList();
				e.Handled = true;
			}
			else if ((int)e.Key == 13)
			{
				Close();
			}
		}

