		private void RefreshPluginList()
		{
			List<PluginDisplayInfo> allPluginDisplayInfos = _pluginManager.Plugins.Values.Select(delegate(IVulnerabilityScannerPlugin p)
			{
				PluginRuntimeStatus status = p.GetStatus();
				bool value;
				bool flag = !_pluginEnabledStates.TryGetValue(p.PluginId, out value) || value;
				return new PluginDisplayInfo
				{
					PluginId = p.PluginId,
					Name = p.Name,
					Version = p.Version,
					Author = p.Author,
					Category = string.Join(", ", p.SupportedScanTypes.Take(3)),
					StatusText = ((!flag) ? "已禁用" : (status.IsInitialized ? "正常" : "未初始化")),
					StatusColor = ((!flag) ? "#95A5A6" : (status.IsInitialized ? "#27AE60" : "#F39C12")),
					IsEnabled = flag,
					IsBuiltIn = p.PluginId.StartsWith("builtin.")
				};
			}).ToList();
			_allPluginDisplayInfos = allPluginDisplayInfos;
			ApplyFilters();
		}

		private void PluginsDataGrid_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			object selectedItem = _pluginsDataGrid.SelectedItem;
			PluginDisplayInfo info = selectedItem as PluginDisplayInfo;
			if (info != null)
			{
				_selectedPlugin = _pluginManager.Plugins.Values.FirstOrDefault((Func<IVulnerabilityScannerPlugin, bool>)((IVulnerabilityScannerPlugin p) => p.PluginId == info.PluginId));
				DisplayPluginDetails(_selectedPlugin, info);
			}
		}

		private void DisplayPluginDetails(IVulnerabilityScannerPlugin? plugin, PluginDisplayInfo? displayInfo)
		{
			//IL_0404: Unknown result type (might be due to invalid IL or missing references)
			IVulnerabilityScannerPlugin plugin2 = plugin;
			_pluginDetailPanel.Children.Clear();
			if (plugin2 == null)
			{
				_pluginDetailPanel.Children.Add(new TextBlock
				{
					Text = "\ud83d\udc48 请从左侧选择一个插件查看详情",
					HorizontalAlignment = System.Windows.HorizontalAlignment.Center,
					Foreground = System.Windows.Media.Brushes.Gray,
					FontSize = 14.0,
					Margin = new Thickness(20.0)
				});
				_configureButton.IsEnabled = false;
				_enableDisableButton.IsEnabled = false;
				_uninstallButton.IsEnabled = false;
				return;
			}
			PluginRuntimeStatus status = plugin2.GetStatus();
			bool flag = displayInfo?.IsEnabled ?? true;
			_pluginDetailPanel.Children.Add(new TextBlock
			{
				Text = plugin2.Name,
				FontSize = 20.0,
				FontWeight = FontWeights.Bold,
				Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2C3E50")),
				Margin = new Thickness(0.0, 0.0, 0.0, 5.0)
			});
			Border border = new Border
			{
				Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(displayInfo?.StatusColor ?? "#95A5A6")),
				CornerRadius = new CornerRadius(4.0),
				Padding = new Thickness(10.0, 4.0, 10.0, 4.0),
				HorizontalAlignment = System.Windows.HorizontalAlignment.Left,
				Margin = new Thickness(0.0, 0.0, 0.0, 15.0)
			};
			border.Child = new TextBlock
			{
				Text = (displayInfo?.StatusText ?? "未知"),
				Foreground = System.Windows.Media.Brushes.White,
				FontWeight = FontWeights.SemiBold,
				FontSize = 12.0
			};
			_pluginDetailPanel.Children.Add(border);
			AddSectionHeader("基本信息");
			AddDetailRow("插件 ID", plugin2.PluginId, "\ud83c\udd94");
			AddDetailRow("版本", plugin2.Version, "\ud83d\udccc");
			AddDetailRow("作者", plugin2.Author, "\ud83d\udc64");
			AddDetailRow("描述", plugin2.Description, "\ud83d\udcdd");
			AddDetailRow("支持类型", string.Join(", ", plugin2.SupportedScanTypes), "\ud83c\udfaf");
			AddSectionHeader("扫描统计");
			AddDetailRow("扫描次数", status.ScanCount.ToString(), "\ud83d\udcca");
			AddDetailRow("发现漏洞", status.VulnerabilityFound.ToString(), "\ud83d\udd0d");
			AddDetailRow("最后扫描", status.LastScanTime?.ToString("yyyy-MM-dd HH:mm:ss") ?? "从未扫描", "\ud83d\udd50");
			AddDetailRow("状态消息", status.Message, "\ud83d\udcac");
			List<PluginConfigParameter> configParameters = plugin2.ConfigParameters;
			if (configParameters != null && configParameters.Any())
			{
				AddSectionHeader("配置参数");
				foreach (PluginConfigParameter configParameter in plugin2.ConfigParameters)
				{
					AddDetailRow(configParameter.DisplayName, $"{configParameter.Description} (类型: {configParameter.Type}, 默认: {configParameter.DefaultValue ?? "无"})", "⚙\ufe0f");
				}
			}
			AddSectionHeader("操作");
			System.Windows.Controls.Button button = new System.Windows.Controls.Button
			{
				Content = "\ud83d\udccb 查看日志",
				Height = 30.0,
				Padding = new Thickness(15.0, 0.0, 15.0, 0.0),
				Margin = new Thickness(0.0, 5.0, 0.0, 0.0),
				Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#3498DB")),
				Foreground = System.Windows.Media.Brushes.White,
