		private async void EnableDisableButton_Click(object sender, RoutedEventArgs e)
		{
			if (_selectedPlugin == null)
			{
				return;
			}
			bool value;
			bool flag = !_pluginEnabledStates.TryGetValue(_selectedPlugin.PluginId, out value) || value;
			_pluginEnabledStates[_selectedPlugin.PluginId] = !flag;
			Dictionary<string, object> dictionary = _pluginManager.GetPluginConfig(_selectedPlugin.PluginId) ?? new Dictionary<string, object>();
			dictionary["IsEnabled"] = !flag;
			await _pluginManager.UpdatePluginConfigAsync(_selectedPlugin.PluginId, dictionary);
			RefreshPluginList();
			if (_pluginsDataGrid.ItemsSource is List<PluginDisplayInfo> source)
			{
				PluginDisplayInfo pluginDisplayInfo = source.FirstOrDefault((PluginDisplayInfo i) => i.PluginId == _selectedPlugin.PluginId);
				if (pluginDisplayInfo != null)
				{
					_pluginsDataGrid.SelectedItem = pluginDisplayInfo;
					DisplayPluginDetails(_selectedPlugin, pluginDisplayInfo);
				}
			}
		}

		private async void UninstallButton_Click(object sender, RoutedEventArgs e)
		{
			if (_selectedPlugin != null && System.Windows.MessageBox.Show("确定要卸载插件 '" + _selectedPlugin.Name + "' 吗？\n\n此操作不可撤销。", "确认卸载", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
			{
				if (await _pluginManager.UninstallPluginAsync(_selectedPlugin.PluginId))
				{
					System.Windows.MessageBox.Show("插件已卸载！", "成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					_selectedPlugin = null;
					RefreshPluginList();
					DisplayPluginDetails(null, null);
				}
				else
				{
					System.Windows.MessageBox.Show("卸载失败！", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				}
			}
		}

