		private void SearchTextBox_TextChanged(object sender, TextChangedEventArgs e)
		{
			ApplyFilters();
		}

		private void CategoryFilterComboBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			ApplyFilters();
		}

		private void ApplyFilters()
		{
			if (_allPluginDisplayInfos == null)
			{
				return;
			}
			string keyword = _searchTextBox?.Text?.Trim().ToLower() ?? "";
			string selectedCategory = _categoryFilterComboBox?.SelectedItem?.ToString() ?? "全部类别";
			if (keyword == "搜索插件...")
			{
				keyword = "";
			}
			IEnumerable<PluginDisplayInfo> source = _allPluginDisplayInfos.AsEnumerable();
			if (!string.IsNullOrWhiteSpace(keyword))
			{
				source = source.Where((PluginDisplayInfo p) => p.Name.ToLower().Contains(keyword) || p.Author.ToLower().Contains(keyword) || p.PluginId.ToLower().Contains(keyword));
			}
			if (selectedCategory != "全部类别")
			{
				source = source.Where((PluginDisplayInfo p) => p.Category.Contains(selectedCategory));
			}
			_pluginsDataGrid.ItemsSource = source.ToList();
		}

		private async void CheckUpdatesButton_Click(object sender, RoutedEventArgs e)
		{
			if (_checkUpdatesButton != null)
			{
				_checkUpdatesButton.IsEnabled = false;
			}
			try
			{
				List<Plugin> list = await new PluginMarketService((LoggingService)null).CheckForUpdatesAsync(default(CancellationToken));
				if (list.Count > 0)
				{
					System.Windows.MessageBox.Show($"发现 {list.Count} 个插件有可用更新！\n\n请前往插件市场查看详情。", "检查更新", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
				else
				{
					System.Windows.MessageBox.Show("所有插件都是最新版本。", "检查更新", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("检查更新失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			finally
			{
				if (_checkUpdatesButton != null)
				{
					_checkUpdatesButton.IsEnabled = true;
				}
			}
		}

		private object GetControlValue(FrameworkElement element)
		{
			if (element is System.Windows.Controls.TextBox textBox)
			{
				return textBox.Text;
			}
			if (element is System.Windows.Controls.CheckBox { IsChecked: var isChecked })
			{
				return isChecked == true;
			}
			if (element is System.Windows.Controls.ComboBox { SelectedItem: var selectedItem })
			{
				return selectedItem?.ToString() ?? "";
			}
			if (element is PasswordBox passwordBox)
			{
				return passwordBox.Password;
			}
			if (element is StackPanel stackPanel && stackPanel.Children.Count > 0 && stackPanel.Children[0] is System.Windows.Controls.TextBox textBox2)
			{
				return textBox2.Text;
			}
			return null;
		}

		private void HighlightErrorControl(FrameworkElement element)
		{
			if (element is System.Windows.Controls.TextBox textBox)
			{
				textBox.BorderBrush = System.Windows.Media.Brushes.Red;
			}
			else if (element is System.Windows.Controls.ComboBox comboBox)
			{
				comboBox.BorderBrush = System.Windows.Media.Brushes.Red;
			}
		}

		private void ViewPluginLog(IVulnerabilityScannerPlugin plugin)
		{
			Window logWindow = new Window
			{
