		private async void PluginMarketWindow_Loaded(object sender, RoutedEventArgs e)
		{
			await LoadPluginsAsync();
		}

		private async Task LoadPluginsAsync()
		{
			try
			{
				LoadingGrid.Visibility = Visibility.Visible;
				PluginSearchCriteria val = new PluginSearchCriteria
				{
					Page = 1,
					PageSize = 50
				};
				_allPlugins = (await _pluginMarketService.GetPluginsAsync(val, default(CancellationToken))).Plugins;
				PluginsItemsControl.ItemsSource = _allPlugins;
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("加载插件列表失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			finally
			{
				LoadingGrid.Visibility = Visibility.Collapsed;
			}
		}

		private void SearchTextBox_TextChanged(object sender, TextChangedEventArgs e)
		{
			FilterPlugins();
		}

		private void CategoryFilterComboBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			FilterPlugins();
		}

		private void SortComboBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			SortPlugins();
		}

		private void FilterPlugins()
		{
			//IL_007b: Unknown result type (might be due to invalid IL or missing references)
			if (_allPlugins == null)
			{
				return;
			}
			string keyword = SearchTextBox.Text?.ToLower() ?? "";
			int selectedIndex = CategoryFilterComboBox.SelectedIndex;
			IEnumerable<Plugin> source = _allPlugins.AsEnumerable();
			if (!string.IsNullOrWhiteSpace(keyword))
			{
				source = source.Where((Plugin p) => p.Name.ToLower().Contains(keyword) || p.Description.ToLower().Contains(keyword));
			}
			if (selectedIndex > 0)
			{
				PluginCategory category = (PluginCategory)(selectedIndex - 1);
				source = source.Where((Plugin p) => p.Category == category);
			}
			PluginsItemsControl.ItemsSource = source.ToList();
		}

		private void SortPlugins()
		{
			if (_allPlugins != null)
			{
				int selectedIndex = SortComboBox.SelectedIndex;
				List<Plugin> source = (PluginsItemsControl.ItemsSource as List<Plugin>) ?? _allPlugins;
				IEnumerable<Plugin> source2 = selectedIndex switch
				{
					0 => source.OrderByDescending((Plugin p) => p.DownloadCount), 
					1 => source.OrderByDescending((Plugin p) => p.PublishDate), 
					2 => source.OrderByDescending((Plugin p) => p.LastUpdateDate), 
					3 => source.OrderByDescending((Plugin p) => p.Rating), 
					_ => source.OrderByDescending((Plugin p) => p.DownloadCount), 
				};
				PluginsItemsControl.ItemsSource = source2.ToList();
			}
		}

		private async void InstallPluginButton_Click(object sender, RoutedEventArgs e)
		{
			System.Windows.Controls.Button button = sender as System.Windows.Controls.Button;
			object obj = button?.Tag;
			Plugin plugin = (Plugin)((obj is Plugin) ? obj : null);
			if (plugin == null || System.Windows.MessageBox.Show($"确定要安装插件 \"{plugin.Name}\" 吗？\n\n版本: {plugin.Version}\n作者: {plugin.Author}\n大小: {FormatFileSize(plugin.Size)}", "确认安装", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes)
			{
				return;
			}
			try
			{
				button.IsEnabled = false;
				button.Content = "安装中...";
				Progress<double> progress = new Progress<double>(delegate(double value)
				{
					((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
					{
						button.Content = $"{value:F0}%";
					});
				});
				_cancellationTokenSource = new CancellationTokenSource();
				if (await _pluginMarketService.InstallPluginAsync(plugin, (IProgress<double>)progress, _cancellationTokenSource.Token))
				{
					System.Windows.MessageBox.Show("插件 \"" + plugin.Name + "\" 安装成功！", "安装成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					button.Content = "已安装";
					button.Background = System.Windows.Media.Brushes.Gray;
				}
				else
				{
					System.Windows.MessageBox.Show("插件 \"" + plugin.Name + "\" 安装失败。", "安装失败", MessageBoxButton.OK, MessageBoxImage.Hand);
					button.Content = "安装";
					button.IsEnabled = true;
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("安装插件时出错: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				button.Content = "安装";
				button.IsEnabled = true;
			}
		}

