		private void TryRunPluginButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				if (!(sender is System.Windows.Controls.Button button))
				{
					return;
				}
				object tag = button.Tag;
				Plugin val = (Plugin)((tag is Plugin) ? tag : null);
				if (val == null)
				{
					return;
				}
				List<VulnerabilityResult> list = PluginOrchestrator.Instance.TryRunAsync(val);
				if (list == null || list.Count == 0)
				{
					System.Windows.MessageBox.Show("插件 \"" + val.Name + "\" 的试运行未产生模拟结果。\n\n（属于正常情况 - 部分插件可能不需要报告漏洞，例如合规评分类。）", "试运行完成", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				StringBuilder stringBuilder = new StringBuilder();
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder3 = stringBuilder2;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(18, 2, stringBuilder2);
				handler.AppendLiteral("插件 \"");
				handler.AppendFormatted(val.Name);
				handler.AppendLiteral("\" 的模拟运行结果（");
				handler.AppendFormatted(list.Count);
				handler.AppendLiteral(" 条）：");
				stringBuilder3.AppendLine(ref handler);
				stringBuilder.AppendLine();
				for (int i = 0; i < list.Count; i++)
				{
					VulnerabilityResult val2 = list[i];
					stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder4 = stringBuilder2;
					handler = new StringBuilder.AppendInterpolatedStringHandler(7, 3, stringBuilder2);
					handler.AppendLiteral("  ");
					handler.AppendFormatted(i + 1);
					handler.AppendLiteral(". [");
					handler.AppendFormatted(val2.RiskLevel);
					handler.AppendLiteral("] ");
					handler.AppendFormatted(val2.Name);
					stringBuilder4.AppendLine(ref handler);
					stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder5 = stringBuilder2;
					handler = new StringBuilder.AppendInterpolatedStringHandler(17, 2, stringBuilder2);
					handler.AppendLiteral("     端口: ");
					handler.AppendFormatted(val2.Port);
					handler.AppendLiteral("    服务: ");
					handler.AppendFormatted(val2.Service);
					stringBuilder5.AppendLine(ref handler);
					stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder6 = stringBuilder2;
					handler = new StringBuilder.AppendInterpolatedStringHandler(5, 1, stringBuilder2);
					handler.AppendLiteral("     ");
					handler.AppendFormatted(val2.Description);
					stringBuilder6.AppendLine(ref handler);
					stringBuilder.AppendLine();
				}
				stringBuilder.AppendLine("⚠ 这只是模拟演示，未真正调用网络。");
				stringBuilder.AppendLine("   如需真实扫描请先点击\"安装\"。");
				System.Windows.MessageBox.Show(stringBuilder.ToString(), "▶ 试运行 - " + val.Name, MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("试运行失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async void CheckUpdatesButton_Click(object sender, RoutedEventArgs e)
		{
			_ = 1;
			try
			{
				LoadingGrid.Visibility = Visibility.Visible;
				LoadingTextBlock.Text = "正在检查更新...";
				List<Plugin> list = await _pluginMarketService.CheckForUpdatesAsync(default(CancellationToken));
				if (list.Count > 0)
				{
					System.Windows.MessageBox.Show($"发现 {list.Count} 个插件有可用更新。", "检查更新", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
				else
				{
					System.Windows.MessageBox.Show("所有插件都是最新版本。", "检查更新", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
				await LoadPluginsAsync();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("检查更新失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			finally
			{
				LoadingGrid.Visibility = Visibility.Collapsed;
				LoadingTextBlock.Text = "加载中...";
			}
		}

		private void MyPluginsButton_Click(object sender, RoutedEventArgs e)
		{
			List<Plugin> installedPlugins = _pluginMarketService.GetInstalledPlugins();
			if (installedPlugins.Count == 0)
			{
				System.Windows.MessageBox.Show("您还没有安装任何插件。", "我的插件", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			string value = string.Join("\n", installedPlugins.Select((Plugin p) => "• " + p.Name + " v" + p.Version));
			System.Windows.MessageBox.Show($"已安装的插件 ({installedPlugins.Count}):\n\n{value}", "我的插件", MessageBoxButton.OK, MessageBoxImage.Asterisk);
		}

		private string GetCategoryName(PluginCategory category)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Expected I4, but got Unknown
			return (int)category switch
			{
				0 => "漏洞检测", 
				1 => "端口扫描", 
				2 => "报告生成", 
				3 => "数据分析", 
				4 => "界面扩展", 
				5 => "集成工具", 
				6 => "其他", 
				_ => "未知", 
			};
		}

		private string FormatFileSize(long bytes)
		{
			string[] array = new string[4] { "B", "KB", "MB", "GB" };
			int num = 0;
			double num2 = bytes;
			while (num2 >= 1024.0 && num < array.Length - 1)
			{
				num++;
				num2 /= 1024.0;
			}
			return $"{num2:F1} {array[num]}";
		}

