		private void LoadPluginsToCheckBox()
		{
			_pluginCheckBoxes.Clear();
			_loadedPlugins.Clear();
			IReadOnlyDictionary<string, IVulnerabilityScannerPlugin> loadedPlugins = _orchestrator.LoadedPlugins;
			if (loadedPlugins != null)
			{
				foreach (KeyValuePair<string, IVulnerabilityScannerPlugin> item2 in loadedPlugins)
				{
					if (item2.Value != null)
					{
						_loadedPlugins.Add(item2.Value);
					}
				}
			}
			if (_loadedPlugins.Count == 0)
			{
				_pluginListControl.ItemsSource = new List<System.Windows.Controls.CheckBox>
				{
					new System.Windows.Controls.CheckBox
					{
						Content = "（暂无可用插件，请先在【插件管理】中加载插件）",
						IsEnabled = false,
						Margin = new Thickness(4.0)
					}
				};
				return;
			}
			List<System.Windows.Controls.CheckBox> list = new List<System.Windows.Controls.CheckBox>();
			foreach (IVulnerabilityScannerPlugin loadedPlugin in _loadedPlugins)
			{
				string text = "通用";
				if (loadedPlugin.SupportedScanTypes != null && loadedPlugin.SupportedScanTypes.Count > 0)
				{
					text = string.Join(" / ", loadedPlugin.SupportedScanTypes);
				}
				else if (!string.IsNullOrWhiteSpace(loadedPlugin.Description))
				{
					text = ((loadedPlugin.Description.Length > 30) ? (loadedPlugin.Description.Substring(0, 30) + "...") : loadedPlugin.Description);
				}
				System.Windows.Controls.CheckBox item = new System.Windows.Controls.CheckBox
				{
					Content = loadedPlugin.Name + "   |   " + text,
					IsChecked = true,
					Margin = new Thickness(4.0, 4.0, 4.0, 4.0),
					Tag = loadedPlugin,
					ToolTip = $"ID: {loadedPlugin.PluginId}\n版本: {loadedPlugin.Version}\n作者: {loadedPlugin.Author}\n适用: {text}"
				};
				_pluginCheckBoxes.Add(item);
				list.Add(item);
			}
			_pluginListControl.ItemsSource = list;
		}

		private void SetAllCheckBoxes(bool isChecked)
		{
			foreach (System.Windows.Controls.CheckBox pluginCheckBox in _pluginCheckBoxes)
			{
				pluginCheckBox.IsChecked = isChecked;
			}
		}

		private void UpdatePortPreview()
		{
			if (_portPreviewText != null)
			{
				List<int> list = ParsePortsInput(_portsTextBox?.Text ?? string.Empty);
				if (list.Count == 0)
				{
					_portPreviewText.Text = "⚠ 当前未解析到有效端口（支持 80,443,554 或 1-1024）";
					_portPreviewText.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#E67E22"));
					return;
				}
				if (list.Count > 2048)
				{
					_portPreviewText.Text = $"已解析 {list.Count} 个端口（较多，扫描会变慢）";
					_portPreviewText.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#E67E22"));
					return;
				}
				string value = ((list.Count > 12) ? (string.Join(",", list.Take(12)) + $" ...（共 {list.Count} 个）") : string.Join(",", list));
				_portPreviewText.Text = $"✓ 将扫描 {list.Count} 个端口：{value}";
				_portPreviewText.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#27AE60"));
			}
		}

		public static List<int> ParsePortsInput(string text)
		{
			List<int> list = new List<int>();
			if (string.IsNullOrWhiteSpace(text))
			{
				return list;
			}
			try
			{
				string[] array = text.Replace(';', ',').Replace('|', ',').Replace(' ', ',')
					.Replace('\n', ',')
					.Replace('\r', ',')
					.Replace('\t', ',')
					.Split(new char[1] { ',' }, StringSplitOptions.RemoveEmptyEntries);
				HashSet<int> hashSet = new HashSet<int>();
				string[] array2 = array;
				for (int i = 0; i < array2.Length; i++)
				{
					string text2 = array2[i].Trim();
					if (string.IsNullOrEmpty(text2))
					{
						continue;
					}
					int result3;
					if (text2.Contains('-'))
					{
						string[] array3 = text2.Split(new char[1] { '-' }, 2, StringSplitOptions.RemoveEmptyEntries);
						if (array3.Length != 2 || !int.TryParse(array3[0].Trim(), out var result) || !int.TryParse(array3[1].Trim(), out var result2))
						{
							continue;
						}
						if (result > result2)
						{
							int num = result2;
							int num2 = result;
							result = num;
							result2 = num2;
						}
						if (result < 1)
						{
							result = 1;
						}
						if (result2 > 65535)
						{
							result2 = 65535;
						}
						if (result2 - result + 1 > 65536)
						{
							result2 = result + 65535;
						}
						for (int j = result; j <= result2; j++)
						{
							if (hashSet.Add(j))
							{
								list.Add(j);
							}
						}
					}
					else if (int.TryParse(text2, out result3) && result3 >= 1 && result3 <= 65535 && hashSet.Add(result3))
					{
						list.Add(result3);
					}
				}
				list.Sort();
				return list;
			}
			catch
			{
				return new List<int>();
			}
		}

