		private async void ExecuteButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				string text = _ipTextBox?.Text?.Trim() ?? string.Empty;
				if (string.IsNullOrEmpty(text))
				{
					System.Windows.MessageBox.Show("请输入目标 IP", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				List<int> list = ParsePortsInput(_portsTextBox?.Text ?? string.Empty);
				if (list.Count == 0)
				{
					System.Windows.MessageBox.Show("请输入至少一个有效端口（例如 80,443,554 或 1-1024）", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				List<string> list2 = new List<string>();
				foreach (System.Windows.Controls.CheckBox pluginCheckBox in _pluginCheckBoxes)
				{
					if (pluginCheckBox.IsChecked == true)
					{
						object tag = pluginCheckBox.Tag;
						IVulnerabilityScannerPlugin val = (IVulnerabilityScannerPlugin)((tag is IVulnerabilityScannerPlugin) ? tag : null);
						if (val != null)
						{
							list2.Add(val.PluginId);
						}
					}
				}
				if (list2.Count == 0 && _loadedPlugins.Count > 0)
				{
					System.Windows.MessageBox.Show("请至少选择一个插件", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				SetExecutingState(executing: true);
				_progressBar.Value = 10.0;
				UpdateStatus($"开始扫描 {text}（{list.Count} 个端口）...", "#3498DB");
				_cts?.Dispose();
				_cts = new CancellationTokenSource();
				CancellationToken token = _cts.Token;
				Stopwatch sw = Stopwatch.StartNew();
				List<VulnerabilityResult> list3;
				try
				{
					new Progress<(int, int, string)>(delegate((int current, int total, string ipLabel) p)
					{
						if (p.total > 0)
						{
							double num = (double)p.current / (double)Math.Max(1, p.total);
							_progressBar.Value = Math.Min(99.0, 10.0 + num * 85.0);
							UpdateStatus($"扫描中 ({p.current}/{p.total}) {p.ipLabel}", "#3498DB");
						}
					});
					list3 = await _orchestrator.ScanTargetAsync(text, list, (IEnumerable<string>)list2, token, (string)null).ConfigureAwait(continueOnCapturedContext: true);
				}
				catch (OperationCanceledException)
				{
					UpdateStatus("⚠ 用户已取消扫描", "#E67E22");
					System.Windows.MessageBox.Show("扫描已取消", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				catch (Exception ex2)
				{
					UpdateStatus("❌ 扫描异常: " + ex2.Message, "#E74C3C");
					System.Windows.MessageBox.Show("扫描异常: " + ex2.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
					return;
				}
				finally
				{
					sw.Stop();
				}
				_progressBar.Value = 100.0;
				UpdateStatus($"✓ 扫描完成 | 耗时 {sw.ElapsedMilliseconds} ms | 发现 {list3?.Count ?? 0} 个漏洞", "#27AE60");
				System.Windows.MessageBox.Show($"扫描完成，共发现 {list3?.Count ?? 0} 个漏洞。\n\n耗时：{sw.ElapsedMilliseconds} ms", "扫描结果", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
			catch (Exception ex3)
			{
				System.Windows.MessageBox.Show("执行扫描失败: " + ex3.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			finally
			{
				SetExecutingState(executing: false);
			}
		}

		private void CancelButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				if (_cts != null && !_cts.IsCancellationRequested)
				{
					_cts.Cancel();
					UpdateStatus("正在取消...", "#E67E22");
					_cancelButton.IsEnabled = false;
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("取消失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

