		{
			if (_executeButton != null)
			{
				_executeButton.IsEnabled = !executing;
			}
			if (_cancelButton != null)
			{
				_cancelButton.IsEnabled = executing;
			}
			if (_closeButton != null)
			{
				_closeButton.IsEnabled = !executing;
			}
			if (_ipTextBox != null)
			{
				_ipTextBox.IsEnabled = !executing;
			}
			if (_portsTextBox != null)
			{
				_portsTextBox.IsEnabled = !executing;
			}
			if (_pluginListControl != null)
			{
				_pluginListControl.IsEnabled = !executing;
			}
			foreach (System.Windows.Controls.CheckBox pluginCheckBox in _pluginCheckBoxes)
			{
				pluginCheckBox.IsEnabled = !executing;
			}
			_progressBar.IsIndeterminate = executing;
		}

