		private async void UsernameTextBox_TextChanged(object sender, TextChangedEventArgs e)
		{
			string username = UsernameTextBox.Text?.Trim() ?? "";
			if (string.IsNullOrEmpty(username))
			{
				UsernameStatusText.Text = "";
				UsernameErrorText.Text = "";
				_usernameAvailable = false;
				UpdateRegisterButton();
				return;
			}
			if (!AuthService.IsValidUsername(username))
			{
				UsernameStatusText.Text = "❌ 格式错";
				UsernameStatusText.Foreground = System.Windows.Media.Brushes.Red;
				UsernameErrorText.Text = "• 用户名必须为 3-32 位字母/数字/下划线";
				_usernameAvailable = false;
				UpdateRegisterButton();
				return;
			}
			try
			{
				bool flag = await Task.Run(() => _authService.IsUsernameAvailable(username));
				if (username != UsernameTextBox.Text?.Trim())
				{
					return;
				}
				if (flag)
				{
					UsernameStatusText.Text = "✅ 可用";
					UsernameStatusText.Foreground = System.Windows.Media.Brushes.Green;
					UsernameErrorText.Text = "";
					_usernameAvailable = true;
				}
				else
				{
					UsernameStatusText.Text = "❌ 已占用";
					UsernameStatusText.Foreground = System.Windows.Media.Brushes.Red;
					UsernameErrorText.Text = "• 该用户名已被占用";
					_usernameAvailable = false;
				}
			}
			catch
