		private void GeneratePasswordButton_Click(object sender, RoutedEventArgs e)
		{
			string text = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%^&*";
			Random random = new Random();
			StringBuilder stringBuilder = new StringBuilder(12);
			stringBuilder.Append("ABCDEFGHJKLMNPQRSTUVWXYZ"[random.Next("ABCDEFGHJKLMNPQRSTUVWXYZ".Length)]);
			stringBuilder.Append("abcdefghijkmnopqrstuvwxyz"[random.Next("abcdefghijkmnopqrstuvwxyz".Length)]);
			stringBuilder.Append("23456789"[random.Next("23456789".Length)]);
			stringBuilder.Append("!@#$%^&*"[random.Next("!@#$%^&*".Length)]);
			for (int i = 4; i < 12; i++)
			{
				stringBuilder.Append(text[random.Next(text.Length)]);
			}
			char[] array = stringBuilder.ToString().ToCharArray();
			for (int num = array.Length - 1; num > 0; num--)
			{
				int num2 = random.Next(num + 1);
				ref char reference = ref array[num];
				ref char reference2 = ref array[num2];
				char c = array[num2];
				char c2 = array[num];
				reference = c;
				reference2 = c2;
			}
			string password = new string(array);
			PasswordBox.Password = password;
			ConfirmPasswordBox.Password = password;
			PasswordErrorText.Text = "\ud83c\udfb2 已生成强密码，请记牢后提交";
			PasswordErrorText.Foreground = System.Windows.Media.Brushes.Green;
		}

		private void PasswordBox_PasswordChanged(object sender, RoutedEventArgs e)
		{
			string text = PasswordBox.Password ?? "";
			int num = AuthService.CalcPasswordStrength(text);
			PasswordStrengthBar.Value = num;
			switch (AuthService.CalcPasswordStrengthLevel(text))
			{
			case 0:
				PasswordStrengthText.Text = "弱";
				PasswordStrengthText.Foreground = System.Windows.Media.Brushes.Red;
				PasswordStrengthBar.Foreground = System.Windows.Media.Brushes.Red;
				break;
			case 1:
				PasswordStrengthText.Text = "中";
				PasswordStrengthText.Foreground = System.Windows.Media.Brushes.Orange;
				PasswordStrengthBar.Foreground = System.Windows.Media.Brushes.Orange;
				break;
			case 2:
				PasswordStrengthText.Text = "强";
				PasswordStrengthText.Foreground = System.Windows.Media.Brushes.Green;
				PasswordStrengthBar.Foreground = System.Windows.Media.Brushes.Green;
				break;
			}
			if (string.IsNullOrEmpty(text))
			{
				PasswordErrorText.Text = "";
			}
			else if (text.Length < 6)
			{
				PasswordErrorText.Text = $"• 至少 6 位（当前 {text.Length}）";
			}
			else
			{
				PasswordErrorText.Text = "";
			}
			ValidateConfirmPassword();
			UpdateRegisterButton();
		}

		private void ConfirmPasswordBox_PasswordChanged(object sender, RoutedEventArgs e)
		{
			ValidateConfirmPassword();
			UpdateRegisterButton();
		}

		private void ValidateConfirmPassword()
		{
			string a = PasswordBox.Password ?? "";
			string text = ConfirmPasswordBox.Password ?? "";
			if (string.IsNullOrEmpty(text))
			{
				ConfirmPasswordErrorText.Text = "";
			}
			else if (!string.Equals(a, text))
			{
				ConfirmPasswordErrorText.Text = "• 两次密码不一致";
			}
			else
			{
				ConfirmPasswordErrorText.Text = "";
			}
		}

		private void UpdateRegisterButton()
		{
			string obj = UsernameTextBox.Text?.Trim() ?? "";
			string text = EmailTextBox.Text?.Trim() ?? "";
			string text2 = PhoneTextBox.Text?.Trim() ?? "";
			string text3 = PasswordBox.Password ?? "";
			string b = ConfirmPasswordBox.Password ?? "";
			bool isEnabled = AuthService.IsValidUsername(obj) && AuthService.IsValidEmail(text) && AuthService.IsValidPhone(text2) && text3.Length >= 6 && string.Equals(text3, b) && (ReasonTextBox.Text?.Length ?? 0) <= 200;
			RegisterButton.IsEnabled = isEnabled;
		}

		private async void RegisterButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				string text = System.IO.Path.Combine(DataPaths.DataRoot, "logs");
				Directory.CreateDirectory(text);
				File.AppendAllText(System.IO.Path.Combine(text, "auth_diag.log"), $"[{DateTime.Now:HH:mm:ss.fff}] RegisterButton_Click: Triggered IsEnabled={RegisterButton.IsEnabled} Username='{UsernameTextBox.Text?.Trim() ?? ""}'\n");
			}
			catch
			{
			}
			string username = UsernameTextBox.Text?.Trim() ?? "";
			string text2 = DisplayNameTextBox.Text?.Trim() ?? "";
			string text3 = EmailTextBox.Text?.Trim() ?? "";
			string text4 = PhoneTextBox.Text?.Trim() ?? "";
			string text5 = ReasonTextBox.Text?.Trim() ?? "";
			string text6 = PasswordBox.Password ?? "";
			if (!_usernameAvailable)
			{
				System.Windows.MessageBox.Show("用户名不可用，请换一个。", "注册失败", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				UsernameTextBox.Focus();
				return;
			}
			if (!_emailAvailable || !_phoneAvailable)
			{
				System.Windows.MessageBox.Show("邮箱或手机号不可用，请检查。", "注册失败", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			RegisterButton.IsEnabled = false;
			try
			{
				RegisterResult val = await _authService.RegisterAsync(username, text6, string.IsNullOrEmpty(text2) ? null : text2, string.IsNullOrEmpty(text3) ? null : text3, string.IsNullOrEmpty(text4) ? null : text4, string.IsNullOrEmpty(text5) ? null : text5);
				if (val.Success)
				{
					User current = SessionContext.Instance.Current;
					bool flag = current != null && current.IsAdmin;
					MessageBoxResult messageBoxResult = System.Windows.MessageBox.Show("注册成功！\n\n账号 [" + username + "] 已创建，状态为「待审核」。\n请等待管理员审核通过后再登录。" + (flag ? "\n\n\ud83d\udc49 点击「是」立即打开「用户审核」窗口查看" : ""), "注册成功", flag ? MessageBoxButton.YesNo : MessageBoxButton.OK, MessageBoxImage.Asterisk);
					if (flag && messageBoxResult == MessageBoxResult.Yes)
					{
						try
						{
							Window window = Window.GetWindow((DependencyObject)(object)this);
							UserApprovalWindow userApprovalWindow = new UserApprovalWindow();
							userApprovalWindow.Owner = window;
							userApprovalWindow.ShowDialog();
						}
						catch (Exception ex)
						{
							System.Windows.MessageBox.Show("打开用户审核窗口失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
						}
					}
					base.DialogResult = true;
					Close();
				}
				else
				{
					System.Windows.MessageBox.Show(val.Message, "注册失败", MessageBoxButton.OK, MessageBoxImage.Exclamation);
					if ((int)val.ErrorCode == 5)
					{
						UsernameTextBox.Focus();
					}
					else if ((int)val.ErrorCode == 6)
					{
						EmailTextBox.Focus();
					}
					else if ((int)val.ErrorCode == 7)
					{
						PhoneTextBox.Focus();
					}
					else if ((int)val.ErrorCode == 2)
					{
						PasswordBox.Focus();
					}
					RegisterButton.IsEnabled = true;
					UpdateRegisterButton();
				}
			}
			catch (Exception ex2)
			{
				System.Windows.MessageBox.Show("注册失败：" + ex2.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				RegisterButton.IsEnabled = true;
			}
		}

