	public class RemediationWizardWindow : Window, IComponentConnector
	{
		private readonly VulnerabilityRemediationService _remediationService;

		private RemediationPlan _remediationPlan;

		private RemediationPlanItem _currentItem;

		private List<VulnerabilityResult> _vulnerabilities;

		internal TextBlock TotalVulnerabilitiesTextBlock;

		internal TextBlock EstimatedTimeTextBlock;

		internal TextBlock CompletedCountTextBlock;

		internal TextBlock ProgressTextBlock;

		internal StackPanel VulnerabilityListPanel;

		internal TextBlock CurrentVulnTitleTextBlock;

		internal TextBlock CurrentVulnDescriptionTextBlock;

		internal TextBlock CurrentVulnRiskTextBlock;

		internal TextBlock CurrentVulnPortTextBlock;

		internal TextBlock CurrentVulnServiceTextBlock;

		internal StackPanel RemediationStepsPanel;

		internal System.Windows.Controls.Button CopyCommandButton;

		internal System.Windows.Controls.Button MarkCompletedButton;

		internal System.Windows.Controls.Button SkipButton;

		internal System.Windows.Controls.Button GenerateReportButton;

		internal System.Windows.Controls.Button CloseWizardButton;

		private bool _contentLoaded;

		public RemediationWizardWindow(List<VulnerabilityResult> vulnerabilities)
		{
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0017: Expected O, but got Unknown
			InitializeComponent();
			_remediationService = new VulnerabilityRemediationService();
			_vulnerabilities = vulnerabilities ?? new List<VulnerabilityResult>();
			base.Loaded += RemediationWizardWindow_Loaded;
		}

		private void RemediationWizardWindow_Loaded(object sender, RoutedEventArgs e)
		{
			GenerateRemediationPlan();
		}

		private void GenerateRemediationPlan()
		{
			if (!_vulnerabilities.Any())
			{
				System.Windows.MessageBox.Show("没有需要修复的漏洞", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			_remediationPlan = _remediationService.GenerateRemediationPlan(_vulnerabilities);
			UpdatePlanOverview();
			RenderVulnerabilityList();
		}

		private void UpdatePlanOverview()
		{
			if (_remediationPlan != null)
			{
				TotalVulnerabilitiesTextBlock.Text = _remediationPlan.TotalVulnerabilities.ToString();
				EstimatedTimeTextBlock.Text = $"{_remediationPlan.EstimatedTotalTime.TotalMinutes:F0}分钟";
				int num = _remediationPlan.Items.Count((RemediationPlanItem i) => i.Status == "Completed");
				CompletedCountTextBlock.Text = num.ToString();
				double value = ((_remediationPlan.TotalVulnerabilities > 0) ? ((double)num / (double)_remediationPlan.TotalVulnerabilities * 100.0) : 0.0);
				ProgressTextBlock.Text = $"{value:F0}%";
			}
		}

		private void RenderVulnerabilityList()
		{
			VulnerabilityListPanel.Children.Clear();
			foreach (RemediationPlanItem item in _remediationPlan.Items)
			{
				Border border = new Border
				{
					BorderBrush = GetRiskColor(item.Vulnerability.RiskLevel),
					BorderThickness = new Thickness(2.0),
					CornerRadius = new CornerRadius(4.0),
					Padding = new Thickness(10.0),
					Margin = new Thickness(0.0, 0.0, 0.0, 5.0),
					Background = ((item.Status == "Completed") ? System.Windows.Media.Brushes.LightGreen : ((item.Status == "Skipped") ? System.Windows.Media.Brushes.LightYellow : System.Windows.Media.Brushes.White)),
					Cursor = System.Windows.Input.Cursors.Hand,
					Tag = item
				};
				border.MouseLeftButtonUp += VulnerabilityItem_Click;
				StackPanel stackPanel = new StackPanel();
				StackPanel stackPanel2 = new StackPanel
				{
					Orientation = System.Windows.Controls.Orientation.Horizontal
				};
				stackPanel2.Children.Add(new TextBlock
				{
					Text = $"#{item.Priority}",
					FontWeight = FontWeights.Bold,
					Margin = new Thickness(0.0, 0.0, 10.0, 0.0),
					Foreground = System.Windows.Media.Brushes.Gray
				});
				stackPanel2.Children.Add(new TextBlock
				{
					Text = item.Vulnerability.RiskLevel,
					FontWeight = FontWeights.Bold,
					Foreground = GetRiskColor(item.Vulnerability.RiskLevel)
				});
				if (item.Status == "Completed")
				{
					stackPanel2.Children.Add(new TextBlock
					{
						Text = " ✓",
						FontWeight = FontWeights.Bold,
						Foreground = System.Windows.Media.Brushes.Green,
						Margin = new Thickness(10.0, 0.0, 0.0, 0.0)
					});
				}
				stackPanel.Children.Add(stackPanel2);
				stackPanel.Children.Add(new TextBlock
				{
					Text = item.Vulnerability.Name,
					FontWeight = FontWeights.SemiBold,
					TextTrimming = TextTrimming.CharacterEllipsis,
					Margin = new Thickness(0.0, 5.0, 0.0, 0.0)
				});
				stackPanel.Children.Add(new TextBlock
				{
					Text = $"端口 {item.Vulnerability.Port} | {item.Vulnerability.Service}",
					FontSize = 11.0,
					Foreground = System.Windows.Media.Brushes.Gray,
					Margin = new Thickness(0.0, 2.0, 0.0, 0.0)
				});
				stackPanel.Children.Add(new TextBlock
				{
					Text = $"预计: {item.EstimatedTime.TotalMinutes:F0}分钟",
					FontSize = 11.0,
					Foreground = System.Windows.Media.Brushes.Blue,
					Margin = new Thickness(0.0, 2.0, 0.0, 0.0)
				});
				border.Child = stackPanel;
				VulnerabilityListPanel.Children.Add(border);
			}
		}

		private void VulnerabilityItem_Click(object sender, MouseButtonEventArgs e)
		{
			if (sender is Border border)
			{
				object tag = border.Tag;
				RemediationPlanItem val = (RemediationPlanItem)((tag is RemediationPlanItem) ? tag : null);
				if (val != null)
				{
					_currentItem = val;
					DisplayRemediationGuide(val);
				}
			}
		}

		private void DisplayRemediationGuide(RemediationPlanItem item)
		{
			CurrentVulnTitleTextBlock.Text = item.RemediationGuide.Title;
			CurrentVulnDescriptionTextBlock.Text = item.RemediationGuide.Description;
			CurrentVulnRiskTextBlock.Text = "风险等级: " + item.Vulnerability.RiskLevel;
			CurrentVulnRiskTextBlock.Foreground = GetRiskColor(item.Vulnerability.RiskLevel);
			CurrentVulnPortTextBlock.Text = $"端口: {item.Vulnerability.Port}";
			CurrentVulnServiceTextBlock.Text = "服务: " + item.Vulnerability.Service;
			RemediationStepsPanel.Children.Clear();
			foreach (RemediationStep step in item.RemediationGuide.Steps)
			{
				Border border = new Border
				{
					Background = (step.IsCompleted ? System.Windows.Media.Brushes.LightGreen : System.Windows.Media.Brushes.White),
					BorderBrush = System.Windows.Media.Brushes.LightGray,
					BorderThickness = new Thickness(1.0),
					CornerRadius = new CornerRadius(4.0),
					Padding = new Thickness(15.0),
					Margin = new Thickness(0.0, 0.0, 0.0, 10.0)
				};
				StackPanel stackPanel = new StackPanel();
				StackPanel stackPanel2 = new StackPanel
				{
					Orientation = System.Windows.Controls.Orientation.Horizontal
				};
				stackPanel2.Children.Add(new TextBlock
				{
					Text = $"步骤 {step.StepNumber}: ",
					FontWeight = FontWeights.Bold,
					FontSize = 14.0
				});
				stackPanel2.Children.Add(new TextBlock
				{
					Text = step.Title,
					FontWeight = FontWeights.Bold,
					FontSize = 14.0
				});
				if (step.IsAutomated)
				{
					stackPanel2.Children.Add(new TextBlock
					{
						Text = " [可自动执行]",
						Foreground = System.Windows.Media.Brushes.Green,
						FontSize = 12.0,
						Margin = new Thickness(5.0, 0.0, 0.0, 0.0)
					});
				}
				stackPanel.Children.Add(stackPanel2);
				stackPanel.Children.Add(new TextBlock
				{
					Text = step.Description,
					TextWrapping = TextWrapping.Wrap,
					Margin = new Thickness(0.0, 5.0, 0.0, 0.0)
				});
				if (!string.IsNullOrEmpty(step.Command))
				{
					Border border2 = new Border
					{
						Background = System.Windows.Media.Brushes.Black,
						CornerRadius = new CornerRadius(4.0),
						Padding = new Thickness(10.0),
						Margin = new Thickness(0.0, 10.0, 0.0, 0.0)
					};
					TextBlock child = new TextBlock
					{
						Text = step.Command,
						Foreground = System.Windows.Media.Brushes.LightGreen,
						FontFamily = new System.Windows.Media.FontFamily("Consolas"),
						TextWrapping = TextWrapping.Wrap
					};
					border2.Child = child;
					stackPanel.Children.Add(border2);
				}
				border.Child = stackPanel;
				RemediationStepsPanel.Children.Add(border);
			}
			if (!item.RemediationGuide.References.Any())
			{
				return;
			}
			Border border3 = new Border
			{
				Background = System.Windows.Media.Brushes.LightBlue,
				CornerRadius = new CornerRadius(4.0),
				Padding = new Thickness(10.0),
				Margin = new Thickness(0.0, 10.0, 0.0, 0.0)
			};
			StackPanel stackPanel3 = new StackPanel();
			stackPanel3.Children.Add(new TextBlock
			{
				Text = "\ud83d\udcda 参考链接:",
				FontWeight = FontWeights.Bold,
				Margin = new Thickness(0.0, 0.0, 0.0, 5.0)
			});
			foreach (string reference in item.RemediationGuide.References)
			{
				TextBlock textBlock = new TextBlock
				{
					Text = reference,
					Foreground = System.Windows.Media.Brushes.Blue,
					TextDecorations = TextDecorations.Underline,
					Cursor = System.Windows.Input.Cursors.Hand,
					Margin = new Thickness(0.0, 2.0, 0.0, 0.0)
				};
				textBlock.MouseLeftButtonUp += delegate
				{
					try
					{
						Process.Start(new ProcessStartInfo
						{
							FileName = reference,
							UseShellExecute = true
						});
					}
					catch (Exception)
					{
					}
				};
				stackPanel3.Children.Add(textBlock);
			}
			border3.Child = stackPanel3;
			RemediationStepsPanel.Children.Add(border3);
		}

		private System.Windows.Media.Brush GetRiskColor(string riskLevel)
		{
			return riskLevel switch
			{
				"严重" => System.Windows.Media.Brushes.Red, 
				"高危" => System.Windows.Media.Brushes.Orange, 
				"中危" => System.Windows.Media.Brushes.Goldenrod, 
				"低危" => System.Windows.Media.Brushes.Green, 
				_ => System.Windows.Media.Brushes.Gray, 
			};
		}

		private void CopyCommandButton_Click(object sender, RoutedEventArgs e)
		{
			if (_currentItem != null)
			{
				string text = string.Join("\n\n", from s in _currentItem.RemediationGuide.Steps
					where !string.IsNullOrEmpty(s.Command)
					select "# " + s.Title + "\n" + s.Command);
				if (!string.IsNullOrEmpty(text))
				{
					System.Windows.Clipboard.SetText(text);
					System.Windows.MessageBox.Show("命令已复制到剪贴板", "复制成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
		}

		private void MarkCompletedButton_Click(object sender, RoutedEventArgs e)
		{
			if (_currentItem != null)
			{
				_currentItem.Status = "Completed";
				UpdatePlanOverview();
				RenderVulnerabilityList();
				RemediationPlanItem val = ((IEnumerable<RemediationPlanItem>)_remediationPlan.Items).FirstOrDefault((Func<RemediationPlanItem, bool>)((RemediationPlanItem i) => i.Status == "Pending"));
				if (val != null)
				{
					_currentItem = val;
					DisplayRemediationGuide(val);
				}
			}
		}

		private void SkipButton_Click(object sender, RoutedEventArgs e)
		{
			if (_currentItem != null)
			{
				_currentItem.Status = "Skipped";
				UpdatePlanOverview();
				RenderVulnerabilityList();
				RemediationPlanItem val = ((IEnumerable<RemediationPlanItem>)_remediationPlan.Items).FirstOrDefault((Func<RemediationPlanItem, bool>)((RemediationPlanItem i) => i.Status == "Pending"));
				if (val != null)
				{
					_currentItem = val;
					DisplayRemediationGuide(val);
				}
			}
		}

		private async void GenerateReportButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
				{
					Filter = "文本文件|*.txt|HTML文件|*.html",
					FileName = $"漏洞修复报告_{DateTime.Now:yyyyMMdd_HHmmss}",
					Title = "保存修复报告"
				};
				if (saveFileDialog.ShowDialog() == true)
				{
					string filePath = saveFileDialog.FileName;
					string contents = ((!(System.IO.Path.GetExtension(filePath).ToLower() == ".html")) ? GenerateTextReport() : GenerateHtmlReport());
					await File.WriteAllTextAsync(filePath, contents);
					System.Windows.MessageBox.Show("修复报告已保存到:\n" + filePath, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("生成报告失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private string GenerateTextReport()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("=".PadRight(60, '='));
			stringBuilder.AppendLine("漏洞修复报告");
			stringBuilder.AppendLine("=".PadRight(60, '='));
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder3 = stringBuilder2;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(6, 1, stringBuilder2);
			handler.AppendLiteral("生成时间: ");
			handler.AppendFormatted(DateTime.Now, "yyyy-MM-dd HH:mm:ss");
			stringBuilder3.AppendLine(ref handler);
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder4 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(6, 1, stringBuilder2);
			handler.AppendLiteral("总漏洞数: ");
			handler.AppendFormatted(_remediationPlan.TotalVulnerabilities);
			stringBuilder4.AppendLine(ref handler);
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder5 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(5, 1, stringBuilder2);
			handler.AppendLiteral("已完成: ");
			handler.AppendFormatted(_remediationPlan.Items.Count((RemediationPlanItem i) => i.Status == "Completed"));
			stringBuilder5.AppendLine(ref handler);
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder6 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(5, 1, stringBuilder2);
			handler.AppendLiteral("已跳过: ");
			handler.AppendFormatted(_remediationPlan.Items.Count((RemediationPlanItem i) => i.Status == "Skipped"));
			stringBuilder6.AppendLine(ref handler);
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder7 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(5, 1, stringBuilder2);
			handler.AppendLiteral("待修复: ");
			handler.AppendFormatted(_remediationPlan.Items.Count((RemediationPlanItem i) => i.Status == "Pending"));
			stringBuilder7.AppendLine(ref handler);
			stringBuilder.AppendLine();
			foreach (RemediationPlanItem item in _remediationPlan.Items)
			{
				stringBuilder.AppendLine("-".PadRight(60, '-'));
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder8 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(6, 1, stringBuilder2);
				handler.AppendLiteral("优先级: #");
				handler.AppendFormatted(item.Priority);
				stringBuilder8.AppendLine(ref handler);
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder9 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(4, 1, stringBuilder2);
				handler.AppendLiteral("漏洞: ");
				handler.AppendFormatted(item.Vulnerability.Name);
				stringBuilder9.AppendLine(ref handler);
				stringBuilder2 = stringBuilder;
