		private void GenerateJwtButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				PluginGovernor governor = _governor;
				if (((governor != null) ? governor.RemoteApi : null) == null)
				{
					System.Windows.MessageBox.Show("PluginGovernor 尚未初始化，无法生成 JWT。", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				}
				else if (sender is System.Windows.Controls.Button { Tag: var tag } && tag is TimeSpan value)
				{
					string text = (string.IsNullOrWhiteSpace(_userTextBox.Text) ? "admin" : _userTextBox.Text.Trim());
					string text2 = (_currentJwt = _governor.RemoteApi.GenerateTempJwt(text, (TimeSpan?)value));
					_jwtOutputTextBox.Text = text2;
					_jwtOutputTextBox.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2C3E50"));
					_jwtTtlTextBlock.Text = $"TTL: {value.TotalHours:0.#}h";
					_jwtGeneratedAtTextBlock.Text = $"生成时间: {DateTime.Now:yyyy-MM-dd HH:mm:ss}    过期: {DateTime.Now.Add(value):yyyy-MM-dd HH:mm:ss}";
					_copyJwtButton.IsEnabled = true;
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("生成 JWT 失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private void CopyJwtButton_Click(object sender, RoutedEventArgs e)
		{
			//IL_00ae: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00cc: Expected O, but got Unknown
			if (string.IsNullOrEmpty(_currentJwt))
			{
				System.Windows.MessageBox.Show("请先生成 JWT。", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
