			{
				System.Windows.MessageBox.Show("复制到剪贴板失败：" + lastError?.Message + "\n\n请手动复制以下 JWT：\n" + _currentJwt, "复制失败", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
