			_copyJwtButton.Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#27AE60"));
			DispatcherTimer timer = new DispatcherTimer
			{
				Interval = TimeSpan.FromSeconds(2.0)
			};
			timer.Tick += delegate
			{
				_copyJwtButton.Content = original;
				_copyJwtButton.Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#27AE60"));
				timer.Stop();
			};
			timer.Start();
		}

