		private async Task ReloadAuditAsync()
		{
			try
			{
				PluginGovernor governor = _governor;
				if (((governor != null) ? governor.Security : null) == null)
				{
					UpdateApiStatus("Governor 未初始化", "#E74C3C");
					return;
				}
				RemoteGovernorApiService remoteApi = _governor.RemoteApi;
				if (remoteApi != null && remoteApi.IsRunning)
				{
					UpdateApiStatus("● 运行中", "#27AE60");
					_apiUrlTextBlock.Text = remoteApi.BaseUrl;
				}
				else
				{
					UpdateApiStatus("● 未启动", "#E74C3C");
					_apiUrlTextBlock.Text = SafeBaseUrl();
				}
				List<PluginAuditEntry> list = new List<PluginAuditEntry>();
				try
				{
					list.AddRange(_governor.Security.GetAuditEntries(DateTime.Today));
				}
				catch
				{
				}
				try
				{
					list.AddRange(_governor.Security.GetAuditEntries(DateTime.Today.AddDays(-1.0)));
				}
				catch
				{
				}
				List<PluginAuditEntry> list2 = (from e in list
					where !string.IsNullOrEmpty(e.Action) && e.Action.IndexOf("RemoteApi", StringComparison.OrdinalIgnoreCase) >= 0
					orderby e.Timestamp descending
					select e).Take(10).ToList();
				_auditGrid.ItemsSource = list2;
				_auditSummaryTextBlock.Text = $"（共 {list2.Count} 条）";
			}
			catch (Exception)
			{
			}
			await Task.CompletedTask;
		}

		private void UpdateApiStatus(string text, string colorHex)
		{
			_apiStatusTextBlock.Text = text;
			_apiStatusTextBlock.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(colorHex));
		}

		private string SafeBaseUrl()
		{
			try
			{
				PluginGovernor governor = _governor;
				RemoteGovernorApiService val = ((governor != null) ? governor.RemoteApi : null);
				if (val == null)
				{
					return "http://127.0.0.1:9530";
				}
				return val.BaseUrl ?? "http://127.0.0.1:9530";
			}
			catch
			{
				return "http://127.0.0.1:9530";
			}
		}

		[DllImport("user32.dll", SetLastError = true)]
		private static extern bool OpenClipboard(IntPtr hWndNewOwner);

		[DllImport("user32.dll", SetLastError = true)]
		private static extern bool CloseClipboard();

		[DllImport("user32.dll", SetLastError = true)]
		private static extern bool EmptyClipboard();

		[DllImport("user32.dll", SetLastError = true)]
		private static extern IntPtr SetClipboardData(uint uFormat, IntPtr hMem);

		private static bool TrySetClipboardText(string text, out Exception? lastError)
		{
			string text2 = text;
			lastError = null;
			if (text2 == null)
			{
				text2 = string.Empty;
			}
			bool win32Ok = false;
			Exception win32Error = null;
			Thread thread = new Thread((ThreadStart)delegate
			{
				try
				{
					win32Ok = SetClipboardTextWin32(text2, out Exception lastError2);
					if (!win32Ok)
					{
						win32Error = lastError2;
					}
				}
				catch (Exception ex)
				{
					win32Error = ex;
				}
			});
			thread.SetApartmentState(ApartmentState.STA);
			thread.IsBackground = true;
			thread.Start();
			thread.Join();
			if (win32Ok)
			{
				return true;
			}
			lastError = win32Error;
			return false;
		}

		private static bool SetClipboardTextWin32(string text, out Exception? lastError)
		{
			lastError = null;
			IntPtr intPtr = IntPtr.Zero;
			try
			{
				byte[] bytes = Encoding.Unicode.GetBytes(text + "\0");
				intPtr = Marshal.AllocHGlobal(bytes.Length);
				if (intPtr == IntPtr.Zero)
				{
					lastError = new InvalidOperationException("AllocHGlobal 失败");
					return false;
				}
				Marshal.Copy(bytes, 0, intPtr, bytes.Length);
				int[] array = new int[4] { 0, 30, 60, 120 };
				bool flag = false;
				int value = 0;
				for (int i = 0; i < array.Length; i++)
				{
					if (array[i] > 0)
					{
						Thread.Sleep(array[i]);
					}
					if (OpenClipboard(IntPtr.Zero))
					{
						flag = true;
						break;
					}
					value = Marshal.GetLastWin32Error();
				}
				if (!flag)
				{
					lastError = new InvalidOperationException($"OpenClipboard 失败 (Win32 错误码={value}, 0x{value:X})");
					return false;
				}
				try
				{
					EmptyClipboard();
					if (SetClipboardData(13u, intPtr) == IntPtr.Zero)
					{
						lastError = new InvalidOperationException($"SetClipboardData 失败 (Win32 错误码={Marshal.GetLastWin32Error()})");
						return false;
					}
					intPtr = IntPtr.Zero;
					return true;
				}
				finally
				{
					CloseClipboard();
				}
			}
			catch (Exception ex)
			{
				lastError = ex;
				return false;
			}
			finally
			{
				if (intPtr != IntPtr.Zero)
				{
					try
					{
						Marshal.FreeHGlobal(intPtr);
					}
					catch
					{
					}
				}
			}
		}

