		private async Task LoadScanHistoryAsync()
		{
			try
			{
				_scanHistoryList = await _historyService.GetScanHistoryAsync((string)null, (DateTime?)null, (DateTime?)null, (string)null);
				var list = _scanHistoryList.Select((ScanHistory s) => new
				{
					Display = $"{s.Target} - {s.ScanTime:yyyy-MM-dd HH:mm} ({s.TotalVulnerabilities}个漏洞)",
					Value = s
				}).ToList();
				BaselineScanComboBox.ItemsSource = list;
