		private void UpdateScanInfo(object selectedItem, TextBlock infoTextBlock)
		{
			if (selectedItem == null)
			{
				infoTextBlock.Text = "请选择扫描记录";
				return;
			}
			ScanHistory val = (ScanHistory)((dynamic)selectedItem).Value;
			infoTextBlock.Text = $"目标: {val.Target} | 时间: {val.ScanTime:yyyy-MM-dd HH:mm} | 漏洞: {val.TotalVulnerabilities}个 | 风险: {val.ScanStatus}";
		}

		private void CompareButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				if (BaselineScanComboBox.SelectedItem == null || CurrentScanComboBox.SelectedItem == null)
				{
					System.Windows.MessageBox.Show("请选择基线扫描和当前扫描", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				dynamic selectedItem = BaselineScanComboBox.SelectedItem;
				dynamic selectedItem2 = CurrentScanComboBox.SelectedItem;
				ScanHistory val = (ScanHistory)selectedItem.Value;
				ScanHistory val2 = (ScanHistory)selectedItem2.Value;
				if (val.ScanId == val2.ScanId)
				{
					System.Windows.MessageBox.Show("基线扫描和当前扫描不能相同", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
					return;
				}
				_comparisonResult = _comparisonService.CompareScans(val, val2);
				DisplayComparisonResult();
				ComparisonResultTabControl.Visibility = Visibility.Visible;
				ExportComparisonButton.IsEnabled = true;
				System.Windows.MessageBox.Show("扫描对比完成！", "对比完成", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("对比扫描失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private void DisplayComparisonResult()
		{
			if (_comparisonResult != null)
			{
				BaselineRiskScoreTextBlock.Text = _comparisonResult.BaselineRiskScore.ToString("F1");
				CurrentRiskScoreTextBlock.Text = _comparisonResult.CurrentRiskScore.ToString("F1");
				double riskScoreChange = _comparisonResult.RiskScoreChange;
				RiskScoreChangeTextBlock.Text = $"({((riskScoreChange >= 0.0) ? "+" : "")}{riskScoreChange:F1})";
				RiskScoreChangeTextBlock.Foreground = ((riskScoreChange > 0.0) ? System.Windows.Media.Brushes.Red : ((riskScoreChange < 0.0) ? System.Windows.Media.Brushes.Green : System.Windows.Media.Brushes.Gray));
				ResolvedCountTextBlock.Text = _comparisonResult.ResolvedVulnerabilities.Count.ToString();
				NewCountTextBlock.Text = _comparisonResult.NewVulnerabilities.Count.ToString();
				PersistentCountTextBlock.Text = _comparisonResult.PersistentVulnerabilities.Count.ToString();
				RiskChangedCountTextBlock.Text = _comparisonResult.RiskChangedVulnerabilities.Count.ToString();
				NewPortsTextBlock.Text = $"新开放: {_comparisonResult.NewOpenPorts.Count}";
				ClosedPortsTextBlock.Text = $"已关闭: {_comparisonResult.ClosedPorts.Count}";
				PersistentPortsTextBlock.Text = $"仍开放: {_comparisonResult.PersistentOpenPorts.Count}";
				NewVulnerabilitiesDataGrid.ItemsSource = _comparisonResult.NewVulnerabilities;
				ResolvedVulnerabilitiesDataGrid.ItemsSource = _comparisonResult.ResolvedVulnerabilities;
				PersistentVulnerabilitiesDataGrid.ItemsSource = _comparisonResult.PersistentVulnerabilities;
			}
		}

		private async void ExportComparisonButton_Click(object sender, RoutedEventArgs e)
		{
			if (_comparisonResult == null)
			{
				return;
			}
			try
			{
				Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
				{
					Filter = "文本文件|*.txt|HTML文件|*.html",
					FileName = $"扫描对比报告_{DateTime.Now:yyyyMMdd_HHmmss}",
					Title = "导出对比报告"
				};
				if (saveFileDialog.ShowDialog() == true)
				{
					string filePath = saveFileDialog.FileName;
					string contents = ((!(System.IO.Path.GetExtension(filePath).ToLower() == ".html")) ? _comparisonService.GenerateComparisonSummary(_comparisonResult) : GenerateHtmlComparisonReport());
					await File.WriteAllTextAsync(filePath, contents);
					System.Windows.MessageBox.Show("对比报告已保存到:\n" + filePath, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出报告失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

