		private StackPanel CreatePortItem(int port, string service, bool isNew)
		{
			StackPanel stackPanel = new StackPanel
			{
				Orientation = System.Windows.Controls.Orientation.Horizontal
			};
			TextBlock element = new TextBlock
			{
				Text = $"端口 {port}",
				FontWeight = FontWeights.SemiBold,
				FontSize = 12.0,
				Foreground = (isNew ? new SolidColorBrush(System.Windows.Media.Color.FromRgb(39, 174, 96)) : new SolidColorBrush(System.Windows.Media.Color.FromRgb(231, 76, 60))),
				Margin = new Thickness(0.0, 0.0, 8.0, 0.0)
			};
			stackPanel.Children.Add(element);
			if (!string.IsNullOrEmpty(service))
			{
				stackPanel.Children.Add(new TextBlock
				{
					Text = "(" + service + ")",
					FontSize = 11.0,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(127, 140, 141))
				});
			}
			return stackPanel;
		}

		private StackPanel CreateVulnItem(VulnerabilityResult vuln, bool isFixed)
		{
			StackPanel stackPanel = new StackPanel();
			StackPanel stackPanel2 = new StackPanel
			{
				Orientation = System.Windows.Controls.Orientation.Horizontal
			};
			TextBlock element = new TextBlock
			{
				Text = vuln.Name,
				FontWeight = FontWeights.SemiBold,
				FontSize = 12.0,
				Foreground = (isFixed ? new SolidColorBrush(System.Windows.Media.Color.FromRgb(39, 174, 96)) : new SolidColorBrush(System.Windows.Media.Color.FromRgb(231, 76, 60))),
				Margin = new Thickness(0.0, 0.0, 8.0, 0.0)
			};
			stackPanel2.Children.Add(element);
			if (!string.IsNullOrEmpty(vuln.CveId))
			{
				stackPanel2.Children.Add(new TextBlock
				{
					Text = vuln.CveId,
					FontSize = 11.0,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(127, 140, 141))
				});
			}
			stackPanel.Children.Add(stackPanel2);
			string text = "";
			if (vuln.Port.HasValue)
			{
				text += $"端口: {vuln.Port}  ";
			}
			if (!string.IsNullOrEmpty(vuln.RiskLevel))
			{
				text = text + "风险: " + vuln.RiskLevel;
			}
			if (!string.IsNullOrEmpty(text))
			{
				stackPanel.Children.Add(new TextBlock
				{
					Text = text,
					FontSize = 11.0,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(149, 165, 166)),
					Margin = new Thickness(0.0, 2.0, 0.0, 0.0)
				});
			}
			return stackPanel;
		}

