		private async void ExportButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
				{
					Filter = "文本文件|*.txt|HTML文件|*.html",
					FileName = $"扫描详情_{_history.ScanId}_{_history.ScanTime:yyyyMMdd}",
					Title = "导出扫描详情"
				};
				if (saveFileDialog.ShowDialog() == true)
				{
					string filePath = saveFileDialog.FileName;
					string contents = ((!(System.IO.Path.GetExtension(filePath).ToLower() == ".html")) ? GenerateTextContent() : GenerateHtmlContent());
					await File.WriteAllTextAsync(filePath, contents, Encoding.UTF8);
					System.Windows.MessageBox.Show("扫描详情已导出到:\n" + filePath, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

