		private bool _contentLoaded;

		public ScanHistoryWindow()
		{
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0017: Expected O, but got Unknown
			InitializeComponent();
			_historyService = new ScanHistoryService();
			_allHistory = new List<ScanHistory>();
			_filteredHistory = new List<ScanHistory>();
			base.Loaded += ScanHistoryWindow_Loaded;
		}

		private async void ScanHistoryWindow_Loaded(object sender, RoutedEventArgs e)
		{
			await LoadHistoryAsync();
		}

		private async Task LoadHistoryAsync()
		{
			try
			{
				_allHistory = await _historyService.GetScanHistoryAsync((string)null, (DateTime?)null, (DateTime?)null, (string)null);
				ApplyFilters();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("加载扫描历史失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private void ApplyFilters()
		{
			_filteredHistory = _allHistory.ToList();
			string searchText = SearchTextBox.Text.Trim().ToLower();
			if (!string.IsNullOrEmpty(searchText))
			{
				_filteredHistory = _filteredHistory.Where((ScanHistory h) => h.Target.ToLower().Contains(searchText) || h.ScanId.ToLower().Contains(searchText) || (h.ScanMode?.ToLower().Contains(searchText) ?? false)).ToList();
			}
			if (RiskFilterComboBox.SelectedItem is ComboBoxItem comboBoxItem && comboBoxItem.Content.ToString() != "所有风险等级")
			{
				string riskLevel = comboBoxItem.Content.ToString();
				_filteredHistory = _filteredHistory.Where((ScanHistory h) => (riskLevel == "严重" && h.CriticalCount > 0) || (riskLevel == "高危" && h.HighCount > 0) || (riskLevel == "中危" && h.MediumCount > 0) || (riskLevel == "低危" && h.LowCount > 0)).ToList();
			}
			if (DateFilterComboBox.SelectedItem is ComboBoxItem comboBoxItem2 && comboBoxItem2.Content.ToString() != "所有时间")
			{
				DateTime now = DateTime.Now;
				_filteredHistory = comboBoxItem2.Content.ToString() switch
				{
					"今天" => _filteredHistory.Where((ScanHistory h) => h.ScanTime.Date == now.Date).ToList(), 
					"最近7天" => _filteredHistory.Where((ScanHistory h) => h.ScanTime >= now.AddDays(-7.0)).ToList(), 
					"最近30天" => _filteredHistory.Where((ScanHistory h) => h.ScanTime >= now.AddDays(-30.0)).ToList(), 
					_ => _filteredHistory, 
				};
			}
			HistoryDataGrid.ItemsSource = _filteredHistory;
		}

		private void SearchTextBox_TextChanged(object sender, TextChangedEventArgs e)
		{
			ApplyFilters();
		}

		private void RiskFilterComboBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			ApplyFilters();
		}

		private void DateFilterComboBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			ApplyFilters();
		}

		private async void RefreshButton_Click(object sender, RoutedEventArgs e)
		{
			await LoadHistoryAsync();
		}

		private void HistoryDataGrid_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			bool isEnabled = HistoryDataGrid.SelectedItem != null;
			ViewDetailsButton.IsEnabled = isEnabled;
			GenerateReportButton.IsEnabled = isEnabled;
			DeleteButton.IsEnabled = isEnabled;
		}

		private void ViewDetailsButton_Click(object sender, RoutedEventArgs e)
		{
			object selectedItem = HistoryDataGrid.SelectedItem;
			ScanHistory val = (ScanHistory)((selectedItem is ScanHistory) ? selectedItem : null);
			if (val != null)
			{
				new ScanHistoryDetailsWindow(val).ShowDialog();
			}
		}

		private async void GenerateReportButton_Click(object sender, RoutedEventArgs e)
		{
			_ = 4;
			try
			{
				object selectedItem = HistoryDataGrid.SelectedItem;
				ScanHistory history = (ScanHistory)((selectedItem is ScanHistory) ? selectedItem : null);
				if (history == null)
				{
					System.Windows.MessageBox.Show("请先选择一条扫描记录", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				CompleteScanResult completeResult = await new JsonDatabaseService().GetScanResultByIdAsync(history.ScanId);
				if (completeResult == null)
				{
					System.Windows.MessageBox.Show("无法获取扫描记录 " + history.ScanId + " 的完整数据。\n可能原因：数据库中未保存完整扫描结果。", "生成报告失败", MessageBoxButton.OK, MessageBoxImage.Exclamation);
					return;
				}
				(ReportFormat, bool?) tuple = ShowReportFormatDialog();
				var (selectedFormat, _) = tuple;
				if (tuple.Item2 != true)
				{
					return;
				}
				string filePath = ShowSaveFileDialog(selectedFormat, history.Target);
				if (string.IsNullOrEmpty(filePath))
				{
					return;
				}
				string directoryName = System.IO.Path.GetDirectoryName(filePath);
				if (!string.IsNullOrEmpty(directoryName) && !Directory.Exists(directoryName))
				{
					Directory.CreateDirectory(directoryName);
				}
				Mouse.OverrideCursor = System.Windows.Input.Cursors.Wait;
				List<CompleteScanResult> results = new List<CompleteScanResult> { completeResult };
				string text = (selectedFormat - 1) switch
				{
					2 => await Task.Run(() => HistoryWordReportGenerator.GenerateFromHistoryRecordToPath(completeResult, filePath)), 
					1 => await GenerateHtmlReportAsync(completeResult, filePath), 
					0 => await GenerateCsvReportAsync(results, filePath), 
					_ => await GenerateTxtReportAsync(results, filePath), 
				};
				Mouse.OverrideCursor = null;
				if (!string.IsNullOrEmpty(text) && File.Exists(text))
				{
					FileInfo fileInfo = new FileInfo(text);
					string value = ((fileInfo.Length > 1048576) ? $"{(double)fileInfo.Length / 1048576.0:F2} MB" : $"{(double)fileInfo.Length / 1024.0:F1} KB");
					string value2 = (selectedFormat - 1) switch
					{
						2 => "Word", 
						1 => "HTML", 
						0 => "CSV", 
						_ => "文本", 
					};
					if (System.Windows.MessageBox.Show($"报告已成功生成！\n\n格式：{value2}\n保存位置：{text}\n文件大小：{value}\n生成时间：{DateTime.Now:yyyy-MM-dd HH:mm:ss}\n\n是否立即打开查看？", "报告生成成功", MessageBoxButton.YesNo, MessageBoxImage.Asterisk) == MessageBoxResult.Yes)
					{
						try
						{
							Process.Start(new ProcessStartInfo
							{
								FileName = text,
								UseShellExecute = true
							});
						}
						catch (Exception)
						{
						}
					}
				}
				else
				{
					System.Windows.MessageBox.Show("报告生成失败，可能原因：选中的记录中无有效扫描数据。", "生成失败", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				}
			}
			catch (Exception ex2)
			{
				Mouse.OverrideCursor = null;
				System.Windows.MessageBox.Show("生成报告失败: " + ex2.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

