		private string ShowSaveFileDialog(ReportFormat selectedFormat, string targetIp)
		{
			//IL_0077: Unknown result type (might be due to invalid IL or missing references)
			//IL_0079: Unknown result type (might be due to invalid IL or missing references)
			//IL_008b: Expected I4, but got Unknown
			string text = (targetIp ?? "unknown").Replace(".", "_").Replace(",", "_").Replace(" ", "")
				.Trim();
			if (text.Length > 30)
			{
				text = text.Substring(0, 30);
			}
			string text2 = DateTime.Now.ToString("yyyyMMdd_HHmmss");
			string text3 = "SecurityReport_" + text + "_" + text2;
			string filter;
			string text4;
			switch (selectedFormat - 1)
			{
			case 2:
				filter = "Word文件 (*.docx)|*.docx";
				text4 = "docx";
				break;
			case 1:
				filter = "HTML文件 (*.html)|*.html";
				text4 = "html";
				break;
			case 0:
				filter = "CSV文件 (*.csv)|*.csv";
				text4 = "csv";
				break;
			default:
				filter = "文本文件 (*.txt)|*.txt";
				text4 = "txt";
				break;
			}
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Title = "保存扫描报告",
				Filter = filter,
				DefaultExt = text4,
				FileName = text3 + "." + text4
			};
			string folderPath = Environment.GetFolderPath(Environment.SpecialFolder.Desktop);
			if (Directory.Exists(folderPath))
			{
				saveFileDialog.InitialDirectory = folderPath;
			}
			if (saveFileDialog.ShowDialog() == true)
			{
				return saveFileDialog.FileName;
			}
			return null;
		}

