		private async void DeleteButton_Click(object sender, RoutedEventArgs e)
		{
			object selectedItem = HistoryDataGrid.SelectedItem;
			ScanHistory val = (ScanHistory)((selectedItem is ScanHistory) ? selectedItem : null);
			if (val != null && System.Windows.MessageBox.Show($"确定要删除扫描记录 '{val.ScanId}' 吗？\n目标: {val.Target}\n时间: {val.ScanTime:yyyy-MM-dd HH:mm}", "确认删除", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
			{
				try
				{
					await _historyService.DeleteScanHistoryAsync(val.ScanId);
					await LoadHistoryAsync();
					System.Windows.MessageBox.Show("记录已删除", "成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
				catch (Exception ex)
				{
					System.Windows.MessageBox.Show("删除失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				}
			}
		}

		private async void ExportButton_Click(object sender, RoutedEventArgs e)
		{
			_ = 1;
			try
			{
				Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
				{
					Filter = "CSV文件|*.csv|JSON文件|*.json",
					FileName = $"扫描历史_{DateTime.Now:yyyyMMdd_HHmmss}",
					Title = "导出扫描历史"
				};
				if (saveFileDialog.ShowDialog() == true)
				{
					string filePath = saveFileDialog.FileName;
					string text = System.IO.Path.GetExtension(filePath).ToLower();
					if (text == ".csv")
					{
						await ExportToCsvAsync(filePath);
					}
					else if (text == ".json")
					{
						await ExportToJsonAsync(filePath);
					}
					System.Windows.MessageBox.Show("扫描历史已导出到:\n" + filePath, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async Task ExportToCsvAsync(string filePath)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("扫描ID,目标,扫描时间,扫描模式,漏洞总数,严重,高危,中危,低危,扫描时长,状态");
			foreach (ScanHistory item in _filteredHistory)
			{
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(10, 11, stringBuilder2);
				handler.AppendFormatted(item.ScanId);
				handler.AppendLiteral(",");
				handler.AppendFormatted(item.Target);
				handler.AppendLiteral(",");
				handler.AppendFormatted(item.ScanTime, "yyyy-MM-dd HH:mm");
				handler.AppendLiteral(",");
				handler.AppendFormatted(item.ScanMode);
				handler.AppendLiteral(",");
				handler.AppendFormatted(item.TotalVulnerabilities);
				handler.AppendLiteral(",");
				handler.AppendFormatted(item.CriticalCount);
				handler.AppendLiteral(",");
				handler.AppendFormatted(item.HighCount);
				handler.AppendLiteral(",");
				handler.AppendFormatted(item.MediumCount);
				handler.AppendLiteral(",");
				handler.AppendFormatted(item.LowCount);
				handler.AppendLiteral(",");
				handler.AppendFormatted(item.Duration);
				handler.AppendLiteral(",");
				handler.AppendFormatted(item.ScanStatus);
				stringBuilder2.AppendLine(ref handler);
			}
			await File.WriteAllTextAsync(filePath, stringBuilder.ToString(), Encoding.UTF8);
		}

		private async Task ExportToJsonAsync(string filePath)
		{
			string contents = JsonSerializer.Serialize(_filteredHistory, new JsonSerializerOptions
			{
				WriteIndented = true,
				PropertyNamingPolicy = JsonNamingPolicy.CamelCase
			});
			await File.WriteAllTextAsync(filePath, contents, Encoding.UTF8);
		}

