		private static void EnsureChineseFontResolver()
		{
			if (_fontResolverInitialized)
			{
				return;
			}
			_fontResolverInitialized = true;
			string[] array = new string[8] { "C:\\Windows\\Fonts\\msyh.ttc", "C:\\Windows\\Fonts\\msyh.ttf", "C:\\Windows\\Fonts\\msyhbd.ttc", "C:\\Windows\\Fonts\\simhei.ttf", "C:\\Windows\\Fonts\\simsun.ttc", "/System/Library/Fonts/PingFang.ttc", "/usr/share/fonts/truetype/wqy/wqy-microhei.ttc", "/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc" };
			foreach (string text2 in array)
			{
				try
				{
					if (File.Exists(text2))
					{
						_chineseTypeface = SKTypeface.FromFile(text2, 0);
						if (_chineseTypeface != null)
						{
							break;
						}
					}
				}
				catch
				{
				}
			}
			if (_chineseTypeface == null)
			{
				try
				{
					SKFontManager @default = SKFontManager.Default;
					try
					{
						array = new string[8] { "Microsoft YaHei", "微软雅黑", "SimHei", "黑体", "SimSun", "宋体", "WenQuanYi Micro Hei", "Noto Sans CJK SC" };
						foreach (string text3 in array)
						{
							try
							{
								SKTypeface val = ((@default != null) ? @default.MatchCharacter(text3, 20013) : null);
								if (val != null)
								{
									_chineseTypeface = val;
									break;
								}
							}
							catch
							{
							}
						}
					}
					finally
					{
						((IDisposable)@default)?.Dispose();
					}
				}
				catch
				{
				}
			}
			try
			{
				MethodInfo method = typeof(LiveChartsSkiaSharp).GetMethod("OverrideSkiaSharpTypefaceResolver", BindingFlags.Static | BindingFlags.Public);
				if (method != null)
				{
					method.Invoke(null, new object[1] { (Func<string, SKFontStyleWeight, SKFontStyleSlant, SKTypeface>)((string text, SKFontStyleWeight weight, SKFontStyleSlant slant) => _chineseTypeface ?? SKTypeface.FromFamilyName(SKTypeface.Default.FamilyName) ?? SKTypeface.Default) });
				}
			}
			catch
			{
			}
		}

