		private async void ScanVisualizationWindow_Loaded(object sender, RoutedEventArgs e)
		{
			try
			{
				await LoadDataAsync(useMockIfEmpty: true);
				RefreshAll();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("加载可视化数据失败: " + ex.Message + "\n\n" + ex.StackTrace, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async Task LoadDataAsync(bool useMockIfEmpty = false)
		{
			try
			{
				_history = await _analyticsService.GetAllScanHistoryAsync();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("加载历史数据失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Exclamation);
			}
			if ((_history == null || _history.Count == 0) && useMockIfEmpty)
			{
				Dictionary<string, object> dictionary = _analyticsService.GenerateMockDataIfEmpty();
				_history = (List<ScanHistoryItem>)dictionary["History"];
			}
		}

		private void RefreshButton_Click(object sender, RoutedEventArgs e)
		{
			Task.Run(async delegate
			{
				await LoadDataAsync();
				((DispatcherObject)this).Dispatcher.Invoke((Action)RefreshAll);
			});
		}

		private async void MockButton_Click(object sender, RoutedEventArgs e)
		{
			if (System.Windows.MessageBox.Show("将生成 1 年的模拟扫描数据用于演示，是否继续？\n（不会覆盖真实历史数据）", "生成演示数据", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
			{
				Dictionary<string, object> dictionary = _analyticsService.GenerateMockDataIfEmpty();
				_history = (List<ScanHistoryItem>)dictionary["History"];
				await Task.Delay(500);
				RefreshAll();
				System.Windows.MessageBox.Show($"演示数据加载成功！共 {_history.Count} 条扫描记录，包含 365 天范围。", "成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
		}

		private void PeriodComboBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			if (base.IsLoaded)
			{
				RefreshAll();
			}
		}

		private TimePeriodType GetSelectedPeriod(out int periods)
		{
			switch ((PeriodComboBox.SelectedItem as ComboBoxItem)?.Tag?.ToString() ?? "Weekly")
			{
			case "Daily":
				periods = 7;
				return (TimePeriodType)0;
			case "Weekly":
				periods = 12;
				return (TimePeriodType)1;
			case "Monthly":
				periods = 12;
				return (TimePeriodType)2;
			case "Quarterly":
				periods = 8;
				return (TimePeriodType)3;
			case "Yearly":
				periods = 5;
				return (TimePeriodType)4;
			default:
				periods = 12;
				return (TimePeriodType)1;
			}
		}

		private void RefreshAll()
		{
			try
			{
				RefreshPeriodOverviewCards();
				RefreshCurrentPeriodKpi();
				RefreshTrendMultiChart();
				RefreshRiskMixPieChart();
				RefreshStackedRiskChart();
				RefreshTopTargetsBarChart();
				RefreshPortVsVulnChart();
				RefreshPeriodDetailGrid();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("刷新图表出错: " + ex.Message, "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
			}
		}

		private void RefreshPeriodOverviewCards()
		{
			//IL_004d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0086: Unknown result type (might be due to invalid IL or missing references)
