			//IL_0131: Unknown result type (might be due to invalid IL or missing references)
			List<PeriodStatisticsSummary> allPeriodSummaries = _analyticsService.GetAllPeriodSummaries(_history);
			if (allPeriodSummaries != null && allPeriodSummaries.Count != 0)
			{
				Apply("Day", (PeriodStatisticsSummary)(((object)((IEnumerable<PeriodStatisticsSummary>)allPeriodSummaries).FirstOrDefault((Func<PeriodStatisticsSummary, bool>)((PeriodStatisticsSummary s) => (int)s.PeriodType == 0))) ?? ((object)new PeriodStatisticsSummary())));
				Apply("Week", (PeriodStatisticsSummary)(((object)((IEnumerable<PeriodStatisticsSummary>)allPeriodSummaries).FirstOrDefault((Func<PeriodStatisticsSummary, bool>)((PeriodStatisticsSummary s) => (int)s.PeriodType == 1))) ?? ((object)new PeriodStatisticsSummary())));
				Apply("Month", (PeriodStatisticsSummary)(((object)((IEnumerable<PeriodStatisticsSummary>)allPeriodSummaries).FirstOrDefault((Func<PeriodStatisticsSummary, bool>)((PeriodStatisticsSummary s) => (int)s.PeriodType == 2))) ?? ((object)new PeriodStatisticsSummary())));
				Apply("Quarter", (PeriodStatisticsSummary)(((object)((IEnumerable<PeriodStatisticsSummary>)allPeriodSummaries).FirstOrDefault((Func<PeriodStatisticsSummary, bool>)((PeriodStatisticsSummary s) => (int)s.PeriodType == 3))) ?? ((object)new PeriodStatisticsSummary())));
				Apply("Year", (PeriodStatisticsSummary)(((object)((IEnumerable<PeriodStatisticsSummary>)allPeriodSummaries).FirstOrDefault((Func<PeriodStatisticsSummary, bool>)((PeriodStatisticsSummary s) => (int)s.PeriodType == 4))) ?? ((object)new PeriodStatisticsSummary())));
			}
			void Apply(string prefix, PeriodStatisticsSummary s)
			{
				TextBlock textBlock = FindName(prefix + "ScanText") as TextBlock;
				TextBlock textBlock2 = FindName(prefix + "VulnText") as TextBlock;
				TextBlock textBlock3 = FindName(prefix + "TrendText") as TextBlock;
				if (textBlock != null)
				{
					textBlock.Text = $"{s.TotalScans} 次";
				}
				if (textBlock2 != null)
				{
					textBlock2.Text = $"漏洞 {s.TotalVulns}";
				}
				if (textBlock3 != null)
				{
					bool flag = s.TrendChangePercent > 0.0;
					string value = (flag ? "\ud83d\udcc8" : "\ud83d\udcc9");
					textBlock3.Text = $"{value} {Math.Abs(s.TrendChangePercent)}%";
					textBlock3.Foreground = (flag ? new SolidColorBrush(Colors.DarkRed) : new SolidColorBrush(Colors.ForestGreen));
				}
			}
		}

