		private void InitializeTimeComboBoxes()
		{
			if (HourComboBox != null && MinuteComboBox != null)
			{
				for (int i = 0; i < 24; i++)
				{
					HourComboBox.Items.Add(i.ToString("D2"));
				}
				HourComboBox.SelectedIndex = 2;
				for (int j = 0; j < 60; j += 5)
				{
					MinuteComboBox.Items.Add(j.ToString("D2"));
				}
				MinuteComboBox.SelectedIndex = 0;
			}
		}

		private void SetupEventHandlers()
		{
			_scheduledScanService.ScanStarted += delegate(object? s, ScheduledScanEventArgs e)
			{
				ScheduledScanEventArgs e4 = e;
				((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
				{
					System.Windows.MessageBox.Show("定时任务 '" + e4.Scan.Name + "' 开始执行", "扫描开始", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				});
			};
			_scheduledScanService.ScanCompleted += delegate(object? s, ScheduledScanEventArgs e)
			{
				ScheduledScanEventArgs e3 = e;
				((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
				{
					System.Windows.MessageBox.Show($"定时任务 '{e3.Scan.Name}' 执行完成\n扫描目标: {e3.Scan.TargetValue}\n发现漏洞: {e3.Result.TotalVulnerabilities} 个\n执行时长: {e3.Duration.TotalMinutes:F1} 分钟", "扫描完成", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					LoadScheduledScans();
				});
			};
			_scheduledScanService.ScanFailed += delegate(object? s, ScheduledScanEventArgs e)
			{
				ScheduledScanEventArgs e2 = e;
				((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
				{
					System.Windows.MessageBox.Show("定时任务 '" + e2.Scan.Name + "' 执行失败: " + e2.Error, "扫描失败", MessageBoxButton.OK, MessageBoxImage.Hand);
				});
			};
		}

		private void LoadScheduledScans()
		{
			List<ScheduledScan> allScheduledScans = _scheduledScanService.GetAllScheduledScans();
			ScheduledScansDataGrid.ItemsSource = allScheduledScans;
		}

		private void TargetTypeComboBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			if (TargetTypeComboBox.SelectedItem is ComboBoxItem { Tag: var tag })
			{
				string text = tag?.ToString();
				if (TargetHintTextBlock != null)
				{
					TextBlock targetHintTextBlock = TargetHintTextBlock;
					targetHintTextBlock.Text = text switch
					{
						"Single" => "提示：输入单个IP地址，如：192.168.1.1", 
						"Range" => "提示：输入IP段，如：192.168.1.1-192.168.1.254", 
						"CIDR" => "提示：输入CIDR格式，如：192.168.1.0/24", 
						"File" => "提示：输入目标列表文件路径", 
						_ => "提示：输入目标值", 
					};
				}
			}
		}

		private void AddTaskButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				ScheduledScan val = CreateScheduledScanFromUI();
				if (val != null)
				{
					_scheduledScanService.AddScheduledScan(val);
					LoadScheduledScans();
					ClearInputFields();
					System.Windows.MessageBox.Show("定时任务添加成功", "成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("添加任务失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private void UpdateTaskButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				object selectedItem = ScheduledScansDataGrid.SelectedItem;
				ScheduledScan val = (ScheduledScan)((selectedItem is ScheduledScan) ? selectedItem : null);
				if (val == null)
				{
					System.Windows.MessageBox.Show("请先选择要更新的任务", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
				ScheduledScan val2 = CreateScheduledScanFromUI();
				if (val2 != null)
				{
					val2.Id = val.Id;
					val2.CreatedAt = val.CreatedAt;
					val2.LastRunTime = val.LastRunTime;
					val2.RunCount = val.RunCount;
					_scheduledScanService.UpdateScheduledScan(val2);
					LoadScheduledScans();
					System.Windows.MessageBox.Show("定时任务更新成功", "成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("更新任务失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private void DeleteTaskButton_Click(object sender, RoutedEventArgs e)
		{
			try
			{
				object selectedItem = ScheduledScansDataGrid.SelectedItem;
				ScheduledScan val = (ScheduledScan)((selectedItem is ScheduledScan) ? selectedItem : null);
				if (val == null)
				{
					System.Windows.MessageBox.Show("请先选择要删除的任务", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
				else if (System.Windows.MessageBox.Show("确定要删除任务 '" + val.Name + "' 吗？", "确认删除", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
				{
					_scheduledScanService.DeleteScheduledScan(val.Id);
					LoadScheduledScans();
					ClearInputFields();
					System.Windows.MessageBox.Show("定时任务删除成功", "成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("删除任务失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

