				FontSize = 14.0,
				FontWeight = FontWeights.SemiBold,
				Margin = new Thickness(0.0, 0.0, 0.0, 15.0)
			});
			System.Windows.Controls.Button button = new System.Windows.Controls.Button
			{
				Content = "\ud83d\udcc4 导出为 TXT 文本",
				Height = 36.0,
				Margin = new Thickness(0.0, 5.0, 0.0, 5.0),
				Background = new SolidColorBrush(System.Windows.Media.Color.FromRgb(52, 152, 219)),
				Foreground = System.Windows.Media.Brushes.White,
				BorderThickness = new Thickness(0.0)
			};
			System.Windows.Controls.Button button2 = new System.Windows.Controls.Button
			{
				Content = "\ud83d\udcca 导出为 CSV 表格",
				Height = 36.0,
				Margin = new Thickness(0.0, 5.0, 0.0, 5.0),
