				Foreground = System.Windows.Media.Brushes.White,
				BorderThickness = new Thickness(0.0)
			};
			button.Click += delegate
			{
				formatDialog.Close();
				ExportToTxt();
			};
			button2.Click += delegate
			{
				formatDialog.Close();
				ExportToCsv();
			};
			stackPanel.Children.Add(button);
			stackPanel.Children.Add(button2);
			formatDialog.Content = stackPanel;
			formatDialog.ShowDialog();
		}

		private void ExportToTxt()
		{
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Filter = "Text Files (*.txt)|*.txt|All Files (*.*)|*.*",
				FileName = $"StatisticsReport_{DateTime.Now:yyyyMMdd_HHmmss}.txt"
			};
			if (saveFileDialog.ShowDialog() == true)
			{
				ExportStatisticsToFile(saveFileDialog.FileName);
			}
		}

		private void ExportToCsv()
		{
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Filter = "CSV Files (*.csv)|*.csv|All Files (*.*)|*.*",
				FileName = $"StatisticsReport_{DateTime.Now:yyyyMMdd_HHmmss}.csv"
			};
			if (saveFileDialog.ShowDialog() != true)
			{
				return;
			}
			try
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.AppendLine("日期,扫描次数,开放端口,漏洞总数,严重,高危,中危,低危");
				IEnumerable enumerable = ScanTrendDataGrid?.ItemsSource;
				StringBuilder stringBuilder2;
				StringBuilder.AppendInterpolatedStringHandler handler;
				if (enumerable != null)
				{
					foreach (object item in enumerable)
					{
						if (item is ScanTrendItem scanTrendItem)
						{
							stringBuilder2 = stringBuilder;
							StringBuilder stringBuilder3 = stringBuilder2;
							handler = new StringBuilder.AppendInterpolatedStringHandler(7, 8, stringBuilder2);
							handler.AppendFormatted(scanTrendItem.Date);
							handler.AppendLiteral(",");
							handler.AppendFormatted(scanTrendItem.ScanCount);
							handler.AppendLiteral(",");
							handler.AppendFormatted(scanTrendItem.PortCount);
							handler.AppendLiteral(",");
							handler.AppendFormatted(scanTrendItem.VulnerabilityCount);
							handler.AppendLiteral(",");
							handler.AppendFormatted(scanTrendItem.CriticalCount);
							handler.AppendLiteral(",");
							handler.AppendFormatted(scanTrendItem.HighCount);
							handler.AppendLiteral(",");
							handler.AppendFormatted(scanTrendItem.MediumCount);
							handler.AppendLiteral(",");
							handler.AppendFormatted(scanTrendItem.LowCount);
							stringBuilder3.AppendLine(ref handler);
						}
					}
				}
				stringBuilder.AppendLine();
				stringBuilder.AppendLine("=== 总体统计 ===");
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder4 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(6, 1, stringBuilder2);
				handler.AppendLiteral("总扫描次数,");
				handler.AppendFormatted(TotalScansTextBlock?.Text ?? "N/A");
				stringBuilder4.AppendLine(ref handler);
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder5 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(5, 1, stringBuilder2);
				handler.AppendLiteral("总漏洞数,");
				handler.AppendFormatted(TotalVulnsTextBlock?.Text ?? "N/A");
				stringBuilder5.AppendLine(ref handler);
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder6 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(6, 1, stringBuilder2);
				handler.AppendLiteral("严重/高危,");
				handler.AppendFormatted(CriticalVulnsTextBlock?.Text ?? "N/A");
				stringBuilder6.AppendLine(ref handler);
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder7 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(5, 1, stringBuilder2);
				handler.AppendLiteral("开放端口,");
				handler.AppendFormatted(TotalPortsTextBlock?.Text ?? "N/A");
				stringBuilder7.AppendLine(ref handler);
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder8 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(5, 1, stringBuilder2);
				handler.AppendLiteral("扫描目标,");
				handler.AppendFormatted(TotalTargetsTextBlock?.Text ?? "N/A");
				stringBuilder8.AppendLine(ref handler);
				File.WriteAllText(saveFileDialog.FileName, stringBuilder.ToString(), Encoding.UTF8);
				System.Windows.MessageBox.Show("CSV报告已导出到:\n" + saveFileDialog.FileName, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出CSV失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

