		private async Task LoadStatisticsAsync()
		{
			_ = 1;
			try
			{
				if (LastUpdateTimeTextBlock != null)
				{
					LastUpdateTimeTextBlock.Text = $"最后更新: {DateTime.Now:yyyy-MM-dd HH:mm:ss}";
				}
				List<ScanHistoryItem> jsonResults = (await SafeGetJsonHistory()) ?? new List<ScanHistoryItem>();
				List<ScanHistory> list = (await SafeGetDbHistory()) ?? new List<ScanHistory>();
				_jsonResults = new List<CompleteScanResult>();
				(DateTime, DateTime, string)? selectedTimeRange = GetSelectedTimeRange();
				if (selectedTimeRange.HasValue)
				{
					DateTime startDate = selectedTimeRange.Value.Item1;
					DateTime endDate = selectedTimeRange.Value.Item2;
					List<ScanHistoryItem> jsonHistory = jsonResults.Where((ScanHistoryItem h) => h != null && h.ScanTime >= startDate && h.ScanTime <= endDate).ToList();
					List<ScanHistory> dbHistory = list.Where((ScanHistory h) => h != null && h.StartTime >= startDate && h.StartTime <= endDate).ToList();
					RiskDistributionPanel?.Children.Clear();
					try
					{
						CalculateOverallStats(jsonHistory, dbHistory);
					}
					catch
					{
					}
					try
					{
						RenderPeriodComparisonCards(jsonResults, list);
					}
					catch
					{
					}
					try
					{
						RenderRiskDistribution(jsonHistory, dbHistory);
					}
					catch
					{
					}
					try
					{
						RenderVulnBarChart(dbHistory);
					}
					catch
					{
					}
					try
					{
						RenderScanTrend(jsonHistory, dbHistory);
					}
					catch
					{
					}
					try
					{
						RenderTopVulnerabilities(jsonHistory, dbHistory);
					}
					catch
					{
					}
					try
					{
						RenderPortAnalysis(jsonHistory, dbHistory);
					}
					catch
					{
					}
					try
					{
						RenderServiceDistribution(jsonHistory, dbHistory);
					}
					catch
					{
					}
					try
					{
						RenderScanHistory(jsonHistory, dbHistory);
					}
					catch
					{
					}
					try
					{
						RenderTimeDimensionAnalysis();
					}
					catch
					{
					}
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("加载统计数据失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private async Task<List<ScanHistoryItem>> SafeGetJsonHistory()
		{
			try
			{
				return await _jsonDatabaseService.GetScanHistoryAsync();
			}
			catch
			{
				return new List<ScanHistoryItem>();
			}
		}

		private async Task<List<ScanHistory>> SafeGetDbHistory()
		{
			try
			{
				if (_scanHistoryService == null)
				{
					return new List<ScanHistory>();
				}
				return await _scanHistoryService.GetScanHistoryAsync((string)null, (DateTime?)null, (DateTime?)null, (string)null);
			}
			catch
			{
				return new List<ScanHistory>();
			}
		}

		private async void ScanHistoryDataGrid_MouseDoubleClick(object sender, MouseButtonEventArgs e)
		{
			if (ScanHistoryDataGrid?.SelectedItem == null || _scanHistoryService == null)
			{
				return;
			}
			object selectedItem = ScanHistoryDataGrid.SelectedItem;
			string scanId = null;
			_ = DateTime.MinValue;
			if (selectedItem is ScanHistoryRecord scanHistoryRecord)
			{
				scanId = scanHistoryRecord.ScanId;
				_ = scanHistoryRecord.TargetIp;
				_ = scanHistoryRecord.ScanTime;
			}
			else
			{
				PropertyInfo[] properties = selectedItem.GetType().GetProperties();
				foreach (PropertyInfo propertyInfo in properties)
				{
					if (propertyInfo.Name == "ScanId")
					{
						scanId = propertyInfo.GetValue(selectedItem)?.ToString();
					}
					if (propertyInfo.Name == "TargetIp")
					{
						propertyInfo.GetValue(selectedItem)?.ToString();
					}
					if (propertyInfo.Name == "ScanTime")
					{
						_ = (DateTime)(propertyInfo.GetValue(selectedItem) ?? ((object)DateTime.MinValue));
					}
				}
			}
			if (string.IsNullOrEmpty(scanId))
			{
				return;
			}
			try
			{
				ScanHistory val = await _scanHistoryService.GetScanByIdAsync(scanId);
				if (val == null)
				{
					System.Windows.MessageBox.Show("未找到扫描记录: " + scanId, "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
				else
				{
					ShowScanHistoryDetail(val);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("加载扫描详情失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

