		private (DateTime Start, DateTime End, string Label)? GetSelectedTimeRange()
		{
			if (TimeRangeComboBox == null)
			{
				return (DateTime.Now.AddDays(-7.0), DateTime.Now, "最近7天");
			}
			string text = (TimeRangeComboBox.SelectedItem as ComboBoxItem)?.Content?.ToString() ?? "本周";
			DateTime now = DateTime.Now;
			return text switch
			{
				"本周" => (GetStartOfWeek(now), now, "本周"), 
				"本月" => (new DateTime(now.Year, now.Month, 1), now, "本月"), 
				"本季度" => (GetStartOfQuarter(now), now, "本季度"), 
				"本年度" => (new DateTime(now.Year, 1, 1), now, "本年度"), 
				"最近7天" => (now.AddDays(-7.0), now, "最近7天"), 
				"最近30天" => (now.AddDays(-30.0), now, "最近30天"), 
				"最近90天" => (now.AddDays(-90.0), now, "最近90天"), 
				"全部时间" => (DateTime.MinValue.AddYears(1900), now, "全部时间"), 
				"自定义..." => (_customStartDate ?? now.AddDays(-7.0), _customEndDate ?? now, "自定义"), 
				_ => (now.AddDays(-7.0), now, "最近7天"), 
			};
		}

		private DateTime GetStartOfWeek(DateTime date)
		{
			int num = (int)(7 + (date.DayOfWeek - 1)) % 7;
			return date.AddDays(-num).Date;
		}

		private DateTime GetStartOfQuarter(DateTime date)
		{
			int month = (date.Month - 1) / 3 * 3 + 1;
			return new DateTime(date.Year, month, 1);
		}

		private int GetTimeRangeDays()
		{
			(DateTime, DateTime, string)? selectedTimeRange = GetSelectedTimeRange();
			if (!selectedTimeRange.HasValue)
			{
				return 7;
			}
			return Math.Max(1, (int)(selectedTimeRange.Value.Item2 - selectedTimeRange.Value.Item1).TotalDays);
		}

		private void CalculateOverallStats(List<ScanHistoryItem> jsonHistory, List<ScanHistory> dbHistory)
		{
			if (jsonHistory == null)
			{
				jsonHistory = new List<ScanHistoryItem>();
			}
			if (dbHistory == null)
			{
				dbHistory = new List<ScanHistory>();
			}
			int num = jsonHistory.Count + dbHistory.Count;
			int num2 = jsonHistory.Sum((ScanHistoryItem h) => (h != null) ? h.VulnerabilitiesCount : 0) + dbHistory.Sum((ScanHistory h) => (h != null) ? h.TotalVulnerabilities : 0);
			int num3 = dbHistory.Sum((ScanHistory h) => (h != null) ? h.OpenPorts : 0);
			int num4 = jsonHistory.Sum(delegate(ScanHistoryItem h)
			{
				string text = ((h != null) ? h.RiskLevel : null);
				if (text == "高")
				{
					return h.VulnerabilitiesCount;
				}
				return (text == "高危") ? h.VulnerabilitiesCount : 0;
			}) + dbHistory.Sum(delegate(ScanHistory h)
			{
				if (h == null)
				{
					int? num6 = ((h != null) ? new int?(h.HighCount) : null);
					int? num7 = num6;
					return num7.GetValueOrDefault();
				}
				return h.CriticalCount;
			});
			int value = (from h in jsonHistory
				select (h == null) ? null : h.TargetIp into t
				where !string.IsNullOrEmpty(t)
				select t).Distinct().Count() + (from h in dbHistory
				select (h == null) ? null : h.Target into t
				where !string.IsNullOrEmpty(t)
				select t).Distinct().Count();
			IEnumerable<DateTime> source = jsonHistory.Select((ScanHistoryItem h) => (h == null) ? DateTime.MinValue : h.ScanTime.Date).Concat(dbHistory.Select((ScanHistory h) => (h == null) ? DateTime.MinValue : h.StartTime.Date));
			if (source.Any())
			{
				DateTime dateTime = source.Min();
				DateTime dateTime2 = source.Max();
				int num5 = (dateTime2 - dateTime).Days + 1;
				if (TimeRangeTextBlock != null)
				{
					TimeRangeTextBlock.Text = dateTime2.ToString("MM-dd");
				}
				if (DaysCountTextBlock != null)
				{
					DaysCountTextBlock.Text = $"{num5} 天";
				}
				double value2 = ((num5 > 0) ? ((double)num / (double)num5) : 0.0);
				if (AvgScansPerDayTextBlock != null)
				{
					AvgScansPerDayTextBlock.Text = $"{value2:F1} 次/天";
				}
			}
			if (TotalScansTextBlock != null)
			{
				TotalScansTextBlock.Text = num.ToString();
			}
			if (TotalVulnsTextBlock != null)
			{
				TotalVulnsTextBlock.Text = num2.ToString();
			}
			if (CriticalVulnsTextBlock != null)
			{
				CriticalVulnsTextBlock.Text = num4.ToString();
			}
			if (TotalPortsTextBlock != null)
			{
				TotalPortsTextBlock.Text = num3.ToString();
			}
			if (TotalTargetsTextBlock != null)
			{
				TotalTargetsTextBlock.Text = value.ToString();
			}
			double value3 = ((num > 0) ? ((double)num2 / (double)num) : 0.0);
			if (VulnsPerScanTextBlock != null)
			{
				VulnsPerScanTextBlock.Text = $"{value3:F1} 个/次";
			}
			double value4 = ((num2 > 0) ? ((double)num4 / (double)num2 * 100.0) : 0.0);
			if (CriticalPercentTextBlock != null)
			{
				CriticalPercentTextBlock.Text = $"{value4:F1}%";
			}
			double value5 = ((num > 0) ? ((double)num3 / (double)num) : 0.0);
			if (AvgPortsPerScanTextBlock != null)
			{
				AvgPortsPerScanTextBlock.Text = $"{value5:F1} 个/次";
			}
			if (UniqueTargetsTextBlock != null)
			{
				UniqueTargetsTextBlock.Text = $"{value} 个唯一";
			}
		}

		private void RenderPeriodComparisonCards(List<ScanHistoryItem> jsonHistory, List<ScanHistory> dbHistory)
		{
			DateTime now = DateTime.Now;
			PeriodStatisticsResult periodStatisticsResult = CalculatePeriodStats(jsonHistory, dbHistory, GetStartOfWeek(now), now);
			PeriodStatisticsResult periodStatisticsResult2 = CalculatePeriodStats(jsonHistory, dbHistory, new DateTime(now.Year, now.Month, 1), now);
			PeriodStatisticsResult periodStatisticsResult3 = CalculatePeriodStats(jsonHistory, dbHistory, GetStartOfQuarter(now), now);
			PeriodStatisticsResult periodStatisticsResult4 = CalculatePeriodStats(jsonHistory, dbHistory, new DateTime(now.Year, 1, 1), now);
			if (WeekScanCountText != null)
			{
				WeekScanCountText.Text = periodStatisticsResult.CurrentCount.ToString();
			}
			if (WeekVulnCountText != null)
			{
				WeekVulnCountText.Text = periodStatisticsResult.CurrentVulnCount.ToString();
			}
			if (WeekScanChangeText != null)
			{
				WeekScanChangeText.Text = FormatChange(periodStatisticsResult.CurrentCount, periodStatisticsResult.PreviousCount);
				WeekScanChangeText.Foreground = GetChangeBrush(periodStatisticsResult.ChangePercent);
			}
			if (MonthScanCountText != null)
			{
				MonthScanCountText.Text = periodStatisticsResult2.CurrentCount.ToString();
			}
			if (MonthVulnCountText != null)
			{
				MonthVulnCountText.Text = periodStatisticsResult2.CurrentVulnCount.ToString();
			}
			if (MonthScanChangeText != null)
			{
				MonthScanChangeText.Text = FormatChange(periodStatisticsResult2.CurrentCount, periodStatisticsResult2.PreviousCount);
				MonthScanChangeText.Foreground = GetChangeBrush(periodStatisticsResult2.ChangePercent);
			}
			if (QuarterScanCountText != null)
			{
				QuarterScanCountText.Text = periodStatisticsResult3.CurrentCount.ToString();
			}
			if (QuarterVulnCountText != null)
			{
				QuarterVulnCountText.Text = periodStatisticsResult3.CurrentVulnCount.ToString();
			}
			if (QuarterScanChangeText != null)
			{
				QuarterScanChangeText.Text = FormatChange(periodStatisticsResult3.CurrentCount, periodStatisticsResult3.PreviousCount);
				QuarterScanChangeText.Foreground = GetChangeBrush(periodStatisticsResult3.ChangePercent);
			}
			if (YearScanCountText != null)
			{
				YearScanCountText.Text = periodStatisticsResult4.CurrentCount.ToString();
			}
			if (YearVulnCountText != null)
			{
				YearVulnCountText.Text = periodStatisticsResult4.CurrentVulnCount.ToString();
			}
			if (YearScanChangeText != null)
			{
				YearScanChangeText.Text = FormatChange(periodStatisticsResult4.CurrentCount, periodStatisticsResult4.PreviousCount);
				YearScanChangeText.Foreground = GetChangeBrush(periodStatisticsResult4.ChangePercent);
			}
		}

		private PeriodStatisticsResult CalculatePeriodStats(List<ScanHistoryItem> jsonHistory, List<ScanHistory> dbHistory, DateTime startDate, DateTime endDate)
		{
			int num = Math.Max(1, (endDate - startDate).Days);
			DateTime previousStart = startDate.AddDays(-num);
			DateTime previousEnd = startDate.AddDays(-1.0);
			List<ScanHistoryItem> list = jsonHistory.Where((ScanHistoryItem h) => h != null && h.ScanTime >= startDate && h.ScanTime <= endDate).ToList();
			List<ScanHistory> list2 = dbHistory.Where((ScanHistory h) => h != null && h.StartTime >= startDate && h.StartTime <= endDate).ToList();
			List<ScanHistoryItem> list3 = jsonHistory.Where((ScanHistoryItem h) => h != null && h.ScanTime >= previousStart && h.ScanTime <= previousEnd).ToList();
			List<ScanHistory> list4 = dbHistory.Where((ScanHistory h) => h != null && h.StartTime >= previousStart && h.StartTime <= previousEnd).ToList();
			int num2 = list.Count + list2.Count;
			int num3 = list3.Count + list4.Count;
			int currentVulnCount = list.Sum((ScanHistoryItem h) => (h != null) ? h.VulnerabilitiesCount : 0) + list2.Sum((ScanHistory h) => (h != null) ? h.TotalVulnerabilities : 0);
			int currentPortCount = list2.Sum((ScanHistory h) => (h != null) ? h.OpenPorts : 0);
			double changePercent = ((num3 > 0) ? ((double)(num2 - num3) / (double)num3 * 100.0) : ((double)((num2 > 0) ? 100 : 0)));
			return new PeriodStatisticsResult
			{
				CurrentCount = num2,
				PreviousCount = num3,
				CurrentVulnCount = currentVulnCount,
				CurrentPortCount = currentPortCount,
				ChangePercent = changePercent
			};
		}

		private string FormatChange(int current, int previous)
		{
			if (previous == 0)
			{
				if (current <= 0)
				{
					return "无数据";
				}
				return "新增";
			}
			int num = current - previous;
			string value = ((num > 0) ? "↑" : "↓");
			double value2 = Math.Abs((double)num / (double)previous * 100.0);
			return $"{value}{Math.Abs(num)}次 ({value2:F0}%)";
		}

		private System.Windows.Media.Brush GetChangeBrush(double changePercent)
		{
			if (changePercent > 0.0)
			{
				return System.Windows.Media.Brushes.Green;
			}
			if (changePercent < 0.0)
			{
				return System.Windows.Media.Brushes.Red;
			}
			return System.Windows.Media.Brushes.Gray;
		}

