		private void RenderRiskDetails(string level, int count, int total, System.Windows.Media.Brush color)
		{
			double value = (double)count / (double)total * 100.0;
			StackPanel stackPanel = new StackPanel
			{
				Margin = new Thickness(0.0, 0.0, 0.0, 12.0)
			};
			StackPanel stackPanel2 = new StackPanel
			{
				Orientation = System.Windows.Controls.Orientation.Horizontal
			};
			Ellipse element = new Ellipse
			{
				Width = 10.0,
				Height = 10.0,
				Fill = color,
				Margin = new Thickness(0.0, 0.0, 8.0, 0.0)
			};
			stackPanel2.Children.Add(element);
			stackPanel2.Children.Add(new TextBlock
			{
				Text = level,
				FontWeight = FontWeights.SemiBold,
				Width = 40.0,
				VerticalAlignment = VerticalAlignment.Center
			});
			stackPanel2.Children.Add(new TextBlock
			{
				Text = $"{count} ({value:F1}%)",
				Foreground = System.Windows.Media.Brushes.Gray,
				VerticalAlignment = VerticalAlignment.Center
			});
			stackPanel.Children.Add(stackPanel2);
			System.Windows.Controls.ProgressBar element2 = new System.Windows.Controls.ProgressBar
			{
				Height = 20.0,
				Maximum = 100.0,
				Value = value,
				Background = System.Windows.Media.Brushes.LightGray,
				Foreground = color
			};
			stackPanel.Children.Add(element2);
			RiskDistributionPanel?.Children.Add(stackPanel);
		}

