		private void RenderTopVulnerabilities(List<ScanHistoryItem> jsonHistory, List<ScanHistory> dbHistory)
		{
			Dictionary<string, (int, string, string)> dictionary = new Dictionary<string, (int, string, string)>();
			foreach (ScanHistory item2 in dbHistory ?? new List<ScanHistory>())
			{
				if (((item2 != null) ? item2.Vulnerabilities : null) == null)
				{
					continue;
				}
				foreach (VulnerabilityRecord vulnerability in item2.Vulnerabilities)
				{
					if (vulnerability != null)
					{
						string key = vulnerability.Name ?? vulnerability.CveId ?? "Unknown";
						if (dictionary.ContainsKey(key))
						{
							int item = dictionary[key].Item1;
							dictionary[key] = (item + 1, vulnerability.RiskLevel ?? "Unknown", vulnerability.CveId ?? "");
						}
						else
						{
							dictionary[key] = (1, vulnerability.RiskLevel ?? "Unknown", vulnerability.CveId ?? "");
						}
					}
				}
			}
			List<TopVulnerabilityItem> itemsSource = dictionary.OrderByDescending<KeyValuePair<string, (int, string, string)>, int>((KeyValuePair<string, (int Count, string RiskLevel, string CveId)> kvp) => kvp.Value.Count).Take(15).Select<KeyValuePair<string, (int, string, string)>, TopVulnerabilityItem>((KeyValuePair<string, (int Count, string RiskLevel, string CveId)> kvp, int index) => new TopVulnerabilityItem
			{
				Rank = index + 1,
				Name = kvp.Key,
				Count = kvp.Value.Count,
				RiskLevel = kvp.Value.RiskLevel,
				CveId = kvp.Value.CveId
			})
				.ToList();
			if (TopVulnerabilitiesDataGrid != null)
			{
				TopVulnerabilitiesDataGrid.ItemsSource = itemsSource;
			}
			RenderVulnTypeChart(dictionary);
		}

