		private void RenderServiceDistribution(List<ScanHistoryItem> jsonHistory, List<ScanHistory> dbHistory)
		{
			ServiceDistributionPanel?.Children.Clear();
			Dictionary<string, int> dictionary = new Dictionary<string, int>();
			foreach (ScanHistory item in dbHistory ?? new List<ScanHistory>())
			{
				if (((item != null) ? item.Vulnerabilities : null) == null)
				{
					continue;
				}
				foreach (VulnerabilityRecord vulnerability in item.Vulnerabilities)
				{
					if (vulnerability != null)
					{
						string key = (string.IsNullOrEmpty(vulnerability.Service) ? "Unknown" : vulnerability.Service);
						if (dictionary.ContainsKey(key))
						{
							dictionary[key]++;
						}
						else
						{
							dictionary[key] = 1;
						}
					}
				}
			}
			IEnumerable<KeyValuePair<string, int>> enumerable = dictionary.OrderByDescending((KeyValuePair<string, int> kvp) => kvp.Value).Take(15);
			int num = dictionary.Values.Sum();
			if (num == 0)
			{
				num = 1;
			}
			foreach (KeyValuePair<string, int> item2 in enumerable)
			{
				double value = (double)item2.Value / (double)num * 100.0;
				StackPanel stackPanel = new StackPanel
				{
					Margin = new Thickness(0.0, 0.0, 0.0, 8.0)
				};
				StackPanel stackPanel2 = new StackPanel
				{
					Orientation = System.Windows.Controls.Orientation.Horizontal
				};
				stackPanel2.Children.Add(new TextBlock
				{
					Text = item2.Key,
					FontWeight = FontWeights.SemiBold,
					Width = 120.0
				});
				stackPanel2.Children.Add(new TextBlock
				{
					Text = $"{item2.Value} ({value:F1}%)",
					Foreground = System.Windows.Media.Brushes.Gray
				});
				stackPanel.Children.Add(stackPanel2);
				System.Windows.Controls.ProgressBar element = new System.Windows.Controls.ProgressBar
				{
					Height = 15.0,
					Maximum = 100.0,
					Value = value,
					Background = System.Windows.Media.Brushes.LightGray,
					Foreground = System.Windows.Media.Brushes.SteelBlue
				};
				stackPanel.Children.Add(element);
				ServiceDistributionPanel?.Children.Add(stackPanel);
			}
		}

		private void RenderScanHistory(List<ScanHistoryItem> jsonHistory, List<ScanHistory> dbHistory)
		{
			List<ScanHistoryRecord> list = new List<ScanHistoryRecord>();
			foreach (ScanHistoryItem item in (jsonHistory ?? new List<ScanHistoryItem>()).OrderByDescending((ScanHistoryItem h) => (h == null) ? null : new DateTime?(h.ScanTime)))
			{
				if (item != null)
				{
					list.Add(new ScanHistoryRecord
					{
						ScanTime = item.ScanTime,
						TargetIp = (item.TargetIp ?? ""),
						ScanType = (item.ScanType ?? ""),
						OpenPortsCount = 0,
						VulnerabilitiesCount = item.VulnerabilitiesCount,
						RiskLevel = (item.RiskLevel ?? ""),
						ScanId = (item.ScanId ?? "")
					});
				}
			}
			foreach (ScanHistory item2 in (dbHistory ?? new List<ScanHistory>()).OrderByDescending((ScanHistory h) => (h == null) ? null : new DateTime?(h.StartTime)))
			{
				if (item2 != null)
				{
					list.Add(new ScanHistoryRecord
					{
						ScanTime = item2.StartTime,
						TargetIp = (item2.Target ?? ""),
						ScanType = (item2.ScanMode ?? ""),
						OpenPortsCount = item2.OpenPorts,
						VulnerabilitiesCount = item2.TotalVulnerabilities,
						RiskLevel = GetRiskLevel(item2),
						ScanId = (item2.ScanId ?? "")
					});
				}
			}
			if (ScanHistoryDataGrid != null)
			{
				ScanHistoryDataGrid.ItemsSource = list.OrderByDescending((ScanHistoryRecord h) => h.ScanTime).ToList();
			}
		}

		private string GetRiskLevel(ScanHistory history)
		{
			if (history == null)
			{
				return "信息";
			}
			if (history.CriticalCount > 0)
			{
				return "严重";
			}
			if (history.HighCount > 0)
			{
				return "高";
			}
			if (history.MediumCount > 0)
			{
				return "中";
			}
			if (history.LowCount > 0)
			{
				return "低";
			}
			return "信息";
		}

