		private async void RenderTimeDimensionAnalysis()
		{
			_ = 1;
			try
			{
				List<ScanHistoryItem> jsonHistory = await SafeGetJsonHistory();
				List<ScanHistory> dbHistory = await SafeGetDbHistory();
				RenderTimeDimensionCards(jsonHistory, dbHistory);
				RenderTimeDimensionTrendChart(jsonHistory, dbHistory);
				RenderComparisonChart(jsonHistory, dbHistory);
			}
			catch
			{
			}
		}

		private void RenderTimeDimensionCards(List<ScanHistoryItem> jsonHistory, List<ScanHistory> dbHistory)
		{
			DateTime now = DateTime.Now;
			PeriodStatisticsResult periodStatisticsResult = CalculatePeriodStats(jsonHistory, dbHistory, now.Date, now);
			PeriodStatisticsResult periodStatisticsResult2 = CalculatePeriodStats(jsonHistory, dbHistory, GetStartOfWeek(now), now);
			PeriodStatisticsResult periodStatisticsResult3 = CalculatePeriodStats(jsonHistory, dbHistory, new DateTime(now.Year, now.Month, 1), now);
			PeriodStatisticsResult periodStatisticsResult4 = CalculatePeriodStats(jsonHistory, dbHistory, GetStartOfQuarter(now), now);
			PeriodStatisticsResult periodStatisticsResult5 = CalculatePeriodStats(jsonHistory, dbHistory, new DateTime(now.Year, 1, 1), now);
			if (DayScanCountText != null)
			{
				DayScanCountText.Text = periodStatisticsResult.CurrentCount.ToString();
			}
			if (DayVulnCountText != null)
			{
				DayVulnCountText.Text = periodStatisticsResult.CurrentVulnCount.ToString();
			}
			if (DayChangeText != null)
			{
				PeriodStatisticsResult periodStatisticsResult6 = CalculatePeriodStats(jsonHistory, dbHistory, now.Date.AddDays(-1.0), now.Date.AddDays(-1.0));
				DayChangeText.Text = FormatGrowth(periodStatisticsResult.CurrentCount, periodStatisticsResult6.CurrentCount);
				DayChangeText.Foreground = GetChangeBrush(periodStatisticsResult.ChangePercent);
			}
			if (WeekPeriodScanCountText != null)
			{
				WeekPeriodScanCountText.Text = periodStatisticsResult2.CurrentCount.ToString();
			}
			if (WeekPeriodVulnCountText != null)
			{
				WeekPeriodVulnCountText.Text = periodStatisticsResult2.CurrentVulnCount.ToString();
			}
			if (WeekPeriodChangeText != null)
			{
				WeekPeriodChangeText.Text = FormatGrowth(periodStatisticsResult2.CurrentCount, periodStatisticsResult2.PreviousCount);
				WeekPeriodChangeText.Foreground = GetChangeBrush(periodStatisticsResult2.ChangePercent);
			}
			if (MonthPeriodScanCountText != null)
			{
				MonthPeriodScanCountText.Text = periodStatisticsResult3.CurrentCount.ToString();
			}
			if (MonthPeriodVulnCountText != null)
			{
				MonthPeriodVulnCountText.Text = periodStatisticsResult3.CurrentVulnCount.ToString();
			}
			if (MonthPeriodChangeText != null)
			{
				MonthPeriodChangeText.Text = FormatGrowth(periodStatisticsResult3.CurrentCount, periodStatisticsResult3.PreviousCount);
				MonthPeriodChangeText.Foreground = GetChangeBrush(periodStatisticsResult3.ChangePercent);
			}
			if (QuarterPeriodScanCountText != null)
			{
				QuarterPeriodScanCountText.Text = periodStatisticsResult4.CurrentCount.ToString();
			}
			if (QuarterPeriodVulnCountText != null)
			{
				QuarterPeriodVulnCountText.Text = periodStatisticsResult4.CurrentVulnCount.ToString();
			}
			if (QuarterPeriodChangeText != null)
			{
				QuarterPeriodChangeText.Text = FormatGrowth(periodStatisticsResult4.CurrentCount, periodStatisticsResult4.PreviousCount);
				QuarterPeriodChangeText.Foreground = GetChangeBrush(periodStatisticsResult4.ChangePercent);
			}
			if (YearPeriodScanCountText != null)
			{
				YearPeriodScanCountText.Text = periodStatisticsResult5.CurrentCount.ToString();
			}
			if (YearPeriodVulnCountText != null)
			{
				YearPeriodVulnCountText.Text = periodStatisticsResult5.CurrentVulnCount.ToString();
			}
			if (YearPeriodChangeText != null)
			{
				PeriodStatisticsResult periodStatisticsResult7 = CalculatePeriodStats(jsonHistory, dbHistory, new DateTime(now.Year - 1, 1, 1), new DateTime(now.Year - 1, 12, 31));
				YearPeriodChangeText.Text = FormatGrowth(periodStatisticsResult5.CurrentCount, periodStatisticsResult7.CurrentCount);
				YearPeriodChangeText.Foreground = GetChangeBrush(periodStatisticsResult5.ChangePercent);
			}
		}

		private string FormatGrowth(int current, int previous)
		{
			if (previous == 0)
			{
				if (current <= 0)
				{
					return "--";
				}
				return "↑ 新增";
			}
			double num = (double)(current - previous) / (double)previous * 100.0;
			if (num > 0.0)
			{
				return $"↑ {num:F0}%";
			}
			if (num < 0.0)
			{
				return $"↓ {Math.Abs(num):F0}%";
			}
			return "持平";
		}

