				HashSet<string> hashSet = (from u in DisplayUsers
					where u.IsSelected
					select u.Username).ToHashSet();
				_allDisplayUsers = _pendingUsers.Select(PendingUserItem.FromUser).ToList();
				foreach (PendingUserItem allDisplayUser in _allDisplayUsers)
				{
					if (hashSet.Contains(allDisplayUser.Username))
					{
						allDisplayUser.IsSelected = true;
					}
				}
				ApplySearchFilter();
				EmptyHint.Visibility = ((_allDisplayUsers.Count != 0) ? Visibility.Collapsed : Visibility.Visible);
				if (!string.IsNullOrEmpty(prevSelectedUsername))
				{
					PendingUserItem pendingUserItem = DisplayUsers.FirstOrDefault((PendingUserItem u) => u.Username == prevSelectedUsername);
					if (pendingUserItem != null)
					{
						PendingUsersDataGrid.SelectedItem = pendingUserItem;
						PendingUsersDataGrid.ScrollIntoView(pendingUserItem);
					}
				}
				UpdateInfoText();
				UpdateButtonsState();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("加载待审核用户失败：" + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private void ApplySearchFilter()
		{
			DisplayUsers.Clear();
			string text = SearchTextBox?.Text?.Trim() ?? "";
			IEnumerable<PendingUserItem> enumerable = _allDisplayUsers;
			if (!string.IsNullOrEmpty(text))
			{
				string kw = text.ToLower();
				enumerable = _allDisplayUsers.Where(delegate(PendingUserItem u)
				{
					string username = u.Username;
					if (username == null || !username.ToLower().Contains(kw))
					{
						string displayName = u.DisplayName;
						if (displayName == null || !displayName.ToLower().Contains(kw))
						{
							string email = u.Email;
							if (email == null || !email.ToLower().Contains(kw))
							{
								return u.Phone?.Contains(kw) ?? false;
							}
						}
					}
					return true;
				});
			}
			foreach (PendingUserItem item in enumerable)
			{
				DisplayUsers.Add(item);
			}
		}

		private void SearchTextBox_TextChanged(object sender, TextChangedEventArgs e)
		{
			ApplySearchFilter();
			UpdateInfoText();
			UpdateButtonsState();
		}

		private void UpdateInfoText()
		{
			if (InfoText != null)
			{
				User current = SessionContext.Instance.Current;
				int num = DisplayUsers.Count((PendingUserItem u) => u.IsSelected);
				string text = ((current == null) ? "" : $"审核者: {current.DisplayName} ({current.Username})  ·  待审 {DisplayUsers.Count}/{_allDisplayUsers.Count} 人");
				string text2 = ((num > 0) ? $"  ·  已勾选 {num}" : "");
				string text3 = ((!string.IsNullOrEmpty(SearchTextBox?.Text)) ? "  ·  \ud83d\udd0d 过滤中" : "");
				InfoText.Text = text + text2 + text3;
			}
		}

		private void UpdateButtonsState()
		{
			int num = DisplayUsers.Count((PendingUserItem u) => u.IsSelected);
			BatchApproveButton.IsEnabled = num > 0;
			BatchRejectButton.IsEnabled = num > 0;
			PendingUserItem pendingUserItem = PendingUsersDataGrid.SelectedItem as PendingUserItem;
			bool isEnabled = pendingUserItem != null || num > 0;
			ApproveButton.IsEnabled = isEnabled;
			RejectButton.IsEnabled = isEnabled;
			if (pendingUserItem != null)
			{
				SelectedUserText.Text = $"为 [{pendingUserItem.Username} ({pendingUserItem.DisplayName})] 分配权限";
			}
			else if (num > 0)
			{
				SelectedUserText.Text = $"已勾选 {num} 个用户（点击「批量批准」/「批量拒绝」应用当前权限）";
			}
			else
			{
				SelectedUserText.Text = "请在左侧选择或勾选待审用户";
			}
		}

