		private async void ApproveButton_Click(object sender, RoutedEventArgs e)
		{
			PendingUserItem single = (PendingUsersDataGrid.SelectedItem as PendingUserItem) ?? DisplayUsers.FirstOrDefault((PendingUserItem u) => u.IsSelected);
			if (single == null)
			{
				System.Windows.MessageBox.Show("请先选中一行或勾选一个用户。", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			List<string> list = CollectCheckedPermissions();
			if (list.Count == 0)
			{
				System.Windows.MessageBox.Show("请至少勾选一项权限。", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			ApproveButton.IsEnabled = false;
			try
			{
				User current = SessionContext.Instance.Current;
				if (await _authService.ApproveUserAsync(current.Username, single.Username, list))
				{
					StatusBarText.Text = $"✅ 已批准 [{single.Username}]  ·  {DateTime.Now:HH:mm:ss}";
					RemarkTextBox.Clear();
					LoadPendingUsers();
				}
				else
				{
					System.Windows.MessageBox.Show("批准失败。", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("批准失败：" + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
			ApproveButton.IsEnabled = true;
		}

