			if (single == null || System.Windows.MessageBox.Show($"确定拒绝 [{single.Username} ({single.DisplayName})] 的注册申请吗？\n该用户将被禁用。", "确认拒绝", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes)
