		private async void BatchApproveButton_Click(object sender, RoutedEventArgs e)
		{
			List<PendingUserItem> targets = DisplayUsers.Where((PendingUserItem u) => u.IsSelected).ToList();
			if (targets.Count == 0)
			{
				return;
			}
			List<string> list = CollectCheckedPermissions();
			if (list.Count == 0)
			{
				System.Windows.MessageBox.Show("请至少勾选一项权限。", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
			}
			else
			{
				if (System.Windows.MessageBox.Show($"确定批量批准 {targets.Count} 个用户并授予 {list.Count} 项权限？\n\n将使用：{string.Join(", ", list)}", "确认批量批准", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes)
				{
					return;
				}
				BatchApproveButton.IsEnabled = false;
				try
				{
					User current = SessionContext.Instance.Current;
					List<string> list2 = targets.Select((PendingUserItem t) => t.Username).ToList();
					int value = await _authService.BatchApproveAsync(current.Username, list2, list);
					StatusBarText.Text = $"✅ 批量批准 {value}/{targets.Count} 个用户  ·  {DateTime.Now:HH:mm:ss}";
					RemarkTextBox.Clear();
					LoadPendingUsers();
				}
				catch (Exception ex)
				{
					System.Windows.MessageBox.Show("批量批准失败：" + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				}
				BatchApproveButton.IsEnabled = true;
			}
		}

		private async void BatchRejectButton_Click(object sender, RoutedEventArgs e)
