		private void ExportCsvButton_Click(object sender, RoutedEventArgs e)
		{
			if (DisplayUsers.Count == 0)
			{
				System.Windows.MessageBox.Show("当前列表为空,无可导出数据。", "导出 CSV", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Title = "导出待审用户为 CSV",
				FileName = $"pending_users_{DateTime.Now:yyyyMMdd_HHmmss}.csv",
				DefaultExt = ".csv",
				Filter = "CSV 文件 (*.csv)|*.csv|所有文件 (*.*)|*.*"
			};
			if (saveFileDialog.ShowDialog(this) != true)
			{
				return;
			}
			try
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.AppendLine("用户名,显示名,邮箱,手机,申请说明,创建时间,等待时长(分钟)");
				foreach (PendingUserItem displayUser in DisplayUsers)
				{
					string text = ((displayUser.CreatedAt > DateTime.MinValue) ? ((int)(DateTime.Now - displayUser.CreatedAt).TotalMinutes).ToString() : "");
					stringBuilder.AppendLine(string.Join(",", CsvEscape(displayUser.Username), CsvEscape(displayUser.DisplayName), CsvEscape(displayUser.Email), CsvEscape(displayUser.Phone), CsvEscape(displayUser.ReasonShort), (displayUser.CreatedAt == DateTime.MinValue) ? "" : displayUser.CreatedAt.ToString("yyyy-MM-dd HH:mm:ss"), text));
				}
				File.WriteAllText(saveFileDialog.FileName, "\ufeff" + stringBuilder.ToString(), new UTF8Encoding(encoderShouldEmitUTF8Identifier: true));
				System.Windows.MessageBox.Show($"✅ 已导出 {DisplayUsers.Count} 个用户到\n{saveFileDialog.FileName}", "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				StatusBarText.Text = $"\ud83d\udcca 已导出 CSV: {DisplayUsers.Count} 行 → {System.IO.Path.GetFileName(saveFileDialog.FileName)}";
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("导出失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private static string CsvEscape(string? value)
		{
			if (string.IsNullOrEmpty(value))
			{
				return "";
			}
			if (value.Contains(',') || value.Contains('"') || value.Contains('\n') || value.Contains('\r'))
			{
				return "\"" + value.Replace("\"", "\"\"") + "\"";
			}
			return value;
		}

