	public class PendingUserItem : INotifyPropertyChanged
	{
		private bool _isSelected;

		public string Username { get; set; } = "";


		public string DisplayName { get; set; } = "";


		public string Email { get; set; } = "";


		public string Phone { get; set; } = "";


		public string Reason { get; set; } = "";


		public DateTime CreatedAt { get; set; }

		public bool IsSelected
		{
			get
			{
				return _isSelected;
			}
			set
			{
				if (_isSelected != value)
				{
					_isSelected = value;
					OnPropertyChanged("IsSelected");
				}
			}
		}

		public string WaitDurationDisplay
		{
			get
			{
				TimeSpan timeSpan = DateTime.Now - CreatedAt;
				if (timeSpan.TotalMinutes < 1.0)
				{
					return "刚刚";
				}
				if (!(timeSpan.TotalHours < 1.0))
				{
					if (!(timeSpan.TotalDays < 1.0))
					{
						return $"{(int)timeSpan.TotalDays} 天";
					}
					return $"{(int)timeSpan.TotalHours} 小时";
				}
				return $"{(int)timeSpan.TotalMinutes} 分钟";
			}
		}

		public string ReasonShort
		{
			get
			{
				if (string.IsNullOrWhiteSpace(Reason))
				{
					return "—";
				}
				string text = Reason.Replace("\r", " ").Replace("\n", " ").Trim();
				if (text.Length <= 30)
				{
					return text;
				}
				return text.Substring(0, 30) + "…";
			}
		}

		public event PropertyChangedEventHandler? PropertyChanged;

		public static PendingUserItem FromUser(User u)
		{
			return new PendingUserItem
			{
				Username = u.Username,
				DisplayName = (u.DisplayName ?? ""),
				Email = (u.Email ?? "—"),
				Phone = (u.Phone ?? "—"),
				Reason = (u.Reason ?? ""),
				CreatedAt = u.CreatedAt
			};
		}

		private void OnPropertyChanged([CallerMemberName] string? n = null)
		{
			this.PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(n));
		}
	}
