				{
					("最后登录", val.LastLoginAt.HasValue ? val.LastLoginAt.Value.ToString("yyyy-MM-dd HH:mm:ss") : "—"),
					("失败次数", val.FailedAttempts.ToString()),
					("锁定到期", val.LockoutUntil.HasValue ? val.LockoutUntil.Value.ToString("yyyy-MM-dd HH:mm:ss") : "—")
				});
				if (val.IsAdmin)
				{
					AddSection("\ud83d\udd11 权限", new(string, string)[1] { ("权限范围", "✅ 全部 10 项权限（管理员内置）") });
				}
				else
				{
					List<string> list = val.Permissions ?? new List<string>();
					string text = ((list.Count == 0) ? "⚠\ufe0f 尚未授予任何权限" : string.Join("\n• ", new string[1] { "" }.Concat(list)));
					AddSection("\ud83d\udd11 权限", new(string, string)[1] { ("已授予", text.TrimStart('\n').TrimStart(' ')) });
				}
				AddSection("\ud83d\udcdd 审计追踪", new(string, string)[4]
				{
