			}
		}

		private void AddSection(string title, (string label, string value)[] rows)
		{
			TextBlock element = new TextBlock
			{
				Text = title,
				FontSize = 14.0,
				FontWeight = FontWeights.Bold,
				Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(45, 52, 54)),
				Margin = new Thickness(0.0, 12.0, 0.0, 8.0)
			};
			DetailPanel.Children.Add(element);
			Border border = new Border
			{
				Background = System.Windows.Media.Brushes.White,
				CornerRadius = new CornerRadius(6.0),
				BorderBrush = new SolidColorBrush(System.Windows.Media.Color.FromRgb(223, 230, 233)),
				BorderThickness = new Thickness(1.0),
				Padding = new Thickness(14.0, 10.0, 14.0, 10.0),
				Margin = new Thickness(0.0, 0.0, 0.0, 0.0)
			};
			StackPanel stackPanel = new StackPanel();
			for (int i = 0; i < rows.Length; i++)
			{
				(string label, string value) tuple = rows[i];
				string item = tuple.label;
				string item2 = tuple.value;
				Grid grid = new Grid();
				grid.ColumnDefinitions.Add(new ColumnDefinition
				{
					Width = new GridLength(110.0)
				});
				grid.ColumnDefinitions.Add(new ColumnDefinition
				{
					Width = new GridLength(1.0, GridUnitType.Star)
				});
				TextBlock element2 = new TextBlock
				{
					Text = item,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(99, 110, 114)),
					FontWeight = FontWeights.SemiBold
				};
				Grid.SetColumn(element2, 0);
				grid.Children.Add(element2);
				TextBlock element3 = new TextBlock
				{
					Text = item2,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(45, 52, 54)),
					TextWrapping = TextWrapping.Wrap,
					FontFamily = new System.Windows.Media.FontFamily("Consolas, Courier New")
				};
				Grid.SetColumn(element3, 1);
				grid.Children.Add(element3);
				stackPanel.Children.Add(grid);
			}
			border.Child = stackPanel;
			DetailPanel.Children.Add(border);
		}

