		private void UserManagementWindow_Loaded(object sender, RoutedEventArgs e)
		{
			User current = SessionContext.Instance.Current;
			string value = ((current == null) ? "未登录" : (current.DisplayName + " (" + current.Username + ")"));
			bool flag = current != null && current.IsAdmin;
			InfoText.Text = $"查看者: {value}  ·  共 {LoadAllUsers()} 个账号{(flag ? "  ·  可双击行编辑权限" : string.Empty)}";
			if (!flag)
			{
				HintText.Visibility = Visibility.Collapsed;
			}
			ApplyFilter();
		}

		private int LoadAllUsers()
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			try
			{
				AuthService val = new AuthService();
				_allUsers = new List<UserDisplayItem>();
				foreach (User allUser in val.GetAllUsers())
				{
					_allUsers.Add(UserDisplayItem.FromUser(allUser));
				}
				return _allUsers.Count;
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("加载账号列表失败：" + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				return 0;
			}
		}

		private void ApplyFilter()
		{
			string keyword = SearchTextBox?.Text?.Trim() ?? "";
			string text = (StatusFilterCombo?.SelectedItem as ComboBoxItem)?.Content?.ToString() ?? "全部";
			IEnumerable<UserDisplayItem> source = _allUsers;
			if (!string.IsNullOrEmpty(keyword))
			{
				source = source.Where((UserDisplayItem u) => (u.Username ?? "").Contains(keyword, StringComparison.OrdinalIgnoreCase) || (u.DisplayName ?? "").Contains(keyword, StringComparison.OrdinalIgnoreCase));
			}
			if (text != "全部")
			{
				UserStatus? wantStatus = text switch
				{
					"⏳ 待审" => (UserStatus)0, 
					"✅ 正常" => (UserStatus)1, 
					"\ud83d\udeab 禁用" => (UserStatus)2, 
					_ => null, 
				};
				if (wantStatus.HasValue)
				{
					source = source.Where((UserDisplayItem u) => u.Status == wantStatus.Value);
				}
			}
			List<UserDisplayItem> list = source.ToList();
			UsersDataGrid.ItemsSource = list;
			FilterStatusText.Text = ((keyword == "" && text == "全部") ? "" : $"筛选后 {list.Count} / {_allUsers.Count}");
		}

