		private void UsersDataGrid_MouseDoubleClick(object sender, MouseButtonEventArgs e)
		{
			//IL_0049: Unknown result type (might be due to invalid IL or missing references)
			//IL_004f: Invalid comparison between Unknown and I4
			User current = SessionContext.Instance.Current;
			if (current == null || !current.IsAdmin || !(UsersDataGrid.SelectedItem is UserDisplayItem userDisplayItem))
			{
				return;
			}
			if (userDisplayItem.IsAdmin)
			{
				System.Windows.MessageBox.Show("超级管理员的权限不允许修改。", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			if ((int)userDisplayItem.Status != 1)
			{
				System.Windows.MessageBox.Show($"用户 [{userDisplayItem.Username}] 当前状态为 {userDisplayItem.StatusText}，不能直接编辑权限。\nPending 请通过「用户审核」处理；Disabled 请先重新启用。", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			try
			{
				if (new UserPermissionEditWindow(userDisplayItem.Username)
				{
					Owner = this
				}.ShowDialog() == true)
				{
					UserManagementWindow_Loaded(this, new RoutedEventArgs());
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("打开权限编辑窗口失败：" + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
