	public class UserPermissionEditWindow : Window, IComponentConnector, IStyleConnector
	{
		private readonly AuthService _authService;

		private readonly string _targetUsername;

		internal TextBlock HeaderText;

		internal System.Windows.Controls.Button SelectAllButton;

		internal System.Windows.Controls.Button SelectNoneButton;

		internal System.Windows.Controls.Button SelectViewOnlyButton;

		internal TextBlock SelectedCountText;

		internal ItemsControl PermissionsItemsControl;

		internal System.Windows.Controls.Button SaveButton;

		internal System.Windows.Controls.Button CancelButton;

		private bool _contentLoaded;

		public ObservableCollection<PermissionCheckItem> PermissionItems { get; } = new ObservableCollection<PermissionCheckItem>();


		public UserPermissionEditWindow(string targetUsername)
		{
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Expected O, but got Unknown
			InitializeComponent();
			_authService = new AuthService();
			_targetUsername = targetUsername;
			base.Loaded += UserPermissionEditWindow_Loaded;
		}

		private void UserPermissionEditWindow_Loaded(object sender, RoutedEventArgs e)
		{
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			User current = SessionContext.Instance.Current;
			if (current == null || !current.IsAdmin)
			{
				System.Windows.MessageBox.Show("此功能仅限管理员使用。", "权限不足", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				Close();
				return;
			}
			User val = ((IEnumerable<User>)new AuthService().GetAllUsers()).FirstOrDefault((Func<User, bool>)((User u) => string.Equals(u.Username, _targetUsername, StringComparison.OrdinalIgnoreCase)));
			if (val == null)
			{
				System.Windows.MessageBox.Show("未找到用户 [" + _targetUsername + "]。", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				Close();
				return;
			}
			HeaderText.Text = $"正在为 [{val.DisplayName} ({val.Username})] 配置权限";
			HashSet<string> hashSet = new HashSet<string>(val.Permissions ?? new List<string>(), StringComparer.OrdinalIgnoreCase);
			for (int i = 0; i < Permission.AllPermissions.Count; i++)
			{
				string text = Permission.AllPermissions[i];
				PermissionItems.Add(new PermissionCheckItem
				{
					Key = text,
					Label = Permission.AllPermissionLabels[i],
					IsChecked = hashSet.Contains(text)
				});
			}
			PermissionsItemsControl.ItemsSource = PermissionItems;
			UpdateSelectedCount();
		}

		private void UpdateSelectedCount()
		{
			int value = PermissionItems.Count((PermissionCheckItem p) => p.IsChecked);
			SelectedCountText.Text = $"已选 {value} / {PermissionItems.Count} 项";
		}

		private void PermissionCheck_Changed(object sender, RoutedEventArgs e)
		{
			UpdateSelectedCount();
		}

		private void SelectAllButton_Click(object sender, RoutedEventArgs e)
		{
			foreach (PermissionCheckItem permissionItem in PermissionItems)
			{
				permissionItem.IsChecked = true;
			}
			UpdateSelectedCount();
		}

		private void SelectNoneButton_Click(object sender, RoutedEventArgs e)
		{
			foreach (PermissionCheckItem permissionItem in PermissionItems)
			{
				permissionItem.IsChecked = false;
			}
			UpdateSelectedCount();
		}

		private void SelectViewOnlyButton_Click(object sender, RoutedEventArgs e)
		{
			foreach (PermissionCheckItem permissionItem in PermissionItems)
			{
				permissionItem.IsChecked = permissionItem.Key == "Asset:View";
			}
			UpdateSelectedCount();
		}

		private async void SaveButton_Click(object sender, RoutedEventArgs e)
		{
			User current = SessionContext.Instance.Current;
			if (current == null || !current.IsAdmin)
			{
				return;
			}
			List<string> perms = (from p in PermissionItems
				where p.IsChecked
				select p.Key).ToList();
			if (!perms.Contains("Asset:View") && System.Windows.MessageBox.Show("当前未勾选「资产查看」。用户将无法看到任何资产。\n是否继续保存？", "确认", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes)
			{
				return;
			}
			SaveButton.IsEnabled = false;
			try
			{
				if (await _authService.SetUserPermissionsAsync(current.Username, _targetUsername, perms))
				{
					System.Windows.MessageBox.Show($"已保存 [{_targetUsername}] 的权限，共 {perms.Count} 项。", "成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					base.DialogResult = true;
					Close();
				}
				else
				{
					System.Windows.MessageBox.Show("保存失败，请检查目标用户状态。", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
					SaveButton.IsEnabled = true;
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("保存失败：" + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				SaveButton.IsEnabled = true;
			}
		}

		private void CancelButton_Click(object sender, RoutedEventArgs e)
		{
			base.DialogResult = false;
			Close();
		}

