		private void ValidateInputs()
		{
			string text = DisplayNameTextBox.Text?.Trim() ?? "";
			string value = OldPasswordBox.Password ?? "";
			string text2 = NewPasswordBox.Password ?? "";
			string text3 = ConfirmPasswordBox.Password ?? "";
			DisplayNameErrorText.Text = (string.IsNullOrWhiteSpace(text) ? "显示名称不能为空" : ((text.Length > 32) ? "显示名称不能超过 32 字符" : ""));
			OldPasswordErrorText.Text = (string.IsNullOrEmpty(value) ? "请输入当前密码" : "");
			bool flag = !string.IsNullOrEmpty(text2);
			NewPasswordErrorText.Text = ((flag && text2.Length < 6) ? "新密码至少 6 位" : "");
			ConfirmPasswordErrorText.Text = ((flag && text2 != text3) ? "两次输入的密码不一致" : "");
			SaveButton.IsEnabled = !string.IsNullOrWhiteSpace(text) && text.Length <= 32 && !string.IsNullOrEmpty(value) && (!flag || (text2.Length >= 6 && text2 == text3));
		}

		private async void SaveButton_Click(object sender, RoutedEventArgs e)
		{
			SaveButton.IsEnabled = false;
			try
			{
				string text = DisplayNameTextBox.Text.Trim();
				string oldPwd = OldPasswordBox.Password;
				string newPwd = NewPasswordBox.Password;
				if (!(await _authService.UpdateDisplayNameAsync(_username, text)))
				{
					System.Windows.MessageBox.Show("修改显示名失败。", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
					SaveButton.IsEnabled = true;
					return;
				}
				if (!string.IsNullOrEmpty(newPwd))
				{
					ChangePasswordResult val = await _authService.ChangePasswordAsync(_username, oldPwd, newPwd);
					if (!val.IsSuccess)
					{
						System.Windows.MessageBox.Show("密码修改失败：" + val.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
						SaveButton.IsEnabled = true;
						return;
					}
				}
				System.Windows.MessageBox.Show("个人资料保存成功！", "成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				base.DialogResult = true;
				Close();
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("保存失败：" + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				SaveButton.IsEnabled = true;
			}
		}

