		private void InitializePaths()
		{
			string text = System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "NetSecurityScanner");
			Directory.CreateDirectory(text);
			_logFilePath = System.IO.Path.Combine(text, "update_log.txt");
			_updateHistoryPath = System.IO.Path.Combine(text, "update_history.json");
			_settingsPath = System.IO.Path.Combine(text, "update_settings.json");
		}

		private void LoadSettings()
		{
			try
			{
				if (File.Exists(_settingsPath))
				{
					string json = File.ReadAllText(_settingsPath);
					_settings = JsonSerializer.Deserialize<UpdateSettings>(json);
				}
			}
			catch
			{
				_settings = new UpdateSettings();
			}
			if (_settings == null)
			{
				_settings = new UpdateSettings();
			}
			NvdEnabledCheckBox.IsChecked = _settings.NvdEnabled;
			CnnvdEnabledCheckBox.IsChecked = _settings.CnnvdEnabled;
			CncertEnabledCheckBox.IsChecked = _settings.CncertEnabled;
			IncrementalUpdateRadio.IsChecked = _settings.IncrementalUpdate;
			FullUpdateRadio.IsChecked = !_settings.IncrementalUpdate;
		}

		private void SaveSettings()
		{
			try
			{
				_settings.NvdEnabled = NvdEnabledCheckBox.IsChecked == true;
				_settings.CnnvdEnabled = CnnvdEnabledCheckBox.IsChecked == true;
				_settings.CncertEnabled = CncertEnabledCheckBox.IsChecked == true;
				_settings.IncrementalUpdate = IncrementalUpdateRadio.IsChecked == true;
				string contents = JsonSerializer.Serialize(_settings, new JsonSerializerOptions
				{
					WriteIndented = true
				});
				File.WriteAllText(_settingsPath, contents);
			}
			catch
			{
			}
		}

