			foreach (UpdateHistoryRecord item in _history)
			{
				num += item.NewCount + item.UpdatedCount;
			}
			TotalVulnsText.Text = num.ToString();
			int num2 = _history.Where((UpdateHistoryRecord h) => h.UpdateTime.Date == DateTime.Now.Date).ToList().Sum((UpdateHistoryRecord h) => h.NewCount + h.UpdatedCount);
			TodayUpdatesText.Text = num2.ToString();
