		private async void StartUpdateButton_Click(object sender, RoutedEventArgs e)
		{
			if (_isUpdating)
			{
				if (_cancellationTokenSource != null)
				{
					_cancellationTokenSource.Cancel();
					AppendLog("⚠\ufe0f 用户取消了更新操作...", "#e67e22");
					StartUpdateButton.Content = "\ud83d\udd04 开始更新";
				}
				return;
			}
			if (NvdEnabledCheckBox.IsChecked != true && CnnvdEnabledCheckBox.IsChecked != true && CncertEnabledCheckBox.IsChecked != true)
			{
				System.Windows.MessageBox.Show("请至少启用一个数据源", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			_isUpdating = true;
			_cancellationTokenSource = new CancellationTokenSource();
			StartUpdateButton.Content = "⏹\ufe0f 取消更新";
			UpdateProgressBar.Visibility = Visibility.Visible;
			UpdateProgressBar.Value = 0.0;
			AppendLog("\ud83d\ude80 开始漏洞数据库更新...", "#27ae60");
			try
			{
				Progress<int> progress = new Progress<int>(delegate(int value)
				{
					((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
					{
						UpdateProgressBar.Value = value;
					});
				});
				await ExecuteUpdateAsync(progress, _cancellationTokenSource.Token);
			}
			catch (OperationCanceledException)
			{
				AppendLog("⚠\ufe0f 更新已被取消", "#e67e22");
				UpdateStatusIcon.Text = "⚠\ufe0f";
				UpdateStatusText.Text = "更新已取消";
				UpdateStatusText.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#e67e22"));
			}
			catch (Exception ex2)
			{
				AppendLog("❌ 更新失败: " + ex2.Message, "#e74c3c");
				UpdateStatusIcon.Text = "❌";
				UpdateStatusText.Text = "更新失败";
				UpdateStatusText.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#e74c3c"));
			}
			finally
			{
				_isUpdating = false;
				StartUpdateButton.Content = "\ud83d\udd04 开始更新";
				UpdateProgressBar.Visibility = Visibility.Collapsed;
				RefreshDatabaseInfo();
				LoadUpdateHistory();
				SaveSettings();
			}
		}

		private async Task ExecuteUpdateAsync(IProgress<int> progress, CancellationToken cancellationToken)
		{
			DateTime updateStartTime = DateTime.Now;
			AppendLog("\ud83d\udce1 正在连接数据源...", "#3498db");
			await Task.Delay(500, cancellationToken);
			List<UpdateResult> results = new List<UpdateResult>();
			if (NvdEnabledCheckBox.IsChecked == true)
			{
				AppendLog("\ufffd 正在从 NVD (美国国家漏洞数据库) 获取数据...", "#3498db");
				results.Add(await UpdateFromNvdAsync(progress, cancellationToken));
			}
			if (CnnvdEnabledCheckBox.IsChecked == true)
			{
				AppendLog("\ud83c\udde8\ud83c\uddf3 正在从 CNNVD (中国国家漏洞数据库) 获取数据...", "#c0392b");
				results.Add(await UpdateFromCnnvdAsync(progress, cancellationToken));
			}
			if (CncertEnabledCheckBox.IsChecked == true)
			{
				AppendLog("\ud83d\udee1\ufe0f 正在从 CNCERT (国家计算机网络应急中心) 获取数据...", "#2980b9");
				results.Add(await UpdateFromCncertAsync(progress, cancellationToken));
			}
			int num = results.Sum((UpdateResult r) => r.NewCount);
			int num2 = results.Sum((UpdateResult r) => r.UpdatedCount);
			int num3 = results.Sum((UpdateResult r) => r.ErrorCount);
			TimeSpan duration = DateTime.Now - updateStartTime;
			if (num > 0 || num2 > 0)
			{
				AppendLog($"✅ 更新完成！新增 {num} 条，更新 {num2} 条", "#27ae60");
				UpdateStatusIcon.Text = "✅";
				UpdateStatusText.Text = "更新成功";
				UpdateStatusText.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#27ae60"));
				_history.Add(new UpdateHistoryRecord
				{
					UpdateTime = updateStartTime,
					Duration = duration,
					NewCount = num,
					UpdatedCount = num2,
					ErrorCount = num3,
					Status = "成功",
					Sources = string.Join(", ", results.Select((UpdateResult r) => r.Source))
				});
				SaveUpdateHistory();
			}
			else
			{
				AppendLog("ℹ\ufe0f 漏洞库已是最新，无需更新", "#3498db");
				UpdateStatusIcon.Text = "ℹ\ufe0f";
				UpdateStatusText.Text = "已是最新";
				UpdateStatusText.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#3498db"));
				_history.Add(new UpdateHistoryRecord
				{
					UpdateTime = updateStartTime,
					Duration = duration,
					NewCount = 0,
					UpdatedCount = 0,
					ErrorCount = num3,
					Status = "已是最新",
					Sources = string.Join(", ", results.Select((UpdateResult r) => r.Source))
				});
				SaveUpdateHistory();
			}
			if (num3 > 0)
			{
				AppendLog($"⚠\ufe0f {num3} 个数据源更新失败", "#e67e22");
			}
			UpdateStatistics();
		}

		private async Task<UpdateResult> UpdateFromNvdAsync(IProgress<int> progress, CancellationToken cancellationToken)
		{
			_ = 2;
			try
			{
				HttpClient httpClient = new HttpClient();
				httpClient.DefaultRequestHeaders.UserAgent.ParseAdd("NetSecurityScanner/1.0");
				DateTime utcNow = DateTime.UtcNow;
				string stringToEscape = utcNow.AddDays(-30.0).ToString("yyyy-MM-ddTHH:mm:ss.fff");
				string stringToEscape2 = utcNow.ToString("yyyy-MM-ddTHH:mm:ss.fff");
				string requestUri = $"https://services.nvd.nist.gov/rest/json/cves/2.0?pubStartDate={Uri.EscapeDataString(stringToEscape)}&pubEndDate={Uri.EscapeDataString(stringToEscape2)}&resultsPerPage=200";
				AppendLog("  → 正在请求 NVD API...", "#7f8c8d");
				progress.Report(20);
				HttpResponseMessage httpResponseMessage = await httpClient.GetAsync(requestUri, cancellationToken);
				if (!httpResponseMessage.IsSuccessStatusCode)
				{
					AppendLog($"  ✗ NVD 请求失败: HTTP {httpResponseMessage.StatusCode}", "#e74c3c");
					return new UpdateResult
					{
						Source = "NVD",
						ErrorCount = 1
					};
				}
				NvdApiResponse nvdData = JsonSerializer.Deserialize<NvdApiResponse>(await httpResponseMessage.Content.ReadAsStringAsync(cancellationToken));
				if (nvdData?.Vulnerabilities == null || nvdData.Vulnerabilities.Count == 0)
				{
					AppendLog("  ℹ\ufe0f NVD 返回空数据", "#7f8c8d");
					return new UpdateResult
					{
						Source = "NVD",
						NewCount = 0,
						UpdatedCount = 0
					};
				}
				AppendLog($"  ✓ 从 NVD 获取 {nvdData.Vulnerabilities.Count} 条漏洞数据", "#27ae60");
				progress.Report(50);
				await SaveNvdDataAsync(nvdData.Vulnerabilities, cancellationToken);
				progress.Report(80);
				AppendLog("  ✓ NVD 数据已保存", "#27ae60");
				return new UpdateResult
				{
					Source = "NVD",
					NewCount = nvdData.Vulnerabilities.Count
				};
			}
			catch (Exception ex)
			{
				AppendLog("  ✗ NVD 更新失败: " + ex.Message, "#e74c3c");
				return new UpdateResult
				{
					Source = "NVD",
					ErrorCount = 1
				};
			}
		}

		private async Task<UpdateResult> UpdateFromCnnvdAsync(IProgress<int> progress, CancellationToken cancellationToken)
		{
			_ = 1;
			try
			{
				AppendLog("  → CNNVD 数据源需配置 API Key，使用模拟数据...", "#f39c12");
				await Task.Delay(2000, cancellationToken);
				List<SimulatedVulnData> simulatedData = GenerateSimulatedCnnvdData();
				await SaveSimulatedDataAsync("CNNVD", simulatedData, cancellationToken);
				AppendLog($"  ✓ CNNVD 获取 {simulatedData.Count} 条漏洞数据", "#27ae60");
				return new UpdateResult
				{
					Source = "CNNVD",
					NewCount = simulatedData.Count
				};
			}
			catch (Exception ex)
			{
				AppendLog("  ✗ CNNVD 更新失败: " + ex.Message, "#e74c3c");
				return new UpdateResult
				{
					Source = "CNNVD",
					ErrorCount = 1
				};
			}
		}

		private async Task<UpdateResult> UpdateFromCncertAsync(IProgress<int> progress, CancellationToken cancellationToken)
		{
			_ = 1;
			try
			{
				AppendLog("  → CNCERT 数据源需配置 API Key，使用模拟数据...", "#f39c12");
				await Task.Delay(2000, cancellationToken);
				List<SimulatedVulnData> simulatedData = GenerateSimulatedCncertData();
				await SaveSimulatedDataAsync("CNCERT", simulatedData, cancellationToken);
				AppendLog($"  ✓ CNCERT 获取 {simulatedData.Count} 条漏洞数据", "#27ae60");
				return new UpdateResult
				{
					Source = "CNCERT",
					NewCount = simulatedData.Count
				};
			}
			catch (Exception ex)
			{
				AppendLog("  ✗ CNCERT 更新失败: " + ex.Message, "#e74c3c");
				return new UpdateResult
				{
					Source = "CNCERT",
					ErrorCount = 1
				};
			}
		}

