		private async Task SaveNvdDataAsync(List<NvdVulnerability> vulnerabilities, CancellationToken cancellationToken)
		{
			string text = System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "NetSecurityScanner");
			Directory.CreateDirectory(text);
			string path = System.IO.Path.Combine(text, "nvd_cache.json");
			string contents = JsonSerializer.Serialize(vulnerabilities, new JsonSerializerOptions
			{
				WriteIndented = true
			});
			await File.WriteAllTextAsync(path, contents, cancellationToken);
		}

		private async Task SaveSimulatedDataAsync(string source, List<SimulatedVulnData> data, CancellationToken cancellationToken)
		{
			string text = System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "NetSecurityScanner");
			Directory.CreateDirectory(text);
			string path = System.IO.Path.Combine(text, source.ToLower() + "_cache.json");
			string contents = JsonSerializer.Serialize(data, new JsonSerializerOptions
			{
				WriteIndented = true
			});
			await File.WriteAllTextAsync(path, contents, cancellationToken);
		}

		private void RefreshDatabaseInfo()
		{
			try
			{
				string path = System.IO.Path.Combine(System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "NetSecurityScanner"), "vulnerability_database.json");
				int value = 0;
				string value2 = "从未";
				if (File.Exists(path))
				{
					StaticVulnerabilityDatabase val = JsonSerializer.Deserialize<StaticVulnerabilityDatabase>(File.ReadAllText(path));
					if (((val != null) ? val.Vulnerabilities : null) != null)
					{
						value = val.Vulnerabilities.Count;
						value2 = ((val.LastUpdated != DateTime.MinValue) ? val.LastUpdated.ToString("yyyy-MM-dd HH:mm:ss") : "从未");
					}
				}
				DatabaseInfoText.Text = $"\ud83d\udcca 当前漏洞库: {value} 条记录 | 最后更新: {value2}";
				if (_updater.LastUpdateTime != DateTime.MinValue)
				{
					LastUpdateText.Text = $"上次更新: {_updater.LastUpdateTime:yyyy-MM-dd HH:mm:ss}";
				}
			}
			catch
			{
				DatabaseInfoText.Text = "\ud83d\udcca 当前漏洞库: 0 条记录 | 最后更新: 从未";
			}
		}

		private void AppendLog(string message, string color = "#2c3e50")
		{
			string message2 = message;
			((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
			{
				string value = DateTime.Now.ToString("HH:mm:ss");
				string text = $"[{value}] {message2}\n";
				UpdateLogTextBox.AppendText(text);
				UpdateLogTextBox.ScrollToEnd();
				try
				{
					File.AppendAllText(_logFilePath, text);
				}
				catch
				{
				}
			});
		}

		private void CloseButton_Click(object sender, RoutedEventArgs e)
		{
			if (_isUpdating)
			{
				if (System.Windows.MessageBox.Show("更新正在进行中，确定要关闭吗？", "确认", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
				{
					_cancellationTokenSource?.Cancel();
					Close();
				}
			}
			else
			{
				Close();
			}
		}

		private void RefreshDbButton_Click(object sender, RoutedEventArgs e)
		{
			RefreshDatabaseInfo();
			LoadUpdateHistory();
			AppendLog("\ud83d\udd04 已刷新数据库状态", "#3498db");
		}

		private void ExportDbButton_Click(object sender, RoutedEventArgs e)
		{
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Filter = "JSON 文件 (*.json)|*.json|CSV 文件 (*.csv)|*.csv",
				Title = "导出漏洞数据库",
				FileName = $"vulnerability_db_{DateTime.Now:yyyyMMdd_HHmmss}"
			};
			if (saveFileDialog.ShowDialog() != true)
			{
				return;
			}
			try
			{
				string text = System.IO.Path.Combine(System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "NetSecurityScanner"), "vulnerability_database.json");
				if (File.Exists(text))
				{
					File.Copy(text, saveFileDialog.FileName, overwrite: true);
					AppendLog("✅ 数据库已导出到: " + saveFileDialog.FileName, "#27ae60");
					System.Windows.MessageBox.Show("数据库导出成功！", "成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
				else
				{
					System.Windows.MessageBox.Show("本地数据库文件不存在，请先执行更新操作", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				}
			}
			catch (Exception ex)
			{
				AppendLog("❌ 导出失败: " + ex.Message, "#e74c3c");
				System.Windows.MessageBox.Show("导出失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

