		private void TabControl_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			if (sender is System.Windows.Controls.TabControl tabControl && tabControl.SelectedItem != LogTab)
			{
				if (tabControl.SelectedItem == HistoryTab)
				{
					ShowUpdateHistory();
				}
				else if (tabControl.SelectedItem == AutoUpdateTab)
				{
					ShowAutoUpdateSettings();
				}
			}
		}

		private void ShowUpdateHistory()
		{
			HistoryListBox.Items.Clear();
			if (_history.Count == 0)
			{
				TextBlock newItem = new TextBlock
				{
					Text = "暂无更新历史记录",
					FontSize = 14.0,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#7f8c8d")),
					HorizontalAlignment = System.Windows.HorizontalAlignment.Center,
					VerticalAlignment = VerticalAlignment.Center,
					Margin = new Thickness(0.0, 50.0, 0.0, 0.0)
				};
				HistoryListBox.Items.Add(newItem);
				return;
			}
			foreach (UpdateHistoryRecord item in _history.OrderByDescending((UpdateHistoryRecord h) => h.UpdateTime))
			{
				Border border = new Border
				{
					Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#f8f9fa")),
					CornerRadius = new CornerRadius(6.0),
					Padding = new Thickness(12.0),
					Margin = new Thickness(0.0, 0.0, 0.0, 8.0),
					BorderBrush = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#e0e0e0")),
					BorderThickness = new Thickness(1.0)
				};
				StackPanel stackPanel = new StackPanel();
				string status = item.Status;
				string text = ((status == "成功") ? "#27ae60" : ((!(status == "已是最新")) ? "#e74c3c" : "#3498db"));
				string value = text;
				TextBlock element = new TextBlock
				{
					Text = $"{item.UpdateTime:yyyy-MM-dd HH:mm:ss} | 状态: {item.Status}",
					FontWeight = FontWeights.SemiBold,
					FontSize = 13.0,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(value)),
					Margin = new Thickness(0.0, 0.0, 0.0, 5.0)
				};
				TextBlock element2 = new TextBlock
				{
					Text = "数据源: " + item.Sources,
					FontSize = 12.0,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2c3e50")),
					Margin = new Thickness(0.0, 0.0, 0.0, 3.0)
				};
				TextBlock element3 = new TextBlock
				{
					Text = $"新增: {item.NewCount} 条 | 更新: {item.UpdatedCount} 条 | 失败: {item.ErrorCount} 个",
					FontSize = 12.0,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2c3e50")),
					Margin = new Thickness(0.0, 0.0, 0.0, 3.0)
				};
				TextBlock element4 = new TextBlock
				{
					Text = $"耗时: {item.Duration.TotalSeconds:F1} 秒",
					FontSize = 12.0,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#7f8c8d"))
				};
				stackPanel.Children.Add(element);
				stackPanel.Children.Add(element2);
				stackPanel.Children.Add(element3);
				stackPanel.Children.Add(element4);
				border.Child = stackPanel;
				HistoryListBox.Items.Add(border);
			}
		}

		private void ShowAutoUpdateSettings()
		{
			LoadSettings();
			AutoUpdateToggleButton.IsChecked = _settings.AutoUpdateEnabled;
			if (_settings.AutoUpdateEnabled)
			{
				AutoUpdateStatusIcon.Text = "✅";
				AutoUpdateStatusText.Text = "自动更新已启用";
				AutoUpdateStatusText.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#27ae60"));
				DateTime value = DateTime.Now.AddDays(_settings.UpdateIntervalDays);
				AutoUpdateNextTimeText.Text = $"下次更新: {value:yyyy-MM-dd HH:mm}";
			}
			else
			{
				AutoUpdateStatusIcon.Text = "❌";
				AutoUpdateStatusText.Text = "自动更新已禁用";
				AutoUpdateStatusText.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#95a5a6"));
				AutoUpdateNextTimeText.Text = "下次更新: 未设置";
			}
			AutoUpdateIntervalText.Text = $"每{_settings.UpdateIntervalDays}天";
			AutoUpdateTimeText.Text = ((_settings.LastAutoUpdateTime != DateTime.MinValue) ? _settings.LastAutoUpdateTime.ToString("yyyy-MM-dd HH:mm") : "从未");
			AutoUpdateLastTimeText.Text = ((_settings.LastAutoUpdateTime != DateTime.MinValue) ? _settings.LastAutoUpdateTime.ToString("yyyy-MM-dd HH:mm") : "从未");
		}

		private void AutoUpdateToggleButton_Changed(object sender, RoutedEventArgs e)
		{
			_settings.AutoUpdateEnabled = AutoUpdateToggleButton.IsChecked == true;
			SaveSettings();
			ShowAutoUpdateSettings();
			AppendLog("自动更新已" + ((AutoUpdateToggleButton.IsChecked == true) ? "启用" : "禁用"), "#3498db");
		}

		private void ClearHistoryButton_Click(object sender, RoutedEventArgs e)
		{
			if (System.Windows.MessageBox.Show("确定要清空更新历史记录吗？", "确认", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
			{
				_history.Clear();
				SaveUpdateHistory();
				ShowUpdateHistory();
				UpdateStatistics();
				AppendLog("\ud83d\uddd1\ufe0f 更新历史记录已清空", "#95a5a6");
			}
		}

