		private void LoadVulnerabilityData()
		{
			if (_vulnerability != null)
			{
				base.Title = "漏洞详情 - " + _vulnerability.Name;
				VulnerabilityNameText.Text = _vulnerability.Name;
				RiskLevelText.Text = _vulnerability.RiskLevel;
				System.Windows.Media.Color riskLevelColor = GetRiskLevelColor(_vulnerability.RiskLevel);
				RiskLevelText.Foreground = new SolidColorBrush(riskLevelColor);
				TargetIpText.Text = (string.IsNullOrEmpty(_vulnerability.Target) ? "N/A" : _vulnerability.Target);
				PortText.Text = (_vulnerability.Port.HasValue ? _vulnerability.Port.Value.ToString() : "N/A");
				ServiceText.Text = (string.IsNullOrEmpty(_vulnerability.Service) ? "N/A" : _vulnerability.Service);
				CveIdText.Text = (string.IsNullOrEmpty(_vulnerability.CveId) ? "N/A" : _vulnerability.CveId);
				DetectionMethodText.Text = (string.IsNullOrEmpty(_vulnerability.DetectionMethod) ? "N/A" : _vulnerability.DetectionMethod);
				DescriptionText.Text = (string.IsNullOrEmpty(_vulnerability.Description) ? "暂无描述信息" : _vulnerability.Description);
				SolutionText.Text = (string.IsNullOrEmpty(_vulnerability.Solution) ? "暂无解决方案信息" : _vulnerability.Solution);
				if (string.IsNullOrEmpty(_vulnerability.References))
				{
					ReferencesText.Text = "暂无参考链接";
					return;
				}
				ReferencesText.Text = _vulnerability.References;
				CreateClickableLinks(_vulnerability.References);
			}
		}

		private void CreateClickableLinks(string references)
		{
			ReferencesLinksPanel.Children.Clear();
			if (string.IsNullOrEmpty(references))
			{
				return;
			}
			string[] array = references.Split(new char[2] { '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries);
			for (int i = 0; i < array.Length; i++)
			{
				string text = array[i].Trim();
				if (!string.IsNullOrEmpty(text))
				{
					if (text.StartsWith("http://", StringComparison.OrdinalIgnoreCase) || text.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
					{
						Hyperlink hyperlink = new Hyperlink
						{
							NavigateUri = new Uri(text),
							Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(52, 152, 219)),
							TextDecorations = TextDecorations.Underline
						};
						hyperlink.Inlines.Add(text);
						hyperlink.RequestNavigate += Hyperlink_RequestNavigate;
						TextBlock textBlock = new TextBlock
						{
							Margin = new Thickness(0.0, 2.0, 0.0, 2.0),
							TextWrapping = TextWrapping.Wrap
						};
						textBlock.Inlines.Add(hyperlink);
						ReferencesLinksPanel.Children.Add(textBlock);
					}
					else
					{
						TextBlock element = new TextBlock
						{
							Text = text,
							FontSize = 14.0,
							Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(52, 73, 94)),
							Margin = new Thickness(0.0, 2.0, 0.0, 2.0),
							TextWrapping = TextWrapping.Wrap
						};
						ReferencesLinksPanel.Children.Add(element);
					}
				}
			}
		}

		private void Hyperlink_RequestNavigate(object sender, RequestNavigateEventArgs e)
		{
			try
			{
				Process.Start(new ProcessStartInfo
				{
					FileName = e.Uri.AbsoluteUri,
					UseShellExecute = true
				});
				e.Handled = true;
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("无法打开链接: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

		private System.Windows.Media.Color GetRiskLevelColor(string riskLevel)
		{
			if (string.IsNullOrEmpty(riskLevel))
			{
				return Colors.Gray;
			}
			return riskLevel switch
			{
				"严重" => System.Windows.Media.Color.FromRgb(192, 57, 43), 
				"高危" => System.Windows.Media.Color.FromRgb(231, 76, 60), 
				"中危" => System.Windows.Media.Color.FromRgb(230, 126, 34), 
				"低危" => System.Windows.Media.Color.FromRgb(241, 196, 15), 
				"信息" => System.Windows.Media.Color.FromRgb(52, 152, 219), 
				_ => Colors.Gray, 
			};
		}

