		public VulnerabilityKnowledgeBaseWindow()
		{
			InitializeComponent();
			_knowledgeBase = InitializeKnowledgeBase();
			_favoritesManager = new FavoritesManager();
			BuildTreeView();
			UpdateStatusBar();
		}

		private void BuildTreeView()
		{
			CategoryTreeView.Items.Clear();
			if (_currentViewMode == "按领域")
			{
				BuildTreeViewByCategory();
			}
			else if (_currentViewMode == "我的收藏")
			{
				BuildTreeViewFavorites();
			}
			else
			{
				BuildTreeViewByRiskLevel();
			}
		}

		private void BuildTreeViewByRiskLevel()
		{
			List<KeyValuePair<string, VulnerabilityKnowledgeItem>> list = (from kv in _knowledgeBase
				where kv.Value.RiskLevel == "高"
				orderby kv.Key
				select kv).ToList();
			List<KeyValuePair<string, VulnerabilityKnowledgeItem>> list2 = (from kv in _knowledgeBase
				where kv.Value.RiskLevel == "中"
				orderby kv.Key
				select kv).ToList();
			List<KeyValuePair<string, VulnerabilityKnowledgeItem>> list3 = (from kv in _knowledgeBase
				where kv.Value.RiskLevel == "低"
				orderby kv.Key
				select kv).ToList();
			if (string.IsNullOrEmpty(_currentFilter) || _currentFilter == "高")
			{
				TreeViewItem treeViewItem = new TreeViewItem
				{
					Header = "\ud83d\udd34 高风险漏洞",
					IsExpanded = true,
					FontWeight = FontWeights.SemiBold
				};
				foreach (KeyValuePair<string, VulnerabilityKnowledgeItem> item in list)
				{
					treeViewItem.Items.Add(new TreeViewItem
					{
						Header = item.Key,
						Tag = item.Key
					});
				}
				CategoryTreeView.Items.Add(treeViewItem);
			}
			if (string.IsNullOrEmpty(_currentFilter) || _currentFilter == "中")
			{
				TreeViewItem treeViewItem2 = new TreeViewItem
				{
					Header = "\ud83d\udfe0 中风险漏洞",
					IsExpanded = true,
					FontWeight = FontWeights.SemiBold
				};
				foreach (KeyValuePair<string, VulnerabilityKnowledgeItem> item2 in list2)
				{
					treeViewItem2.Items.Add(new TreeViewItem
					{
						Header = item2.Key,
						Tag = item2.Key
					});
				}
				CategoryTreeView.Items.Add(treeViewItem2);
			}
			if (!string.IsNullOrEmpty(_currentFilter) && !(_currentFilter == "低"))
			{
				return;
			}
			TreeViewItem treeViewItem3 = new TreeViewItem
			{
				Header = "\ud83d\udfe1 低风险漏洞",
				IsExpanded = true,
				FontWeight = FontWeights.SemiBold
			};
			foreach (KeyValuePair<string, VulnerabilityKnowledgeItem> item3 in list3)
			{
				treeViewItem3.Items.Add(new TreeViewItem
				{
					Header = item3.Key,
					Tag = item3.Key
				});
			}
			CategoryTreeView.Items.Add(treeViewItem3);
		}

		private void BuildTreeViewByCategory()
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>
			{
				{ "Web应用", "\ud83c\udf10 Web应用" },
				{ "认证授权", "\ud83d\udd10 认证授权" },
				{ "配置管理", "\ud83d\udd27 配置管理" },
				{ "数据序列化", "\ud83d\udce6 数据序列化" },
				{ "系统级", "\ud83d\udda5\ufe0f 系统级" }
			};
			foreach (IGrouping<string, KeyValuePair<string, VulnerabilityKnowledgeItem>> item in from kv in _knowledgeBase
				group kv by kv.Value.Category ?? "其他" into g
				orderby g.Key
				select g)
			{
				string key = item.Key;
				if (!dictionary.ContainsKey(key))
				{
					continue;
				}
				string value = dictionary[key];
				TreeViewItem treeViewItem = new TreeViewItem
				{
					Header = $"{value} ({item.Count()})",
					IsExpanded = true,
					FontWeight = FontWeights.SemiBold
				};
				foreach (KeyValuePair<string, VulnerabilityKnowledgeItem> item2 in from kv in item
					orderby kv.Value.CvssScore, kv.Key
					select kv)
				{
					string text = ((item2.Value.CvssScore > 0.0) ? $" [{item2.Value.CvssScore:F1}]" : "");
					treeViewItem.Items.Add(new TreeViewItem
					{
						Header = item2.Key + text,
						Tag = item2.Key
					});
				}
				CategoryTreeView.Items.Add(treeViewItem);
			}
		}

		private void BuildTreeViewFavorites()
		{
			List<string> favorites = _favoritesManager.GetFavorites();
			TreeViewItem treeViewItem = new TreeViewItem
			{
				Header = $"\ud83c\udf1f 我的收藏 ({favorites.Count})",
				IsExpanded = true,
				FontWeight = FontWeights.SemiBold
			};
			if (favorites.Count == 0)
			{
				treeViewItem.Items.Add(new TreeViewItem
				{
					Header = "（暂无收藏，右键添加）",
					FontWeight = FontWeights.Normal,
					Foreground = System.Windows.Media.Brushes.Gray,
					IsEnabled = false
				});
			}
			else
			{
				foreach (string item in favorites)
				{
					if (_knowledgeBase.ContainsKey(item))
					{
						VulnerabilityKnowledgeItem vulnerabilityKnowledgeItem = _knowledgeBase[item];
						string text = ((vulnerabilityKnowledgeItem.CvssScore > 0.0) ? $" [{vulnerabilityKnowledgeItem.CvssScore:F1}]" : "");
						treeViewItem.Items.Add(new TreeViewItem
						{
							Header = item + text,
							Tag = item
						});
					}
				}
			}
			CategoryTreeView.Items.Add(treeViewItem);
		}

		private void UpdateStatusBar()
		{
			int count = _knowledgeBase.Count;
			int value = _knowledgeBase.Count<KeyValuePair<string, VulnerabilityKnowledgeItem>>((KeyValuePair<string, VulnerabilityKnowledgeItem> kv) => kv.Value.RiskLevel == "高");
			int value2 = _knowledgeBase.Count<KeyValuePair<string, VulnerabilityKnowledgeItem>>((KeyValuePair<string, VulnerabilityKnowledgeItem> kv) => kv.Value.RiskLevel == "中");
			int value3 = _knowledgeBase.Count<KeyValuePair<string, VulnerabilityKnowledgeItem>>((KeyValuePair<string, VulnerabilityKnowledgeItem> kv) => kv.Value.RiskLevel == "低");
			StatusTotalText.Text = $"漏洞总数: {count}";
			StatusHighText.Text = $"高: {value}";
			StatusMediumText.Text = $"中: {value2}";
			StatusLowText.Text = $"低: {value3}";
		}

		private void UpdateCurrentVulnDisplay(string title)
		{
			CurrentVulnName.Text = title;
			StatusCurrentText.Text = "当前查看: " + title;
		}

