		private void SearchButton_Click(object sender, RoutedEventArgs e)
		{
			PerformSearch();
		}

		private void SearchTextBox_KeyDown(object sender, System.Windows.Input.KeyEventArgs e)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0007: Invalid comparison between Unknown and I4
			if ((int)e.Key == 6)
			{
				PerformSearch();
				e.Handled = true;
			}
		}

		private void PerformSearch()
		{
			string keywordLower = (_currentSearchKeyword = SearchTextBox.Text.Trim()).ToLower();
			if (string.IsNullOrEmpty(keywordLower))
			{
				ResetAll();
				return;
			}
			List<KeyValuePair<string, VulnerabilityKnowledgeItem>> list = _knowledgeBase.Where<KeyValuePair<string, VulnerabilityKnowledgeItem>>((KeyValuePair<string, VulnerabilityKnowledgeItem> kvp) => kvp.Key.ToLower().Contains(keywordLower) || kvp.Value.Title.ToLower().Contains(keywordLower) || kvp.Value.Description.ToLower().Contains(keywordLower) || (kvp.Value.CVEIds != null && kvp.Value.CVEIds.Any((string c) => c.ToLower().Contains(keywordLower))) || (kvp.Value.RelatedVulns != null && kvp.Value.RelatedVulns.Any((string r) => r.ToLower().Contains(keywordLower))) || (!string.IsNullOrEmpty(kvp.Value.Category) && kvp.Value.Category.ToLower().Contains(keywordLower))).ToList();
			if (list.Any())
			{
				BuildTreeViewBySearch(list);
			}
			else
			{
				System.Windows.MessageBox.Show("未找到相关内容", "搜索结果", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
		}

		private void ResetButton_Click(object sender, RoutedEventArgs e)
		{
			ResetAll();
		}

		private void ResetAll()
		{
			SearchTextBox.Text = "";
			_currentSearchKeyword = "";
			_currentFilter = "";
			_currentViewMode = "全部";
			BuildTreeView();
			UpdateStatusBar();
			VulnCountText.Text = $"共 {_knowledgeBase.Count} 项";
			ResetFilterButtonStyles();
			DetailPanel.Children.Clear();
			DetailPanel.Children.Add(new TextBlock
			{
				Text = "\ud83d\udc48 请从左侧选择一个漏洞分类查看详情",
				HorizontalAlignment = System.Windows.HorizontalAlignment.Center,
				VerticalAlignment = VerticalAlignment.Center,
				FontSize = 16.0,
				Foreground = System.Windows.Media.Brushes.Gray,
				Margin = new Thickness(0.0, 100.0, 0.0, 0.0)
			});
			CurrentVulnName.Text = "请选择左侧漏洞查看详情";
			StatusCurrentText.Text = "未选择漏洞";
		}

		private void CategoryTreeView_SelectedItemChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
		{
			if (e.NewValue is TreeViewItem { Tag: not null } treeViewItem)
			{
				string key = treeViewItem.Tag.ToString();
				if (_knowledgeBase.ContainsKey(key))
				{
					DisplayKnowledgeItem(_knowledgeBase[key]);
					UpdateCurrentVulnDisplay(_knowledgeBase[key].Title);
				}
			}
		}

		private void DisplayKnowledgeItem(VulnerabilityKnowledgeItem item)
		{
