			grid.Children.Add(element3);
			stackPanel2.Children.Add(grid);
			stackPanel.Children.Add(stackPanel2);
			stackPanel.Children.Add(CreateSection("\ud83d\udccb 漏洞描述", item2.Description));
			stackPanel.Children.Add(CreateListSection("\ud809\udea0\ufe0f 危害影响", item2.Impact));
			stackPanel.Children.Add(CreateListSection("\ud83d\udee1\ufe0f 防护建议", item2.Prevention));
			if (!string.IsNullOrEmpty(item2.Example))
			{
				stackPanel.Children.Add(new TextBlock
				{
					Text = "\ud83d\udcbb 代码示例",
					FontWeight = FontWeights.Bold,
					FontSize = 16.0,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2c3e50")),
					Margin = new Thickness(0.0, 20.0, 0.0, 10.0)
				});
				Border border4 = new Border
				{
					Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#1e1e1e")),
					CornerRadius = new CornerRadius(6.0),
					Padding = new Thickness(15.0),
					Margin = new Thickness(0.0, 0.0, 0.0, 20.0),
					BorderBrush = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#333333")),
					BorderThickness = new Thickness(1.0)
				};
				border4.Child = new TextBlock
				{
					Text = item2.Example,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#d4d4d4")),
					FontFamily = new System.Windows.Media.FontFamily("Consolas"),
					FontSize = 13.0,
					TextWrapping = TextWrapping.Wrap
				};
				stackPanel.Children.Add(border4);
			}
			if (item2.CVEIds != null && item2.CVEIds.Any())
			{
				stackPanel.Children.Add(new TextBlock
				{
					Text = "\ud83d\udd17 CVE参考编号",
					FontWeight = FontWeights.Bold,
					FontSize = 16.0,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2c3e50")),
					Margin = new Thickness(0.0, 20.0, 0.0, 10.0)
				});
				StackPanel stackPanel3 = new StackPanel();
				foreach (string cve in item2.CVEIds)
				{
					TextBlock textBlock = new TextBlock
					{
						Text = cve,
						FontSize = 13.0,
						Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#3498db")),
						Margin = new Thickness(0.0, 4.0, 0.0, 4.0),
						Cursor = System.Windows.Input.Cursors.Hand
					};
					textBlock.MouseLeftButtonUp += delegate
					{
						Process.Start(new ProcessStartInfo
						{
							FileName = "https://nvd.nist.gov/vuln/detail/" + cve,
							UseShellExecute = true
						});
					};
					stackPanel3.Children.Add(textBlock);
				}
				stackPanel.Children.Add(stackPanel3);
			}
			if (item2.References != null && item2.References.Any())
			{
				stackPanel.Children.Add(new TextBlock
				{
					Text = "\ud83d\udcda 外部参考链接",
					FontWeight = FontWeights.Bold,
					FontSize = 16.0,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2c3e50")),
					Margin = new Thickness(0.0, 20.0, 0.0, 10.0)
				});
				StackPanel stackPanel4 = new StackPanel();
				foreach (string refUrl in item2.References)
				{
					TextBlock textBlock2 = new TextBlock
					{
						Text = refUrl,
						FontSize = 12.0,
						Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2980b9")),
						TextWrapping = TextWrapping.Wrap,
						Margin = new Thickness(0.0, 4.0, 0.0, 4.0),
						Cursor = System.Windows.Input.Cursors.Hand,
						TextDecorations = TextDecorations.Underline
					};
					textBlock2.MouseLeftButtonUp += delegate
					{
						Process.Start(new ProcessStartInfo
						{
							FileName = refUrl,
							UseShellExecute = true
						});
					};
					stackPanel4.Children.Add(textBlock2);
				}
				stackPanel.Children.Add(stackPanel4);
			}
			if (item2.RelatedVulns != null && item2.RelatedVulns.Any())
			{
				stackPanel.Children.Add(new TextBlock
				{
					Text = "\ud83d\udd17 相关联漏洞",
					FontWeight = FontWeights.Bold,
					FontSize = 16.0,
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2c3e50")),
					Margin = new Thickness(0.0, 20.0, 0.0, 10.0)
				});
				WrapPanel wrapPanel2 = new WrapPanel();
				foreach (string relatedVuln in item2.RelatedVulns)
				{
					Border border5 = new Border
					{
						Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#ecf0f1")),
						CornerRadius = new CornerRadius(4.0),
						Padding = new Thickness(8.0, 4.0, 8.0, 4.0),
						Margin = new Thickness(0.0, 0.0, 8.0, 8.0),
						Cursor = System.Windows.Input.Cursors.Hand
					};
					border5.Child = new TextBlock
					{
						Text = relatedVuln,
						FontSize = 12.0,
						Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2c3e50"))
					};
					string relatedName = relatedVuln;
					border5.MouseLeftButtonUp += delegate
					{
						if (_knowledgeBase.ContainsKey(relatedName))
						{
							DisplayKnowledgeItem(_knowledgeBase[relatedName]);
							UpdateCurrentVulnDisplay(_knowledgeBase[relatedName].Title);
						}
					};
					wrapPanel2.Children.Add(border5);
				}
				stackPanel.Children.Add(wrapPanel2);
			}
			scrollViewer.Content = stackPanel;
			DetailPanel.Children.Add(scrollViewer);
		}

		private StackPanel CreateInfoItem(string label, string value)
		{
			return new StackPanel
			{
				Margin = new Thickness(0.0, 0.0, 15.0, 0.0),
				Children = 
				{
					(UIElement)new TextBlock
					{
						Text = label,
						FontSize = 11.0,
						Foreground = System.Windows.Media.Brushes.Gray,
						Margin = new Thickness(0.0, 0.0, 0.0, 2.0)
					},
					(UIElement)new TextBlock
					{
						Text = value,
						FontSize = 13.0,
						FontWeight = FontWeights.SemiBold,
						Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#2c3e50"))
					}
				}
			};
		}

