		private void UpdateFilterButtonStyles(string activeFilter)
		{
			SetButtonStyle(FilterAllButton, activeFilter == "全部", "#3498db", "White", "#e0e0e0", "#2c3e50");
			SetButtonStyle(FilterHighButton, activeFilter == "高", "#e74c3c", "White", "#e0e0e0", "#2c3e50");
			SetButtonStyle(FilterMediumButton, activeFilter == "中", "#f39c12", "White", "#e0e0e0", "#2c3e50");
			SetButtonStyle(FilterLowButton, activeFilter == "低", "#27ae60", "White", "#e0e0e0", "#2c3e50");
			if (FindName("FilterByDomainButton") is System.Windows.Controls.Button btn)
			{
				SetButtonStyle(btn, activeFilter == "按领域", "#9b59b6", "White", "#e0e0e0", "#2c3e50");
			}
			if (FindName("FilterFavoritesButton") is System.Windows.Controls.Button btn2)
			{
				SetButtonStyle(btn2, activeFilter == "我的收藏", "#f39c12", "White", "#e0e0e0", "#2c3e50");
			}
		}

		private void ResetFilterButtonStyles()
		{
			SetButtonStyle(FilterAllButton, isActive: true, "#3498db", "White", "#e0e0e0", "#2c3e50");
			SetButtonStyle(FilterHighButton, isActive: false, "#e74c3c", "White", "#e0e0e0", "#2c3e50");
			SetButtonStyle(FilterMediumButton, isActive: false, "#f39c12", "White", "#e0e0e0", "#2c3e50");
			SetButtonStyle(FilterLowButton, isActive: false, "#27ae60", "White", "#e0e0e0", "#2c3e50");
			if (FindName("FilterByDomainButton") is System.Windows.Controls.Button btn)
			{
				SetButtonStyle(btn, isActive: false, "#9b59b6", "White", "#e0e0e0", "#2c3e50");
			}
			if (FindName("FilterFavoritesButton") is System.Windows.Controls.Button btn2)
			{
				SetButtonStyle(btn2, isActive: false, "#f39c12", "White", "#e0e0e0", "#2c3e50");
			}
		}

		private void SetButtonStyle(System.Windows.Controls.Button btn, bool isActive, string activeBg, string activeFg, string normalBg, string normalFg)
		{
			string value = (isActive ? activeBg : normalBg);
			string value2 = (isActive ? activeFg : normalFg);
			btn.Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(value));
			btn.Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(value2));
		}

		private void ExportButton_Click(object sender, RoutedEventArgs e)
		{
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Filter = "Markdown文件 (*.md)|*.md|文本文件 (*.txt)|*.txt",
				DefaultExt = ".md",
				FileName = $"漏洞知识库_{DateTime.Now:yyyyMMdd_HHmmss}.md"
			};
			if (saveFileDialog.ShowDialog() == true)
			{
				try
				{
					string contents = GenerateMarkdownExport();
					File.WriteAllText(saveFileDialog.FileName, contents, Encoding.UTF8);
					System.Windows.MessageBox.Show("已成功导出到: " + saveFileDialog.FileName, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				}
				catch (Exception ex)
				{
					System.Windows.MessageBox.Show("导出失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				}
			}
		}

		private string GenerateMarkdownExport()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("# \ud83d\udcda 漏洞知识库\n");
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder3 = stringBuilder2;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(9, 1, stringBuilder2);
			handler.AppendLiteral("> 生成时间: ");
			handler.AppendFormatted(DateTime.Now, "yyyy-MM-dd HH:mm:ss");
			handler.AppendLiteral("\n");
			stringBuilder3.AppendLine(ref handler);
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder4 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(13, 1, stringBuilder2);
			handler.AppendLiteral("**漏洞总数**: ");
			handler.AppendFormatted(_knowledgeBase.Count);
			handler.AppendLiteral(" | ");
			stringBuilder4.AppendLine(ref handler);
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder5 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(11, 1, stringBuilder2);
			handler.AppendLiteral("**高危**: ");
			handler.AppendFormatted(_knowledgeBase.Count<KeyValuePair<string, VulnerabilityKnowledgeItem>>((KeyValuePair<string, VulnerabilityKnowledgeItem> kv) => kv.Value.RiskLevel == "高"));
			handler.AppendLiteral(" | ");
			stringBuilder5.AppendLine(ref handler);
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder6 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(11, 1, stringBuilder2);
			handler.AppendLiteral("**中危**: ");
			handler.AppendFormatted(_knowledgeBase.Count<KeyValuePair<string, VulnerabilityKnowledgeItem>>((KeyValuePair<string, VulnerabilityKnowledgeItem> kv) => kv.Value.RiskLevel == "中"));
			handler.AppendLiteral(" | ");
			stringBuilder6.AppendLine(ref handler);
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder7 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(9, 1, stringBuilder2);
			handler.AppendLiteral("**低危**: ");
			handler.AppendFormatted(_knowledgeBase.Count<KeyValuePair<string, VulnerabilityKnowledgeItem>>((KeyValuePair<string, VulnerabilityKnowledgeItem> kv) => kv.Value.RiskLevel == "低"));
			handler.AppendLiteral("\n");
			stringBuilder7.AppendLine(ref handler);
			stringBuilder.AppendLine("---\n");
			foreach (KeyValuePair<string, VulnerabilityKnowledgeItem> item in from x in _knowledgeBase
				orderby (!(x.Value.RiskLevel == "高")) ? ((x.Value.RiskLevel == "中") ? 1 : 2) : 0, x.Key
				select x)
			{
				VulnerabilityKnowledgeItem value = item.Value;
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder8 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(4, 1, stringBuilder2);
				handler.AppendLiteral("## ");
				handler.AppendFormatted(value.Title);
				handler.AppendLiteral("\n");
				stringBuilder8.AppendLine(ref handler);
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder9 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(10, 1, stringBuilder2);
				handler.AppendLiteral("**风险等级**: ");
				handler.AppendFormatted(value.RiskLevel);
				stringBuilder9.AppendLine(ref handler);
				if (value.CvssScore > 0.0)
				{
					stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder10 = stringBuilder2;
					handler = new StringBuilder.AppendInterpolatedStringHandler(12, 1, stringBuilder2);
					handler.AppendLiteral("**CVSS评分**: ");
					handler.AppendFormatted(value.CvssScore, "F1");
					stringBuilder10.AppendLine(ref handler);
				}
				if (!string.IsNullOrEmpty(value.FixPriority))
				{
					stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder11 = stringBuilder2;
					handler = new StringBuilder.AppendInterpolatedStringHandler(11, 1, stringBuilder2);
					handler.AppendLiteral("**修复优先级**: ");
					handler.AppendFormatted(value.FixPriority);
					stringBuilder11.AppendLine(ref handler);
				}
				if (!string.IsNullOrEmpty(value.Category))
				{
					stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder12 = stringBuilder2;
					handler = new StringBuilder.AppendInterpolatedStringHandler(10, 1, stringBuilder2);
					handler.AppendLiteral("**领域分类**: ");
					handler.AppendFormatted(value.Category);
					stringBuilder12.AppendLine(ref handler);
				}
				stringBuilder.AppendLine();
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder13 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(11, 1, stringBuilder2);
				handler.AppendLiteral("### 漏洞描述\n\n");
				handler.AppendFormatted(value.Description);
				handler.AppendLiteral("\n");
				stringBuilder13.AppendLine(ref handler);
				stringBuilder.AppendLine("### 危害影响\n");
				foreach (string item2 in value.Impact)
				{
					stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder14 = stringBuilder2;
					handler = new StringBuilder.AppendInterpolatedStringHandler(2, 1, stringBuilder2);
					handler.AppendLiteral("- ");
					handler.AppendFormatted(item2);
					stringBuilder14.AppendLine(ref handler);
				}
				stringBuilder.AppendLine();
				stringBuilder.AppendLine("### 防护建议\n");
				foreach (string item3 in value.Prevention)
				{
					stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder15 = stringBuilder2;
					handler = new StringBuilder.AppendInterpolatedStringHandler(2, 1, stringBuilder2);
					handler.AppendLiteral("- ");
					handler.AppendFormatted(item3);
					stringBuilder15.AppendLine(ref handler);
				}
				stringBuilder.AppendLine();
				if (!string.IsNullOrEmpty(value.Example))
				{
					stringBuilder.AppendLine("### 代码示例\n");
					stringBuilder.AppendLine("```\n" + value.Example + "\n```\n");
				}
				if (value.CVEIds != null && value.CVEIds.Any())
				{
					stringBuilder.AppendLine("### CVE参考\n");
					foreach (string cVEId in value.CVEIds)
					{
						stringBuilder2 = stringBuilder;
						StringBuilder stringBuilder16 = stringBuilder2;
						handler = new StringBuilder.AppendInterpolatedStringHandler(39, 2, stringBuilder2);
						handler.AppendLiteral("- [");
						handler.AppendFormatted(cVEId);
						handler.AppendLiteral("](https://nvd.nist.gov/vuln/detail/");
						handler.AppendFormatted(cVEId);
						handler.AppendLiteral(")");
						stringBuilder16.AppendLine(ref handler);
					}
					stringBuilder.AppendLine();
				}
				if (value.References != null && value.References.Any())
				{
					stringBuilder.AppendLine("### 外部参考\n");
					foreach (string reference in value.References)
					{
						stringBuilder2 = stringBuilder;
						StringBuilder stringBuilder17 = stringBuilder2;
						handler = new StringBuilder.AppendInterpolatedStringHandler(6, 2, stringBuilder2);
						handler.AppendLiteral("- [");
						handler.AppendFormatted(reference);
						handler.AppendLiteral("](");
						handler.AppendFormatted(reference);
						handler.AppendLiteral(")");
						stringBuilder17.AppendLine(ref handler);
					}
					stringBuilder.AppendLine();
				}
				if (value.RelatedVulns != null && value.RelatedVulns.Any())
				{
					stringBuilder.AppendLine("### 相关联漏洞\n");
					stringBuilder.AppendLine(string.Join(", ", value.RelatedVulns));
					stringBuilder.AppendLine();
				}
				stringBuilder.AppendLine("---\n");
			}
			stringBuilder.AppendLine("*本报告仅供安全评估参考，请勿用于非法目的。*\n");
			return stringBuilder.ToString();
		}

		private void PrintButton_Click(object sender, RoutedEventArgs e)
		{
			ContextMenu contextMenu = new ContextMenu();
			MenuItem menuItem = new MenuItem
			{
				Header = "打印当前漏洞"
			};
			menuItem.Click += delegate
			{
				PrintCurrentVulnerability();
			};
			contextMenu.Items.Add(menuItem);
			MenuItem menuItem2 = new MenuItem
			{
				Header = "打印全部知识库"
			};
			menuItem2.Click += delegate
			{
				PrintAllKnowledgeBase();
			};
			contextMenu.Items.Add(menuItem2);
			contextMenu.IsOpen = true;
		}

		private void PrintCurrentVulnerability()
		{
			if (CategoryTreeView.SelectedItem is TreeViewItem { Tag: not null } treeViewItem)
			{
				string key = treeViewItem.Tag.ToString();
				if (_knowledgeBase.ContainsKey(key))
				{
					PrintVulnerability(_knowledgeBase[key]);
				}
			}
			else
			{
				System.Windows.MessageBox.Show("请先选择一个漏洞", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
		}

		private void PrintAllKnowledgeBase()
		{
			if (_knowledgeBase.Count == 0)
			{
				System.Windows.MessageBox.Show("知识库为空", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			System.Windows.Controls.PrintDialog printDialog = new System.Windows.Controls.PrintDialog();
			if (printDialog.ShowDialog() != true)
			{
				return;
			}
			FlowDocument flowDocument = new FlowDocument();
			flowDocument.PagePadding = new Thickness(50.0);
			flowDocument.ColumnWidth = double.PositiveInfinity;
			BlockUIContainer item = new BlockUIContainer(new TextBlock
			{
				Text = "\ud83d\udcda 漏洞知识库",
				FontSize = 28.0,
				FontWeight = FontWeights.Bold,
				Foreground = System.Windows.Media.Brushes.DarkSlateGray,
				TextAlignment = TextAlignment.Center
			});
			flowDocument.Blocks.Add(item);
			Paragraph item2 = new Paragraph(new Run($"生成时间: {DateTime.Now:yyyy-MM-dd HH:mm:ss}"))
			{
				TextAlignment = TextAlignment.Center,
				FontSize = 12.0,
				Foreground = System.Windows.Media.Brushes.Gray
			};
			flowDocument.Blocks.Add(item2);
			flowDocument.Blocks.Add(new Paragraph(new Run("")));
			Paragraph item3 = new Paragraph(new Run($"漏洞总数: {_knowledgeBase.Count} | 高危: {_knowledgeBase.Count<KeyValuePair<string, VulnerabilityKnowledgeItem>>((KeyValuePair<string, VulnerabilityKnowledgeItem> kv) => kv.Value.RiskLevel == "高")} | 中危: {_knowledgeBase.Count<KeyValuePair<string, VulnerabilityKnowledgeItem>>((KeyValuePair<string, VulnerabilityKnowledgeItem> kv) => kv.Value.RiskLevel == "中")} | 低危: {_knowledgeBase.Count<KeyValuePair<string, VulnerabilityKnowledgeItem>>((KeyValuePair<string, VulnerabilityKnowledgeItem> kv) => kv.Value.RiskLevel == "低")}"))
			{
				TextAlignment = TextAlignment.Center,
				FontSize = 12.0
			};
			flowDocument.Blocks.Add(item3);
			flowDocument.Blocks.Add(new Paragraph());
			foreach (KeyValuePair<string, VulnerabilityKnowledgeItem> item4 in from x in _knowledgeBase
				orderby (!(x.Value.RiskLevel == "高")) ? ((x.Value.RiskLevel == "中") ? 1 : 2) : 0, x.Key
				select x)
			{
				AddVulnerabilityToFlowDocument(flowDocument, item4.Value);
			}
			printDialog.PrintDocument(((IDocumentPaginatorSource)flowDocument).DocumentPaginator, "漏洞知识库打印");
		}

		private void PrintVulnerability(VulnerabilityKnowledgeItem item)
		{
			System.Windows.Controls.PrintDialog printDialog = new System.Windows.Controls.PrintDialog();
			if (printDialog.ShowDialog() == true)
			{
				FlowDocument flowDocument = new FlowDocument();
				flowDocument.PagePadding = new Thickness(50.0);
				flowDocument.ColumnWidth = double.PositiveInfinity;
				AddVulnerabilityToFlowDocument(flowDocument, item);
				printDialog.PrintDocument(((IDocumentPaginatorSource)flowDocument).DocumentPaginator, item.Title);
			}
		}

		private void AddVulnerabilityToFlowDocument(FlowDocument flowDoc, VulnerabilityKnowledgeItem item)
		{
