		private System.Windows.Media.Brush GetRiskBrush(string riskLevel)
		{
			return riskLevel switch
			{
				"高" => new SolidColorBrush(Colors.Red), 
				"中" => new SolidColorBrush(Colors.Orange), 
				"低" => new SolidColorBrush(Colors.Green), 
				_ => System.Windows.Media.Brushes.Gray, 
			};
		}

		private System.Windows.Media.Brush GetCvssBrush(double score)
		{
			if (score >= 7.0)
			{
				if (score >= 9.0)
				{
					return new SolidColorBrush(Colors.Red);
				}
				return new SolidColorBrush(Colors.Orange);
			}
			if (score >= 4.0)
			{
				return new SolidColorBrush(Colors.Gold);
			}
			return new SolidColorBrush(Colors.Green);
		}

		private BaseFont GetChineseFont()
		{
			string text = "C:\\Windows\\Fonts\\msyh.ttc";
			if (File.Exists(text))
			{
				return BaseFont.CreateFont(text + ",0", "Identity-H", true);
			}
			string[] array = new string[3] { "simsun.ttc", "simhei.ttf", "mingliu.ttc" };
			foreach (string text2 in array)
			{
				string text3 = "C:\\Windows\\Fonts\\" + text2;
				if (File.Exists(text3))
				{
					return BaseFont.CreateFont(text3 + ",0", "Identity-H", true);
				}
			}
			return BaseFont.CreateFont("Helvetica", "Cp1252", false);
		}

		private void PdfExportButton_Click(object sender, RoutedEventArgs e)
		{
			ContextMenu contextMenu = new ContextMenu();
			MenuItem menuItem = new MenuItem
			{
				Header = "导出当前漏洞"
			};
			menuItem.Click += delegate
			{
				ExportToPdf(currentOnly: true);
			};
			contextMenu.Items.Add(menuItem);
			MenuItem menuItem2 = new MenuItem
			{
				Header = "导出全部知识库"
			};
			menuItem2.Click += delegate
			{
				ExportToPdf(currentOnly: false);
			};
			contextMenu.Items.Add(menuItem2);
			contextMenu.IsOpen = true;
		}

		private void ExportToPdf(bool currentOnly)
		{
			VulnerabilityKnowledgeItem vulnerabilityKnowledgeItem = null;
			if (currentOnly)
			{
				if (CategoryTreeView.SelectedItem is TreeViewItem { Tag: not null } treeViewItem)
				{
					string key = treeViewItem.Tag.ToString();
					if (_knowledgeBase.ContainsKey(key))
					{
						vulnerabilityKnowledgeItem = _knowledgeBase[key];
					}
				}
				if (vulnerabilityKnowledgeItem == null)
				{
					System.Windows.MessageBox.Show("请先选择一个漏洞", "提示", MessageBoxButton.OK, MessageBoxImage.Asterisk);
					return;
				}
			}
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Filter = "PDF文件 (*.pdf)|*.pdf",
				DefaultExt = ".pdf",
				FileName = (currentOnly ? $"漏洞_{vulnerabilityKnowledgeItem.Title}_{DateTime.Now:yyyyMMdd_HHmmss}.pdf" : $"漏洞知识库_{DateTime.Now:yyyyMMdd_HHmmss}.pdf")
			};
			if (saveFileDialog.ShowDialog() != true)
			{
				return;
			}
			try
			{
				string fileName = saveFileDialog.FileName;
				IEnumerable<VulnerabilityKnowledgeItem> items;
				if (!currentOnly)
				{
					IEnumerable<VulnerabilityKnowledgeItem> values = _knowledgeBase.Values;
					items = values;
				}
				else
				{
					IEnumerable<VulnerabilityKnowledgeItem> values = new VulnerabilityKnowledgeItem[1] { vulnerabilityKnowledgeItem };
					items = values;
				}
				GeneratePdf(fileName, items);
				System.Windows.MessageBox.Show("PDF已成功导出到:\n" + saveFileDialog.FileName, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("PDF导出失败: " + ex.Message + "\n\n请确保系统中有中文字体文件。", "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}

