		private TextBlock HighlightText(string text, string keyword)
		{
			TextBlock textBlock = new TextBlock();
			if (string.IsNullOrEmpty(keyword))
			{
				textBlock.Inlines.Add(new Run(text));
				return textBlock;
			}
			string text2 = text.ToLower();
			string value = keyword.ToLower();
			int num = 0;
			int num2;
			while ((num2 = text2.IndexOf(value, num, StringComparison.Ordinal)) >= 0)
			{
				if (num2 > num)
				{
					textBlock.Inlines.Add(new Run(text.Substring(num, num2 - num)));
				}
				Run item = new Run(text.Substring(num2, keyword.Length))
				{
					FontWeight = FontWeights.Bold,
					Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#FFFDEB"))
				};
				textBlock.Inlines.Add(item);
				num = num2 + keyword.Length;
			}
			if (num < text.Length)
			{
				textBlock.Inlines.Add(new Run(text.Substring(num)));
			}
			return textBlock;
		}

		private TextBlock CreateHighlightedTextBlock(string text, string keyword)
		{
			TextBlock textBlock = new TextBlock
			{
				TextWrapping = TextWrapping.Wrap,
				Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#34495e")),
				LineHeight = 22.0
			};
			if (string.IsNullOrEmpty(keyword))
			{
				textBlock.Text = text;
				return textBlock;
			}
			string text2 = text.ToLower();
			string value = keyword.ToLower();
			int num = 0;
			int num2;
			while ((num2 = text2.IndexOf(value, num, StringComparison.Ordinal)) >= 0)
			{
				if (num2 > num)
				{
					textBlock.Inlines.Add(new Run(text.Substring(num, num2 - num)));
				}
				Run item = new Run(text.Substring(num2, keyword.Length))
				{
					FontWeight = FontWeights.Bold,
					Background = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#FFFDEB")),
					Foreground = new SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#34495e"))
				};
				textBlock.Inlines.Add(item);
				num = num2 + keyword.Length;
			}
			if (num < text.Length)
			{
				textBlock.Inlines.Add(new Run(text.Substring(num)));
			}
			return textBlock;
		}

		private void BuildTreeViewBySearch(List<KeyValuePair<string, VulnerabilityKnowledgeItem>> matchedItems)
		{
			CategoryTreeView.Items.Clear();
			TreeViewItem treeViewItem = new TreeViewItem
			{
				Header = $"\ud83d\udd0d 搜索结果 ({matchedItems.Count})",
				IsExpanded = true,
				FontWeight = FontWeights.SemiBold
			};
			foreach (KeyValuePair<string, VulnerabilityKnowledgeItem> item in matchedItems.OrderBy<KeyValuePair<string, VulnerabilityKnowledgeItem>, string>((KeyValuePair<string, VulnerabilityKnowledgeItem> kv) => kv.Key))
			{
				string text = ((item.Value.CvssScore > 0.0) ? $" [{item.Value.CvssScore:F1}]" : "");
				TreeViewItem newItem = new TreeViewItem
				{
					Header = HighlightText(item.Key + text, _currentSearchKeyword),
					Tag = item.Key
				};
				treeViewItem.Items.Add(newItem);
			}
			CategoryTreeView.Items.Add(treeViewItem);
			VulnCountText.Text = $"找到 {matchedItems.Count} 项";
			DisplayKnowledgeItem(matchedItems.First().Value);
			UpdateCurrentVulnDisplay(matchedItems.First().Value.Title);
		}

