	public class FavoritesManager
	{
		private readonly string _favoritesFilePath;

		private List<string> _favorites;

		public string FavoritesFilePath => _favoritesFilePath;

		public FavoritesManager()
		{
			string text = System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "NetSecurityScanner");
			if (!Directory.Exists(text))
			{
				Directory.CreateDirectory(text);
			}
			_favoritesFilePath = System.IO.Path.Combine(text, "favorites.json");
			_favorites = LoadFavorites();
		}

		private List<string> LoadFavorites()
		{
			try
			{
				if (File.Exists(_favoritesFilePath))
				{
					return JsonConvert.DeserializeObject<List<string>>(File.ReadAllText(_favoritesFilePath)) ?? new List<string>();
				}
			}
			catch (Exception)
			{
			}
			return new List<string>();
		}

		private void SaveFavorites()
		{
			try
			{
				string contents = JsonConvert.SerializeObject((object)_favorites, (Formatting)1);
				File.WriteAllText(_favoritesFilePath, contents);
			}
			catch (Exception)
			{
			}
		}

		public void AddFavorite(string vulnKey)
		{
			if (!string.IsNullOrEmpty(vulnKey) && !_favorites.Contains(vulnKey))
			{
				_favorites.Add(vulnKey);
				SaveFavorites();
			}
		}

		public void RemoveFavorite(string vulnKey)
		{
			if (!string.IsNullOrEmpty(vulnKey) && _favorites.Contains(vulnKey))
			{
				_favorites.Remove(vulnKey);
				SaveFavorites();
			}
		}

		public bool IsFavorite(string vulnKey)
		{
			return _favorites.Contains(vulnKey);
		}

		public List<string> GetFavorites()
		{
			return new List<string>(_favorites);
		}
	}
