		private async void StartTrace_Click(object sender, RoutedEventArgs e)
		{
			string targetUrl = TargetUrlTextBox.Text.Trim();
			if (string.IsNullOrEmpty(targetUrl) || targetUrl == "http://")
			{
				System.Windows.MessageBox.Show("请输入有效的目标URL", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			if (!Uri.TryCreate(targetUrl, UriKind.Absolute, out Uri result2) || (result2.Scheme != "http" && result2.Scheme != "https"))
			{
				if (targetUrl.StartsWith("http://") || targetUrl.StartsWith("https://"))
				{
					System.Windows.MessageBox.Show("URL格式无效，请输入正确的URL（如 http://example.com）", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
					return;
				}
				targetUrl = "http://" + targetUrl;
				if (!Uri.TryCreate(targetUrl, UriKind.Absolute, out result2))
				{
					System.Windows.MessageBox.Show("URL格式无效，请输入正确的URL（如 http://example.com）", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
					return;
				}
			}
			TargetUrlTextBox.Text = targetUrl;
			_cts = new CancellationTokenSource();
			_stopwatch = Stopwatch.StartNew();
			_lastResult = null;
			StartTraceButton.IsEnabled = false;
			StopTraceButton.IsEnabled = true;
			LogTextBox.Clear();
			StatusText.Text = "正在追踪...";
			PathCountText.Text = "发现: 0条路径";
			ElapsedTimeText.Text = "耗时: 0s";
			ScanProgressBar.Value = 0.0;
			TraceMode selectedMode = GetSelectedMode();
			_tracer = new WebPathTracerService
			{
				EnableSelenium = (EnableSeleniumCheckBox.IsChecked == true),
				EnableBrute = (EnableBruteCheckBox.IsChecked == true),
				EnableCrawl = (EnableCrawlCheckBox.IsChecked == true),
				SameDomainOnly = (SameDomainOnlyCheckBox.IsChecked == true),
				Mode = selectedMode,
				BruteConcurrency = (int)ConcurrencySlider.Value,
				MaxCrawlDepth = (int)CrawlDepthSlider.Value
			};
			_tracer.OnLog += delegate(string log)
			{
				string log2 = log;
				((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
				{
					LogTextBox.AppendText(log2 + Environment.NewLine);
					LogTextBox.ScrollToEnd();
					if (log2.Contains("第一层"))
					{
						ScanProgressBar.Value = 8.0;
					}
					else if (log2.Contains("技术栈识别"))
					{
						ScanProgressBar.Value = 12.0;
					}
					else if (log2.Contains("开放重定向"))
					{
						ScanProgressBar.Value = 16.0;
					}
					else if (log2.Contains("后缀智能探测") || log2.Contains("后缀探测"))
					{
						ScanProgressBar.Value = 20.0;
					}
					else if (log2.Contains("第二层"))
					{
						ScanProgressBar.Value = 30.0;
					}
					else if (log2.Contains("递进追踪"))
					{
						ScanProgressBar.Value = 40.0;
					}
					else if (log2.Contains("第三层"))
					{
						ScanProgressBar.Value = 50.0;
					}
					else if (log2.Contains("目录爆破"))
					{
						ScanProgressBar.Value = 60.0;
					}
					else if (log2.Contains("根据技术栈"))
					{
						ScanProgressBar.Value = 65.0;
					}
					else if (log2.Contains("合并后缀探测"))
					{
						ScanProgressBar.Value = 68.0;
					}
					else if (log2.Contains("第四层"))
					{
						ScanProgressBar.Value = 75.0;
					}
					else if (log2.Contains("注入") && log2.Contains("Cookie"))
					{
						ScanProgressBar.Value = 78.0;
					}
					else if (log2.Contains("深度爬取"))
					{
						ScanProgressBar.Value = 82.0;
					}
					else if (log2.Contains("注入") && log2.Contains("Layer2"))
					{
						ScanProgressBar.Value = 85.0;
					}
					else if (log2.Contains("验证"))
					{
						ScanProgressBar.Value = 90.0;
					}
					else if (log2.Contains("追踪链摘要"))
					{
						ScanProgressBar.Value = 95.0;
					}
				});
			};
			UpdateElapsedTimeAsync();
			try
			{
				WebPathTraceResult result = await _tracer.TraceAsync(targetUrl, _cts.Token);
				_lastResult = result;
				_stopwatch.Stop();
				SslCertificateInfo sslResult = null;
				if (result.Layer1Results != null && targetUrl.StartsWith("https", StringComparison.OrdinalIgnoreCase))
				{
					sslResult = await new WebPathTracerService().AnalyzeSslCertificate(targetUrl, default(CancellationToken));
				}
				((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
				{
					//IL_0223: Unknown result type (might be due to invalid IL or missing references)
					//IL_0229: Expected O, but got Unknown
					ScanProgressBar.Value = 100.0;
					ShowLayer1Result(result.Layer1Results, ((IEnumerable<PathStep>)result.PathChain).Select((Func<PathStep, PathStep>)((PathStep p) => new PathStep
					{
						Url = p.Url,
						StatusCode = p.StatusCode,
						LocationHeader = p.LocationHeader
					})).ToList());
					ShowLayer2Result(result.Layer2Results);
					ShowLayer3Result(result.Layer3Results);
					ShowLayer4Result(result.Layer4Results);
					ShowBruteResult(result.BruteResults);
					ShowPathSegmentResult(result.PathSegmentResults);
					ShowSensitivePathResult(result.SensitivePaths, result);
					ShowCrawlResult(result.CrawlResults);
					ShowFinalResult(result);
					_lastTraceResult = result;
					ExportMarkdownButton.Visibility = Visibility.Visible;
					ExportJson.Visibility = Visibility.Visible;
					PathCountText.Text = $"发现: {result.AllDiscoveredPaths.Count}条路径";
					ElapsedTimeText.Text = $"耗时: {_stopwatch.ElapsedMilliseconds / 1000}s";
					if (sslResult != null)
					{
						_lastSslCertificate = sslResult;
						ShowSslCertificateResult(sslResult);
					}
					if (result.Layer1Results != null)
					{
						WebPathTracerService val = new WebPathTracerService();
						SecurityAuditResult audit = val.AuditSecurityHeaders(result.Layer1Results);
						ShowSecurityAuditResult(audit);
						TechFingerprint techStack = result.Layer1Results.TechStack;
						if (techStack != null && techStack.DetectedTechs.Count > 0)
						{
							ShowVulnerabilityInfo(result.Layer1Results.TechStack.DetectedTechs, val);
						}
					}
					if (result.FoundPath)
					{
						StatusText.Text = "✅ 追踪完成 - 发现路径";
					}
					else
					{
						StatusText.Text = "追踪完成 - 未发现路径";
					}
				});
			}
			catch (OperationCanceledException)
			{
				_stopwatch?.Stop();
				((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
				{
					StatusText.Text = "追踪已取消";
					ScanProgressBar.Value = 0.0;
				});
			}
			catch (Exception ex3)
			{
				Exception ex4 = ex3;
				Exception ex = ex4;
				_stopwatch?.Stop();
				((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
				{
					StatusText.Text = "追踪失败: " + ex.Message;
					ScanProgressBar.Value = 0.0;
					System.Windows.MessageBox.Show("追踪失败: " + ex.Message, "错误", MessageBoxButton.OK, MessageBoxImage.Hand);
				});
			}
			finally
			{
				((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
				{
					StartTraceButton.IsEnabled = true;
					StopTraceButton.IsEnabled = false;
				});
			}
		}

		private async Task UpdateElapsedTimeAsync()
		{
			while (_stopwatch != null && _stopwatch.IsRunning)
			{
				await Task.Delay(1000);
				if (_stopwatch.IsRunning)
				{
					((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
					{
						ElapsedTimeText.Text = $"耗时: {_stopwatch.ElapsedMilliseconds / 1000}s";
					});
				}
			}
		}

		private void StopTrace_Click(object sender, RoutedEventArgs e)
		{
			_cts?.Cancel();
			StatusText.Text = "正在取消...";
		}

		private async void ScanPorts_Click(object sender, RoutedEventArgs e)
		{
			string targetUrl = TargetUrlTextBox.Text.Trim();
			if (string.IsNullOrEmpty(targetUrl) || !Uri.IsWellFormedUriString(targetUrl, UriKind.Absolute))
			{
				System.Windows.MessageBox.Show("请输入有效的目标URL", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			ScanPortsButton.IsEnabled = false;
			ScanPortsButton.Content = "\ud83d\udd0c 扫描中...";
			PortScanPanel.Children.Clear();
			PortScanPanel.Children.Add(new TextBlock
			{
				Text = "正在扫描端口...",
				Foreground = System.Windows.Media.Brushes.Gray,
				FontSize = 14.0
			});
			await Task.Run(async delegate
			{
				WebPortScanResult portResult = await new WebPathTracerService().ScanCommonPorts(targetUrl, default(CancellationToken));
				((DispatcherObject)this).Dispatcher.Invoke((Action)delegate
				{
					ShowPortScanResult(portResult);
				});
			});
			ScanPortsButton.IsEnabled = true;
			ScanPortsButton.Content = "\ud83d\udd0c 端口扫描";
		}

		private void ShowPortScanResult(WebPortScanResult result)
		{
			PortScanPanel.Children.Clear();
			PortScanPanel.Children.Add(new TextBlock
			{
				Text = "\ud83d\udd0c 端口扫描结果 - " + result.Host,
				FontSize = 16.0,
				FontWeight = FontWeights.Bold,
				Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(44, 62, 80)),
				Margin = new Thickness(0.0, 0.0, 0.0, 15.0)
			});
			PortScanPanel.Children.Add(CreateInfoRow("扫描主机:", result.Host));
			PortScanPanel.Children.Add(CreateInfoRow("扫描端口数:", result.TotalScanned.ToString()));
			PortScanPanel.Children.Add(CreateInfoRow("开放端口:", result.OpenPorts.Count.ToString()));
			PortScanPanel.Children.Add(CreateInfoRow("扫描耗时:", $"{result.ScanDuration.TotalSeconds:F2}秒"));
			if (result.OpenPorts.Count > 0)
			{
				PortScanPanel.Children.Add(new TextBlock
				{
					Text = $"开放端口列表 ({result.OpenPorts.Count}):",
					FontWeight = FontWeights.Bold,
					Foreground = System.Windows.Media.Brushes.Red,
					Margin = new Thickness(0.0, 15.0, 0.0, 10.0)
				});
				{
					foreach (WebPortInfo openPort in result.OpenPorts)
					{
						System.Windows.Media.Color color = ((openPort.Port == 22) ? Colors.Orange : ((openPort.Port == 3306 || openPort.Port == 5432 || openPort.Port == 6379 || openPort.Port == 27017) ? Colors.Red : Colors.Teal));
						Border border = new Border
						{
							Background = new SolidColorBrush(System.Windows.Media.Color.FromArgb(16, color.R, color.G, color.B)),
							BorderBrush = new SolidColorBrush(color),
							BorderThickness = new Thickness(1.0),
							CornerRadius = new CornerRadius(3.0),
							Margin = new Thickness(0.0, 3.0, 0.0, 3.0),
							Padding = new Thickness(8.0)
						};
						StackPanel stackPanel = new StackPanel();
						stackPanel.Children.Add(new TextBlock
						{
							Text = $"\ud83d\udd13 端口 {openPort.Port} - {openPort.Service}",
							FontWeight = FontWeights.Bold,
							Foreground = new SolidColorBrush(color)
						});
						stackPanel.Children.Add(new TextBlock
						{
							Text = $"响应时间: {openPort.ResponseTime.TotalMilliseconds:F0}ms",
							Foreground = System.Windows.Media.Brushes.Gray,
							FontSize = 11.0
						});
						border.Child = stackPanel;
						PortScanPanel.Children.Add(border);
					}
					return;
				}
			}
			PortScanPanel.Children.Add(new TextBlock
			{
				Text = "✅ 未发现开放端口",
				Foreground = System.Windows.Media.Brushes.Green,
				FontWeight = FontWeights.Bold,
				Margin = new Thickness(0.0, 20.0, 0.0, 0.0)
			});
		}

		private void ExportMarkdown_Click(object sender, RoutedEventArgs e)
		{
			//IL_001c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			if (_lastTraceResult == null)
			{
				System.Windows.MessageBox.Show("请先执行路径追踪", "提示", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			WebPathTracerService val = new WebPathTracerService();
			TraceReport val2 = val.GenerateReport(_lastTraceResult, _stopwatch.Elapsed);
			string contents = val.ExportReportAsMarkdown(val2);
			Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
			{
				Filter = "Markdown文件|*.md",
				FileName = $"WebPathTrace_{DateTime.Now:yyyyMMdd_HHmmss}.md",
				InitialDirectory = Environment.GetFolderPath(Environment.SpecialFolder.Desktop)
			};
			if (saveFileDialog.ShowDialog() == true)
			{
				File.WriteAllText(saveFileDialog.FileName, contents, Encoding.UTF8);
				System.Windows.MessageBox.Show("报告已导出到:\n" + saveFileDialog.FileName, "导出成功", MessageBoxButton.OK, MessageBoxImage.Asterisk);
			}
		}

