					Foreground = System.Windows.Media.Brushes.Gray,
					Margin = new Thickness(0.0, 0.0, 0.0, 2.0)
				});
				foreach (string item in result.WafInfo.Indicators.Take(3))
				{
					Layer1Panel.Children.Add(new TextBlock
					{
						Text = "    → " + item,
						TextWrapping = TextWrapping.Wrap,
						Foreground = System.Windows.Media.Brushes.Gray,
						FontSize = 11.0
					});
				}
			}
			if (result.DiscoveredApis.Count > 0)
			{
				Layer1Panel.Children.Add(new TextBlock
				{
					Text = $"\ud83d\udd17 API端点发现 ({result.DiscoveredApis.Count}个):",
					FontWeight = FontWeights.Bold,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(26, 122, 156)),
					Margin = new Thickness(0.0, 10.0, 0.0, 3.0)
