				foreach (ApiEndpoint item2 in result.DiscoveredApis.Take(10))
				{
					SolidColorBrush foreground = item2.Type switch
					{
						"GraphQL" => new SolidColorBrush(System.Windows.Media.Color.FromRgb(224, 53, 152)), 
