						"API Client" => new SolidColorBrush(System.Windows.Media.Color.FromRgb(byte.MaxValue, 152, 0)), 
						_ => System.Windows.Media.Brushes.Gray, 
					};
					Layer1Panel.Children.Add(new TextBlock
					{
						Text = "  [" + item2.Type + "] " + item2.Url,
						TextWrapping = TextWrapping.Wrap,
						Foreground = foreground,
						Margin = new Thickness(0.0, 1.0, 0.0, 1.0)
					});
				}
			}
			if (result.DiscoveredSubdomains.Count > 0)
			{
				Layer1Panel.Children.Add(new TextBlock
				{
					Text = $"\ud83c\udf10 子域名发现 ({result.DiscoveredSubdomains.Count}个):",
					FontWeight = FontWeights.Bold,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(46, 134, 171)),
					Margin = new Thickness(0.0, 10.0, 0.0, 3.0)
				});
				foreach (string item3 in result.DiscoveredSubdomains.Take(10))
				{
					Layer1Panel.Children.Add(CreateInfoRow("  →", item3));
				}
			}
			if (result.ParamVulnerabilityHints.Count > 0)
			{
				Layer1Panel.Children.Add(new TextBlock
				{
					Text = $"⚠\ufe0f 参数漏洞风险提示 ({result.ParamVulnerabilityHints.Count}个):",
					FontWeight = FontWeights.Bold,
					Foreground = new SolidColorBrush(Colors.OrangeRed),
					Margin = new Thickness(0.0, 10.0, 0.0, 3.0)
