			}
			if (result.PageContent != null)
			{
				PageContentAnalysis pageContent = result.PageContent;
				Layer1Panel.Children.Add(new TextBlock
				{
					Text = "\ud83d\udcc4 页面内容分析:",
					FontWeight = FontWeights.Bold,
