				if (!string.IsNullOrEmpty(pageContent.CmsDetected))
				{
					Border border = new Border
					{
						Background = new SolidColorBrush(System.Windows.Media.Color.FromRgb(232, 248, 245)),
						BorderBrush = new SolidColorBrush(System.Windows.Media.Color.FromRgb(26, 188, 156)),
						BorderThickness = new Thickness(1.0),
