						Background = new SolidColorBrush(System.Windows.Media.Color.FromRgb(235, 245, 251)),
						BorderBrush = new SolidColorBrush(System.Windows.Media.Color.FromRgb(52, 152, 219)),
						BorderThickness = new Thickness(1.0),
						CornerRadius = new CornerRadius(3.0),
						Padding = new Thickness(5.0),
