					Margin = new Thickness(0.0, 5.0, 0.0, 0.0)
				};
				stackPanel.Children.Add(CreateStatBox("\ud83d\udd17", pageContent.LinkCount.ToString(), "链接"));
				stackPanel.Children.Add(CreateStatBox("\ud83d\uddbc\ufe0f", pageContent.ImageCount.ToString(), "图片"));
				stackPanel.Children.Add(CreateStatBox("\ud83d\udcdd", pageContent.FormCount.ToString(), "表单"));
				stackPanel.Children.Add(CreateStatBox("\ud83d\udcdc", pageContent.ScriptCount.ToString(), "脚本"));
				stackPanel.Children.Add(CreateStatBox("\ud83c\udfa8", pageContent.StyleCount.ToString(), "样式"));
				Layer1Panel.Children.Add(stackPanel);
			}
			if (result.FoundUrl != null)
			{
				Layer1Panel.Children.Add(CreateResultBox("✅ 发现跳转URL", result.FoundUrl, Colors.Green));
			}
			if (result.LinkHeaderUrl != null)
			{
				Layer1Panel.Children.Add(CreateResultBox("Link头跳转", result.LinkHeaderUrl, Colors.Teal));
			}
			if (result.XRedirectUrl != null)
			{
				Layer1Panel.Children.Add(CreateResultBox("X-Redirect头跳转", result.XRedirectUrl, Colors.Purple));
			}
			if (result.MissingSecurityHeaders.Count > 0)
			{
				Layer1Panel.Children.Add(new TextBlock
				{
					Text = $"⚠\ufe0f 缺少安全头 ({result.MissingSecurityHeaders.Count}):",
					FontWeight = FontWeights.Bold,
					Foreground = System.Windows.Media.Brushes.OrangeRed,
					Margin = new Thickness(0.0, 15.0, 0.0, 5.0)
				});
				foreach (string missingSecurityHeader in result.MissingSecurityHeaders)
				{
					Layer1Panel.Children.Add(new TextBlock
					{
						Text = "  ❌ " + missingSecurityHeader,
						Foreground = System.Windows.Media.Brushes.OrangeRed,
						Margin = new Thickness(0.0, 1.0, 0.0, 1.0)
					});
				}
			}
			if (result.SecurityHeaders.Count > 0)
			{
				Layer1Panel.Children.Add(new TextBlock
				{
					Text = $"已设置安全头 ({result.SecurityHeaders.Count}):",
					FontWeight = FontWeights.Bold,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(39, 174, 96)),
					Margin = new Thickness(0.0, 10.0, 0.0, 5.0)
				});
				foreach (string securityHeader in result.SecurityHeaders)
				{
					Layer1Panel.Children.Add(new TextBlock
					{
						Text = "  ✅ " + securityHeader,
						Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(39, 174, 96)),
						Margin = new Thickness(0.0, 1.0, 0.0, 1.0)
					});
				}
			}
			if (redirectChain.Count > 0)
			{
				Layer1Panel.Children.Add(new TextBlock
				{
					Text = $"重定向链 ({redirectChain.Count} 步):",
					FontWeight = FontWeights.Bold,
					FontSize = 14.0,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(44, 62, 80)),
					Margin = new Thickness(0.0, 15.0, 0.0, 10.0)
				});
				for (int i = 0; i < redirectChain.Count; i++)
				{
					Layer1Panel.Children.Add(CreateRedirectChainItem(redirectChain[i], i + 1));
				}
			}
			if (result.Headers.Count <= 0)
			{
				return;
			}
			Layer1Panel.Children.Add(new TextBlock
			{
				Text = "响应头:",
				FontWeight = FontWeights.Bold,
				Margin = new Thickness(0.0, 15.0, 0.0, 5.0)
			});
			foreach (KeyValuePair<string, string> item5 in result.Headers.Take(20))
			{
				Layer1Panel.Children.Add(CreateInfoRow("  " + item5.Key + ":", item5.Value));
			}
		}

		private void ShowLayer2Result(Layer2Result? result)
		{
			Layer2Panel.Children.Clear();
			if (result == null)
			{
				Layer2Panel.Children.Add(new TextBlock
				{
					Text = "未执行",
					Foreground = System.Windows.Media.Brushes.Gray
				});
				return;
			}
			if (result.Error != null)
			{
				Layer2Panel.Children.Add(CreateResultBox("❌ HTML分析失败", result.Error, Colors.Red));
				return;
			}
			if (result.MetaRefreshUrl != null)
			{
				Layer2Panel.Children.Add(CreateResultBox("Meta Refresh跳转", result.MetaRefreshUrl, Colors.Orange));
			}
			if (result.JsRedirectUrl != null)
			{
				Layer2Panel.Children.Add(CreateResultBox("JavaScript跳转", result.JsRedirectUrl, Colors.Blue));
			}
			if (result.JsRedirectUrls.Count > 0)
			{
				Layer2Panel.Children.Add(new TextBlock
				{
					Text = $"JS跳转URL ({result.JsRedirectUrls.Count}):",
					FontWeight = FontWeights.Bold,
					Foreground = System.Windows.Media.Brushes.Blue,
					Margin = new Thickness(0.0, 10.0, 0.0, 5.0)
				});
				foreach (string jsRedirectUrl in result.JsRedirectUrls)
				{
					Layer2Panel.Children.Add(CreateInfoRow("  →", jsRedirectUrl));
				}
			}
			if (result.SpaRouteUrls.Count > 0)
			{
				Layer2Panel.Children.Add(new TextBlock
				{
					Text = $"SPA路由 ({result.SpaRouteUrls.Count}):",
					FontWeight = FontWeights.Bold,
					Foreground = System.Windows.Media.Brushes.Purple,
					Margin = new Thickness(0.0, 10.0, 0.0, 5.0)
				});
				foreach (string spaRouteUrl in result.SpaRouteUrls)
				{
					Layer2Panel.Children.Add(CreateInfoRow("  →", spaRouteUrl));
				}
			}
			if (result.DecodedUrls.Count > 0)
			{
				Layer2Panel.Children.Add(new TextBlock
				{
					Text = $"Base64解码URL ({result.DecodedUrls.Count}):",
					FontWeight = FontWeights.Bold,
					Foreground = System.Windows.Media.Brushes.Teal,
					Margin = new Thickness(0.0, 10.0, 0.0, 5.0)
				});
				foreach (string decodedUrl in result.DecodedUrls)
				{
					Layer2Panel.Children.Add(CreateInfoRow("  →", decodedUrl));
				}
			}
			if (result.FoundLoginLinks.Count > 0)
			{
				Layer2Panel.Children.Add(new TextBlock
				{
					Text = $"登录链接 ({result.FoundLoginLinks.Count}):",
					FontWeight = FontWeights.Bold,
					Foreground = System.Windows.Media.Brushes.OrangeRed,
					Margin = new Thickness(0.0, 10.0, 0.0, 5.0)
				});
				foreach (string foundLoginLink in result.FoundLoginLinks)
				{
					Layer2Panel.Children.Add(CreateResultBox("\ud83d\udd17 登录链接", foundLoginLink, Colors.OrangeRed));
				}
			}
			if (result.AllLinks.Count > 0)
			{
				List<IGrouping<string, ClassifiedLink>> list = (from l in result.AllLinks
					group l by l.Category into g
					orderby g.Count() descending
					select g).ToList();
				Layer2Panel.Children.Add(new TextBlock
				{
					Text = $"\ud83d\udccb 页面链接分类 ({result.AllLinks.Count}个):",
					FontWeight = FontWeights.Bold,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(44, 62, 80)),
					Margin = new Thickness(0.0, 15.0, 0.0, 5.0)
				});
				foreach (IGrouping<string, ClassifiedLink> item in list)
				{
					System.Windows.Media.Color color = item.Key switch
					{
						"login" => Colors.OrangeRed, 
						"admin" => Colors.Purple, 
						"api" => Colors.Teal, 
						"form" => Colors.Blue, 
						"register" => Colors.DeepPink, 
						_ => Colors.Gray, 
					};
					Layer2Panel.Children.Add(new TextBlock
					{
						Text = $"  {item.Key} ({item.Count()}个):",
						FontWeight = FontWeights.Bold,
						Foreground = new SolidColorBrush(color),
						Margin = new Thickness(0.0, 5.0, 0.0, 2.0)
					});
					foreach (ClassifiedLink item2 in item.Take(10))
					{
						string text = ((!string.IsNullOrEmpty(item2.Text)) ? (" [" + item2.Text + "]") : "");
						Layer2Panel.Children.Add(CreateInfoRow("    →", item2.Url + text));
					}
					if (item.Count() > 10)
					{
						Layer2Panel.Children.Add(new TextBlock
						{
							Text = $"    ... 还有 {item.Count() - 10} 个",
							Foreground = System.Windows.Media.Brushes.Gray,
							Margin = new Thickness(0.0, 1.0, 0.0, 3.0)
						});
					}
				}
			}
			if (result.ExternalResources.Count > 0)
			{
				Layer2Panel.Children.Add(new TextBlock
				{
					Text = $"\ud83d\udce6 外部资源 ({result.ExternalResources.Count}个):",
					FontWeight = FontWeights.Bold,
					Foreground = System.Windows.Media.Brushes.Gray,
					Margin = new Thickness(0.0, 10.0, 0.0, 5.0)
				});
				foreach (string item3 in result.ExternalResources.Take(20))
				{
					Layer2Panel.Children.Add(new TextBlock
					{
						Text = "  " + item3,
						TextWrapping = TextWrapping.Wrap,
						Foreground = System.Windows.Media.Brushes.Gray,
						FontSize = 11.0,
						Margin = new Thickness(0.0, 1.0, 0.0, 1.0)
					});
				}
				if (result.ExternalResources.Count > 20)
				{
					Layer2Panel.Children.Add(new TextBlock
					{
						Text = $"  ... 还有 {result.ExternalResources.Count - 20} 个",
						Foreground = System.Windows.Media.Brushes.Gray,
						Margin = new Thickness(0.0, 1.0, 0.0, 3.0)
					});
				}
			}
			if (result.InlineEventHandlers.Count > 0)
			{
				Layer2Panel.Children.Add(new TextBlock
				{
					Text = $"⚡ 内联事件处理 ({result.InlineEventHandlers.Count}个):",
					FontWeight = FontWeights.Bold,
					Foreground = System.Windows.Media.Brushes.Orange,
					Margin = new Thickness(0.0, 10.0, 0.0, 5.0)
				});
				foreach (string item4 in result.InlineEventHandlers.Take(10))
				{
					Layer2Panel.Children.Add(new TextBlock
					{
						Text = "  " + item4,
						TextWrapping = TextWrapping.Wrap,
						Foreground = System.Windows.Media.Brushes.Orange,
						FontSize = 11.0,
						Margin = new Thickness(0.0, 1.0, 0.0, 1.0)
					});
				}
			}
			if (result.FoundUrl == null && result.MetaRefreshUrl == null && result.JsRedirectUrl == null && result.JsRedirectUrls.Count == 0 && result.SpaRouteUrls.Count == 0 && result.FoundLoginLinks.Count == 0 && result.DecodedUrls.Count == 0 && result.AllLinks.Count == 0)
			{
				Layer2Panel.Children.Add(new TextBlock
				{
					Text = "HTML源码中未发现明显跳转或登录链接",
					Foreground = System.Windows.Media.Brushes.Gray,
					Margin = new Thickness(0.0, 10.0, 0.0, 0.0)
				});
			}
		}

		private void ShowLayer3Result(Layer3Result? result)
		{
			Layer3Panel.Children.Clear();
			if (result == null)
			{
				Layer3Panel.Children.Add(new TextBlock
				{
					Text = "未执行",
					Foreground = System.Windows.Media.Brushes.Gray
				});
				return;
			}
			if (result.FoundUrls.Count > 0)
			{
				Layer3Panel.Children.Add(new TextBlock
				{
					Text = $"发现 {result.FoundUrls.Count} 个敏感文件:",
					FontWeight = FontWeights.Bold,
					Margin = new Thickness(0.0, 0.0, 0.0, 10.0)
				});
				foreach (string foundUrl in result.FoundUrls)
				{
					Layer3Panel.Children.Add(CreateResultBox("\ud83d\udcc4", foundUrl, Colors.Red));
				}
			}
			else
			{
				Layer3Panel.Children.Add(new TextBlock
				{
					Text = "未发现敏感文件",
					Foreground = System.Windows.Media.Brushes.Gray
				});
			}
			if (result.DisallowPaths.Count > 0)
			{
				Layer3Panel.Children.Add(new TextBlock
				{
					Text = $"robots.txt Disallow 路径 ({result.DisallowPaths.Count}):",
					FontWeight = FontWeights.Bold,
					Margin = new Thickness(0.0, 15.0, 0.0, 5.0)
				});
				foreach (string disallowPath in result.DisallowPaths)
				{
					Layer3Panel.Children.Add(CreateInfoRow("  \ud83d\udeab", disallowPath));
				}
			}
			if (result.AllowPaths.Count > 0)
			{
				Layer3Panel.Children.Add(new TextBlock
				{
					Text = $"robots.txt Allow 路径 ({result.AllowPaths.Count}):",
					FontWeight = FontWeights.Bold,
					Margin = new Thickness(0.0, 15.0, 0.0, 5.0)
				});
				foreach (string allowPath in result.AllowPaths)
				{
					Layer3Panel.Children.Add(CreateInfoRow("  ✅", allowPath));
				}
			}
			if (result.SitemapUrls.Count <= 0)
			{
				return;
			}
			Layer3Panel.Children.Add(new TextBlock
			{
				Text = $"Sitemap URL ({result.SitemapUrls.Count}):",
				FontWeight = FontWeights.Bold,
				Margin = new Thickness(0.0, 15.0, 0.0, 5.0)
			});
			foreach (string sitemapUrl in result.SitemapUrls)
			{
				Layer3Panel.Children.Add(CreateInfoRow("  \ud83d\uddfa", sitemapUrl));
			}
		}

		private void ShowLayer4Result(Layer4Result? result)
		{
			Layer4Panel.Children.Clear();
			if (result == null)
			{
				string text = ((EnableSeleniumCheckBox.IsChecked == true) ? "未执行" : "Selenium检测已跳过(未启用)");
				Layer4Panel.Children.Add(new TextBlock
				{
					Text = text,
					Foreground = System.Windows.Media.Brushes.Gray
				});
				return;
			}
			if (result.Error != null)
			{
				Layer4Panel.Children.Add(CreateResultBox("❌ Selenium检测失败", result.Error, Colors.Red));
				Layer4Panel.Children.Add(new TextBlock
				{
					Text = "提示: 请确保已安装Chrome浏览器。如无法使用Selenium，可取消勾选[Selenium动态检测]。",
					Foreground = System.Windows.Media.Brushes.OrangeRed,
					TextWrapping = TextWrapping.Wrap,
					Margin = new Thickness(0.0, 10.0, 0.0, 0.0)
				});
				return;
			}
			Layer4Panel.Children.Add(new TextBlock
			{
				Text = "Selenium动态检测结果",
				FontSize = 16.0,
				FontWeight = FontWeights.Bold,
				Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(44, 62, 80)),
				Margin = new Thickness(0.0, 0.0, 0.0, 15.0)
			});
			Layer4Panel.Children.Add(CreateInfoRow("初始URL:", result.InitialUrl));
			Layer4Panel.Children.Add(CreateInfoRow("最终URL:", result.FinalUrl ?? "无变化"));
			if (result.UrlChanged)
			{
				Layer4Panel.Children.Add(CreateResultBox("✅ 检测到URL变化!", result.FinalUrl ?? "", Colors.Green));
				if (result.RedirectChain.Count > 0)
				{
					Layer4Panel.Children.Add(new TextBlock
					{
						Text = "跳转链:",
						FontWeight = FontWeights.Bold,
						Margin = new Thickness(0.0, 10.0, 0.0, 5.0)
					});
					for (int i = 0; i < result.RedirectChain.Count; i++)
					{
						Layer4Panel.Children.Add(CreateInfoRow($"  {i + 1}.", result.RedirectChain[i]));
					}
				}
			}
			else
			{
				Layer4Panel.Children.Add(new TextBlock
				{
					Text = "URL未发生变化(页面可能无动态跳转)",
					Foreground = System.Windows.Media.Brushes.Gray,
					Margin = new Thickness(0.0, 5.0, 0.0, 0.0)
				});
			}
			if (result.FoundForms.Count > 0)
			{
				Layer4Panel.Children.Add(new TextBlock
				{
					Text = $"发现 {result.FoundForms.Count} 个表单:",
					FontWeight = FontWeights.Bold,
					Foreground = System.Windows.Media.Brushes.Orange,
					Margin = new Thickness(0.0, 15.0, 0.0, 5.0)
				});
				foreach (string foundForm in result.FoundForms)
				{
					Layer4Panel.Children.Add(CreateResultBox("\ud83d\udcdd 表单", foundForm, Colors.Orange));
				}
			}
			if (result.FoundIframes.Count > 0)
			{
				Layer4Panel.Children.Add(new TextBlock
				{
					Text = $"发现 {result.FoundIframes.Count} 个iframe:",
					FontWeight = FontWeights.Bold,
					Foreground = System.Windows.Media.Brushes.Blue,
					Margin = new Thickness(0.0, 15.0, 0.0, 5.0)
				});
				foreach (string foundIframe in result.FoundIframes)
				{
					Layer4Panel.Children.Add(CreateResultBox("\ud83d\uddbc iframe", foundIframe, Colors.Blue));
				}
			}
			if (result.FoundDynamicLinks.Count > 0)
			{
				Layer4Panel.Children.Add(new TextBlock
				{
					Text = $"发现 {result.FoundDynamicLinks.Count} 个动态链接:",
					FontWeight = FontWeights.Bold,
					Foreground = System.Windows.Media.Brushes.Purple,
					Margin = new Thickness(0.0, 15.0, 0.0, 5.0)
				});
				foreach (string foundDynamicLink in result.FoundDynamicLinks)
				{
					Layer4Panel.Children.Add(CreateResultBox("\ud83d\udd17 动态链接", foundDynamicLink, Colors.Purple));
				}
			}
			if (result.FoundAjaxCalls.Count > 0)
			{
				Layer4Panel.Children.Add(new TextBlock
				{
					Text = $"发现 {result.FoundAjaxCalls.Count} 个AJAX请求:",
					FontWeight = FontWeights.Bold,
					Foreground = System.Windows.Media.Brushes.Teal,
					Margin = new Thickness(0.0, 15.0, 0.0, 5.0)
				});
				foreach (string foundAjaxCall in result.FoundAjaxCalls)
				{
					Layer4Panel.Children.Add(CreateInfoRow("  →", foundAjaxCall));
				}
			}
			if (result.ConsoleLogs.Count > 0)
			{
				Layer4Panel.Children.Add(new TextBlock
				{
					Text = $"浏览器控制台日志 ({result.ConsoleLogs.Count} 条):",
					FontWeight = FontWeights.Bold,
					Foreground = System.Windows.Media.Brushes.Gray,
					Margin = new Thickness(0.0, 15.0, 0.0, 5.0)
				});
				foreach (string item in result.ConsoleLogs.Take(20))
				{
					Layer4Panel.Children.Add(new TextBlock
					{
						Text = "  " + item,
						TextWrapping = TextWrapping.Wrap,
						FontFamily = new System.Windows.Media.FontFamily("Consolas"),
						FontSize = 10.0,
						Foreground = System.Windows.Media.Brushes.Gray
					});
				}
			}
			if (!string.IsNullOrEmpty(result.ScreenshotPath) && File.Exists(result.ScreenshotPath))
			{
				Layer4Panel.Children.Add(new TextBlock
				{
					Text = "\ud83d\udcf7 页面截图:",
					FontWeight = FontWeights.Bold,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(107, 207, 127)),
					Margin = new Thickness(0.0, 15.0, 0.0, 5.0)
				});
				try
				{
					BitmapImage bitmapImage = new BitmapImage();
					bitmapImage.BeginInit();
					bitmapImage.CacheOption = BitmapCacheOption.OnLoad;
					bitmapImage.UriSource = new Uri(result.ScreenshotPath);
					bitmapImage.EndInit();
					((Freezable)bitmapImage).Freeze();
					System.Windows.Controls.Image image = new System.Windows.Controls.Image
					{
						Source = bitmapImage,
						MaxWidth = 800.0,
						MaxHeight = 450.0,
						Stretch = Stretch.Uniform,
						Margin = new Thickness(0.0, 5.0, 0.0, 5.0),
						Cursor = System.Windows.Input.Cursors.Hand
					};
					System.Windows.Controls.ToolTip toolTip = new System.Windows.Controls.ToolTip
					{
						Content = result.ScreenshotPath
					};
					image.ToolTip = toolTip;
					Layer4Panel.Children.Add(image);
					Layer4Panel.Children.Add(new TextBlock
					{
						Text = "路径: " + result.ScreenshotPath,
						TextWrapping = TextWrapping.Wrap,
						Foreground = System.Windows.Media.Brushes.Gray,
						FontSize = 11.0,
						Margin = new Thickness(0.0, 2.0, 0.0, 5.0)
					});
				}
				catch
				{
					Layer4Panel.Children.Add(new TextBlock
					{
						Text = "截图加载失败: " + result.ScreenshotPath,
						Foreground = System.Windows.Media.Brushes.Gray,
						Margin = new Thickness(0.0, 2.0, 0.0, 5.0)
					});
				}
			}
			if (result.FoundForms.Count == 0 && result.FoundIframes.Count == 0 && result.FoundDynamicLinks.Count == 0 && result.FoundAjaxCalls.Count == 0 && string.IsNullOrEmpty(result.ScreenshotPath))
			{
				Layer4Panel.Children.Add(new TextBlock
				{
					Text = "Selenium动态检测未发现额外跳转、表单或隐藏路径",
					Foreground = System.Windows.Media.Brushes.Gray,
					Margin = new Thickness(0.0, 15.0, 0.0, 0.0)
				});
			}
		}

		private void ShowBruteResult(DirectoryBruteResult? result)
		{
			BrutePanel.Children.Clear();
			if (result == null)
			{
				BrutePanel.Children.Add(new TextBlock
				{
					Text = "未执行(仅在标准/深度模式下运行)",
					Foreground = System.Windows.Media.Brushes.Gray
				});
				return;
			}
			BrutePanel.Children.Add(new TextBlock
			{
				Text = "目录爆破结果",
				FontSize = 16.0,
				FontWeight = FontWeights.Bold,
				Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(44, 62, 80)),
				Margin = new Thickness(0.0, 0.0, 0.0, 15.0)
			});
			BrutePanel.Children.Add(CreateInfoRow("测试总数:", result.TotalTested.ToString()));
			BrutePanel.Children.Add(CreateInfoRow("发现路径:", result.FoundPaths.Count.ToString()));
			if (result.HasCustom404)
			{
				BrutePanel.Children.Add(new TextBlock
				{
					Text = "⚠\ufe0f 检测到自定义404页面，已启用内容相似度过滤",
					Foreground = System.Windows.Media.Brushes.Orange,
					TextWrapping = TextWrapping.Wrap,
					Margin = new Thickness(0.0, 5.0, 0.0, 5.0)
				});
			}
			int num = result.FoundPaths.Count((DiscoveredPath p) => p.Confidence >= 70);
			int num2 = result.FoundPaths.Count((DiscoveredPath p) => p.Confidence >= 50 && p.Confidence < 70);
			int num3 = result.FoundPaths.Count((DiscoveredPath p) => p.Confidence < 50);
			if (num > 0 || num2 > 0 || num3 > 0)
			{
				BrutePanel.Children.Add(new TextBlock
				{
					Text = $"置信度分布: 高={num} 中={num2} 低(疑似404)={num3}",
					Foreground = System.Windows.Media.Brushes.Gray,
					Margin = new Thickness(0.0, 5.0, 0.0, 5.0)
				});
			}
			if (result.ByStatusCode.Count > 0)
			{
				BrutePanel.Children.Add(new TextBlock
				{
					Text = "按状态码分类:",
					FontWeight = FontWeights.Bold,
					Margin = new Thickness(0.0, 15.0, 0.0, 5.0)
				});
				foreach (KeyValuePair<int, List<DiscoveredPath>> item in result.ByStatusCode.OrderByDescending((KeyValuePair<int, List<DiscoveredPath>> x) => x.Key))
				{
					System.Windows.Media.Color color = ((item.Key == 200) ? Colors.Green : ((item.Key == 403) ? Colors.Orange : ((item.Key >= 400) ? Colors.Red : Colors.Blue)));
					BrutePanel.Children.Add(new TextBlock
					{
						Text = $"  [{item.Key}] - {item.Value.Count} 个路径",
						FontWeight = FontWeights.Bold,
						Foreground = new SolidColorBrush(color),
						Margin = new Thickness(0.0, 5.0, 0.0, 3.0)
					});
					foreach (DiscoveredPath item2 in item.Value)
					{
						BrutePanel.Children.Add(CreateInfoRow("    →", item2.Url + " (" + item2.PathType + ")"));
					}
				}
			}
			if (result.FoundPaths.Count <= 0)
			{
				return;
			}
			BrutePanel.Children.Add(new TextBlock
			{
				Text = "所有发现路径:",
				FontWeight = FontWeights.Bold,
				Margin = new Thickness(0.0, 15.0, 0.0, 5.0)
			});
			foreach (DiscoveredPath foundPath in result.FoundPaths)
			{
				System.Windows.Media.Color borderColor = ((foundPath.StatusCode == 200) ? Colors.Green : ((foundPath.StatusCode == 403) ? Colors.Orange : Colors.Red));
				string value = ((foundPath.Confidence < 50) ? $" [⚠\ufe0f置信度:{foundPath.Confidence}%]" : ((foundPath.Confidence < 70) ? $" [置信度:{foundPath.Confidence}%]" : ""));
				string text = ((!string.IsNullOrEmpty(foundPath.Title)) ? (" \"" + foundPath.Title + "\"") : "");
				string text2 = ((foundPath.ContentLength > 0) ? $" [{foundPath.ContentLength}B]" : "");
				BrutePanel.Children.Add(CreateResultBox($"[{foundPath.StatusCode}] {foundPath.PathType}{value}", foundPath.Url + text + text2, borderColor));
			}
		}

