				System.Windows.Media.Color borderColor = ((text == "高风险") ? Colors.Red : ((text == "中风险") ? Colors.Orange : Colors.Gray));
				SensitivePathPanel.Children.Add(CreateResultBox("⚠\ufe0f " + text, sensitivePath, borderColor));
			}
			IOrderedEnumerable<IGrouping<string, string>> orderedEnumerable = from p in sensitivePaths
				group p by GetSensitivePathCategory(p) into g
				orderby g.Count() descending
				select g;
			SensitivePathPanel.Children.Add(new TextBlock
			{
				Text = "敏感路径分类统计:",
