			});
			foreach (IGrouping<string, string> item in orderedEnumerable)
			{
				System.Windows.Media.Color color = item.Key switch
				{
					"管理后台" => Colors.Red, 
					"认证相关" => Colors.Orange, 
					"API接口" => Colors.Teal, 
					"配置文件" => Colors.Purple, 
					"调试信息" => Colors.Blue, 
					_ => Colors.Gray, 
				};
				SensitivePathPanel.Children.Add(new TextBlock
				{
					Text = $"  {item.Key}: {item.Count()} 个路径",
					FontWeight = FontWeights.Bold,
					Foreground = new SolidColorBrush(color),
					Margin = new Thickness(0.0, 5.0, 0.0, 5.0)
				});
				foreach (string item2 in item.Take(5))
				{
					SensitivePathPanel.Children.Add(CreateInfoRow("    →", item2));
				}
				if (item.Count() > 5)
				{
					SensitivePathPanel.Children.Add(new TextBlock
					{
						Text = $"    ... 还有 {item.Count() - 5} 个",
						Foreground = System.Windows.Media.Brushes.Gray,
						Margin = new Thickness(0.0, 2.0, 0.0, 5.0)
					});
				}
			}
		}

		private static string ClassifySensitivePath(string path)
		{
			string text = path.ToLower();
			if (text.Contains("admin") || text.Contains("manage") || text.Contains("dashboard"))
			{
				return "高风险";
			}
			if (text.Contains("login") || text.Contains("auth") || text.Contains("token"))
			{
				return "高风险";
			}
			if (text.Contains("config") || text.Contains("env") || text.Contains("secret"))
			{
				return "高风险";
			}
			if (text.Contains("api") || text.Contains("graphql"))
			{
				return "中风险";
			}
			if (text.Contains("debug") || text.Contains("test") || text.Contains("dev"))
			{
				return "中风险";
			}
			return "低风险";
		}

		private static string GetSensitivePathCategory(string path)
		{
			string text = path.ToLower();
			if (text.Contains("admin") || text.Contains("manage") || text.Contains("dashboard") || text.Contains("console"))
			{
				return "管理后台";
			}
			if (text.Contains("login") || text.Contains("auth") || text.Contains("token") || text.Contains("register"))
			{
				return "认证相关";
			}
			if (text.Contains("api") || text.Contains("graphql") || text.Contains("rest"))
			{
				return "API接口";
			}
			if (text.Contains("config") || text.Contains("env") || text.Contains("secret") || text.Contains("backup"))
			{
				return "配置文件";
			}
			if (text.Contains("debug") || text.Contains("test") || text.Contains("dev"))
			{
				return "调试信息";
			}
			return "其他";
		}

