		private void ShowFinalResult(WebPathTraceResult result)
		{
			//IL_00d7: Unknown result type (might be due to invalid IL or missing references)
			//IL_00dc: Unknown result type (might be due to invalid IL or missing references)
			FinalResultPanel.Children.Clear();
			FinalResultPanel.Children.Add(new TextBlock
			{
				Text = (result.FoundPath ? "\ud83c\udfaf 追踪成功!" : "❌ 未发现路径"),
				FontSize = 20.0,
				FontWeight = FontWeights.Bold,
				Foreground = (result.FoundPath ? System.Windows.Media.Brushes.Green : System.Windows.Media.Brushes.Red),
				Margin = new Thickness(0.0, 0.0, 0.0, 20.0)
			});
			FinalResultPanel.Children.Add(CreateInfoRow("原始URL:", result.OriginalUrl));
			UIElementCollection children = FinalResultPanel.Children;
			TraceMode mode = result.Mode;
			children.Add(CreateInfoRow("追踪模式:", ((object)(TraceMode)(ref mode)).ToString()));
			Layer1Result layer1Results = result.Layer1Results;
			if (((layer1Results != null) ? layer1Results.TechStack : null) != null && result.Layer1Results.TechStack.DetectedTechs.Count > 0)
			{
				TechFingerprint techStack = result.Layer1Results.TechStack;
				FinalResultPanel.Children.Add(new TextBlock
				{
					Text = "\ud83d\udd27 技术栈: " + string.Join(", ", techStack.DetectedTechs),
					TextWrapping = TextWrapping.Wrap,
					FontWeight = FontWeights.Bold,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(142, 68, 173)),
					Margin = new Thickness(0.0, 5.0, 0.0, 5.0)
				});
			}
			if (result.FinalUrl != null)
			{
				FinalResultPanel.Children.Add(CreateResultBox("最终路径:", result.FinalUrl, Colors.Green));
			}
			FinalResultPanel.Children.Add(new TextBlock
			{
				Text = "各层探测结果:",
				FontWeight = FontWeights.Bold,
				FontSize = 14.0,
				Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(44, 62, 80)),
				Margin = new Thickness(0.0, 15.0, 0.0, 10.0)
			});
			UIElementCollection children2 = FinalResultPanel.Children;
			Layer1Result layer1Results2 = result.Layer1Results;
			children2.Add(CreateInfoRow("第一层(HTTP重定向):", (((layer1Results2 != null) ? layer1Results2.FoundUrl : null) != null) ? ("✅ 发现 → " + result.Layer1Results.FoundUrl) : "❌ 未发现"));
			UIElementCollection children3 = FinalResultPanel.Children;
			Layer2Result layer2Results = result.Layer2Results;
			children3.Add(CreateInfoRow("第二层(HTML/JS):", (((layer2Results != null) ? layer2Results.FoundUrl : null) != null) ? ("✅ 发现 → " + result.Layer2Results.FoundUrl) : "❌ 未发现"));
			UIElementCollection children4 = FinalResultPanel.Children;
			Layer3Result layer3Results = result.Layer3Results;
			children4.Add(CreateInfoRow("第三层(敏感文件):", (layer3Results != null && layer3Results.FoundUrls.Count > 0) ? $"发现 {result.Layer3Results.FoundUrls.Count} 个" : "❌ 未发现"));
			if (result.Layer4Results != null)
			{
				string value = ((result.Layer4Results.Error != null) ? ("⚠\ufe0f 失败: " + result.Layer4Results.Error) : (result.Layer4Results.UrlChanged ? ("✅ 发现动态跳转 → " + result.Layer4Results.FinalUrl) : "❌ 未发现动态跳转"));
				FinalResultPanel.Children.Add(CreateInfoRow("第四层(Selenium动态):", value));
			}
			else
			{
				FinalResultPanel.Children.Add(CreateInfoRow("第四层(Selenium动态):", "⏭ 已跳过"));
			}
			if (result.BruteResults != null)
			{
				FinalResultPanel.Children.Add(CreateInfoRow("目录爆破:", (result.BruteResults.FoundPaths.Count > 0) ? $"发现 {result.BruteResults.FoundPaths.Count} 个路径" : "❌ 未发现"));
			}
			if (result.CrawlResults != null)
			{
				FinalResultPanel.Children.Add(CreateInfoRow("深度爬取:", (result.CrawlResults.FoundPaths.Count > 0) ? $"发现 {result.CrawlResults.FoundPaths.Count} 个路径" : "❌ 未发现"));
			}
			if (result.AllDiscoveredPaths.Count <= 0)
			{
				return;
			}
			FinalResultPanel.Children.Add(new TextBlock
			{
				Text = $"所有发现的路径 ({result.AllDiscoveredPaths.Count}):",
				FontWeight = FontWeights.Bold,
				FontSize = 14.0,
				Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(44, 62, 80)),
				Margin = new Thickness(0.0, 15.0, 0.0, 10.0)
			});
			foreach (DiscoveredPath allDiscoveredPath in result.AllDiscoveredPaths)
			{
				System.Windows.Media.Color borderColor = ((allDiscoveredPath.PathType == "login") ? Colors.OrangeRed : ((allDiscoveredPath.PathType == "admin") ? Colors.Purple : ((allDiscoveredPath.PathType == "redirect") ? Colors.Blue : ((allDiscoveredPath.PathType == "api") ? Colors.Teal : Colors.Green))));
				FinalResultPanel.Children.Add(CreateResultBox($"[{allDiscoveredPath.PathType}] [{allDiscoveredPath.StatusCode}]", allDiscoveredPath.Url, borderColor));
			}
		}

		private TextBlock CreateInfoRow(string label, string value)
		{
			string value2 = value;
			string label2 = label;
			TextBlock tb = new TextBlock
			{
				Text = label2 + " " + value2,
				TextWrapping = TextWrapping.Wrap,
				Margin = new Thickness(0.0, 2.0, 0.0, 2.0)
			};
			if (value2.StartsWith("http://") || value2.StartsWith("https://"))
			{
				tb.Cursor = System.Windows.Input.Cursors.Hand;
				tb.Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(41, 128, 185));
				tb.MouseLeftButtonUp += delegate
				{
					try
					{
						System.Windows.Clipboard.SetText(value2);
						string oldText = tb.Text;
						tb.Text = label2 + " " + value2 + " [已复制!]";
						tb.FontWeight = FontWeights.Bold;
						((DispatcherObject)this).Dispatcher.BeginInvoke((Delegate)(Action)delegate
						{
							tb.Text = oldText;
							tb.FontWeight = FontWeights.Normal;
						}, (DispatcherPriority)2, Array.Empty<object>());
					}
					catch
					{
					}
				};
			}
			return tb;
		}

		private void ShowSecurityAuditResult(SecurityAuditResult audit)
		{
			SecurityAuditPanel.Children.Clear();
			System.Windows.Media.Color color = ((audit.OverallScore >= 80) ? Colors.Green : ((audit.OverallScore >= 60) ? Colors.Orange : Colors.Red));
			SecurityAuditPanel.Children.Add(new TextBlock
			{
				Text = "\ud83d\udd12 安全审计报告",
				FontSize = 16.0,
				FontWeight = FontWeights.Bold,
				Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(44, 62, 80)),
				Margin = new Thickness(0.0, 0.0, 0.0, 15.0)
			});
			Border border = new Border
			{
				Background = new SolidColorBrush(System.Windows.Media.Color.FromArgb(32, color.R, color.G, color.B)),
				BorderBrush = new SolidColorBrush(color),
				BorderThickness = new Thickness(2.0),
				CornerRadius = new CornerRadius(5.0),
				Padding = new Thickness(15.0),
				Margin = new Thickness(0.0, 0.0, 0.0, 15.0)
			};
			StackPanel stackPanel = new StackPanel
			{
				Orientation = System.Windows.Controls.Orientation.Horizontal
			};
			stackPanel.Children.Add(new TextBlock
			{
				Text = "安全得分: ",
				FontWeight = FontWeights.Bold,
				FontSize = 16.0
			});
			stackPanel.Children.Add(new TextBlock
			{
				Text = $"{audit.OverallScore}/100",
				FontWeight = FontWeights.Bold,
				FontSize = 20.0,
				Foreground = new SolidColorBrush(color)
			});
			border.Child = stackPanel;
			SecurityAuditPanel.Children.Add(border);
			if (audit.PassedChecks.Count > 0)
			{
				SecurityAuditPanel.Children.Add(new TextBlock
				{
					Text = $"✅ 通过检查 ({audit.PassedChecks.Count}):",
					FontWeight = FontWeights.Bold,
					Foreground = System.Windows.Media.Brushes.Green,
					Margin = new Thickness(0.0, 10.0, 0.0, 5.0)
				});
				foreach (string passedCheck in audit.PassedChecks)
				{
					SecurityAuditPanel.Children.Add(new TextBlock
					{
						Text = "  " + passedCheck,
						Foreground = System.Windows.Media.Brushes.Green,
						Margin = new Thickness(0.0, 2.0, 0.0, 2.0)
					});
				}
			}
			if (audit.FailedChecks.Count > 0)
			{
				SecurityAuditPanel.Children.Add(new TextBlock
				{
					Text = $"❌ 未通过检查 ({audit.FailedChecks.Count}):",
					FontWeight = FontWeights.Bold,
					Foreground = System.Windows.Media.Brushes.Red,
					Margin = new Thickness(0.0, 15.0, 0.0, 5.0)
				});
				foreach (string failedCheck in audit.FailedChecks)
				{
					SecurityAuditPanel.Children.Add(new TextBlock
					{
						Text = "  " + failedCheck,
						Foreground = System.Windows.Media.Brushes.Red,
						Margin = new Thickness(0.0, 2.0, 0.0, 2.0)
					});
				}
			}
			if (audit.Findings.Count <= 0)
			{
				return;
			}
			SecurityAuditPanel.Children.Add(new TextBlock
			{
				Text = $"安全发现 ({audit.Findings.Count}):",
				FontWeight = FontWeights.Bold,
				Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(230, 126, 34)),
				Margin = new Thickness(0.0, 15.0, 0.0, 10.0)
			});
			foreach (SecurityFinding finding in audit.Findings)
			{
				System.Windows.Media.Color color2 = finding.Severity switch
				{
					"Critical" => Colors.Red, 
					"High" => Colors.OrangeRed, 
					"Medium" => Colors.Orange, 
					"Low" => Colors.Gray, 
					_ => Colors.Blue, 
				};
				Border border2 = new Border
				{
					Background = System.Windows.Media.Brushes.White,
					BorderBrush = new SolidColorBrush(color2),
					BorderThickness = new Thickness(1.0),
					CornerRadius = new CornerRadius(3.0),
					Padding = new Thickness(10.0),
					Margin = new Thickness(0.0, 5.0, 0.0, 5.0)
				};
				StackPanel stackPanel2 = new StackPanel();
				stackPanel2.Children.Add(new TextBlock
				{
					Text = "[" + finding.Severity + "] " + finding.Title,
					FontWeight = FontWeights.Bold,
					Foreground = new SolidColorBrush(color2)
				});
				stackPanel2.Children.Add(new TextBlock
				{
					Text = finding.Description,
					TextWrapping = TextWrapping.Wrap,
					Foreground = System.Windows.Media.Brushes.DarkGray,
					Margin = new Thickness(0.0, 3.0, 0.0, 0.0)
				});
				stackPanel2.Children.Add(new TextBlock
				{
					Text = "建议: " + finding.Recommendation,
					TextWrapping = TextWrapping.Wrap,
					Foreground = System.Windows.Media.Brushes.Green,
					Margin = new Thickness(0.0, 5.0, 0.0, 0.0),
					FontSize = 11.0
				});
				border2.Child = stackPanel2;
				SecurityAuditPanel.Children.Add(border2);
			}
		}

		private void ShowVulnerabilityInfo(List<string> techs, WebPathTracerService tracer)
		{
			VulnInfoPanel.Children.Clear();
			VulnInfoPanel.Children.Add(new TextBlock
			{
				Text = "\ud83d\udcca 技术栈漏洞信息",
				FontSize = 16.0,
				FontWeight = FontWeights.Bold,
				Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(44, 62, 80)),
				Margin = new Thickness(0.0, 0.0, 0.0, 15.0)
			});
			bool flag = false;
			foreach (string tech in techs)
			{
				TechVulnerabilityInfo techVulnerabilities = tracer.GetTechVulnerabilities(tech);
				if (techVulnerabilities.KnownVulnerabilities.Count == 0)
				{
					continue;
				}
				flag = true;
				VulnInfoPanel.Children.Add(new TextBlock
				{
					Text = "\ud83d\udd27 " + tech + " 已知漏洞:",
					FontWeight = FontWeights.Bold,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(231, 76, 60)),
					Margin = new Thickness(0.0, 10.0, 0.0, 5.0)
				});
				foreach (CveInfo knownVulnerability in techVulnerabilities.KnownVulnerabilities)
				{
					System.Windows.Media.Color color = knownVulnerability.Severity switch
					{
						"Critical" => Colors.Red, 
						"High" => Colors.OrangeRed, 
						"Medium" => Colors.Orange, 
						_ => Colors.Gray, 
					};
					Border border = new Border
					{
						Background = new SolidColorBrush(System.Windows.Media.Color.FromArgb(8, color.R, color.G, color.B)),
						BorderBrush = new SolidColorBrush(color),
						BorderThickness = new Thickness(1.0),
						CornerRadius = new CornerRadius(3.0),
						Padding = new Thickness(10.0),
						Margin = new Thickness(0.0, 3.0, 0.0, 5.0)
					};
					StackPanel stackPanel = new StackPanel();
					stackPanel.Children.Add(new TextBlock
					{
						Text = $"{knownVulnerability.CveId} [{knownVulnerability.Severity}] CVSS: {knownVulnerability.CvssScore:F1}",
						FontWeight = FontWeights.Bold,
						Foreground = new SolidColorBrush(color)
					});
					stackPanel.Children.Add(new TextBlock
					{
						Text = knownVulnerability.Description,
						TextWrapping = TextWrapping.Wrap,
						Margin = new Thickness(0.0, 3.0, 0.0, 0.0)
					});
					if (!string.IsNullOrEmpty(knownVulnerability.FixVersion))
					{
						stackPanel.Children.Add(new TextBlock
						{
							Text = "修复版本: " + knownVulnerability.FixVersion,
							Foreground = System.Windows.Media.Brushes.Green,
							Margin = new Thickness(0.0, 3.0, 0.0, 0.0),
							FontWeight = FontWeights.Bold,
							FontSize = 11.0
						});
					}
					border.Child = stackPanel;
					VulnInfoPanel.Children.Add(border);
				}
			}
			if (!flag)
			{
				VulnInfoPanel.Children.Add(new TextBlock
				{
					Text = "✅ 未检测到已知漏洞",
					Foreground = System.Windows.Media.Brushes.Green,
					FontWeight = FontWeights.Bold,
					Margin = new Thickness(0.0, 20.0, 0.0, 0.0)
				});
			}
		}

		private void ShowSslCertificateResult(SslCertificateInfo? ssl)
		{
			SslCertificatePanel.Children.Clear();
			if (ssl == null)
			{
				SslCertificatePanel.Children.Add(new TextBlock
				{
					Text = "⚠\ufe0f SSL证书分析失败或未执行",
					Foreground = System.Windows.Media.Brushes.Gray,
					FontSize = 14.0,
					Margin = new Thickness(0.0, 10.0, 0.0, 0.0)
				});
				return;
			}
			SslCertificatePanel.Children.Add(new TextBlock
			{
				Text = "\ud83d\udd10 SSL/TLS 证书分析报告",
				FontSize = 16.0,
				FontWeight = FontWeights.Bold,
				Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(44, 62, 80)),
				Margin = new Thickness(0.0, 0.0, 0.0, 15.0)
			});
			if (!ssl.IsValid)
			{
				_ = Colors.Red;
			}
			else
			{
				_ = Colors.Green;
			}
			SslCertificatePanel.Children.Add(CreateInfoRow("证书状态:", ssl.IsValid ? "✅ 有效" : "❌ 无效/警告"));
			SslCertificatePanel.Children.Add(CreateInfoRow("主题:", ssl.Subject));
			SslCertificatePanel.Children.Add(CreateInfoRow("颁发者:", ssl.Issuer));
			SslCertificatePanel.Children.Add(CreateInfoRow("颁发日期:", ssl.ValidFrom ?? "未知"));
			SslCertificatePanel.Children.Add(CreateInfoRow("到期日期:", ssl.ValidTo ?? "未知"));
			if (ssl.DaysUntilExpiry.HasValue)
			{
				System.Windows.Media.Color color = ((ssl.DaysUntilExpiry.Value > 30) ? Colors.Green : ((ssl.DaysUntilExpiry.Value > 7) ? Colors.Orange : Colors.Red));
				TextBlock element = new TextBlock
				{
					Text = $"剩余天数: {ssl.DaysUntilExpiry.Value}天",
					Foreground = new SolidColorBrush(color),
					FontWeight = FontWeights.Bold,
					Margin = new Thickness(0.0, 2.0, 0.0, 2.0)
				};
				SslCertificatePanel.Children.Add(element);
			}
			SslCertificatePanel.Children.Add(CreateInfoRow("序列号:", ssl.SerialNumber ?? "未知"));
			SslCertificatePanel.Children.Add(CreateInfoRow("证书版本:", ssl.Version ?? "未知"));
			SslCertificatePanel.Children.Add(CreateInfoRow("签名算法:", ssl.SignatureAlgorithm ?? "未知"));
			SslCertificatePanel.Children.Add(CreateInfoRow("公钥算法:", ssl.PublicKeyAlgorithm ?? "未知"));
			if (ssl.KeySize.HasValue)
			{
				System.Windows.Media.Color color2 = ((ssl.KeySize.Value >= 2048) ? Colors.Green : Colors.Red);
				SslCertificatePanel.Children.Add(new TextBlock
				{
					Text = $"密钥长度: {ssl.KeySize.Value}位",
					Foreground = new SolidColorBrush(color2),
					Margin = new Thickness(0.0, 2.0, 0.0, 2.0)
				});
			}
			SslCertificatePanel.Children.Add(CreateInfoRow("TLS协议:", ssl.ProtocolVersion ?? "未知"));
			SslCertificatePanel.Children.Add(CreateInfoRow("加密套件:", ssl.CipherSuite ?? "未知"));
			SslCertificatePanel.Children.Add(CreateInfoRow("支持TLS 1.2:", ssl.SupportsTls12 ? "✅ 是" : "❌ 否"));
			SslCertificatePanel.Children.Add(CreateInfoRow("支持TLS 1.3:", ssl.SupportsTls13 ? "✅ 是" : "❌ 否"));
			SslCertificatePanel.Children.Add(new TextBlock
			{
				Text = "自签名证书: " + (ssl.IsSelfSigned ? "⚠\ufe0f 是（不受信任）" : "✅ 否（受信任）"),
				Foreground = (ssl.IsSelfSigned ? System.Windows.Media.Brushes.Red : System.Windows.Media.Brushes.Green),
				Margin = new Thickness(0.0, 2.0, 0.0, 2.0)
			});
			if (ssl.SubjectAlternativeNames.Count > 0)
			{
				SslCertificatePanel.Children.Add(new TextBlock
				{
					Text = $"\ud83c\udf10 主题备用域名 ({ssl.SubjectAlternativeNames.Count}个):",
					FontWeight = FontWeights.Bold,
					Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(44, 62, 80)),
					Margin = new Thickness(0.0, 10.0, 0.0, 5.0)
				});
				foreach (string item in ssl.SubjectAlternativeNames.Take(10))
				{
					SslCertificatePanel.Children.Add(new TextBlock
					{
						Text = "  • " + item,
						Foreground = System.Windows.Media.Brushes.Gray,
						Margin = new Thickness(0.0, 1.0, 0.0, 1.0)
					});
				}
			}
			if (!string.IsNullOrEmpty(ssl.CrlDistributionPoints))
			{
				SslCertificatePanel.Children.Add(CreateInfoRow("CRL吊销检查:", ssl.CrlDistributionPoints));
			}
			if (!string.IsNullOrEmpty(ssl.OcspResponderUrl))
			{
				SslCertificatePanel.Children.Add(CreateInfoRow("OCSP状态:", ssl.OcspResponderUrl));
			}
			if (ssl.Warnings.Count <= 0)
			{
				return;
			}
			SslCertificatePanel.Children.Add(new TextBlock
			{
				Text = $"⚠\ufe0f 警告信息 ({ssl.Warnings.Count}个):",
				FontWeight = FontWeights.Bold,
				Foreground = System.Windows.Media.Brushes.Red,
				Margin = new Thickness(0.0, 15.0, 0.0, 5.0)
			});
			foreach (string warning in ssl.Warnings)
			{
				SslCertificatePanel.Children.Add(new TextBlock
				{
					Text = "  • " + warning,
					Foreground = System.Windows.Media.Brushes.Red,
					TextWrapping = TextWrapping.Wrap,
					Margin = new Thickness(0.0, 2.0, 0.0, 2.0)
				});
			}
		}

		private Border CreateStatBox(string icon, string value, string label)
		{
			Border obj = new Border
			{
				Background = System.Windows.Media.Brushes.White,
				BorderBrush = new SolidColorBrush(System.Windows.Media.Color.FromRgb(221, 221, 221)),
				BorderThickness = new Thickness(1.0),
				CornerRadius = new CornerRadius(4.0),
				Padding = new Thickness(8.0, 4.0, 8.0, 4.0),
				Margin = new Thickness(0.0, 0.0, 8.0, 0.0)
			};
			StackPanel stackPanel = new StackPanel
			{
				Orientation = System.Windows.Controls.Orientation.Horizontal
			};
			stackPanel.Children.Add(new TextBlock
			{
				Text = icon,
				FontSize = 14.0,
				Margin = new Thickness(0.0, 0.0, 4.0, 0.0)
			});
			stackPanel.Children.Add(new TextBlock
			{
				Text = value,
				FontWeight = FontWeights.Bold,
				Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(44, 62, 80)),
				Margin = new Thickness(0.0, 0.0, 2.0, 0.0)
			});
			stackPanel.Children.Add(new TextBlock
