			});
			obj.Child = stackPanel;
			return obj;
		}

		private Border CreateResultBox(string label, string value, System.Windows.Media.Color borderColor)
		{
			string value2 = value;
			SolidColorBrush solidColorBrush = new SolidColorBrush(borderColor);
			StackPanel stackPanel = new StackPanel
			{
				Margin = new Thickness(10.0)
			};
			stackPanel.Children.Add(new TextBlock
			{
				Text = label,
				FontWeight = FontWeights.Bold,
				Foreground = solidColorBrush
			});
			TextBlock valueTb = new TextBlock
			{
				Text = value2,
				TextWrapping = TextWrapping.Wrap
			};
			if (value2.StartsWith("http://") || value2.StartsWith("https://"))
			{
				valueTb.Cursor = System.Windows.Input.Cursors.Hand;
				valueTb.Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(41, 128, 185));
				valueTb.MouseLeftButtonUp += delegate
				{
					try
					{
						System.Windows.Clipboard.SetText(value2);
						string oldText = valueTb.Text;
						valueTb.Text = value2 + " [已复制!]";
						valueTb.FontWeight = FontWeights.Bold;
						((DispatcherObject)this).Dispatcher.BeginInvoke((Delegate)(Action)delegate
						{
							valueTb.Text = oldText;
							valueTb.FontWeight = FontWeights.Normal;
						}, (DispatcherPriority)2, Array.Empty<object>());
					}
					catch
					{
					}
				};
			}
			stackPanel.Children.Add(valueTb);
			return new Border
			{
				Background = System.Windows.Media.Brushes.WhiteSmoke,
				BorderBrush = solidColorBrush,
				BorderThickness = new Thickness(2.0),
				CornerRadius = new CornerRadius(5.0),
				Margin = new Thickness(0.0, 5.0, 0.0, 5.0),
				Child = stackPanel
			};
		}

		private Border CreateRedirectChainItem(PathStep step, int index)
		{
			SolidColorBrush solidColorBrush = new SolidColorBrush((step.StatusCode >= 300 && step.StatusCode < 400) ? Colors.Blue : ((step.StatusCode >= 400) ? Colors.Red : Colors.Green));
			StackPanel stackPanel = new StackPanel
			{
				Margin = new Thickness(10.0)
			};
			stackPanel.Children.Add(new TextBlock
			{
				Text = $"步骤 {index}",
				FontWeight = FontWeights.Bold,
				Foreground = solidColorBrush
			});
			stackPanel.Children.Add(new TextBlock
			{
				Text = "URL: " + step.Url,
				TextWrapping = TextWrapping.Wrap
			});
			stackPanel.Children.Add(new TextBlock
			{
				Text = $"状态码: {step.StatusCode}"
			});
			if (step.LocationHeader != null)
			{
				stackPanel.Children.Add(new TextBlock
				{
					Text = "Location: " + step.LocationHeader,
					TextWrapping = TextWrapping.Wrap,
					Foreground = System.Windows.Media.Brushes.Blue
				});
			}
			return new Border
			{
				Background = System.Windows.Media.Brushes.WhiteSmoke,
				BorderBrush = solidColorBrush,
				BorderThickness = new Thickness(2.0, 0.0, 0.0, 2.0),
				CornerRadius = new CornerRadius(3.0),
				Margin = new Thickness(20.0, 3.0, 0.0, 3.0),
				Child = stackPanel
			};
		}

