	public class UiUpdateThrottler : IDisposable
	{
		private readonly Dispatcher _dispatcher;

		private readonly System.Threading.Timer _timer;

		private readonly ConcurrentQueue<Action> _pendingActions;

		private readonly object _lockObject = new object();

		private int _updateIntervalMs;

		private bool _isDisposed;

		private long _totalProcessed;

		private long _mergedUpdates;

		public int PendingCount => _pendingActions.Count;

		public int UpdateIntervalMs
		{
			get
			{
				return _updateIntervalMs;
			}
			set
			{
				if (value > 0)
				{
					_updateIntervalMs = value;
					_timer.Change(value, value);
				}
			}
		}

		public long TotalProcessed => _totalProcessed;

		public long MergedUpdates => _mergedUpdates;

		public UiUpdateThrottler(Dispatcher dispatcher, int updateIntervalMs = 500)
		{
			_dispatcher = dispatcher ?? throw new ArgumentNullException("dispatcher");
			_pendingActions = new ConcurrentQueue<Action>();
			_updateIntervalMs = Math.Max(50, updateIntervalMs);
			_timer = new System.Threading.Timer(OnTimerTick, null, _updateIntervalMs, _updateIntervalMs);
		}

		public void Enqueue(Action action)
		{
			if (!_isDisposed && action != null)
			{
				_pendingActions.Enqueue(action);
				if (_pendingActions.Count > 1000)
				{
					ProcessPendingUpdates();
				}
			}
		}

		public void Enqueue(Action action, bool highPriority)
		{
			if (_isDisposed || action == null)
			{
				return;
			}
			if (highPriority)
			{
				try
				{
					if (_dispatcher.CheckAccess())
					{
						action();
					}
					else
					{
						_dispatcher.BeginInvoke((Delegate)action, Array.Empty<object>());
					}
					Interlocked.Increment(ref _totalProcessed);
					return;
				}
				catch (Exception)
				{
					return;
				}
			}
			Enqueue(action);
		}

		public void Flush()
		{
			ProcessPendingUpdates();
		}

		private void OnTimerTick(object state)
		{
			ProcessPendingUpdates();
		}

		private void ProcessPendingUpdates()
		{
			if (_isDisposed || _pendingActions.IsEmpty)
			{
				return;
			}
			lock (_lockObject)
			{
				if (_pendingActions.IsEmpty)
				{
					return;
				}
				try
				{
					_dispatcher.BeginInvoke((Delegate)(Action)delegate
					{
						try
						{
							int num = 0;
							Action result;
							while (_pendingActions.TryDequeue(out result) && num < 100)
							{
								try
								{
									result?.Invoke();
									num++;
								}
								catch (Exception)
								{
								}
							}
							if (num > 1)
							{
								Interlocked.Add(ref _mergedUpdates, num - 1);
							}
							Interlocked.Add(ref _totalProcessed, num);
						}
						catch (Exception)
						{
						}
					}, Array.Empty<object>());
				}
				catch (Exception)
				{
				}
			}
		}

		public void Clear()
		{
			while (!_pendingActions.IsEmpty)
			{
				_pendingActions.TryDequeue(out Action _);
			}
		}

		public string GetStatistics()
		{
			return $"UI节流器统计:\n- 更新间隔: {_updateIntervalMs}ms\n- 总处理次数: {TotalProcessed}\n- 合并的更新: {MergedUpdates}\n- 当前队列大小: {_pendingActions.Count}\n- 节省UI刷新率: {((TotalProcessed > 0) ? ((double)MergedUpdates / (double)TotalProcessed * 100.0) : 0.0):F1}%";
		}

		public void Dispose()
		{
			Dispose(disposing: true);
			GC.SuppressFinalize(this);
		}

		protected virtual void Dispose(bool disposing)
		{
			if (!_isDisposed)
			{
				if (disposing)
				{
					_timer?.Dispose();
					Clear();
				}
				_isDisposed = true;
			}
		}
	}
	public class DataPager<T> where T : class
	{
		private readonly IList<T> _allData;

		private readonly int _pageSize;

		private int _currentPage;

		public int PageSize => _pageSize;

		public int CurrentPage => _currentPage;

		public int TotalPages => (int)Math.Ceiling((double)_allData.Count / (double)_pageSize);

		public int TotalCount => _allData.Count;

		public bool HasPreviousPage => _currentPage > 0;

		public bool HasNextPage => _currentPage < TotalPages - 1;

		public DataPager(IList<T> data, int pageSize = 100)
		{
			_allData = data ?? throw new ArgumentNullException("data");
			_pageSize = Math.Max(10, Math.Min(pageSize, 1000));
			_currentPage = 0;
		}

		public List<T> GetCurrentPage()
		{
			return GetPage(_currentPage);
		}

		public List<T> GetPage(int pageIndex)
		{
			if (pageIndex < 0 || pageIndex >= TotalPages)
			{
				throw new ArgumentOutOfRangeException("pageIndex");
			}
			_currentPage = pageIndex;
			int num = pageIndex * _pageSize;
			int num2 = Math.Min(_pageSize, _allData.Count - num);
			List<T> list = new List<T>(num2);
			for (int i = 0; i < num2; i++)
			{
				list.Add(_allData[num + i]);
			}
			return list;
		}

		public List<T> NextPage()
		{
			if (!HasNextPage)
			{
				throw new InvalidOperationException("已经是最后一页");
			}
			return GetPage(_currentPage + 1);
		}

		public List<T> PreviousPage()
		{
			if (!HasPreviousPage)
			{
				throw new InvalidOperationException("已经是第一页");
			}
			return GetPage(_currentPage - 1);
		}

		public List<T> FirstPage()
		{
			return GetPage(0);
		}

		public List<T> LastPage()
		{
			return GetPage(TotalPages - 1);
		}

		public void Reset()
		{
			_currentPage = 0;
		}
	}
	public class ThreadSafeProgress<T> : IProgress<T>
	{
		private readonly Action<T> _handler;

		private readonly Window _window;

		public ThreadSafeProgress(Window window, Action<T> handler)
		{
			_window = window ?? throw new ArgumentNullException("window");
			_handler = handler ?? throw new ArgumentNullException("handler");
		}

		public void Report(T value)
		{
			T value2 = value;
			try
			{
				if (((DispatcherObject)_window).Dispatcher.CheckAccess())
				{
					ExecuteHandler(value2);
					return;
				}
				((DispatcherObject)_window).Dispatcher.BeginInvoke((Delegate)(Action)delegate
				{
					ExecuteHandler(value2);
				}, Array.Empty<object>());
			}
			catch (Exception ex)
			{
				LogException("Report", ex);
			}
		}

		private void ExecuteHandler(T value)
		{
			try
			{
				_handler(value);
			}
			catch (Exception ex)
			{
				LogException("ExecuteHandler", ex);
			}
		}

		private void LogException(string methodName, Exception ex)
		{
			try
			{
				string text = System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "logs");
				Directory.CreateDirectory(text);
				string path = System.IO.Path.Combine(text, $"app_{DateTime.Now:yyyyMMdd}.log");
				string text2 = $"[{DateTime.Now:HH:mm:ss.fff}] ThreadSafeProgress.{methodName} 异常: {ex.Message}\n{ex.StackTrace}";
				File.AppendAllText(path, text2 + Environment.NewLine);
			}
			catch (Exception)
			{
			}
		}
	}
