namespace NetSecurityScanner.Services
{
	public sealed class CameraSystemNotifier : IDisposable
	{
		private static CameraSystemNotifier? _instance;

		private static readonly object _lock = new object();

		private NotifyIcon? _notifyIcon;

		private bool _initialized;

		private bool _disposed;

		public static CameraSystemNotifier Instance
		{
			get
			{
				if (_instance == null)
				{
					lock (_lock)
					{
						if (_instance == null)
						{
							_instance = new CameraSystemNotifier();
						}
					}
				}
				return _instance;
			}
		}

		private CameraSystemNotifier()
		{
			try
			{
				_notifyIcon = new NotifyIcon
				{
					Icon = LoadAppIcon(),
					Visible = true,
					Text = "NetSecurityScanner 摄像头告警"
				};
				_notifyIcon.BalloonTipClosed += delegate
				{
				};
				_initialized = true;
			}
			catch (Exception)
			{
				_initialized = false;
			}
			CameraAlertService.SystemNotifySink = ShowBalloon;
		}

		public void ShowBalloon(string title, string message, string level)
		{
			if (!_initialized || _notifyIcon == null)
			{
				return;
			}
			try
			{
				ToolTipIcon toolTipIcon = ((level == "严重") ? ToolTipIcon.Error : ((!(level == "高")) ? ToolTipIcon.Info : ToolTipIcon.Warning));
				ToolTipIcon balloonTipIcon = toolTipIcon;
				_notifyIcon.BalloonTipIcon = balloonTipIcon;
				_notifyIcon.BalloonTipTitle = "[" + level + "] " + title;
				_notifyIcon.BalloonTipText = Truncate(message, 250);
				_notifyIcon.ShowBalloonTip(5000);
			}
			catch (Exception)
			{
			}
		}

		private static Icon LoadAppIcon()
		{
			try
			{
				string text = Assembly.GetEntryAssembly()?.Location;
				if (!string.IsNullOrEmpty(text) && File.Exists(text))
				{
					Icon icon = Icon.ExtractAssociatedIcon(text);
					if (icon != null)
					{
						return icon;
					}
				}
			}
			catch
			{
			}
			return SystemIcons.Information;
		}

		private static string Truncate(string s, int max)
		{
			if (!string.IsNullOrEmpty(s))
			{
				if (s.Length > max)
				{
					return s.Substring(0, max) + "...";
				}
				return s;
			}
			return string.Empty;
		}

		public void Dispose()
		{
			if (_disposed)
			{
				return;
			}
			_disposed = true;
			try
			{
				if (_notifyIcon != null)
				{
					_notifyIcon.Visible = false;
					_notifyIcon.Dispose();
					_notifyIcon = null;
				}
				CameraAlertService.SystemNotifySink = null;
			}
			catch
			{
			}
		}
	}
