			double num = Math.Max(300.0, (base.ActualWidth > 0.0) ? base.ActualWidth : 480.0);
			List<KeyValuePair<string, int>> list = dictionary.OrderByDescending((KeyValuePair<string, int> kv) => kv.Value).ToList();
			int num2 = Math.Max(1, list.Max((KeyValuePair<string, int> kv) => kv.Value));
			double height = 16.0 + (double)list.Count * 32.0;
			_chartCanvas.Height = height;
			_chartCanvas.Width = num;
			SolidColorBrush foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(51, 65, 85));
			SolidColorBrush foreground2 = new SolidColorBrush(System.Windows.Media.Color.FromRgb(30, 41, 59));
			SolidColorBrush fill = new SolidColorBrush(System.Windows.Media.Color.FromRgb(37, 99, 235));
			SolidColorBrush fill2 = new SolidColorBrush(System.Windows.Media.Color.FromRgb(226, 232, 240));
			double num3 = num - 110.0 - 50.0 - 24.0;
			for (int i = 0; i < list.Count; i++)
			{
				KeyValuePair<string, int> keyValuePair = list[i];
				double num4 = 8.0 + (double)i * 32.0;
				TextBlock element2 = new TextBlock
				{
					Text = Truncate(keyValuePair.Key, 16),
					FontSize = 12.0,
					Foreground = foreground,
					Width = 110.0,
					TextTrimming = TextTrimming.CharacterEllipsis,
					VerticalAlignment = VerticalAlignment.Center,
					TextAlignment = TextAlignment.Right
				};
				Canvas.SetLeft(element2, 8.0);
				Canvas.SetTop(element2, num4 + 5.0);
				_chartCanvas.Children.Add(element2);
				System.Windows.Shapes.Rectangle element3 = new System.Windows.Shapes.Rectangle
				{
					Width = num3,
					Height = 16.0,
					RadiusX = 3.0,
					RadiusY = 3.0,
					Fill = fill2
				};
				Canvas.SetLeft(element3, 126.0);
				Canvas.SetTop(element3, num4 + 5.0);
				_chartCanvas.Children.Add(element3);
				double num5 = Math.Max(2.0, num3 * (double)keyValuePair.Value / (double)num2);
				if (num5 < 50.0 && keyValuePair.Value > 0)
				{
					num5 = 50.0;
				}
				System.Windows.Shapes.Rectangle element4 = new System.Windows.Shapes.Rectangle
				{
					Width = Math.Min(num3, num5),
					Height = 16.0,
					RadiusX = 3.0,
					RadiusY = 3.0,
					Fill = fill,
					ToolTip = $"{keyValuePair.Key}: {keyValuePair.Value}"
				};
				Canvas.SetLeft(element4, 126.0);
				Canvas.SetTop(element4, num4 + 5.0);
				_chartCanvas.Children.Add(element4);
				TextBlock element5 = new TextBlock
				{
					Text = keyValuePair.Value.ToString(CultureInfo.InvariantCulture),
					FontSize = 12.0,
					FontWeight = FontWeights.SemiBold,
					Foreground = foreground2,
					Width = 50.0,
					TextAlignment = TextAlignment.Left
				};
				Canvas.SetLeft(element5, 126.0 + num3 + 6.0);
				Canvas.SetTop(element5, num4 + 5.0);
				_chartCanvas.Children.Add(element5);
			}
		}

		private static string Truncate(string s, int max)
		{
			if (string.IsNullOrEmpty(s))
			{
				return string.Empty;
			}
			if (s.Length > max)
			{
				return s.Substring(0, max - 1) + "…";
			}
			return s;
		}
	}
}
